BEGIN;
UPDATE tarot_cards SET meaning = 'A blank page and a leap of faith — a new journey begins with an open heart. You do not need a complete map before taking the first step. Curiosity helps you learn from each attempt, while a little preparation keeps freedom from becoming carelessness.' WHERE id = 'fool';
UPDATE tarot_cards SET meaning = 'You hold all the tools you need. Focus your will and turn intention into action. An idea becomes real when your attention, time, and available resources point toward the same task. Look at the tools already within reach before waiting for another sign.' WHERE id = 'magician';
UPDATE tarot_cards SET meaning = 'Quiet wisdom hides beneath the surface. Listen to your intuition and inner voice. Silence may reveal a pattern, a feeling you cannot yet name, or information that is still missing. Observe a little longer before bringing everything into the open.' WHERE id = 'high-priestess';
UPDATE tarot_cards SET meaning = 'Growth, abundance, and nurturing energy surround you. Let beauty and care flourish. A relationship, project, or part of yourself may grow through steady care. Abundance here means having room to develop, not giving until you have nothing left.' WHERE id = 'empress';
UPDATE tarot_cards SET meaning = 'Structure, authority, and steady leadership. Build on solid ground with discipline. A useful structure gives people the safety to grow. Notice the difference between taking responsibility and trying to control every detail; they can look alike at first.' WHERE id = 'emperor';
UPDATE tarot_cards SET meaning = 'Tradition and trusted guidance offer a reliable path. Learn from what has come before. A teacher, community, or established method may offer a sound starting point. Learn why a tradition works so that you can apply it thoughtfully to your own situation.' WHERE id = 'hierophant';
UPDATE tarot_cards SET meaning = 'A meaningful bond or an important choice. Follow what your heart truly values. Lasting harmony asks both sides to speak honestly about needs and boundaries. If this is a decision rather than a romance, ask which path reflects your deeper values.' WHERE id = 'lovers';
UPDATE tarot_cards SET meaning = 'Willpower and momentum carry you forward. Stay focused and you will prevail. Opposing impulses can still carry you forward when you give them a shared direction. Progress depends on steering your feelings and actions, not simply pushing harder.' WHERE id = 'chariot';
UPDATE tarot_cards SET meaning = 'True power is gentle — patience, courage, and compassion tame any challenge. Gentleness is an active form of courage: you can stay with discomfort without letting it decide your response. Acknowledge fear and move with care rather than waiting for fear to disappear.' WHERE id = 'strength';
UPDATE tarot_cards SET meaning = 'Time to step back and seek inner clarity. Solitude now brings deeper answers. Stepping back can make your own voice easier to hear amid other people''s opinions. Solitude helps when it leads to understanding, but it can also become a way of avoiding connection.' WHERE id = 'hermit';
UPDATE tarot_cards SET meaning = 'Fortune turns and cycles shift. What changes now is part of a larger rhythm. An old cycle may be turning, bringing inconvenience alongside possibility. You cannot choose every event, but you can choose what to carry forward and how to prepare for the next turn.' WHERE id = 'wheel-of-fortune';
UPDATE tarot_cards SET meaning = 'Truth and fairness carry the day. Cause and effect now come into balance. What is happening may reflect a chain of earlier choices rather than one isolated moment. Check the facts, hear the people involved, and own the part that belongs to you.' WHERE id = 'justice';
UPDATE tarot_cards SET meaning = 'A necessary pause. Release control and see the situation from a new angle. Waiting can feel uncomfortable when action is your usual answer. A changed perspective, or something you choose to release, may reveal what more pressure could not.' WHERE id = 'hanged-man';
UPDATE tarot_cards SET meaning = 'An ending clears the way for renewal. Release what has served its time. This card speaks of transition rather than a literal prediction of loss. You may have outgrown an old role, habit, or expectation; leaving it behind can still take time.' WHERE id = 'death';
UPDATE tarot_cards SET meaning = 'Balance and patience bring harmony. Blend opposites with grace. Look for what can be blended from two different approaches. Quiet progress may take the form of a sustainable habit, a calmer conversation, or a pace you can actually keep.' WHERE id = 'temperance';
UPDATE tarot_cards SET meaning = 'Beware of attachment, temptation, or a binding pattern. Recognize the chains. A short-term benefit can make a costly pattern hard to leave. Naming what you gain from it, as well as what it costs, can return a little freedom of choice.' WHERE id = 'devil';
UPDATE tarot_cards SET meaning = 'Sudden change shatters the false and reveals the truth. What falls was never meant to stand. Disruption is difficult when it shakes a plan you trusted. You do not have to find a bright side immediately; first notice what has truly changed and what remains standing.' WHERE id = 'tower';
UPDATE tarot_cards SET meaning = 'Hope, healing, and quiet inspiration renew your spirit after the storm. Hope is not a promise that everything will resolve on its own. It is room to breathe after difficulty and continue caring for what matters before the outcome is visible.' WHERE id = 'star';
UPDATE tarot_cards SET meaning = 'Illusion and uncertainty blur the way. Trust your intuition, not appearances. When facts are incomplete, memory and fear can fill the gaps with a convincing story. Slow down, notice your reaction, and separate what you feel from what you have verified.' WHERE id = 'moon';
UPDATE tarot_cards SET meaning = 'Joy, success, and radiant clarity. Everything is bright and full of life. Clarity can help you recognize your progress and share joy without minimizing it. If work remains, this renewed energy can help you meet it more openly.' WHERE id = 'sun';
UPDATE tarot_cards SET meaning = 'A call to rise, renew, and be honest with yourself. A verdict of awakening. Reviewing the past need not mean blaming yourself forever. Take the lesson, forgive what you can, and answer the call to change with a conscious choice now.' WHERE id = 'judgement';
UPDATE tarot_cards SET meaning = 'Completion and fulfillment — a cycle closes in perfect wholeness. The achievement includes the skills, relationships, and perspective you gained along the way. Honor the completion of this cycle even as a wider journey continues.' WHERE id = 'world';
UPDATE tarot_cards SET meaning = 'A spark of inspiration opens a bold creative path. An invitation, project, or new desire may make you feel more alive. This is potential rather than a guaranteed result; it needs room to experiment and commitment after the first excitement fades.' WHERE id = 'ace-of-wands';
UPDATE tarot_cards SET meaning = 'A future is taking shape through planning and a choice of direction. You can see more than one route and are beginning to ask how far you want to go. A broad view helps, but endless planning can keep you on the threshold.' WHERE id = 'two-of-wands';
UPDATE tarot_cards SET meaning = 'Early effort expands as opportunities and wider horizons come into view. What you started is beginning to draw a response beyond familiar territory. Stay open to contacts and feedback while allowing time for your earlier work to bear fruit.' WHERE id = 'three-of-wands';
UPDATE tarot_cards SET meaning = 'Stability, welcome, and shared celebration create a strong foundation. A milestone deserves celebration even when the journey is not over. Belonging and the people who helped build this moment can strengthen your next step.' WHERE id = 'four-of-wands';
UPDATE tarot_cards SET meaning = 'Competing aims create friction, noise, or a test of confidence. Many competing voices can hide the shared goal. Conflict may sharpen an idea when everyone knows what they are actually debating and can listen across differences.' WHERE id = 'five-of-wands';
UPDATE tarot_cards SET meaning = 'Recognition follows determined effort and visible progress. Your effort may finally be seen by others. Recognition can encourage you, but the value of your work remains even when no audience is watching.' WHERE id = 'six-of-wands';
UPDATE tarot_cards SET meaning = 'You hold valuable ground while pressure tests your resolve. Protecting what matters requires knowing why it matters to you. Pressure can come from several directions, yet not every challenge deserves a fight.' WHERE id = 'seven-of-wands';
UPDATE tarot_cards SET meaning = 'Events accelerate, messages arrive, and momentum clears delay. News or decisions may arrive faster than expected. Speed helps when everyone understands the direction; unclear information can turn momentum into confusion.' WHERE id = 'eight-of-wands';
UPDATE tarot_cards SET meaning = 'Resilience is strong, though past strain makes you watchful. Past strain has taught you how to protect yourself, but constant vigilance is exhausting. Judge the risk in front of you by today''s evidence as well as yesterday''s wounds.' WHERE id = 'nine-of-wands';
UPDATE tarot_cards SET meaning = 'Responsibility has become heavy and success now carries a burden. Something you once took pride in may now carry too many obligations. Your ability is real, but it does not require you to hold every task alone.' WHERE id = 'ten-of-wands';
UPDATE tarot_cards SET meaning = 'Curiosity brings a lively message, experiment, or new creative interest. A fresh idea can bring back a beginner''s excitement. You need not master everything before exploring; give yourself permission to try, adjust, and learn in practice.' WHERE id = 'page-of-wands';
UPDATE tarot_cards SET meaning = 'Passion charges ahead quickly, bringing adventure and possible impatience. The pull of something new may make you want to leave immediately. This energy serves you best when a clear aim keeps you from changing course with every passing impulse.' WHERE id = 'knight-of-wands';
UPDATE tarot_cards SET meaning = 'Warm confidence and creative independence draw others toward your vision. Your open presence can encourage others to believe in a shared vision. Confidence here does not require outshining anyone; it makes room for others to shine too.' WHERE id = 'queen-of-wands';
UPDATE tarot_cards SET meaning = 'Mature vision turns inspiration into decisive and ethical leadership. A large vision needs decisions, responsibility, and the ability to sustain a team''s energy. Lead through a clear purpose rather than pressure or ego alone.' WHERE id = 'king-of-wands';
UPDATE tarot_cards SET meaning = 'The heart opens to new affection, compassion, and emotional renewal. A meeting, a new feeling, or an inner softening may invite you to give and receive more freely. Let emotion be acknowledged before forcing it toward a particular outcome.' WHERE id = 'ace-of-cups';
UPDATE tarot_cards SET meaning = 'Mutual recognition creates partnership, attraction, or sincere agreement. The deeper promise lies in two people seeing each other clearly, beyond initial attraction. A sincere conversation, apology, or fair agreement may strengthen the bond.' WHERE id = 'two-of-cups';
UPDATE tarot_cards SET meaning = 'Friendship, community, and shared joy bring emotional support. A small gathering or timely support can remind you that joy need not be carried alone. Remember those who stood beside you before things became easier.' WHERE id = 'three-of-cups';
UPDATE tarot_cards SET meaning = 'Emotional withdrawal makes an available gift difficult to notice. When you are tired or discouraged, even a good offer may appear dull. Be honest about your present feelings before deciding that nothing around you matters.' WHERE id = 'four-of-cups';
UPDATE tarot_cards SET meaning = 'Loss draws attention to what spilled while something meaningful remains. Grief deserves to be named rather than covered with quick optimism. Even so, one loss may not tell the whole story; support or possibility may still remain nearby.' WHERE id = 'five-of-cups';
UPDATE tarot_cards SET meaning = 'Memory, innocence, or a familiar bond returns with gentle warmth. An old friend or memory may reconnect you with a sense of safety. Welcome that warmth while recognizing that the present has changed and you have changed with it.' WHERE id = 'six-of-cups';
UPDATE tarot_cards SET meaning = 'Many appealing possibilities blur the difference between vision and illusion. Each option may seem to carry a beautiful promise, but not every promise has the same foundation. Separate what you truly want from what you have imagined around it.' WHERE id = 'seven-of-cups';
UPDATE tarot_cards SET meaning = 'A once-meaningful situation no longer nourishes the heart. Leaving something once meaningful can be both sad and right for you now. Its value was real, even if your need for deeper meaning has changed.' WHERE id = 'eight-of-cups';
UPDATE tarot_cards SET meaning = 'Contentment and gratitude make a heartfelt wish feel close. You may have reached something you once wished for and deserve to enjoy it. Satisfaction lasts longer when you know where it comes from instead of rushing to the next desire.' WHERE id = 'nine-of-cups';
UPDATE tarot_cards SET meaning = 'Emotional harmony, belonging, and lasting connection surround the home. Harmony grows through repeated care and listening, not through a home without disagreement. This card evokes the freedom to be yourself among people willing to keep building together.' WHERE id = 'ten-of-cups';
UPDATE tarot_cards SET meaning = 'A tender message or intuitive discovery invites emotional openness. A tender message, unexpected feeling, or imaginative idea may catch your attention. Make room for surprise without treating every sign as a firm promise.' WHERE id = 'page-of-cups';
UPDATE tarot_cards SET meaning = 'Romance, imagination, or an ideal draws the heart forward. You may want to follow a heartfelt invitation or ideal. Sincerity gives the journey meaning, while practicality helps you see which people and plans can travel with you over time.' WHERE id = 'knight-of-cups';
UPDATE tarot_cards SET meaning = 'Deep empathy and intuition create a calm space for truth. Listening closely can help someone feel safe enough to speak. Deep empathy also means knowing which needs are yours and which sadness you cannot carry for another person.' WHERE id = 'queen-of-cups';
UPDATE tarot_cards SET meaning = 'Emotional maturity steadies strong feelings without suppressing them. Strong feelings can remain present while you choose a calm, responsible response. That steadiness can make a difficult conversation safer for everyone involved.' WHERE id = 'king-of-cups';
UPDATE tarot_cards SET meaning = 'A clean insight cuts through confusion and reveals a new truth. A new fact or honest conversation may cut through confusion. Truth can be sharp, so use it to understand and decide more clearly rather than to wound.' WHERE id = 'ace-of-swords';
UPDATE tarot_cards SET meaning = 'A guarded stalemate delays a choice that cannot remain suspended forever. You may be maintaining balance by refusing to choose, though the pressure has not gone away. Calm is useful; avoiding uncomfortable information will not make the decision disappear.' WHERE id = 'two-of-swords';
UPDATE tarot_cards SET meaning = 'A painful truth, separation, or disappointment asks to be acknowledged. Words, separation, or a broken expectation may leave a real ache. Name the hurt and seek support instead of rushing to prove that you are already fine.' WHERE id = 'three-of-swords';
UPDATE tarot_cards SET meaning = 'Rest and mental quiet are needed after pressure or conflict. After a long stretch of reacting to pressure, your mind needs room to settle. Rest is part of recovery and preparation, not proof that you have given up.' WHERE id = 'four-of-swords';
UPDATE tarot_cards SET meaning = 'Conflict may produce a hollow victory or leave trust damaged. Winning an argument may still damage trust or exhaust you. Ask what the victory costs and what boundaries would protect your self-respect.' WHERE id = 'five-of-swords';
UPDATE tarot_cards SET meaning = 'A difficult passage moves gradually toward calmer conditions. The transition may be quiet: leaving a deadlocked conversation, an old environment, or a tiring way of thinking. You need not see a perfect destination to know you are moving toward greater peace.' WHERE id = 'six-of-swords';
UPDATE tarot_cards SET meaning = 'Strategy, secrecy, or avoidance complicates the path. Keeping a plan private can sometimes protect you; evading responsibility creates a different kind of distance. Examine the motive behind a strategy before deciding to use it.' WHERE id = 'seven-of-swords';
UPDATE tarot_cards SET meaning = 'Fear and restrictive beliefs make the available options hard to see. The feeling of being trapped may be larger than the limits actually around you. As fear eases, one small option, a helpful person, or an overlooked path may become visible.' WHERE id = 'eight-of-swords';
UPDATE tarot_cards SET meaning = 'Anxiety magnifies danger in the dark and exhausts the mind. Repeating thoughts can feel fiercest when you face them alone. Separate what has happened from what you imagine might happen, and allow yourself to ask for help.' WHERE id = 'nine-of-swords';
UPDATE tarot_cards SET meaning = 'A painful cycle reaches its final limit and cannot continue unchanged. The ending may leave you drained after a situation has gone on too long. The old pattern cannot continue unchanged, but clearer boundaries can make space for gradual recovery.' WHERE id = 'ten-of-swords';
UPDATE tarot_cards SET meaning = 'Alert curiosity seeks facts, asks questions, and watches for change. Curiosity pushes you to ask questions and check details before accepting a conclusion. That alertness supports learning when it does not harden into suspicion of everyone.' WHERE id = 'page-of-swords';
UPDATE tarot_cards SET meaning = 'Focused intellect moves fast and confronts obstacles directly. A clear idea may send you forward and make you speak directly. Determination works best when you still hear new evidence and notice how your words affect others.' WHERE id = 'knight-of-swords';
UPDATE tarot_cards SET meaning = 'Clear perception and honest boundaries cut away confusion. Experience can help you see what matters among competing feelings and promises. Be direct and keep sound boundaries without losing compassion.' WHERE id = 'queen-of-swords';
UPDATE tarot_cards SET meaning = 'Reason, fairness, and disciplined judgment guide a consequential decision. A difficult decision asks for consistent standards and clear reasoning. The authority of this card comes from fairness, not merely from having the final word.' WHERE id = 'king-of-swords';
UPDATE tarot_cards SET meaning = 'A tangible opportunity offers the seed of prosperity, work, or wellbeing. A practical opening might appear as work, support, a skill, or healthier conditions. Its value depends on how it is tended over time, not only on its first appeal.' WHERE id = 'ace-of-pentacles';
UPDATE tarot_cards SET meaning = 'Several priorities move at once and require flexible balance. You may be balancing work, money, time, and personal needs at once. Flexibility keeps things moving, but a long stretch of juggling calls for clearer priorities.' WHERE id = 'two-of-pentacles';
UPDATE tarot_cards SET meaning = 'Skill grows through collaboration, feedback, and careful craftsmanship. Good work grows when each person understands their part and strengths. Specific feedback, learning a craft, and respect for quiet effort all matter here.' WHERE id = 'three-of-pentacles';
UPDATE tarot_cards SET meaning = 'Holding tightly to security can preserve resources but restrict healthy flow. Holding on to hard-won resources can feel sensible during uncertainty. When fear of loss governs every choice, both money and peace of mind can feel constrained.' WHERE id = 'four-of-pentacles';
UPDATE tarot_cards SET meaning = 'Material strain or exclusion creates worry and a sense of scarcity. Hardship can make you feel alone or undeserving of help. Practical support may still be close, even when distress makes the way toward it difficult to see.' WHERE id = 'five-of-pentacles';
UPDATE tarot_cards SET meaning = 'Resources are exchanged, raising questions of generosity, power, and fairness. Help works best when both giver and receiver retain dignity and a voice. Look at whether the exchange is balanced and what conditions come with generosity.' WHERE id = 'six-of-pentacles';
UPDATE tarot_cards SET meaning = 'Patient investment reaches a point of assessment before the next effort. You have invested effort, but results may not arrive on your preferred schedule. Review the progress and distinguish what needs more patience from what needs a new approach.' WHERE id = 'seven-of-pentacles';
UPDATE tarot_cards SET meaning = 'Focused repetition develops mastery and dependable results. Skill develops through repetition, correction, and attention to small details. The card values steady practice that others may never see, rather than a sudden leap.' WHERE id = 'eight-of-pentacles';
UPDATE tarot_cards SET meaning = 'Self-reliance and cultivated comfort reflect disciplined progress. Your present comfort may reflect many disciplined choices made earlier. Enjoy what you have built at your own pace and recognize the work behind it.' WHERE id = 'nine-of-pentacles';
UPDATE tarot_cards SET meaning = 'Long-term security grows through legacy, family, and shared foundations. The story extends beyond one person''s success to family, community, or those who follow. A durable foundation grows from thoughtful care for shared resources.' WHERE id = 'ten-of-pentacles';
UPDATE tarot_cards SET meaning = 'A practical message invites study, planning, or a grounded new venture. A practical opportunity becomes clearer when you learn its basics. Explore patiently, test it on a small scale, and notice what has lasting value.' WHERE id = 'page-of-pentacles';
UPDATE tarot_cards SET meaning = 'Reliable effort advances slowly but rarely abandons the task. Progress may feel so slow that you question whether you are moving, yet consistency is building a foundation. Reliability also needs room for rest.' WHERE id = 'knight-of-pentacles';
UPDATE tarot_cards SET meaning = 'Resourceful care creates comfort, health, and practical abundance. Safety can be created through concrete acts of care and wise use of resources. Sustainable generosity begins with remembering your own needs as well.' WHERE id = 'queen-of-pentacles';
UPDATE tarot_cards SET meaning = 'Material leadership turns experience into stable and generous stewardship. Experience can support a stable future for work, family, or community. Success means more when the people who helped build it can share in that stability.' WHERE id = 'king-of-pentacles';
UPDATE card_translations SET payload = '{"name":"El Loco","meaning":"Una página en blanco y un acto de fe: un nuevo viaje comienza con un corazón abierto. No necesitas un mapa completo antes de dar el primer paso. La curiosidad te ayuda a aprender de cada intento, mientras que un poco de preparación evita que la libertad se convierta en descuido.","advice":"Confía en el camino que tienes delante y da ese primer paso, incluso sin todas las respuestas.","yesNoMeaning":"Un nuevo comienzo rara vez conlleva una respuesta fija: el resultado depende del paso que se dé."}' WHERE card_id = 'fool' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"El Mago","meaning":"Tienes todas las herramientas que necesitas. Enfoca tu voluntad y convierte la intención en acción. Una idea se vuelve realidad cuando tu atención, tiempo y recursos disponibles apuntan hacia la misma tarea. Mira las herramientas que ya tienes a tu alcance antes de esperar otra señal.","advice":"Usa tus habilidades y recursos deliberadamente — ahora es el momento de hacerlo realidad.","yesNoMeaning":"Ya posees todo lo necesario: la energía apoya avanzar con enfoque."}' WHERE card_id = 'magician' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"La Sacerdotisa","meaning":"La sabiduría silenciosa se esconde debajo de la superficie. Escucha tu intuición y tu voz interior. El silencio puede revelar un patrón, un sentimiento que aún no puedes nombrar o información que aún falta. Observa un poco más antes de sacar todo a la luz.","advice":"Haz una pausa, ve hacia adentro y deja que tus instintos te guíen antes de actuar.","yesNoMeaning":"La respuesta está oculta bajo la superficie por ahora — confía en tu intuición en lugar de forzar un sí o no claro."}' WHERE card_id = 'high-priestess' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"La Emperatriz","meaning":"El crecimiento, la abundancia y la energía enriquecedora te rodean. Deja que florezcan la belleza y el cuidado. Una relación, un proyecto o una parte de ti puede crecer gracias a un cuidado constante. Abundancia aquí significa tener espacio para desarrollarse, no dar hasta que no te quede nada.","advice":"Sea paciente y generoso: cree con amor y deje que las cosas maduren naturalmente.","yesNoMeaning":"El crecimiento, la abundancia y la energía enriquecedora respaldan tu deseo: la respuesta es un tranquilo sí."}' WHERE card_id = 'empress' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"El Emperador","meaning":"Estructura, autoridad y liderazgo constante. Construya sobre terreno sólido con disciplina. Una estructura útil brinda a las personas la seguridad para crecer. Note la diferencia entre asumir responsabilidades y tratar de controlar cada detalle; pueden parecerse al principio.","advice":"Toma el control con un plan claro; los límites firmes traen estabilidad duradera.","yesNoMeaning":"La estructura, la autoridad y la disciplina constante respaldan un sí confiado."}' WHERE card_id = 'emperor' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"El Sumo Sacerdote","meaning":"La tradición y los buenos consejos pueden orientarte. Aprende de la experiencia de quienes vinieron antes. Un maestro, una comunidad o un método establecido pueden ofrecer un buen punto de partida. Comprende por qué funciona una tradición antes de adaptarla a tu situación.","advice":"Siga la sabiduría establecida y busque el consejo de aquellos en quienes confía.","yesNoMeaning":"La tradición y la guía confiable apuntan a un sí confiable: apóyate en lo que ya ha demostrado su valía."}' WHERE card_id = 'hierophant' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Los Enamorados","meaning":"Un vínculo significativo o una elección importante. Sigue lo que tu corazón realmente valora. La armonía duradera exige que ambas partes hablen honestamente sobre las necesidades y los límites. Si se trata de una decisión más que de un romance, pregunta qué camino refleja tus valores más profundos.","advice":"Elige con honestidad y alineación: la conexión se profundiza cuando eres sincero.","yesNoMeaning":"Tu corazón y tus valores están alineados aquí: la respuesta es sí, especialmente cuando eliges con honestidad."}' WHERE card_id = 'lovers' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"El Carro","meaning":"La fuerza de voluntad y el impulso te hacen avanzar. Mantente enfocado y prevalecerás. Los impulsos opuestos aún pueden hacerte avanzar cuando les das una dirección compartida. El progreso depende de guiar tus emociones y acciones, no simplemente de esforzarse más.","advice":"Mantén la vista en la meta y conduce con confianza a través de cada obstáculo.","yesNoMeaning":"La fuerza de voluntad y el impulso están de tu lado: un sí enfocado, siempre que te mantengas comprometido."}' WHERE card_id = 'chariot' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Fuerza","meaning":"El verdadero poder es gentil: la paciencia, el coraje y la compasión dominan cualquier desafío. La gentileza es una forma activa de coraje: puedes permanecer con el malestar sin dejar que éste decida tu respuesta. Reconozca el miedo y actúe con cuidado en lugar de esperar a que desaparezca.","advice":"Lidera con calma y fuerza; una mano suave suele ser la más fuerte.","yesNoMeaning":"El coraje gentil y la resolución paciente hacen que esto sea un sí: lidere con calma, no con fuerza."}' WHERE card_id = 'strength' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"El Ermitaño","meaning":"Es hora de dar un paso atrás y buscar la claridad interior. La soledad ahora trae respuestas más profundas. Tomar distancia puede ayudarte a escuchar tu propia voz en medio de las opiniones de otras personas. La soledad ayuda cuando conduce a la comprensión, pero también puede convertirse en una forma de evitar la conexión.","advice":"Vuelve hacia tu interior, reflexiona y deja que la tranquilidad revele lo que realmente necesitas.","yesNoMeaning":"Todavía no: la carta te pide que des un paso atrás y encuentres claridad interior antes de actuar."}' WHERE card_id = 'hermit' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Rueda de la Fortuna","meaning":"La fortuna cambia y los ciclos cambian. Lo que cambia ahora es parte de un ritmo más amplio. Es posible que esté cambiando un viejo ciclo, que trae consigo inconvenientes y posibilidades. No puedes elegir todos los eventos, pero puedes elegir qué llevar adelante y cómo prepararte para el siguiente turno.","advice":"Sigue la corriente con flexibilidad — abraza el giro, bueno o no.","yesNoMeaning":"La fortuna está cambiando: el resultado depende de cómo aproveche el cambio en lugar de un sí o un no fijo."}' WHERE card_id = 'wheel-of-fortune' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Justicia","meaning":"La verdad y la justicia prevalecen. La causa y el efecto ahora se equilibran. Lo que está sucediendo puede reflejar una cadena de decisiones anteriores más que un momento aislado. Verifique los hechos, escuche a las personas involucradas y sea dueño de la parte que le pertenece.","advice":"Actuar con honestidad y sopesar ambas partes; la balanza se estabilizará de manera justa.","yesNoMeaning":"Las balanzas aún están equilibrando: la respuesta justa depende de los hechos y de tu honestidad."}' WHERE card_id = 'justice' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"El Colgado","meaning":"Una pausa necesaria. Libera el control y mira la situación desde un nuevo ángulo. Esperar puede resultar incómodo cuando la acción es la respuesta habitual. Un cambio de perspectiva, o algo que decidas soltar, puede revelar lo que más presión no podría revelar.","advice":"Deja de empujar — entrégate al momento y permite que llegue una nueva perspectiva.","yesNoMeaning":"Primero es necesaria una pausa; forzar esto ahora sólo impediría una respuesta más clara."}' WHERE card_id = 'hanged-man' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Muerte","meaning":"Un final allana el camino para la renovación. Suelta lo que ya cumplió su ciclo. Esta carta habla de transición más que de una predicción literal de pérdida. Tal vez hayas dejado atrás un antiguo papel, hábito o expectativa; dejarlo atrás todavía puede llevar tiempo.","advice":"Déjalo ir sin arrepentimiento; una profunda transformación está abriendo una nueva puerta.","yesNoMeaning":"Un final está despejando el camino: el camino actual se está cerrando para que pueda comenzar uno nuevo."}' WHERE card_id = 'death' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Templanza","meaning":"El equilibrio y la paciencia traen armonía. Combina los opuestos con gracia. Busque lo que se puede combinar desde dos enfoques diferentes. El progreso silencioso puede tomar la forma de un hábito sostenible, una conversación más tranquila o un ritmo que realmente puedas mantener.","advice":"Muévete con moderación y mantén la calma: con pasos firmes llegas al destino.","yesNoMeaning":"El equilibrio y la paciencia traen armonía: un sí medido, dado paso firme a la vez."}' WHERE card_id = 'temperance' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"El Diablo","meaning":"Ten cuidado con el apego, la tentación o los hábitos que te atan. Reconoce las cadenas. Un beneficio a corto plazo puede hacer que sea difícil abandonar un patrón costoso. Reconocer lo que obtienes de ese hábito y lo que te cuesta puede devolverte parte de tu libertad para elegir.","advice":"Nombra lo que te retiene y reclama tu libertad: la cadena solo te ata si tú lo permites.","yesNoMeaning":"El apego o un patrón vinculante se interpone en el camino; todavía no, hasta que la cadena sea nombrada y rota."}' WHERE card_id = 'devil' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"La Torre","meaning":"El cambio repentino destruye lo falso y revela la verdad. Lo que cae nunca estuvo destinado a permanecer en pie. La sacudida puede ser difícil cuando sacude un plan en el que confiabas. No necesitas buscarle el lado positivo de inmediato; primero observa lo que realmente ha cambiado y lo que permanece en pie.","advice":"Da la bienvenida al cambio; de entre los escombros se puede construir una base más clara.","yesNoMeaning":"El cambio súbito está destrozando lo antiguo; el terreno debe asentarse antes de que un sí firme sea posible."}' WHERE card_id = 'tower' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"La Estrella","meaning":"La esperanza, la curación y la tranquila inspiración renuevan tu espíritu después de la tormenta. La esperanza no es una promesa de que todo se resolverá por sí solo. Es espacio para respirar después de las dificultades y seguir cuidando lo que importa antes de que el resultado sea visible.","advice":"Confía en la luz que tienes delante y sigue creyendo: tus deseos están al alcance.","yesNoMeaning":"La esperanza y la tranquila renovación indican que sí: confía en la luz que te espera y mantén vivo tu deseo."}' WHERE card_id = 'star' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"La Luna","meaning":"La ilusión y la incertidumbre empañan el camino. Confía en tu intuición, no en las apariencias. Cuando los hechos están incompletos, la memoria y el miedo pueden llenar los vacíos con una historia convincente. Baja el ritmo, observa tu reacción y separa lo que sientes de lo que has verificado.","advice":"Reduce la velocidad y mira más profundo; la claridad vendrá cuando la niebla se disipe.","yesNoMeaning":"La ilusión y la incertidumbre desdibujan el camino: la respuesta no está clara hasta que se mira más allá de las apariencias."}' WHERE card_id = 'moon' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"El Sol","meaning":"Alegría, éxito y claridad radiante. Todo es luminoso y lleno de vida. La claridad puede ayudarte a reconocer tu progreso y compartir la alegría sin minimizarla. Si queda trabajo, esta energía renovada puede ayudarte a afrontarlo más abiertamente.","advice":"Celebre y brille: la energía positiva atrae los resultados que desea.","yesNoMeaning":"La alegría y la claridad radiante confirman un sí brillante: todo está funcionando a tu favor."}' WHERE card_id = 'sun' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Juicio","meaning":"Un llamado a levantarte, renovarte y ser honesto contigo mismo. Un veredicto de despertar. Revisar el pasado no tiene por qué significar culparse a uno mismo para siempre. Aprende la lección, perdona lo que puedas y responde al llamado a cambiar con una elección consciente ahora.","advice":"Responde al llamado con valentía; perdona el pasado y entra en tu próximo capítulo.","yesNoMeaning":"Un llamado a levantarse y renovarse, sí, especialmente una vez que perdonas el pasado y respondes con honestidad."}' WHERE card_id = 'judgement' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"El Mundo","meaning":"Finalización y cumplimiento: un ciclo se cierra en perfecta totalidad. El logro incluye las habilidades, las relaciones y la perspectiva que adquirió a lo largo del camino. Honren la finalización de este ciclo incluso mientras continúa un viaje más amplio.","advice":"Celebra lo que has logrado; la puerta está abierta a un mundo más amplio.","yesNoMeaning":"La plenitud y la plenitud marcan esto como un sí cumplido: el ciclo se cierra a tu favor."}' WHERE card_id = 'world' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"As de bastos","meaning":"Una chispa de inspiración abre un camino creativo audaz. Una invitación, un proyecto o un nuevo deseo pueden hacerte sentir más vivo. Este es un resultado potencial más que garantizado; necesita espacio para experimentar y compromiso una vez que se desvanece el primer entusiasmo.","advice":"Comienza mientras la energía está fresca y dale a la idea un primer paso real.","yesNoMeaning":"El As de Bastos se inclina hacia sí: comienza mientras la energía es fresca y da a la idea un primer paso real."}' WHERE card_id = 'ace-of-wands' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Dos de Bastos","meaning":"Un futuro está tomando forma a través de la planificación y la elección de dirección. Puedes ver más de una ruta y empiezas a preguntar hasta dónde quieres llegar. Una visión amplia ayuda, pero una planificación interminable puede mantenerte en el umbral.","advice":"Mire más allá de lo que le resulta familiar y luego comprométase con el camino que tiene espacio para crecer.","yesNoMeaning":"El Dos de Bastos sigue siendo condicional: mira más allá de lo que es familiar, luego comprométete con el camino con espacio para crecer."}' WHERE card_id = 'two-of-wands' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Tres de Bastos","meaning":"El esfuerzo inicial se expande a medida que aparecen oportunidades y horizontes más amplios. Lo que empezaste está empezando a generar una respuesta más allá del territorio familiar. Mantente abierto a nuevos contactos y comentarios mientras das tiempo a que tu trabajo dé frutos.","advice":"Continúe construyendo y prepárese para encontrar la respuesta que atrae su trabajo.","yesNoMeaning":"El Tres de Bastos se inclina hacia sí: sigue construyendo y estate preparado para recibir la respuesta que atrae tu trabajo."}' WHERE card_id = 'three-of-wands' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"cuatro de bastos","meaning":"La estabilidad, la bienvenida y la celebración compartida crean una base sólida. Un hito merece celebración incluso cuando el viaje no ha terminado. La pertenencia y las personas que ayudaron a construir este momento pueden fortalecer tu siguiente paso.","advice":"Marque el hito y deje que las personas que lo apoyen lo compartan.","yesNoMeaning":"El Cuatro de Bastos se inclina hacia sí: marca el hito y deja que las personas que apoyan lo compartan."}' WHERE card_id = 'four-of-wands' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"cinco de bastos","meaning":"Los objetivos en competencia crean fricción, ruido o una prueba de confianza. Muchas voces en competencia pueden ocultar el objetivo compartido. El conflicto puede agudizar una idea cuando todos saben lo que realmente están debatiendo y pueden escuchar a pesar de las diferencias.","advice":"Convierte la rivalidad en práctica útil y rechaza el conflicto que no tiene propósito.","yesNoMeaning":"El Cinco de Bastos sigue siendo condicional: convierte la rivalidad en práctica útil y rechaza el conflicto que no tiene propósito."}' WHERE card_id = 'five-of-wands' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Seis de Bastos","meaning":"El reconocimiento sigue a un esfuerzo decidido y un progreso visible. Quizá los demás por fin estén viendo tu esfuerzo. El reconocimiento puede animarte, pero el valor de tu trabajo permanece incluso cuando no hay audiencia mirando.","advice":"Acepte el estímulo, pero mantenga su confianza ligada al trabajo honesto.","yesNoMeaning":"El Seis de Bastos se inclina hacia el sí: acepta el estímulo, pero mantiene tu confianza ligada al trabajo honesto."}' WHERE card_id = 'six-of-wands' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Siete de Bastos","meaning":"Mantienes un terreno valioso mientras la presión pone a prueba tu determinación. Proteger lo que importa requiere saber por qué es importante para ti. La presión puede provenir de varias direcciones, pero no todos los desafíos merecen una pelea.","advice":"Defiende lo que importa con límites claros en lugar de luchar contra todos los desafíos.","yesNoMeaning":"El Siete de Bastos se inclina hacia el sí: defiende lo que importa con límites claros en lugar de luchar contra cada desafío."}' WHERE card_id = 'seven-of-wands' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Ocho de Bastos","meaning":"Los acontecimientos se aceleran, llegan mensajes y el impulso elimina los retrasos. Las noticias o decisiones pueden llegar más rápido de lo esperado. La velocidad ayuda cuando todos entienden la dirección; La información poco clara puede convertir el impulso en confusión.","advice":"Actúe con prontitud y mantenga la comunicación directa mientras el camino esté abierto.","yesNoMeaning":"El Ocho de Bastos se inclina hacia sí: actúa con prontitud y mantén la comunicación directa mientras el camino esté abierto."}' WHERE card_id = 'eight-of-wands' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Nueve de Bastos","meaning":"La resiliencia es fuerte, aunque las tensiones pasadas te hacen estar alerta. Las tensiones del pasado te han enseñado cómo protegerte, pero la vigilancia constante es agotadora. Evalúa el riesgo que tienes delante con los hechos de hoy, no solo con las heridas de ayer.","advice":"Protege tu energía y da el siguiente paso sin esperar que cada herida se repita.","yesNoMeaning":"El Nueve de Bastos permanece condicional: protege tu energía y da el siguiente paso sin esperar que cada herida se repita."}' WHERE card_id = 'nine-of-wands' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Diez de Bastos","meaning":"La responsabilidad se ha vuelto pesada y el éxito ahora conlleva una carga. Algo de lo que antes se enorgullecía ahora puede conllevar demasiadas obligaciones. Tu habilidad es real, pero no requiere que realices todas las tareas solo.","advice":"Delega, simplifica y deja de lado el trabajo que ya no es tuyo.","yesNoMeaning":"El Diez de Bastos dice que no: delega, simplifica y deja de lado el trabajo que ya no es realmente tuyo."}' WHERE card_id = 'ten-of-wands' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Sota de Bastos","meaning":"La curiosidad trae un mensaje animado, un experimento o un nuevo interés creativo. Una nueva idea puede devolverle el entusiasmo a un principiante. No es necesario dominarlo todo antes de explorar; Date permiso para intentar, adaptarte y aprender en la práctica.","advice":"Explora con valentía y deja que la energía del principiante te enseñe a través de la acción.","yesNoMeaning":"El Paje de Bastos se inclina hacia sí: explora con coraje y deja que la energía de principiante te enseñe a través de la acción."}' WHERE card_id = 'page-of-wands' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Caballero de Bastos","meaning":"La pasión avanza rápidamente, trayendo aventura y posible impaciencia. La atracción por algo nuevo puede hacer que quieras irte inmediatamente. Esta energía te resulta más útil cuando un objetivo claro te impide cambiar de rumbo con cada impulso que pasa.","advice":"Usa el impulso, pero elige una dirección antes de que la velocidad disperse tu esfuerzo.","yesNoMeaning":"El Caballero de Bastos sigue siendo condicional: usa el impulso, pero elige una dirección antes de que la velocidad disperse tu esfuerzo."}' WHERE card_id = 'knight-of-wands' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"reina de bastos","meaning":"La cálida confianza y la independencia creativa atraen a otros hacia tu visión. Tu actitud abierta puede animar a otros a creer en una visión compartida. La confianza aquí no requiere eclipsar a nadie; deja espacio para que otros también brillen.","advice":"Confía en tu presencia, anima a los demás y no reduzcas tu ambición.","yesNoMeaning":"La Reina de Bastos se inclina hacia el sí: confía en tu presencia, anima a los demás y no reduzcas tu ambición."}' WHERE card_id = 'queen-of-wands' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"rey de bastos","meaning":"La visión madura convierte la inspiración en un liderazgo decisivo y ético. Una visión amplia necesita decisiones, responsabilidad y la capacidad de sostener la energía de un equipo. Lidera a través de un propósito claro en lugar de presión o ego únicamente.","advice":"Lidera desde un propósito más amplio y da a otros espacio para contribuir.","yesNoMeaning":"El Rey de Bastos se inclina al sí: lidera desde un propósito más grande y da espacio a los demás para contribuir."}' WHERE card_id = 'king-of-wands' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"As de copas","meaning":"El corazón se abre a nuevos afectos, compasión y renovación emocional. Un encuentro, un nuevo sentimiento o un ablandamiento interior pueden invitarte a dar y recibir más libremente. Dejemos que se reconozca la emoción antes de forzarla hacia un resultado particular.","advice":"Reciba el sentimiento con honestidad y deje que la atención fluya sin forzar un resultado.","yesNoMeaning":"El As de Copas se inclina por el sí: recibe el sentimiento honestamente y deja que el cuidado fluya sin forzar un resultado."}' WHERE card_id = 'ace-of-cups' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Dos de Copas","meaning":"El reconocimiento mutuo crea asociación, atracción o acuerdo sincero. La promesa más profunda reside en que dos personas se vean claramente, más allá de la atracción inicial. Una conversación sincera, una disculpa o un acuerdo justo pueden fortalecer el vínculo.","advice":"Conoce a la otra persona como a un igual y habla desde el corazón.","yesNoMeaning":"El Dos de Copas se inclina hacia el sí: encuentra a la otra persona como un igual y habla desde el corazón."}' WHERE card_id = 'two-of-cups' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Tres de Copas","meaning":"La amistad, la comunidad y la alegría compartida brindan apoyo emocional. Una pequeña reunión o un apoyo oportuno pueden recordarte que la alegría no debe llevarse sola. Recuerda a quienes estuvieron a tu lado antes de que las cosas se volvieran más fáciles.","advice":"Celebren juntos y recuerden quién realmente aparece por ustedes.","yesNoMeaning":"El Tres de Copas inclina hacia el sí: celebren juntos y recuerden quién realmente se presenta por ustedes."}' WHERE card_id = 'three-of-cups' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Cuatro de Copas","meaning":"El retraimiento emocional hace que sea difícil notar un regalo disponible. Cuando estás cansado o desanimado, incluso una buena oferta puede parecer aburrida. Sé sincero con lo que sientes ahora antes de decidir que nada a tu alrededor importa.","advice":"Haga una pausa en la comparación y observe nuevamente lo que se ofrece silenciosamente.","yesNoMeaning":"El Cuatro de Copas se inclina hacia no: pausa la comparación y observa de nuevo lo que se ofrece silenciosamente."}' WHERE card_id = 'four-of-cups' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Cinco de Copas","meaning":"La pérdida llama la atención sobre lo que se derramó mientras queda algo significativo. El dolor merece ser nombrado en lugar de cubrirlo con un rápido optimismo. Aun así, es posible que una pérdida no cuente toda la historia; El apoyo o la posibilidad aún pueden permanecer cerca.","advice":"Honre la decepción y luego recurra al apoyo que todavía está presente.","yesNoMeaning":"El Cinco de Copas se inclina hacia no: honra la decepción y luego vuelve tu atención hacia el apoyo que aún está presente."}' WHERE card_id = 'five-of-cups' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Seis de Copas","meaning":"El recuerdo, la inocencia o un vínculo familiar regresan con suave calidez. Un viejo amigo o un recuerdo pueden reconectarte con una sensación de seguridad. Dale la bienvenida a esa calidez reconociendo al mismo tiempo que el presente ha cambiado y tú has cambiado con él.","advice":"Da la bienvenida a la bondad del pasado sin pretender que debes vivir allí de nuevo.","yesNoMeaning":"El Seis de Copas se inclina hacia el sí: da la bienvenida a la bondad del pasado sin pretender que debes vivir allí nuevamente."}' WHERE card_id = 'six-of-cups' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Siete de Copas","meaning":"Muchas posibilidades atractivas desdibujan la diferencia entre visión e ilusión. Puede parecer que cada opción conlleva una hermosa promesa, pero no todas las promesas tienen el mismo fundamento. Separa lo que realmente quieres de lo que has imaginado a su alrededor.","advice":"Limite las opciones y compare un sueño con la realidad antes de comprometerse.","yesNoMeaning":"El Siete de Copas todavía no está claro: reduce las opciones y prueba un sueño contra la realidad antes de comprometerte."}' WHERE card_id = 'seven-of-cups' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Ocho de Copas","meaning":"Una situación que alguna vez fue significativa ya no nutre el corazón. Dejar algo que alguna vez fue significativo puede doler y, aun así, ser lo adecuado para ti ahora. Aquello tuvo valor, incluso si tu necesidad de un significado más profundo había cambiado.","advice":"Vete con honestidad y avanza hacia la satisfacción más profunda que ahora necesitas.","yesNoMeaning":"El Ocho de Copas se inclina hacia no: vete con honestidad y avanza hacia la realización más profunda que ahora necesitas."}' WHERE card_id = 'eight-of-cups' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Nueve de Copas","meaning":"La alegría y la gratitud hacen que un deseo sincero se sienta cercano. Es posible que hayas alcanzado algo que alguna vez deseaste y mereces disfrutarlo. La satisfacción dura más cuando sabes de dónde viene en lugar de apresurarte hacia el siguiente deseo.","advice":"Disfruta lo que hay aquí y pregúntate si el deseo también sirve a tus valores más profundos.","yesNoMeaning":"El Nueve de Copas se inclina al sí: disfruta lo que está aquí y pregunta si el deseo también sirve a tus valores más profundos."}' WHERE card_id = 'nine-of-cups' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Diez de Copas","meaning":"La armonía emocional, la pertenencia y la conexión duradera rodean el hogar. La armonía crece a través del cuidado y la escucha repetidos, no a través de un hogar sin desacuerdos. Esta carta evoca la libertad de ser uno mismo entre personas dispuestas a seguir construyendo juntas.","advice":"Fomentar los vínculos que hacen que la alegría sea sostenible y compartida.","yesNoMeaning":"El Diez de Copas se inclina hacia el sí: cultiva los lazos que hacen que la alegría sea sostenible y compartida."}' WHERE card_id = 'ten-of-cups' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Sota de Copas","meaning":"Un mensaje tierno o un descubrimiento intuitivo invita a la apertura emocional. Un mensaje tierno, un sentimiento inesperado o una idea imaginativa pueden llamar tu atención. Deje espacio para la sorpresa sin tratar cada señal como una promesa firme.","advice":"Mantente curioso sobre la sensación y responde con sinceridad en lugar de suponer.","yesNoMeaning":"El Paje de Copas permanece condicional: mantente curioso sobre el sentimiento y responde con sinceridad en lugar de suposiciones."}' WHERE card_id = 'page-of-cups' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Caballero de Copas","meaning":"El romance, la imaginación o un ideal atraen el corazón. Quizás quieras seguir una invitación o un ideal sincero. La sinceridad le da sentido al viaje, mientras que la practicidad te ayuda a ver qué personas y planes pueden viajar contigo a lo largo del tiempo.","advice":"Siga la invitación, pero mantenga un pie en la tierra a medida que se desarrollen las promesas.","yesNoMeaning":"El Caballero de Copas se inclina al sí: sigue la invitación, pero mantén un pie en la tierra mientras se desarrollan las promesas."}' WHERE card_id = 'knight-of-cups' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"reina de copas","meaning":"La empatía y la intuición profundas crean un espacio tranquilo para la verdad. Escuchar atentamente puede ayudar a que alguien se sienta lo suficientemente seguro como para hablar. La empatía profunda también significa saber qué necesidades son las tuyas y qué tristeza no puedes cargar con otra persona.","advice":"Escuche con compasión mientras preserva los límites que mantienen la atención saludable.","yesNoMeaning":"La Reina de Copas se inclina hacia el sí: escucha con compasión mientras preservas los límites que mantienen el cuidado saludable."}' WHERE card_id = 'queen-of-cups' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"rey de copas","meaning":"La madurez emocional estabiliza los sentimientos fuertes sin reprimirlos. Los sentimientos fuertes pueden permanecer presentes mientras eliges una respuesta tranquila y responsable. Esa firmeza puede hacer que una conversación difícil sea más segura para todos los involucrados.","advice":"Responda con compasión y dominio propio, especialmente cuando los demás sean reactivos.","yesNoMeaning":"El Rey de Copas se inclina hacia sí: responde con compasión y autodominio, especialmente cuando otros son reactivos."}' WHERE card_id = 'king-of-cups' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"As de espadas","meaning":"Una visión clara rompe la confusión y revela una nueva verdad. Un hecho nuevo o una conversación honesta pueden eliminar la confusión. La verdad puede ser aguda, así que úsala para comprender y decidir con mayor claridad en lugar de herir.","advice":"Nombra el problema claramente y utiliza la claridad al servicio de una decisión justa.","yesNoMeaning":"El As de Espadas se inclina hacia sí: nombra el problema claramente y usa la claridad al servicio de una decisión justa."}' WHERE card_id = 'ace-of-swords' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Dos de Espadas","meaning":"Un cauteloso estancamiento retrasa una elección que no puede permanecer suspendida para siempre. Es posible que esté manteniendo el equilibrio al negarse a elegir, aunque la presión no ha desaparecido. La calma es útil; evitar información incómoda no hará que la decisión desaparezca.","advice":"Quítese la venda de los ojos con cuidado, recopile el dato que falta y decida desde el equilibrio.","yesNoMeaning":"El Dos de Espadas aún no está claro: quita la venda suavemente, reúne el hecho que falta y decide desde el equilibrio."}' WHERE card_id = 'two-of-swords' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Tres de Espadas","meaning":"Una verdad dolorosa, una separación o una decepción piden ser reconocidas. Las palabras, la separación o una expectativa rota pueden dejar un verdadero dolor. Nombra el dolor y busca apoyo en lugar de apresurarte a demostrar que ya estás bien.","advice":"Deja que el sentimiento te atraviese y evita convertir el dolor en una historia permanente.","yesNoMeaning":"El Tres de Espadas dice no: deja que el sentimiento pase por ti y evita convertir el dolor en una historia permanente."}' WHERE card_id = 'three-of-swords' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"cuatro de espadas","meaning":"Se necesita descanso y tranquilidad mental después de una presión o un conflicto. Después de un largo período de reacción a la presión, tu mente necesita espacio para calmarse. El descanso es parte de la recuperación y la preparación, no una prueba de que te has rendido.","advice":"Haga una pausa antes de responder; la recuperación es productiva cuando restablece el pensamiento claro.","yesNoMeaning":"El Cuatro de Espadas se inclina hacia no: pausa antes de responder; la recuperación es productiva cuando restaura un pensamiento claro."}' WHERE card_id = 'four-of-swords' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Cinco de Espadas","meaning":"El conflicto puede producir una victoria vacía o dañar la confianza. Ganar una discusión aún puede dañar la confianza o agotarte. Pregúntate cuánto cuesta esa victoria y qué límites protegerían tu autoestima.","advice":"Elija la dignidad antes que ganar y aléjese de tácticas que cuestan demasiado.","yesNoMeaning":"El Cinco de Espadas se inclina hacia no: elige la dignidad sobre la victoria y aléjate de tácticas que cuestan demasiado."}' WHERE card_id = 'five-of-swords' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Seis de Espadas","meaning":"Un pasaje difícil avanza gradualmente hacia condiciones más tranquilas. La transición puede ser silenciosa: salir de una conversación estancada, de un entorno antiguo o de una forma de pensar agotadora. No es necesario que veas un destino perfecto para saber que estás avanzando hacia una mayor paz.","advice":"Toma lo que has aprendido, acepta apoyo y sigue alejándote del caos.","yesNoMeaning":"El Seis de Espadas se inclina hacia el sí: toma lo que has aprendido, acepta apoyo y sigue alejándote de la agitación."}' WHERE card_id = 'six-of-swords' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Siete de Espadas","meaning":"La estrategia, el secreto o la evasión complican el camino. Mantener un plan privado a veces puede protegerlo; evadir la responsabilidad crea un tipo diferente de distancia. Examine el motivo detrás de una estrategia antes de decidir utilizarla.","advice":"Actuar con inteligencia pero con transparencia; Los atajos que traicionan la confianza volverán en forma de problemas.","yesNoMeaning":"El Siete de Espadas se inclina hacia el no: actúa con astucia pero de manera transparente; los atajos que traicionan la confianza regresarán como problemas."}' WHERE card_id = 'seven-of-swords' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Ocho de espadas","meaning":"El miedo y las creencias restrictivas hacen que sea difícil ver las opciones disponibles. La sensación de estar atrapado puede ser mayor que los límites que realmente te rodean. A medida que el miedo disminuye, una pequeña opción, una persona útil o un camino pasado por alto pueden hacerse visibles.","advice":"Cuestiona el pensamiento que dice que estás atrapado y realiza una pequeña acción liberadora.","yesNoMeaning":"El Ocho de Espadas se inclina hacia no: cuestiona el pensamiento que dice que estás atrapado y da una pequeña acción liberadora."}' WHERE card_id = 'eight-of-swords' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Nueve de espadas","meaning":"La ansiedad magnifica el peligro en la oscuridad y agota la mente. Los pensamientos repetidos pueden resultar más feroces cuando los enfrentas solo. Separa lo que ha sucedido de lo que imaginas que podría suceder y permítete pedir ayuda.","advice":"Saque el miedo a la luz del día, busque apoyo y separe los hechos de los resultados imaginados.","yesNoMeaning":"El Nueve de Espadas se inclina hacia no: trae el miedo a la luz del día, busca apoyo y separa los hechos de los resultados imaginados."}' WHERE card_id = 'nine-of-swords' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Diez de Espadas","meaning":"Un ciclo doloroso llega a su límite final y no puede continuar sin cambios. El final puede dejarte agotado después de que una situación haya durado demasiado. El patrón anterior ya no puede seguir igual, pero unos límites más claros pueden dejar espacio para una recuperación gradual.","advice":"Acepta el final, protege tu recuperación y permite que surja un comienzo diferente.","yesNoMeaning":"El Diez de Espadas advierte: acepta el final, protege tu recuperación y permite que emerja un nuevo comienzo."}' WHERE card_id = 'ten-of-swords' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Sota de espadas","meaning":"La curiosidad alerta busca hechos, hace preguntas y observa cambios. La curiosidad te empuja a hacer preguntas y comprobar detalles antes de aceptar una conclusión. Ese estado de alerta apoya el aprendizaje cuando no se convierte en sospecha de todos.","advice":"Investigue detenidamente y hable con precisión en lugar de reaccionar a cada señal.","yesNoMeaning":"El Paje de Espadas permanece condicional: investiga cuidadosamente y habla con precisión en lugar de reaccionar a cada señal."}' WHERE card_id = 'page-of-swords' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Caballero de espadas","meaning":"El intelecto enfocado se mueve rápido y enfrenta los obstáculos directamente. Una idea clara puede hacerte avanzar y hacerte hablar directamente. La determinación funciona mejor cuando aún escuchas nueva evidencia y notas cómo tus palabras afectan a los demás.","advice":"Avanza con valentía, pero lo suficientemente lento como para escuchar lo que tu certeza podría pasar por alto.","yesNoMeaning":"El Caballero de Espadas sigue siendo condicional: avanza con coraje, pero lo suficientemente despacio como para escuchar lo que tu certeza podría pasar por alto."}' WHERE card_id = 'knight-of-swords' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"reina de espadas","meaning":"La percepción clara y los límites honestos eliminan la confusión. La experiencia puede ayudarle a ver lo que importa entre los sentimientos y las promesas en competencia. Sea directo y mantenga límites sólidos sin perder la compasión.","advice":"Di lo que es verdadero con compasión y deja que la experiencia te afile, no te endurezca.","yesNoMeaning":"La Reina de Espadas se inclina hacia el sí: di lo que es verdad con compasión y deja que la experiencia te agudice, no te endurezca."}' WHERE card_id = 'queen-of-swords' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"rey de espadas","meaning":"La razón, la justicia y el juicio disciplinado guían una decisión importante. Una decisión difícil requiere estándares consistentes y un razonamiento claro. La autoridad de esta carta proviene de la justicia, no simplemente de tener la última palabra.","advice":"Usa evidencia, define el estándar y mantén el sesgo personal fuera del veredicto.","yesNoMeaning":"El Rey de Espadas se inclina al sí: usa evidencia, define el estándar y mantén el sesgo personal fuera del veredicto."}' WHERE card_id = 'king-of-swords' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"As de Oros","meaning":"Una oportunidad tangible ofrece la semilla de la prosperidad, el trabajo o el bienestar. Una apertura práctica puede aparecer como trabajo, apoyo, una habilidad o condiciones más saludables. Su valor depende de cómo lo cultives con el tiempo, no solo de lo atractivo que parezca al principio.","advice":"Fundamente la oportunidad en un plan práctico y cuídela constantemente.","yesNoMeaning":"El As de Oros se inclina hacia sí: cimenta la oportunidad en un plan práctico y cuídala de manera constante."}' WHERE card_id = 'ace-of-pentacles' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Dos de Pentáculos","meaning":"Varias prioridades cambian a la vez y requieren un equilibrio flexible. Es posible que esté equilibrando trabajo, dinero, tiempo y necesidades personales al mismo tiempo. La flexibilidad mantiene las cosas en movimiento, pero un largo período de malabarismo exige prioridades más claras.","advice":"Ajusta el ritmo, protege lo esencial y evita prometer más de lo que puedes cumplir.","yesNoMeaning":"El Dos de Pentáculos sigue siendo condicional: ajusta el ritmo, protege lo esencial y evita prometer más de lo que puedes cargar."}' WHERE card_id = 'two-of-pentacles' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Tres de Pentáculos","meaning":"La habilidad crece a través de la colaboración, la retroalimentación y el trabajo cuidadoso. El buen trabajo crece cuando cada persona comprende su parte y sus fortalezas. Aquí son importantes los comentarios específicos, el aprendizaje de un oficio y el respeto por el esfuerzo silencioso.","advice":"Contribuya con su fuerza, respete su experiencia y construya un estándar compartido.","yesNoMeaning":"El Tres de Pentáculos se inclina a sí: contribuye con tu fuerza, respeta la experiencia y construye según un estándar compartido."}' WHERE card_id = 'three-of-pentacles' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Cuatro de Oros","meaning":"Mantener estrictamente la seguridad puede preservar los recursos pero restringir el flujo saludable. Aferrarse a los recursos ganados con tanto esfuerzo puede resultar sensato durante la incertidumbre. Cuando el miedo a perder gobierna todas las decisiones, tanto el dinero como la tranquilidad pueden sentirse limitados.","advice":"Protege lo que importa sin dejar que el miedo tome todas las decisiones por ti.","yesNoMeaning":"El Cuatro de Oros sigue siendo condicional: protege lo que importa sin dejar que el miedo tome todas tus decisiones."}' WHERE card_id = 'four-of-pentacles' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Cinco de Oros","meaning":"La tensión material o la exclusión crean preocupación y una sensación de escasez. Las dificultades pueden hacerte sentir solo o que no mereces ayuda. El apoyo práctico todavía puede estar cerca, incluso cuando la angustia hace que sea difícil ver el camino hacia él.","advice":"Pida ayuda práctica y observe la puerta que las dificultades han hecho fácil pasar por alto.","yesNoMeaning":"El Cinco de Oros se inclina hacia no: pide ayuda práctica y nota la puerta que la adversidad ha hecho fácil de pasar por alto."}' WHERE card_id = 'five-of-pentacles' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Seis de Pentáculos","meaning":"Se intercambian recursos, lo que plantea cuestiones de generosidad, poder y justicia. La ayuda funciona mejor cuando tanto el donante como el receptor conservan la dignidad y la voz. Observa si el intercambio es equilibrado y qué condiciones conlleva la generosidad.","advice":"Dar o recibir con términos claros para que el apoyo preserve la dignidad de ambas partes.","yesNoMeaning":"El Seis de Oros se inclina hacia el sí: da o recibe con condiciones claras para que el apoyo preserve la dignidad de ambos lados."}' WHERE card_id = 'six-of-pentacles' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Siete de Pentáculos","meaning":"La inversión paciente llega a un punto de evaluación antes del siguiente esfuerzo. Ha invertido esfuerzo, pero es posible que los resultados no lleguen en el cronograma preferido. Revisar el progreso y distinguir lo que necesita más paciencia de lo que necesita un nuevo enfoque.","advice":"Revisa lo que está creciendo, mejora el método y permite tiempo a los resultados valiosos.","yesNoMeaning":"El Siete de Oros sigue siendo condicional: revisa lo que está creciendo, mejora el método y permite tiempo para resultados valiosos."}' WHERE card_id = 'seven-of-pentacles' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Ocho de Oros","meaning":"La repetición enfocada desarrolla dominio y resultados confiables. La habilidad se desarrolla mediante la repetición, la corrección y la atención a los pequeños detalles. La carta valora la práctica constante que otros tal vez nunca vean, en lugar de un salto repentino.","advice":"Practique la habilidad esencial, agradezca las correcciones y deje que la calidad se acumule.","yesNoMeaning":"El Ocho de Oros se inclina hacia sí: practica la habilidad esencial, acepta la corrección y deja que la calidad se acumule."}' WHERE card_id = 'eight-of-pentacles' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Nueve de Oros","meaning":"La autosuficiencia y el confort cultivado reflejan un progreso disciplinado. Su comodidad actual puede reflejar muchas decisiones disciplinadas tomadas anteriormente. Disfruta de lo que has construido a tu propio ritmo y reconoce el trabajo que hay detrás.","advice":"Disfruta de lo que has construido y mantén la independencia conectada con la gratitud.","yesNoMeaning":"El Nueve de Oros se inclina hacia sí: disfruta lo que has construido y mantén la independencia conectada con la gratitud."}' WHERE card_id = 'nine-of-pentacles' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Diez de Oros","meaning":"La seguridad a largo plazo crece a través del legado, la familia y las fundaciones compartidas. La historia se extiende más allá del éxito de una persona y llega a la familia, la comunidad o quienes le siguen. Una base duradera surge del cuidado cuidadoso de los recursos compartidos.","advice":"Planifique más allá de la victoria inmediata y proteja lo que pueda ayudar a otros con el tiempo.","yesNoMeaning":"El Diez de Oros se inclina hacia el sí: planifica más allá de la victoria inmediata y protege lo que puede apoyar a otros con el tiempo."}' WHERE card_id = 'ten-of-pentacles' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Sota de Oros","meaning":"Un mensaje práctico invita al estudio, la planificación o un nuevo emprendimiento fundamentado. Una oportunidad práctica se vuelve más clara cuando aprendes sus conceptos básicos. Explora con paciencia, prueba a pequeña escala y observa qué tiene valor duradero.","advice":"Aprenda los conceptos básicos, defina la siguiente tarea y demuestre la idea mediante un trabajo constante.","yesNoMeaning":"El Paje de Oros se inclina hacia sí: aprende lo básico, define la siguiente tarea y prueba la idea mediante trabajo constante."}' WHERE card_id = 'page-of-pentacles' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Caballero de Oros","meaning":"El esfuerzo confiable avanza lentamente pero rara vez abandona la tarea. El progreso puede parecer tan lento que te preguntas si de verdad estás avanzando, pero la constancia está construyendo una base. La fiabilidad también necesita espacio para descansar.","advice":"Mantenga la rutina honesta y consistente; El progreso importa más que la emoción.","yesNoMeaning":"El Caballero de Oros se inclina al sí: mantén la rutina honesta y consistente; el progreso importa más que la emoción."}' WHERE card_id = 'knight-of-pentacles' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Reina de Oros","meaning":"El cuidado ingenioso crea comodidad, salud y abundancia práctica. La seguridad se puede crear mediante actos concretos de cuidado y uso racional de los recursos. La generosidad sostenible comienza con recordar también tus propias necesidades.","advice":"Cuide a las personas y los planes de manera que sigan siendo sostenibles para usted.","yesNoMeaning":"La Reina de Oros se inclina hacia el sí: nutre a las personas y los planes de maneras que sigan siendo sostenibles para ti."}' WHERE card_id = 'queen-of-pentacles' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"Rey de Oros","meaning":"El liderazgo material convierte la experiencia en una mayordomía estable y generosa. La experiencia puede respaldar un futuro estable para el trabajo, la familia o la comunidad. El éxito significa más cuando las personas que ayudaron a construirlo pueden compartir esa estabilidad.","advice":"Tome la decisión acertada a largo plazo y utilice el éxito de manera responsable.","yesNoMeaning":"El Rey de Oros se inclina hacia sí: toma la decisión sólida a largo plazo y usa el éxito responsablemente."}' WHERE card_id = 'king-of-pentacles' AND locale = 'es-419';
UPDATE card_translations SET payload = '{"name":"O Louco","meaning":"Uma página em branco e um salto de fé – uma nova jornada começa com o coração aberto. Você não precisa de um mapa completo antes de dar o primeiro passo. A curiosidade ajuda você a aprender com cada tentativa, enquanto um pouco de preparação evita que a liberdade se transforme em descuido.","advice":"Confie no caminho à sua frente e dê o primeiro passo, mesmo sem todas as respostas.","yesNoMeaning":"Um novo começo raramente traz uma resposta fixa — o resultado depende do passo que você dá."}' WHERE card_id = 'fool' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"O Mágico","meaning":"Você possui todas as ferramentas que precisa. Concentre sua vontade e transforme intenção em ação. Uma ideia se torna real quando sua atenção, tempo e recursos disponíveis apontam para a mesma tarefa. Observe as ferramentas que já estão ao seu alcance antes de esperar por outro sinal.","advice":"Use suas habilidades e recursos deliberadamente — agora é o momento de fazer acontecer.","yesNoMeaning":"Você já possui tudo o que é necessário — a energia apoia avançar com foco."}' WHERE card_id = 'magician' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"A Sacerdotisa","meaning":"A sabedoria silenciosa se esconde abaixo da superfície. Ouça sua intuição e voz interior. O silêncio pode revelar um padrão, um sentimento que você ainda não consegue nomear ou uma informação que ainda está faltando. Observe um pouco mais antes de trazer tudo à luz.","advice":"Faça uma pausa, volte-se para dentro e deixe seus instintos guiarem você antes de agir.","yesNoMeaning":"A resposta está escondida abaixo da superfície por enquanto — confie na sua intuição em vez de forçar um sim ou não claro."}' WHERE card_id = 'high-priestess' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"A Imperatriz","meaning":"Crescimento, abundância e energia nutritiva cercam você. Deixe a beleza e o cuidado florescerem. Um relacionamento, projeto ou parte de você pode crescer através de cuidados constantes. Abundância aqui significa ter espaço para se desenvolver, não dar até que não tenha mais nada.","advice":"Seja paciente e generoso — crie com amor e deixe as coisas amadurecerem naturalmente.","yesNoMeaning":"Crescimento, abundância e energia de cuidado apoiam seu desejo — a resposta é um sim silencioso."}' WHERE card_id = 'empress' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"O Imperador","meaning":"Estrutura, autoridade e liderança estável. Construa em terreno sólido com disciplina. Uma estrutura útil dá às pessoas segurança para crescer. Observe a diferença entre assumir responsabilidades e tentar controlar cada detalhe; eles podem ser parecidos no início.","advice":"Assuma o controle com um plano claro; limites firmes trazem estabilidade duradoura.","yesNoMeaning":"Estrutura, autoridade e disciplina constante estão por trás de um sim confiante."}' WHERE card_id = 'emperor' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"O Hierofante","meaning":"A tradição e a orientação confiável oferecem um caminho confiável. Aprenda com o que veio antes. Um professor, uma comunidade ou um método estabelecido podem oferecer um bom ponto de partida. Aprenda por que uma tradição funciona para que você possa aplicá-la cuidadosamente à sua própria situação.","advice":"Siga a sabedoria estabelecida e busque conselho daqueles em quem você confia.","yesNoMeaning":"Tradição e orientação confiável apontam para um sim confiável — apoie-se no que já se provou."}' WHERE card_id = 'hierophant' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Os Amantes","meaning":"Um vínculo significativo ou uma escolha importante. Siga o que seu coração realmente valoriza. A harmonia duradoura exige que ambos os lados falem honestamente sobre necessidades e limites. Se esta for uma decisão e não um romance, pergunte qual caminho reflete seus valores mais profundos.","advice":"Escolha com honestidade e alinhamento — a conexão se aprofunda quando você é sincero.","yesNoMeaning":"Seu coração e valores estão alinhados aqui — a resposta é sim, especialmente quando você escolhe com honestidade."}' WHERE card_id = 'lovers' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"O Carro","meaning":"Força de vontade e impulso levam você adiante. Mantenha o foco e você prevalecerá. Impulsos opostos ainda podem levá-lo adiante quando você lhes dá uma direção compartilhada. O progresso depende de direcionar seus sentimentos e ações, e não simplesmente de forçar mais.","advice":"Mantenha seus olhos no objetivo e conduza com confiança através de cada obstáculo.","yesNoMeaning":"Força de vontade e impulso estão ao seu lado — um sim focado, desde que você permaneça comprometido."}' WHERE card_id = 'chariot' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Força","meaning":"O verdadeiro poder é gentil – paciência, coragem e compaixão superam qualquer desafio. A gentileza é uma forma ativa de coragem: você pode permanecer com o desconforto sem deixar que ele decida sua resposta. Reconheça o medo e aja com cuidado, em vez de esperar que o medo desapareça.","advice":"Lidere com força tranquila; uma mão suave é frequentemente a mais forte.","yesNoMeaning":"Coragem gentil e resolução paciente fazem deste um sim — conduza com calma, não com força."}' WHERE card_id = 'strength' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"O Eremita","meaning":"É hora de dar um passo atrás e buscar clareza interior. A solidão agora traz respostas mais profundas. Recuar pode tornar sua própria voz mais fácil de ouvir em meio às opiniões de outras pessoas. A solidão ajuda quando leva à compreensão, mas também pode se tornar uma forma de evitar a conexão.","advice":"Volte-se para dentro, reflita e deixe o silêncio revelar o que você realmente precisa.","yesNoMeaning":"Ainda não — a carta pede que você dê um passo atrás e encontre clareza interior antes de agir."}' WHERE card_id = 'hermit' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Roda da Fortuna","meaning":"A fortuna gira e os ciclos mudam. O que muda agora faz parte de um ritmo maior. Um velho ciclo pode estar mudando, trazendo inconveniências e possibilidades. Você não pode escolher todos os eventos, mas pode escolher o que levar adiante e como se preparar para o próximo turno.","advice":"Siga a maré com flexibilidade — abrace a mudança, seja ela boa ou não.","yesNoMeaning":"A sorte está mudando — o resultado depende de como você lida com a mudança, em vez de um sim ou não fixo."}' WHERE card_id = 'wheel-of-fortune' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Justiça","meaning":"A verdade e a justiça vencem. Causa e efeito agora entram em equilíbrio. O que está a acontecer pode reflectir uma cadeia de escolhas anteriores e não um momento isolado. Verifique os fatos, ouça as pessoas envolvidas e assuma a parte que lhe pertence.","advice":"Aja com honestidade e pese ambos os lados; a balança se equilibrará de forma justa.","yesNoMeaning":"As balanças ainda estão pesando — a resposta justa depende dos fatos e da sua honestidade."}' WHERE card_id = 'justice' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"O Enforcado","meaning":"Uma pausa necessária. Libere o controle e veja a situação de um novo ângulo. Esperar pode ser desconfortável quando a ação é sua resposta habitual. Uma perspectiva alterada, ou algo que você escolhe liberar, pode revelar o que mais pressão não poderia.","advice":"Pare de insistir — entregue-se ao momento e deixe uma nova perspectiva chegar.","yesNoMeaning":"Pausa é necessária primeiro — forçar isso agora só atrasaria uma resposta mais clara."}' WHERE card_id = 'hanged-man' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Morte","meaning":"Um final abre caminho para a renovação. Deixe para trás o que já cumpriu seu ciclo. Esta carta fala de transição e não de uma previsão literal de perda. Você pode ter superado um antigo papel, hábito ou expectativa; deixá-lo para trás ainda pode levar tempo.","advice":"Deixe ir sem arrependimentos; uma transformação profunda está abrindo uma nova porta.","yesNoMeaning":"Um fim está abrindo caminho — o caminho atual está se fechando para que um novo possa começar."}' WHERE card_id = 'death' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Temperança","meaning":"Equilíbrio e paciência trazem harmonia. Misture opostos com graça. Procure o que pode ser combinado a partir de duas abordagens diferentes. O progresso silencioso pode assumir a forma de um hábito sustentável, de uma conversa mais calma ou de um ritmo que você realmente pode manter.","advice":"Mova-se com moderação e mantenha a calma — passos firmes alcançam o destino.","yesNoMeaning":"Equilíbrio e paciência trazem harmonia — um sim ponderado, dado um passo firme de cada vez."}' WHERE card_id = 'temperance' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"O Diabo","meaning":"Cuidado com o apego, a tentação ou um hábito que prende você. Reconheça as correntes. Um benefício de curto prazo pode dificultar a saída de um hábito que cobra um preço alto. Nomear o que você ganha com isso, bem como quanto custa, pode devolver um pouco de liberdade de escolha.","advice":"Nomeie o que te mantém preso e recupere sua liberdade — a corrente só prende se você permitir.","yesNoMeaning":"O apego ou um padrão vinculativo impede — ainda não, até que a corrente seja nomeada e quebrada."}' WHERE card_id = 'devil' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"A Torre","meaning":"A mudança repentina destrói o falso e revela a verdade. O que cai nunca foi feito para ficar de pé. A disrupção é difícil quando abala um plano em que você confiava. Você não precisa encontrar o lado positivo imediatamente; primeiro observe o que realmente mudou e o que permanece de pé.","advice":"Aceite a turbulência; dos escombros pode-se construir uma base mais clara.","yesNoMeaning":"A mudança súbita está destruindo o antigo — o terreno deve se acomodar antes que um sim firme seja possível."}' WHERE card_id = 'tower' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"A Estrela","meaning":"Esperança, cura e inspiração tranquila renovam seu espírito após a tempestade. A esperança não é uma promessa de que tudo se resolverá sozinho. É espaço para respirar depois da dificuldade e continuar cuidando do que importa antes que o resultado seja visível.","advice":"Confie na luz à frente e continue acreditando — seus desejos estão ao alcance.","yesNoMeaning":"Esperança e renovação tranquila apontam para o sim — confie na luz à frente e mantenha seu desejo vivo."}' WHERE card_id = 'star' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"A Lua","meaning":"A ilusão e a incerteza confundem o caminho. Confie na sua intuição, não nas aparências. Quando os fatos estão incompletos, a memória e o medo podem preencher as lacunas com uma história convincente. Vá mais devagar, observe sua reação e separe o que você sente daquilo que você verificou.","advice":"Desacelere e olhe mais fundo; a clareza virá quando a névoa se dissipar.","yesNoMeaning":"Ilusão e incerteza confundem o caminho — a resposta não é clara até você olhar além das aparências."}' WHERE card_id = 'moon' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"O Sol","meaning":"Alegria, sucesso e clareza radiante. Tudo é brilhante e cheio de vida. A clareza pode ajudá-lo a reconhecer seu progresso e compartilhar alegria sem minimizá-lo. Se o trabalho persistir, esta energia renovada pode ajudá-lo a enfrentá-lo de forma mais aberta.","advice":"Celebre e brilhe — a energia positiva atrai os resultados que você deseja.","yesNoMeaning":"Alegria e clareza radiante confirmam um sim brilhante — tudo está funcionando a seu favor."}' WHERE card_id = 'sun' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Julgamento","meaning":"Um chamado para crescer, renovar e ser honesto consigo mesmo. Um veredicto de despertar. Rever o passado não significa necessariamente culpar-se para sempre. Aprenda a lição, perdoe o que puder e responda ao chamado para mudar com uma escolha consciente agora.","advice":"Responda ao chamado com coragem; perdoe o passado e entre no seu próximo capítulo.","yesNoMeaning":"Um chamado para se erguer e se renovar — sim, especialmente quando você perdoa o passado e responde honestamente."}' WHERE card_id = 'judgement' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"O Mundo","meaning":"Conclusão e realização – um ciclo se fecha em perfeita totalidade. A conquista inclui as habilidades, relacionamentos e perspectivas que você adquiriu ao longo do caminho. Honre a conclusão deste ciclo, mesmo enquanto uma jornada mais ampla continua.","advice":"Celebre o que você conquistou; a porta está aberta para um mundo mais amplo.","yesNoMeaning":"Conclusão e plenitude marcam este como um sim realizado — o ciclo se fecha a seu favor."}' WHERE card_id = 'world' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Ás de Paus","meaning":"Uma centelha de inspiração abre um caminho criativo ousado. Um convite, projeto ou novo desejo pode fazer você se sentir mais vivo. Isto é potencial e não um resultado garantido; precisa de espaço para experimentar e se comprometer depois que o primeiro entusiasmo passa.","advice":"Comece enquanto a energia está fresca e dê à ideia um verdadeiro primeiro passo.","yesNoMeaning":"O Ás de Paus aponta sim: comece enquanto a energia está fresca e dê à ideia um primeiro passo real."}' WHERE card_id = 'ace-of-wands' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Dois de Paus","meaning":"Um futuro está tomando forma através do planejamento e da escolha de direção. Você pode ver mais de uma rota e começa a se perguntar até onde deseja ir. Uma visão ampla ajuda, mas um planejamento interminável pode mantê-lo no limite.","advice":"Olhe além do que é familiar, então comprometa-se com o caminho com espaço para crescer.","yesNoMeaning":"O Dois de Paus permanece condicional: olhe além do que é familiar, então comprometa-se com o caminho deixando espaço para crescer."}' WHERE card_id = 'two-of-wands' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Três de Paus","meaning":"Os esforços iniciais expandem-se à medida que surgem oportunidades e horizontes mais amplos. O que você começou está começando a gerar uma resposta além do território familiar. Mantenha-se aberto a contatos e feedback e ao mesmo tempo reserve tempo para que seu trabalho anterior dê frutos.","advice":"Continue construindo e esteja pronto para receber a resposta que seu trabalho atrai.","yesNoMeaning":"O Três de Paus inclina-se para o sim: continue construindo e esteja pronto para receber a resposta que seu trabalho atrai."}' WHERE card_id = 'three-of-wands' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Quatro de Paus","meaning":"Estabilidade, acolhimento e celebração partilhada criam uma base sólida. Um marco merece comemoração mesmo quando a jornada ainda não terminou. O pertencimento e as pessoas que ajudaram a construir esse momento podem fortalecer o seu próximo passo.","advice":"Marque o marco e permita que pessoas de apoio compartilhem deste momento.","yesNoMeaning":"O Quatro de Paus inclina-se para sim: marque o marco e deixe que pessoas apoiadoras compartilhem disso."}' WHERE card_id = 'four-of-wands' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Cinco de Paus","meaning":"Objetivos concorrentes criam atrito, ruído ou um teste de confiança. Muitas vozes concorrentes podem esconder o objetivo comum. O conflito pode aguçar uma ideia quando todos sabem o que estão realmente debatendo e podem ouvir as diferenças.","advice":"Transforme a rivalidade em prática útil e recuse conflitos que não têm propósito.","yesNoMeaning":"O Cinco de Paus permanece condicional: transforme a rivalidade em prática útil e recuse conflitos que não têm propósito."}' WHERE card_id = 'five-of-wands' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Seis de Varinhas","meaning":"O reconhecimento segue um esforço determinado e um progresso visível. Seu esforço pode finalmente ser visto por outras pessoas. O reconhecimento pode encorajá-lo, mas o valor do seu trabalho permanece mesmo quando nenhum público está assistindo.","advice":"Aceite o incentivo, mas mantenha sua confiança vinculada ao trabalho honesto.","yesNoMeaning":"O Seis de Paus tende para sim: aceite o incentivo, mas mantenha sua confiança vinculada ao trabalho honesto."}' WHERE card_id = 'six-of-wands' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Sete de Paus","meaning":"Você mantém um terreno valioso enquanto a pressão testa sua determinação. Proteger o que é importante requer saber por que isso é importante para você. A pressão pode vir de diversas direções, mas nem todos os desafios merecem uma luta.","advice":"Defenda o que importa com limites claros em vez de lutar contra todos os desafios.","yesNoMeaning":"O Sete de Paus tende para sim: defenda o que importa com limites claros em vez de lutar contra todos os desafios."}' WHERE card_id = 'seven-of-wands' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Oito de Paus","meaning":"Os eventos aceleram, as mensagens chegam e o impulso elimina atrasos. Notícias ou decisões podem chegar mais rápido do que o esperado. A velocidade ajuda quando todos entendem a direção; informações pouco claras podem transformar o ímpeto em confusão.","advice":"Aja prontamente e mantenha a comunicação direta enquanto o caminho estiver aberto.","yesNoMeaning":"O Oito de Paus aponta sim: aja prontamente e mantenha a comunicação direta enquanto o caminho estiver aberto."}' WHERE card_id = 'eight-of-wands' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Nove de Paus","meaning":"A resiliência é forte, embora as tensões do passado o tornem vigilante. As tensões passadas ensinaram você a se proteger, mas a vigilância constante é exaustiva. Julgue o risco que está diante de você pelas evidências de hoje, bem como pelas feridas de ontem.","advice":"Proteja sua energia e dê o próximo passo sem esperar que toda ferida se repita.","yesNoMeaning":"O Nove de Paus permanece condicional: proteja sua energia e dê o próximo passo sem esperar que cada ferida se repita."}' WHERE card_id = 'nine-of-wands' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Dez de Paus","meaning":"A responsabilidade tornou-se pesada e o sucesso agora carrega um fardo. Algo de que você antes se orgulhava agora pode acarretar muitas obrigações. Sua habilidade é real, mas não exige que você execute todas as tarefas sozinho.","advice":"Delegue, simplifique e deixe de lado trabalhos que não são mais realmente seus.","yesNoMeaning":"O Dez de Paus tende para não: delegue, simplifique e largue o trabalho que não é mais verdadeiramente seu."}' WHERE card_id = 'ten-of-wands' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Pajem de Paus","meaning":"A curiosidade traz uma mensagem viva, um experimento ou um novo interesse criativo. Uma ideia nova pode trazer de volta o entusiasmo de um iniciante. Você não precisa dominar tudo antes de explorar; dê a si mesmo permissão para experimentar, ajustar e aprender na prática.","advice":"Explore com coragem e deixe que a energia de iniciante o ensine por meio da ação.","yesNoMeaning":"O Pajem de Paus tende ao sim: explore com coragem e deixe que a energia de iniciante ensine você por meio da ação."}' WHERE card_id = 'page-of-wands' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Cavaleiro de Paus","meaning":"A paixão avança rapidamente, trazendo aventura e possível impaciência. A atração por algo novo pode fazer você querer sair imediatamente. Essa energia é mais útil quando um objetivo claro o impede de mudar de rumo a cada impulso passageiro.","advice":"Use o momentum, mas escolha uma direção antes que a velocidade disperse seu esforço.","yesNoMeaning":"O Cavaleiro de Paus permanece condicional: use o impulso, mas escolha uma direção antes que a velocidade disperse seu esforço."}' WHERE card_id = 'knight-of-wands' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Rainha de Paus","meaning":"A confiança calorosa e a independência criativa atraem outras pessoas para a sua visão. A sua presença aberta pode encorajar outros a acreditar numa visão partilhada. A confiança aqui não exige ofuscar ninguém; abre espaço para que outros também brilhem.","advice":"Confie em sua presença, incentive os outros e não diminua sua ambição.","yesNoMeaning":"A Rainha de Paus tende para sim: confie na sua presença, encoraje os outros e não diminua sua ambição."}' WHERE card_id = 'queen-of-wands' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Rei de Paus","meaning":"A visão madura transforma inspiração em liderança ética e decisiva. Uma visão ampla precisa de decisões, responsabilidade e capacidade de sustentar a energia de uma equipe. Lidere através de um propósito claro, em vez de apenas pressão ou ego.","advice":"Lidere a partir de um propósito maior e dê aos outros espaço para contribuir.","yesNoMeaning":"O Rei de Paus inclina-se para sim: lidere a partir de um propósito maior e dê aos outros espaço para contribuir."}' WHERE card_id = 'king-of-wands' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Ás de Copas","meaning":"O coração se abre para um novo afeto, compaixão e renovação emocional. Um encontro, um novo sentimento ou um abrandamento interior podem convidá-lo a dar e receber com mais liberdade. Deixe a emoção ser reconhecida antes de forçá-la a um resultado específico.","advice":"Receba o sentimento honestamente e deixe o cuidado fluir sem forçar um resultado.","yesNoMeaning":"O Ás de Copas indica sim: receba o sentimento honestamente e deixe o cuidado fluir sem forçar um resultado."}' WHERE card_id = 'ace-of-cups' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Dois de Copas","meaning":"O reconhecimento mútuo cria parceria, atração ou acordo sincero. A promessa mais profunda reside em duas pessoas se verem claramente, além da atração inicial. Uma conversa sincera, um pedido de desculpas ou um acordo justo podem fortalecer o vínculo.","advice":"Encontre a outra pessoa como igual e fale com o coração.","yesNoMeaning":"O Dois de Copas inclina-se sim: encontre a outra pessoa como igual e fale do coração."}' WHERE card_id = 'two-of-cups' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Três de Copas","meaning":"Amizade, comunidade e alegria compartilhada trazem apoio emocional. Uma pequena reunião ou apoio oportuno pode lembrá-lo de que a alegria não precisa ser carregada sozinha. Lembre-se daqueles que estiveram ao seu lado antes que as coisas ficassem mais fáceis.","advice":"Celebre junto e lembre-se de quem realmente aparece para você.","yesNoMeaning":"O Três de Copas tende para sim: celebre junto e lembre-se de quem realmente está presente para você."}' WHERE card_id = 'three-of-cups' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Quatro de Copas","meaning":"O retraimento emocional torna difícil perceber um presente disponível. Quando você está cansado ou desanimado, até mesmo uma boa oferta pode parecer enfadonha. Seja honesto sobre seus sentimentos atuais antes de decidir que nada ao seu redor importa.","advice":"Pause a comparação e olhe novamente para o que está sendo oferecido silenciosamente.","yesNoMeaning":"O Quatro de Copas inclina-se para não: pause a comparação e olhe novamente para o que está sendo oferecido silenciosamente."}' WHERE card_id = 'four-of-cups' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Cinco de Copas","meaning":"A perda chama a atenção para o que foi derramado enquanto algo significativo permanece. O luto merece ser nomeado, em vez de ser coberto com otimismo rápido. Mesmo assim, uma perda pode não contar toda a história; suporte ou possibilidade ainda podem permanecer próximos.","advice":"Honre a decepção, depois volte-se para o apoio que ainda está presente.","yesNoMeaning":"O Cinco de Copas inclina-se para não: honre a decepção, depois volte-se para o apoio que ainda está presente."}' WHERE card_id = 'five-of-cups' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Seis de Copas","meaning":"A memória, a inocência ou um vínculo familiar retorna com um calor suave. Um velho amigo ou memória pode reconectá-lo com uma sensação de segurança. Dê boas-vindas a esse calor ao mesmo tempo em que reconhece que o presente mudou e você mudou com ele.","advice":"Receba a bondade do passado sem fingir que você deve viver lá novamente.","yesNoMeaning":"O Seis de Copas tende para sim: receba a bondade do passado sem fingir que precisa viver lá de novo."}' WHERE card_id = 'six-of-cups' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Sete de Copas","meaning":"Muitas possibilidades atraentes confundem a diferença entre visão e ilusão. Cada opção pode parecer conter uma bela promessa, mas nem todas as promessas têm o mesmo fundamento. Separe o que você realmente quer do que você imaginou em torno disso.","advice":"Reduza as escolhas e teste um sonho contra a realidade antes de se comprometer.","yesNoMeaning":"O Sete de Copas ainda não está claro: restrinja as escolhas e teste um sonho contra a realidade antes de se comprometer."}' WHERE card_id = 'seven-of-cups' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Oito de Copas","meaning":"Uma situação que antes era significativa não nutre mais o coração. Deixar algo que antes era significativo pode ser triste e certo para você agora. Seu valor era real, mesmo que sua necessidade de um significado mais profundo tenha mudado.","advice":"Saia com honestidade e siga em direção à realização mais profunda que você agora precisa.","yesNoMeaning":"O Oito de Copas aponta não: saia com honestidade e mova-se em direção à realização mais profunda que você agora precisa."}' WHERE card_id = 'eight-of-cups' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Nove de Copas","meaning":"Contentamento e gratidão fazem com que um desejo sincero pareça próximo. Você pode ter alcançado algo que antes desejava e merece desfrutar disso. A satisfação dura mais quando você sabe de onde ela vem, em vez de correr para o próximo desejo.","advice":"Aproveite o que está aqui e pergunte se o desejo também serve aos seus valores mais profundos.","yesNoMeaning":"O Nove de Copas inclina-se para sim: aproveite o que está aqui e pergunte se o desejo também serve aos seus valores mais profundos."}' WHERE card_id = 'nine-of-cups' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Dez de Copas","meaning":"Harmonia emocional, pertencimento e conexão duradoura cercam o lar. A harmonia cresce através do cuidado e da escuta repetidos, não através de um lar sem divergências. Esta carta evoca a liberdade de ser você mesmo entre pessoas dispostas a continuar construindo juntas.","advice":"Nutra os laços que tornam a alegria sustentável e compartilhada.","yesNoMeaning":"O Dez de Copas tende para sim: nutra os laços que tornam a alegria sustentável e compartilhada."}' WHERE card_id = 'ten-of-cups' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Pajem de Copas","meaning":"Uma mensagem terna ou uma descoberta intuitiva convida à abertura emocional. Uma mensagem terna, um sentimento inesperado ou uma ideia imaginativa podem chamar sua atenção. Abra espaço para surpresas sem tratar cada sinal como uma promessa firme.","advice":"Fique curioso sobre o sentimento e responda com sinceridade, em vez de suposições.","yesNoMeaning":"O Pajem de Copas permanece condicional: mantenha-se curioso sobre o sentimento e responda com sinceridade em vez de presunção."}' WHERE card_id = 'page-of-cups' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Cavaleiro de Copas","meaning":"Romance, imaginação ou um ideal impulsionam o coração. Você pode querer seguir um convite ou ideal sincero. A sinceridade dá sentido à viagem, enquanto a praticidade ajuda você a ver quais pessoas e planos podem viajar com você ao longo do tempo.","advice":"Siga o convite, mas mantenha um pé no chão enquanto as promessas se desenrolam.","yesNoMeaning":"O Cavaleiro de Copas inclina-se para sim: siga o convite, mas mantenha um pé no chão enquanto as promessas se desenrolam."}' WHERE card_id = 'knight-of-cups' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Rainha de Copas","meaning":"A empatia e a intuição profundas criam um espaço calmo para a verdade. Ouvir com atenção pode ajudar alguém a se sentir seguro o suficiente para falar. Empatia profunda também significa saber quais necessidades são suas e quais tristezas você não pode carregar para outra pessoa.","advice":"Ouça com compaixão enquanto mantém os limites que mantêm o cuidado saudável.","yesNoMeaning":"A Rainha de Copas tende ao sim: escute com compaixão enquanto preserva os limites que mantêm o cuidado saudável."}' WHERE card_id = 'queen-of-cups' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Rei de Copas","meaning":"A maturidade emocional estabiliza sentimentos fortes sem suprimi-los. Sentimentos fortes podem permanecer presentes enquanto você escolhe uma resposta calma e responsável. Essa firmeza pode tornar uma conversa difícil mais segura para todos os envolvidos.","advice":"Responda com compaixão e autocontrole, especialmente quando os outros estiverem reativos.","yesNoMeaning":"O Rei de Copas inclina-se para sim: responda com compaixão e autocontrole, especialmente quando os outros estão reativos."}' WHERE card_id = 'king-of-cups' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Ás de Espadas","meaning":"Uma visão clara elimina a confusão e revela uma nova verdade. Um fato novo ou uma conversa honesta pode acabar com a confusão. A verdade pode ser nítida, então use-a para compreender e decidir com mais clareza, em vez de ferir.","advice":"Nomeie o problema claramente e use a clareza a serviço de uma decisão justa.","yesNoMeaning":"O Ás de Espadas aponta sim: nomeie a questão claramente e use a clareza a serviço de uma decisão justa."}' WHERE card_id = 'ace-of-swords' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Dois de Espadas","meaning":"Um impasse cauteloso atrasa uma escolha que não pode ficar suspensa para sempre. Você pode estar mantendo o equilíbrio ao se recusar a escolher, embora a pressão não tenha desaparecido. A calma é útil; evitar informações desconfortáveis ​​não fará com que a decisão desapareça.","advice":"Remova a venda suavemente, reúna o fato faltante e decida a partir do equilíbrio.","yesNoMeaning":"O Dois de Espadas ainda não está claro: remova a venda suavemente, reúna o fato que falta e decida a partir do equilíbrio."}' WHERE card_id = 'two-of-swords' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Três de Espadas","meaning":"Uma verdade dolorosa, uma separação ou uma decepção pedem para ser reconhecidas. Palavras, separação ou uma expectativa quebrada podem causar uma verdadeira dor. Identifique a dor e busque apoio em vez de se apressar para provar que já está bem.","advice":"Deixe o sentimento percorrer você e evite transformar a dor em uma história permanente.","yesNoMeaning":"O Três de Espadas inclina-se para não: deixe o sentimento passar por você e evite transformar a dor em uma história permanente."}' WHERE card_id = 'three-of-swords' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Quatro de Espadas","meaning":"Descanso e tranquilidade mental são necessários após pressão ou conflito. Depois de um longo período reagindo à pressão, sua mente precisa de espaço para se acalmar. O descanso faz parte da recuperação e da preparação, não é uma prova de que você desistiu.","advice":"Pausa antes de responder; a recuperação é produtiva quando restaura o pensamento claro.","yesNoMeaning":"O Quatro de Espadas inclina-se para não: pause antes de responder; a recuperação é produtiva quando restaura o pensamento claro."}' WHERE card_id = 'four-of-swords' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Cinco de Espadas","meaning":"O conflito pode produzir uma vitória vazia ou prejudicar a confiança. Ganhar uma discussão ainda pode prejudicar a confiança ou exauri-lo. Pergunte quanto custa a vitória e quais limites protegeriam seu respeito próprio.","advice":"Escolha a dignidade em vez de vencer e afaste-se de táticas que custam muito.","yesNoMeaning":"O Cinco de Espadas inclina-se para não: escolha dignidade em vez de vencer e afaste-se de táticas que custam demais."}' WHERE card_id = 'five-of-swords' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Seis de Espadas","meaning":"Uma passagem difícil avança gradualmente em direção a condições mais calmas. A transição pode ser tranquila: sair de uma conversa travada, de um ambiente antigo ou de uma forma cansativa de pensar. Você não precisa ver um destino perfeito para saber que está caminhando em direção a uma paz maior.","advice":"Pegue o que você aprendeu, aceite apoio e continue se afastando da turbulência.","yesNoMeaning":"O Seis de Espadas tende para sim: leve o que você aprendeu, aceite apoio e continue se afastando da turbulência."}' WHERE card_id = 'six-of-swords' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Sete de Espadas","meaning":"Estratégia, sigilo ou evitação complicam o caminho. Manter um plano privado às vezes pode protegê-lo; fugir da responsabilidade cria um tipo diferente de distância. Examine o motivo por trás de uma estratégia antes de decidir usá-la.","advice":"Aja com inteligência, mas de forma transparente; atalhos que traem a confiança voltarão como problemas.","yesNoMeaning":"O Sete de Espadas tende para não: aja de forma inteligente, mas transparente; atalhos que traem a confiança voltarão como problemas."}' WHERE card_id = 'seven-of-swords' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Oito de Espadas","meaning":"O medo e as crenças restritivas tornam difícil ver as opções disponíveis. A sensação de estar preso pode ser maior do que os limites que realmente o cercam. À medida que o medo diminui, uma pequena opção, uma pessoa prestativa ou um caminho esquecido podem se tornar visíveis.","advice":"Questione o pensamento que diz que você está preso e tome uma pequena ação libertadora.","yesNoMeaning":"O Oito de Espadas aponta não: questione o pensamento que diz que você está preso e tome uma pequena ação libertadora."}' WHERE card_id = 'eight-of-swords' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Nove de Espadas","meaning":"A ansiedade amplia o perigo no escuro e esgota a mente. Repetir pensamentos pode parecer mais violento quando você os enfrenta sozinho. Separe o que aconteceu do que você imagina que possa acontecer e permita-se pedir ajuda.","advice":"Traga o medo para a luz do dia, busque apoio e separe fatos de resultados imaginados.","yesNoMeaning":"O Nove de Espadas inclina-se para não: traga o medo à luz do dia, busque apoio e separe os fatos dos resultados imaginados."}' WHERE card_id = 'nine-of-swords' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Dez de Espadas","meaning":"Um ciclo doloroso atinge o seu limite final e não pode continuar inalterado. O final pode deixá-lo esgotado depois que a situação se prolonga por muito tempo. O antigo padrão não pode continuar inalterado, mas limites mais claros podem abrir espaço para uma recuperação gradual.","advice":"Aceite o fim, proteja sua recuperação e permita que um novo começo surja.","yesNoMeaning":"O Dez de Espadas tende para não: aceite o fim, proteja sua recuperação e permita que um novo começo surja."}' WHERE card_id = 'ten-of-swords' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Pajem de Espadas","meaning":"A curiosidade alerta busca fatos, faz perguntas e observa mudanças. A curiosidade leva você a fazer perguntas e verificar detalhes antes de aceitar uma conclusão. Esse estado de alerta apoia a aprendizagem quando esta não se transforma em suspeita de todos.","advice":"Pesquise cuidadosamente e fale com precisão em vez de reagir a cada sinal.","yesNoMeaning":"O Pajem de Espadas permanece condicional: pesquise cuidadosamente e fale com precisão, em vez de reagir a todo sinal."}' WHERE card_id = 'page-of-swords' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Cavaleiro de Espadas","meaning":"O intelecto focado move-se rapidamente e enfrenta os obstáculos diretamente. Uma ideia clara pode levá-lo adiante e falar diretamente. A determinação funciona melhor quando você ainda ouve novas evidências e percebe como suas palavras afetam os outros.","advice":"Avance com coragem, mas devagar o suficiente para ouvir o que sua certeza pode estar perdendo.","yesNoMeaning":"O Cavaleiro de Espadas permanece condicional: avance com coragem, mas devagar o suficiente para ouvir o que sua certeza pode estar perdendo."}' WHERE card_id = 'knight-of-swords' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Rainha de Espadas","meaning":"A percepção clara e os limites honestos eliminam a confusão. A experiência pode ajudá-lo a ver o que é importante entre sentimentos e promessas concorrentes. Seja direto e mantenha limites sólidos sem perder a compaixão.","advice":"Diga o que é verdade com compaixão e deixe que a experiência te refine, não te endureça.","yesNoMeaning":"A Rainha de Espadas tende ao sim: diga o que é verdadeiro com compaixão e deixe que a experiência te refine, não endureça."}' WHERE card_id = 'queen-of-swords' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Rei de Espadas","meaning":"Razão, justiça e julgamento disciplinado guiam uma decisão consequente. Uma decisão difícil exige padrões consistentes e raciocínio claro. A autoridade desta carta vem da justiça, não apenas de ter a palavra final.","advice":"Use evidências, defina o padrão e mantenha o viés pessoal fora do veredicto.","yesNoMeaning":"O Rei de Espadas inclina-se para sim: use evidências, defina o padrão e mantenha o viés pessoal fora do veredicto."}' WHERE card_id = 'king-of-swords' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Ás de Ouros","meaning":"Uma oportunidade tangível oferece a semente da prosperidade, do trabalho ou do bem-estar. Uma abertura prática pode aparecer como trabalho, apoio, habilidade ou condições mais saudáveis. O seu valor depende de como é cuidado ao longo do tempo, e não apenas do seu primeiro recurso.","advice":"Baseie a oportunidade em um plano prático e cuide dela de forma consistente.","yesNoMeaning":"O Ás de Ouros indica sim: concretize a oportunidade em um plano prático e cuide dela de forma consistente."}' WHERE card_id = 'ace-of-pentacles' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Dois de Ouros","meaning":"Várias prioridades mudam ao mesmo tempo e exigem um equilíbrio flexível. Você pode estar equilibrando trabalho, dinheiro, tempo e necessidades pessoais ao mesmo tempo. A flexibilidade mantém as coisas em movimento, mas um longo malabarismo exige prioridades mais claras.","advice":"Ajuste o ritmo, proteja o essencial e evite prometer mais do que você pode carregar.","yesNoMeaning":"O Dois de Ouros permanece condicional: ajuste o ritmo, proteja o essencial e evite prometer mais do que pode carregar."}' WHERE card_id = 'two-of-pentacles' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Três de Ouros","meaning":"A habilidade cresce por meio da colaboração, feedback e trabalho cuidadoso. O bom trabalho cresce quando cada pessoa entende sua parte e seus pontos fortes. Feedback específico, aprendizado de um ofício e respeito pelo esforço silencioso são importantes aqui.","advice":"Contribua com sua força, respeite a expertise e construa um padrão compartilhado.","yesNoMeaning":"O Três de Ouros inclina-se para sim: contribua com sua força, respeite a experiência e construa de acordo com um padrão compartilhado."}' WHERE card_id = 'three-of-pentacles' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Quatro de Ouros","meaning":"Apegar-se firmemente à segurança pode preservar recursos, mas restringir o fluxo saudável. Manter recursos arduamente conquistados pode parecer sensato durante a incerteza. Quando o medo da perda governa todas as escolhas, tanto o dinheiro quanto a paz de espírito podem parecer limitados.","advice":"Proteja o que importa sem deixar que o medo tome todas as suas decisões.","yesNoMeaning":"O Quatro de Ouros permanece condicional: proteja o que importa sem deixar que o medo tome todas as suas decisões."}' WHERE card_id = 'four-of-pentacles' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Cinco de Ouros","meaning":"A tensão ou exclusão material cria preocupação e uma sensação de escassez. As dificuldades podem fazer você se sentir sozinho ou indigno de ajuda. O apoio prático ainda pode estar próximo, mesmo quando a angústia torna difícil ver o caminho até ele.","advice":"Peça ajuda prática e perceba a porta que a dificuldade tornou fácil de ser ignorada.","yesNoMeaning":"O Cinco de Ouros inclina-se para não: peça ajuda prática e perceba a porta que a dificuldade tornou fácil de ignorar."}' WHERE card_id = 'five-of-pentacles' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Seis de Pentáculos","meaning":"Os recursos são trocados, levantando questões de generosidade, poder e justiça. A ajuda funciona melhor quando tanto o doador quanto o receptor mantêm dignidade e voz. Veja se a troca está equilibrada e quais condições vêm com a generosidade.","advice":"Dar ou receber com termos claros para que o apoio preserve a dignidade de ambos os lados.","yesNoMeaning":"O Seis de Ouros tende para sim: dê ou receba com termos claros para que o apoio preserve a dignidade de ambos os lados."}' WHERE card_id = 'six-of-pentacles' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Sete de Ouros","meaning":"O investimento do paciente atinge um ponto de avaliação antes do próximo esforço. Você investiu esforço, mas os resultados podem não chegar no cronograma preferido. Revise o progresso e diferencie o que precisa de mais paciência do que precisa de uma nova abordagem.","advice":"Revise o que está crescendo, melhore o método e dê tempo para resultados valiosos.","yesNoMeaning":"O Sete de Ouros permanece condicional: reveja o que está crescendo, melhore o método e dê tempo para resultados que valham a pena."}' WHERE card_id = 'seven-of-pentacles' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Oito de Ouros","meaning":"A repetição focada desenvolve domínio e resultados confiáveis. A habilidade se desenvolve por meio da repetição, correção e atenção aos pequenos detalhes. A carta valoriza a prática constante que outros talvez nunca vejam, em vez de um salto repentino.","advice":"Pratique a habilidade essencial, aceite correções e deixe a qualidade se acumular.","yesNoMeaning":"O Oito de Ouros aponta sim: pratique a habilidade essencial, aceite correções e deixe a qualidade se acumular."}' WHERE card_id = 'eight-of-pentacles' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Nove de Ouros","meaning":"A autossuficiência e o conforto cultivado refletem um progresso disciplinado. Seu conforto atual pode refletir muitas escolhas disciplinadas feitas anteriormente. Aproveite o que você construiu no seu próprio ritmo e reconheça o trabalho por trás disso.","advice":"Aproveite o que você construiu e mantenha a independência conectada à gratidão.","yesNoMeaning":"O Nove de Ouros inclina-se para sim: aproveite o que você construiu e mantenha a independência conectada à gratidão."}' WHERE card_id = 'nine-of-pentacles' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Dez de Ouros","meaning":"A segurança a longo prazo cresce através do legado, da família e de fundações partilhadas. A história se estende além do sucesso de uma pessoa até a família, a comunidade ou aqueles que a seguem. Uma base durável surge do cuidado cuidadoso com os recursos compartilhados.","advice":"Planeje além da vitória imediata e proteja o que pode apoiar os outros ao longo do tempo.","yesNoMeaning":"O Dez de Ouros tende para sim: planeje além da vitória imediata e proteja o que pode apoiar outros ao longo do tempo."}' WHERE card_id = 'ten-of-pentacles' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Pajem de Ouros","meaning":"Uma mensagem prática convida ao estudo, ao planejamento ou a um novo empreendimento fundamentado. Uma oportunidade prática fica mais clara quando você aprende o básico. Explore pacientemente, teste em pequena escala e observe o que tem valor duradouro.","advice":"Aprenda o básico, defina a próxima tarefa e prove a ideia através de trabalho constante.","yesNoMeaning":"O Pajem de Ouros tende ao sim: aprenda o básico, defina a próxima tarefa e comprove a ideia por meio de trabalho constante."}' WHERE card_id = 'page-of-pentacles' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Cavaleiro de Ouros","meaning":"O esforço confiável avança lentamente, mas raramente abandona a tarefa. O progresso pode parecer tão lento que você questiona se está avançando, mas a consistência está construindo uma base. A confiabilidade também precisa de espaço para descanso.","advice":"Mantenha a rotina honesta e consistente; progresso importa mais do que entusiasmo.","yesNoMeaning":"O Cavaleiro de Ouros inclina-se para sim: mantenha a rotina honesta e consistente; o progresso importa mais do que a empolgação."}' WHERE card_id = 'knight-of-pentacles' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Rainha de Ouros","meaning":"O cuidado engenhoso cria conforto, saúde e abundância prática. A segurança pode ser criada através de atos concretos de cuidado e do uso inteligente dos recursos. A generosidade sustentável começa com a lembrança também das suas próprias necessidades.","advice":"Nutra pessoas e planos de maneiras que permaneçam sustentáveis para você.","yesNoMeaning":"A Rainha de Ouros tende ao sim: cuide de pessoas e planos de maneiras que permaneçam sustentáveis para você."}' WHERE card_id = 'queen-of-pentacles' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"Rei de Ouros","meaning":"A liderança material transforma a experiência em administração estável e generosa. A experiência pode apoiar um futuro estável para o trabalho, a família ou a comunidade. O sucesso significa mais quando as pessoas que ajudaram a construí-lo podem partilhar dessa estabilidade.","advice":"Faça a escolha de longo prazo e use o sucesso de forma responsável.","yesNoMeaning":"O Rei de Ouros inclina-se para sim: faça a escolha sólida de longo prazo e use o sucesso de forma responsável."}' WHERE card_id = 'king-of-pentacles' AND locale = 'pt-BR';
UPDATE card_translations SET payload = '{"name":"The Fool","meaning":"Halaman kosong dan lompatan keyakinan — perjalanan baru dimulai dengan hati yang terbuka. Anda tidak memerlukan peta lengkap sebelum mengambil langkah pertama. Rasa ingin tahu membantu Anda belajar dari setiap upaya, sementara sedikit persiapan menjaga kebebasan dari kecerobohan.","advice":"Percayalah pada jalur di depan Anda dan ambil langkah pertama itu, bahkan tanpa semua jawaban.","yesNoMeaning":"Sebuah awal baru jarang membawa jawaban yang pasti — hasilnya tergantung pada langkah yang kamu ambil."}' WHERE card_id = 'fool' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Sang Penyihir","meaning":"Anda memegang semua alat yang Anda butuhkan. Fokuskan keinginan Anda dan ubah niat menjadi tindakan. Sebuah ide menjadi nyata ketika perhatian, waktu, dan sumber daya yang tersedia mengarah pada tugas yang sama. Lihatlah alat-alat yang sudah dalam jangkauan sebelum menunggu tanda lainnya.","advice":"Gunakan keterampilan dan sumber daya Anda dengan sengaja — sekaranglah waktunya untuk mewujudkannya.","yesNoMeaning":"Anda sudah memegang semua yang dibutuhkan — energi mendukung bergerak maju dengan fokus."}' WHERE card_id = 'magician' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Pendeta Agung Perempuan","meaning":"Kebijaksanaan yang tenang tersembunyi di bawah permukaan. Dengarkan intuisi dan suara hati Anda. Keheningan mungkin mengungkapkan suatu pola, perasaan yang belum dapat Anda sebutkan, atau informasi yang masih hilang. Amati sedikit lebih lama sebelum mengungkapkan semuanya.","advice":"Berhenti sejenak, masuk ke dalam diri, dan biarkan nalurimu membimbingmu sebelum bertindak.","yesNoMeaning":"Jawabannya tersembunyi di bawah permukaan untuk saat ini — percayai intuisi Anda daripada memaksakan jawaban ya atau tidak yang jelas."}' WHERE card_id = 'high-priestess' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"The Empress","meaning":"Pertumbuhan, kelimpahan, dan energi pengasuhan mengelilingi Anda. Biarkan keindahan dan perhatian berkembang. Suatu hubungan, proyek, atau bagian dari diri Anda dapat tumbuh melalui perhatian yang terus-menerus. Kelimpahan di sini berarti mempunyai ruang untuk berkembang, tidak memberi sampai tidak ada lagi yang tersisa.","advice":"Bersabarlah dan murah hati — ciptakan dengan cinta dan biarkan segala sesuatu matang secara alami.","yesNoMeaning":"Pertumbuhan, kelimpahan, dan energi yang mendukung kembali keinginan Anda — jawabannya adalah ya yang tenang."}' WHERE card_id = 'empress' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"The Emperor","meaning":"Struktur, otoritas, dan kepemimpinan yang mantap. Bangunlah landasan yang kokoh dengan disiplin. Struktur yang berguna memberi orang keamanan untuk bertumbuh. Perhatikan perbedaan antara mengambil tanggung jawab dan mencoba mengendalikan setiap detail; mereka mungkin terlihat mirip pada awalnya.","advice":"Ambil kendali dengan rencana yang jelas; batasan yang tegas membawa kestabilan yang langgeng.","yesNoMeaning":"Struktur, otoritas, dan disiplin yang konsisten mendukung jawaban ''ya'' dengan percaya diri."}' WHERE card_id = 'emperor' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Hierofant","meaning":"Tradisi dan bimbingan tepercaya menawarkan jalan yang dapat diandalkan. Belajar dari apa yang telah terjadi sebelumnya. Seorang guru, komunitas, atau metode yang sudah mapan mungkin menawarkan titik awal yang baik. Pelajari mengapa suatu tradisi berhasil sehingga Anda dapat menerapkannya dengan bijaksana pada situasi Anda sendiri.","advice":"Ikuti kebijaksanaan yang sudah ada dan carilah nasihat dari mereka yang Anda percayai.","yesNoMeaning":"Tradisi dan panduan yang dipercaya menunjukkan jawaban yang dapat diandalkan — bersandar pada apa yang telah terbukti."}' WHERE card_id = 'hierophant' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Para Kekasih","meaning":"Ikatan yang bermakna atau pilihan penting. Ikuti apa yang benar-benar dihargai oleh hati Anda. Keharmonisan yang langgeng meminta kedua belah pihak untuk berbicara jujur ​​mengenai kebutuhan dan batasan. Jika ini adalah sebuah keputusan dan bukan sebuah romansa, tanyakan jalan mana yang mencerminkan nilai-nilai terdalam Anda.","advice":"Pilih dengan kejujuran dan keselarasan — koneksi akan lebih dalam saat Anda tulus.","yesNoMeaning":"Hati dan nilai-nilai Anda selaras di sini — jawabannya adalah ya, terutama ketika Anda memilih dengan kejujuran."}' WHERE card_id = 'lovers' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"The Chariot","meaning":"Tekad dan momentum membawa Anda maju. Tetap fokus dan Anda akan menang. Dorongan yang berlawanan masih dapat membawa Anda maju jika Anda memberinya arahan yang sama. Kemajuan bergantung pada pengendalian perasaan dan tindakan Anda, bukan sekadar berusaha lebih keras.","advice":"Tetap fokus pada tujuan dan kendalikan dengan percaya diri melalui setiap rintangan.","yesNoMeaning":"Kemauan dan momentum ada di pihak Anda — sebuah ya yang terfokus, selama Anda tetap berkomitmen."}' WHERE card_id = 'chariot' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Kekuatan","meaning":"Kekuatan sejati itu lembut — kesabaran, keberanian, dan kasih sayang menjinakkan tantangan apa pun. Kelemahlembutan adalah bentuk keberanian yang aktif: Anda bisa bertahan dalam ketidaknyamanan tanpa membiarkannya menentukan respons Anda. Akui rasa takut dan bergeraklah dengan hati-hati daripada menunggu rasa takut hilang.","advice":"Pimpin dengan kekuatan yang tenang; tangan yang lembut sering kali adalah yang terkuat.","yesNoMeaning":"Keberanian lembut dan ketekunan yang sabar membuat ini menjadi ya — pimpin dengan tenang, bukan dengan paksa."}' WHERE card_id = 'strength' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Pertapa","meaning":"Saatnya untuk mundur dan mencari kejernihan batin. Kesendirian kini membawa jawaban yang lebih dalam. Mundur dapat membuat suara Anda lebih mudah didengar di tengah opini orang lain. Kesendirian membantu ketika mengarah pada pemahaman, namun juga bisa menjadi cara untuk menghindari koneksi.","advice":"Berbalik ke dalam, renungkan, dan biarkan keheningan mengungkap apa yang benar-benar Anda butuhkan.","yesNoMeaning":"Belum — kartu meminta kamu untuk mundur sejenak dan menemukan kejelasan batin sebelum bertindak."}' WHERE card_id = 'hermit' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Roda Keberuntungan","meaning":"Peruntungan berputar dan siklus bergeser. Perubahan yang terjadi saat ini adalah bagian dari ritme yang lebih besar. Siklus lama mungkin akan berubah, membawa ketidaknyamanan dan kemungkinan. Anda tidak dapat memilih setiap acara, namun Anda dapat memilih apa yang akan dilanjutkan dan bagaimana mempersiapkan diri untuk giliran berikutnya.","advice":"Naik gelombang dengan fleksibilitas — sambut perubahan, baik atau buruk.","yesNoMeaning":"Peruntungan sedang berbalik — hasilnya tergantung bagaimana Anda menghadapi perubahan tersebut daripada jawaban ya atau tidak yang tetap."}' WHERE card_id = 'wheel-of-fortune' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Keadilan","meaning":"Kebenaran dan keadilan membawa manfaatnya. Sebab dan akibat kini menjadi seimbang. Apa yang terjadi mungkin mencerminkan rangkaian pilihan sebelumnya, bukan hanya satu momen saja. Periksa faktanya, dengarkan orang-orang yang terlibat, dan miliki bagian yang menjadi milik Anda.","advice":"Bertindaklah dengan jujur dan timbang kedua sisi; timbangan akan menyeimbangkan dengan adil.","yesNoMeaning":"Timbangan masih menimbang — jawaban yang adil tergantung pada fakta dan kejujuran Anda."}' WHERE card_id = 'justice' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Orang yang Digantung","meaning":"Jeda yang diperlukan dapat membantumu melihat situasi dari sudut pandang baru. Menunggu mungkin terasa tidak nyaman ketika kamu terbiasa menyelesaikan masalah dengan bertindak. Namun, mengendurkan kendali atau melepaskan satu harapan dapat membuka pemahaman yang tidak muncul saat kamu terus memaksa diri.","advice":"Berhenti mendorong — menyerahlah pada momen dan biarkan perspektif baru muncul.","yesNoMeaning":"Berhenti sejenak diperlukan terlebih dahulu — memaksakan ini sekarang hanya akan menahan jawaban yang lebih jelas."}' WHERE card_id = 'hanged-man' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Kematian","meaning":"Sebuah akhir membuka jalan bagi pembaruan. Lepaskan hal yang sudah selesai masanya. Kartu ini berbicara tentang transisi daripada ramalan tentang kehilangan secara harfiah. Anda mungkin sudah melampaui peran, kebiasaan, atau harapan lama; meninggalkannya masih membutuhkan waktu.","advice":"Lepaskan tanpa penyesalan; transformasi yang mendalam membuka pintu baru.","yesNoMeaning":"Sebuah akhir sedang membuka jalan — jalur saat ini menutup sehingga yang baru dapat dimulai."}' WHERE card_id = 'death' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Kesederhanaan","meaning":"Keseimbangan dan kesabaran membawa harmoni. Padukan hal-hal yang berlawanan dengan keanggunan. Carilah apa yang dapat dipadukan dari dua pendekatan berbeda. Kemajuan yang diam-diam dapat berupa kebiasaan yang berkelanjutan, percakapan yang lebih tenang, atau langkah yang benar-benar dapat Anda pertahankan.","advice":"Bergeraklah dengan moderasi dan tetap tenang — langkah yang mantap mencapai tujuan.","yesNoMeaning":"Keseimbangan dan kesabaran membawa harmoni — sebuah ''ya'' yang terukur, diambil satu langkah mantap dalam satu waktu."}' WHERE card_id = 'temperance' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"The Devil","meaning":"Keterikatan, godaan, atau kebiasaan yang membelenggu mungkin sedang membatasi pilihanmu. Manfaat sesaat dapat membuat kebiasaan yang merugikan terasa sulit ditinggalkan. Perhatikan apa yang kamu dapat darinya dan harga yang harus dibayar; dari situ, ruang untuk memilih kembali dapat terbuka.","advice":"Sebutkan apa yang menahanmu dan pulihkan kebebasanmu — rantai hanya mengikat jika kamu membiarkannya.","yesNoMeaning":"Keterikatan atau pola yang mengikat menghalangi — belum, sampai rantai itu dinamai dan diputus."}' WHERE card_id = 'devil' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Menara","meaning":"Perubahan mendadak dapat mengguncang hal yang selama ini kamu anggap kokoh dan memperlihatkan kebenaran yang terabaikan. Guncangan itu terasa berat, terutama bila menyentuh rencana yang kamu percaya. Kamu tidak perlu segera mencari sisi baiknya; lihat dulu apa yang benar-benar berubah dan apa yang masih dapat menjadi pijakan.","advice":"Sambut gejolak; dari reruntuhan, fondasi yang lebih jelas bisa dibangun.","yesNoMeaning":"Perubahan tiba-tiba menghancurkan yang lama — tanah harus menetap sebelum kata ya yang mantap bisa terjadi."}' WHERE card_id = 'tower' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Bintang","meaning":"Harapan, kesembuhan, dan inspirasi yang tenang memperbarui semangat Anda setelah badai. Harapan bukanlah janji bahwa segala sesuatunya akan terselesaikan dengan sendirinya. Ini adalah ruang untuk bernapas setelah kesulitan dan terus memperhatikan hal-hal penting sebelum hasilnya terlihat.","advice":"Percayalah pada cahaya di depan dan teruslah percaya — keinginan Anda ada dalam jangkauan.","yesNoMeaning":"Harapan dan pembaruan yang tenang menunjukkan ya — percayalah pada cahaya di depan dan pertahankan harapan Anda tetap hidup."}' WHERE card_id = 'star' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Bulan","meaning":"Ilusi dan ketidakpastian mengaburkan jalan. Percayai intuisi Anda, bukan penampilan. Ketika fakta tidak lengkap, ingatan dan ketakutan dapat mengisi kekosongan tersebut dengan cerita yang meyakinkan. Pelan-pelan, perhatikan reaksi Anda, dan pisahkan apa yang Anda rasakan dari apa yang telah Anda verifikasi.","advice":"Perlambat dan pandang lebih dalam; kejelasan akan datang saat kabut menghilang.","yesNoMeaning":"Ilusi dan ketidakpastian mengaburkan jalan — jawabannya tidak jelas sampai Anda melihat di balik penampilan."}' WHERE card_id = 'moon' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Matahari","meaning":"Kegembiraan, kesuksesan, dan kejernihan yang bersinar. Semuanya cerah dan penuh kehidupan. Kejelasan dapat membantu Anda mengenali kemajuan Anda dan berbagi kegembiraan tanpa meremehkannya. Jika pekerjaan masih ada, energi baru ini dapat membantu Anda menghadapinya dengan lebih terbuka.","advice":"Rayakan dan bersinarlah — energi positif menarik hasil yang kamu inginkan.","yesNoMeaning":"Kegembiraan dan kejernihan yang bersinar menegaskan jawaban ya yang cerah — semuanya bekerja sesuai keinginanmu."}' WHERE card_id = 'sun' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Pengadilan","meaning":"Panggilan untuk bangkit, memperbarui, dan jujur ​​pada diri sendiri. Sebuah keputusan kebangkitan. Mengulas masa lalu bukan berarti selalu menyalahkan diri sendiri. Ambil pelajarannya, maafkan apa yang Anda bisa, dan jawab panggilan untuk berubah dengan pilihan sadar sekarang.","advice":"Jawablah panggilan dengan keberanian; maafkan masa lalu dan melangkahlah ke bab berikutnya dalam hidupmu.","yesNoMeaning":"Seruan untuk bangkit dan memperbarui — ya, terutama setelah Anda memaafkan masa lalu dan menjawab dengan jujur."}' WHERE card_id = 'judgement' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Dunia","meaning":"Penyelesaian dan pemenuhan - sebuah siklus berakhir dengan keutuhan yang sempurna. Pencapaian tersebut mencakup keterampilan, hubungan, dan perspektif yang Anda peroleh selama ini. Hormatilah penyelesaian siklus ini bahkan ketika perjalanan yang lebih luas terus berlanjut.","advice":"Rayakan apa yang telah Anda capai; pintu terbuka ke dunia yang lebih luas.","yesNoMeaning":"Penyelesaian dan kesempurnaan menandai ini sebagai ya yang terpenuhi — siklus berakhir menguntungkan Anda."}' WHERE card_id = 'world' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"As Tongkat","meaning":"Percikan inspirasi membuka jalur kreatif yang berani. Undangan, proyek, atau keinginan baru mungkin membuat Anda merasa lebih hidup. Hal ini lebih bersifat potensial dan bukan merupakan hasil yang dijamin; dibutuhkan ruang untuk bereksperimen dan komitmen setelah kegembiraan pertama memudar.","advice":"Mulailah saat energi masih segar dan berikan ide itu langkah pertama yang nyata.","yesNoMeaning":"The Ace of Wands condong ke ya: mulai ketika energinya masih segar dan berikan ide itu langkah pertama yang nyata."}' WHERE card_id = 'ace-of-wands' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Dua Tongkat","meaning":"Masa depan terbentuk melalui perencanaan dan pilihan arah. Anda dapat melihat lebih dari satu rute dan mulai menanyakan seberapa jauh Anda ingin pergi. Pandangan yang luas memang membantu, namun perencanaan tanpa akhir dapat membuat Anda tetap berada di ambang batas.","advice":"Lihat melampaui apa yang sudah dikenal, kemudian berkomitmen pada jalan dengan ruang untuk tumbuh.","yesNoMeaning":"Dua Tongkat tetap bersifat kondisional: lihat melampaui apa yang sudah dikenal, lalu berkomitmen pada jalan dengan ruang untuk berkembang."}' WHERE card_id = 'two-of-wands' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Tiga Tongkat","meaning":"Upaya awal akan berkembang seiring dengan munculnya peluang dan cakrawala yang lebih luas. Apa yang Anda mulai mulai mendapat tanggapan di luar wilayah yang sudah dikenal. Tetap terbuka terhadap kontak dan masukan sambil memberikan waktu agar pekerjaan Anda sebelumnya membuahkan hasil.","advice":"Terus membangun dan bersiaplah menerima respons yang ditarik oleh pekerjaanmu.","yesNoMeaning":"Tiga Tongkat condong ya: teruslah membangun dan bersiaplah untuk menghadapi respons yang ditarik oleh pekerjaanmu."}' WHERE card_id = 'three-of-wands' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Empat Tongkat","meaning":"Stabilitas, sambutan, dan perayaan bersama menciptakan landasan yang kuat. Sebuah pencapaian patut dirayakan bahkan ketika perjalanannya belum berakhir. Rasa memiliki dan orang-orang yang membantu membangun momen ini dapat memperkuat langkah Anda selanjutnya.","advice":"Tandai tonggak sejarah dan biarkan orang-orang yang mendukung berbagi dalam hal itu.","yesNoMeaning":"Empat Tong condong ke ya: tandai pencapaian dan biarkan orang-orang yang mendukung ikut merayakannya."}' WHERE card_id = 'four-of-wands' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Lima Tongkat","meaning":"Tujuan yang bersaing menciptakan gesekan, kebisingan, atau ujian kepercayaan diri. Banyak suara yang bersaing dapat menyembunyikan tujuan bersama. Konflik dapat mempertajam suatu gagasan ketika semua orang mengetahui apa yang sebenarnya mereka perdebatkan dan dapat mendengarkan perbedaan yang ada.","advice":"Ubah persaingan menjadi praktik yang berguna dan tolak konflik yang tidak memiliki tujuan.","yesNoMeaning":"Lima Tongkat tetap bersyarat: ubah persaingan menjadi latihan yang berguna dan tolak konflik yang tidak memiliki tujuan."}' WHERE card_id = 'five-of-wands' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Enam Tongkat","meaning":"Pengakuan mengikuti upaya yang gigih dan kemajuan yang terlihat. Usaha Anda akhirnya dapat dilihat oleh orang lain. Pengakuan dapat menyemangati Anda, namun nilai karya Anda tetap ada meskipun tidak ada penonton yang menonton.","advice":"Terimalah dorongan itu, tetapi pertahankan kepercayaan diri Anda terkait dengan kerja jujur.","yesNoMeaning":"Enam Tongkat condong ya: terima dorongan, tetapi tetap pertahankan kepercayaan diri yang terikat pada kerja jujur."}' WHERE card_id = 'six-of-wands' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Tujuh Tongkat","meaning":"Anda memegang teguh pendirian sementara tekanan menguji tekad Anda. Melindungi hal yang penting memerlukan mengetahui mengapa hal tersebut penting bagi Anda. Tekanan bisa datang dari berbagai arah, namun tidak setiap tantangan layak untuk diperjuangkan.","advice":"Pertahankan apa yang penting dengan batasan yang jelas daripada menghadapi setiap tantangan.","yesNoMeaning":"Tujuh Tongkat condong ke ya: pertahankan apa yang penting dengan batasan yang jelas daripada menghadapi setiap tantangan."}' WHERE card_id = 'seven-of-wands' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Delapan Tongkat","meaning":"Peristiwa semakin cepat, pesan tiba, dan momentum menghilangkan penundaan. Berita atau keputusan mungkin datang lebih cepat dari perkiraan. Kecepatan membantu ketika semua orang memahami arah; informasi yang tidak jelas dapat mengubah momentum menjadi kebingungan.","advice":"Bertindaklah segera dan jaga komunikasi tetap langsung selama jalannya terbuka.","yesNoMeaning":"The Eight of Wands condong ke ya: bertindaklah dengan cepat dan jaga komunikasi tetap langsung selagi jalan terbuka."}' WHERE card_id = 'eight-of-wands' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Sembilan Tongkat","meaning":"Ketahanan itu kuat, meski tekanan di masa lalu membuat Anda waspada. Ketegangan di masa lalu telah mengajari Anda cara melindungi diri sendiri, namun kewaspadaan terus-menerus memang melelahkan. Nilailah risiko yang ada di hadapan Anda berdasarkan bukti hari ini dan juga luka kemarin.","advice":"Lindungi energimu dan ambil langkah berikutnya tanpa mengharapkan setiap luka terulang.","yesNoMeaning":"Sembilan Tongkat tetap bersyarat: lindungi energimu dan ambil langkah berikutnya tanpa mengharapkan setiap luka terulang."}' WHERE card_id = 'nine-of-wands' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Sepuluh Tongkat","meaning":"Tanggung jawab menjadi berat dan kesuksesan kini membawa beban. Sesuatu yang pernah Anda banggakan sekarang mungkin membawa terlalu banyak kewajiban. Kemampuan Anda memang nyata, tetapi tidak mengharuskan Anda melakukan setiap tugas sendirian.","advice":"Mendelegasikan, menyederhanakan, dan meletakkan pekerjaan yang tidak lagi benar-benar milikmu.","yesNoMeaning":"Sepuluh Tongkat condong tidak: delegasikan, sederhanakan, dan letakkan pekerjaan yang tidak benar-benar menjadi milikmu lagi."}' WHERE card_id = 'ten-of-wands' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Halaman Tongkat","meaning":"Keingintahuan membawa pesan yang hidup, eksperimen, atau minat kreatif baru. Sebuah ide segar dapat mengembalikan semangat seorang pemula. Anda tidak perlu menguasai segalanya sebelum menjelajah; izinkan diri Anda untuk mencoba, menyesuaikan, dan belajar dalam praktik.","advice":"Jelajahi dengan keberanian dan biarkan energi pemula mengajarimu melalui tindakan.","yesNoMeaning":"Page of Wands condong ke ya: jelajahi dengan keberanian dan biarkan energi pemula mengajarkanmu melalui tindakan."}' WHERE card_id = 'page-of-wands' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Kesatria Tongkat","meaning":"Gairah menyerbu dengan cepat, membawa petualangan dan kemungkinan ketidaksabaran. Tarikan terhadap sesuatu yang baru mungkin membuat Anda ingin segera pergi. Energi ini memberikan manfaat terbaik bagi Anda ketika tujuan yang jelas menghalangi Anda mengubah arah setiap kali terjadi dorongan hati.","advice":"Manfaatkan momentum, tetapi pilih arah sebelum kecepatan menyebar upaya Anda.","yesNoMeaning":"Ksatria Tongkat tetap bersyarat: gunakan momentum, tetapi pilih arah sebelum kecepatan menyebarkan usahamu."}' WHERE card_id = 'knight-of-wands' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Ratu Tongkat","meaning":"Kepercayaan diri yang hangat dan kemandirian kreatif menarik orang lain menuju visi Anda. Kehadiran Anda yang terbuka dapat mendorong orang lain untuk percaya pada visi bersama. Kepercayaan diri di sini tidak berarti harus mengungguli siapa pun; itu memberi ruang bagi orang lain untuk bersinar juga.","advice":"Percayalah pada kehadiran Anda, dorong orang lain, dan jangan kurangi ambisi Anda.","yesNoMeaning":"Ratu Tongkat condong ya: percayai kehadiranmu, dorong orang lain, dan jangan kecilkan ambisimu."}' WHERE card_id = 'queen-of-wands' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Raja Tongkat","meaning":"Visi yang matang mengubah inspirasi menjadi kepemimpinan yang tegas dan etis. Visi yang besar membutuhkan keputusan, tanggung jawab, dan kemampuan untuk mempertahankan energi tim. Pimpin melalui tujuan yang jelas, bukan tekanan atau ego saja.","advice":"Pimpin dari tujuan yang lebih besar dan beri ruang bagi orang lain untuk berkontribusi.","yesNoMeaning":"Raja Tong condong ke ya: pimpin dengan tujuan yang lebih besar dan beri ruang bagi orang lain untuk berkontribusi."}' WHERE card_id = 'king-of-wands' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"As Piala","meaning":"Hati terbuka terhadap kasih sayang baru, kasih sayang, dan pembaruan emosional. Sebuah pertemuan, perasaan baru, atau pelunakan batin mungkin mengundang Anda untuk memberi dan menerima dengan lebih leluasa. Biarkan emosi diakui sebelum memaksanya menuju hasil tertentu.","advice":"Terima perasaan itu dengan jujur dan biarkan perhatian mengalir tanpa memaksakan hasil.","yesNoMeaning":"Ace of Cups condong ya: terima perasaan dengan jujur dan biarkan kepedulian mengalir tanpa memaksakan hasil."}' WHERE card_id = 'ace-of-cups' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Dua Piala","meaning":"Saling mengakui menciptakan kemitraan, ketertarikan, atau persetujuan yang tulus. Janji yang lebih dalam terletak pada dua orang yang melihat satu sama lain dengan jelas, melampaui ketertarikan awal. Percakapan yang tulus, permintaan maaf, atau kesepakatan yang adil dapat memperkuat ikatan.","advice":"Temui orang lain sebagai setara dan berbicaralah dari hati.","yesNoMeaning":"Dua Cawan condong ke ya: temui orang lain sebagai setara dan berbicaralah dari hati."}' WHERE card_id = 'two-of-cups' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Tiga Piala","meaning":"Persahabatan, komunitas, dan kegembiraan bersama membawa dukungan emosional. Pertemuan kecil atau dukungan tepat waktu dapat mengingatkan Anda bahwa kegembiraan tidak harus dibawa sendirian. Ingatlah mereka yang berdiri di samping Anda sebelum segalanya menjadi lebih mudah.","advice":"Rayakan bersama dan ingat siapa yang benar-benar hadir untuk Anda.","yesNoMeaning":"Tiga Piala condong ya: rayakan bersama dan ingat siapa yang benar-benar hadir untukmu."}' WHERE card_id = 'three-of-cups' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Empat Gelas","meaning":"Penarikan diri secara emosional membuat hadiah yang ada sulit untuk diperhatikan. Saat Anda lelah atau putus asa, tawaran bagus pun mungkin tampak membosankan. Jujurlah tentang perasaan Anda saat ini sebelum memutuskan bahwa tidak ada apa pun di sekitar Anda yang penting.","advice":"Jeda perbandingan dan lihat lagi apa yang sedang ditawarkan dengan tenang.","yesNoMeaning":"Empat Cawan condong tidak: berhentilah membandingkan dan lihat lagi apa yang dengan tenang ditawarkan."}' WHERE card_id = 'four-of-cups' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Lima Piala","meaning":"Kehilangan menarik perhatian pada apa yang tumpah sementara sesuatu yang berarti tetap ada. Kesedihan layak untuk disebutkan daripada ditutupi dengan optimisme yang cepat. Meski begitu, satu kekalahan belum tentu menjelaskan keseluruhan cerita; dukungan atau kemungkinan mungkin masih ada.","advice":"Hormati kekecewaan, lalu beralih ke dukungan yang masih ada.","yesNoMeaning":"Lima Cawan condong tidak: hargai kekecewaan, lalu beralihlah pada dukungan yang masih ada."}' WHERE card_id = 'five-of-cups' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Enam Cangkir","meaning":"Ingatan, kepolosan, atau ikatan akrab kembali dengan kehangatan lembut. Teman atau kenangan lama mungkin menghubungkan Anda kembali dengan rasa aman. Sambut kehangatan itu sambil menyadari bahwa masa kini telah berubah dan Anda pun ikut berubah.","advice":"Sambut kebaikan masa lalu tanpa berpura-pura bahwa Anda harus hidup di sana lagi.","yesNoMeaning":"Enam Cawan condong ke ya: sambutlah kebaikan masa lalu tanpa berpura-pura bahwa kamu harus hidup di sana lagi."}' WHERE card_id = 'six-of-cups' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Tujuh Cawan","meaning":"Banyak kemungkinan menarik yang mengaburkan perbedaan antara penglihatan dan ilusi. Setiap pilihan mungkin tampak membawa janji yang indah, namun tidak setiap janji memiliki dasar yang sama. Pisahkan apa yang sebenarnya Anda inginkan dari apa yang Anda bayangkan di sekitarnya.","advice":"Persempit pilihan dan uji satu impian terhadap kenyataan sebelum berkomitmen.","yesNoMeaning":"Tujuh Cawan belum jelas: persempit pilihan dan uji satu mimpi terhadap kenyataan sebelum berkomitmen."}' WHERE card_id = 'seven-of-cups' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Delapan Piala","meaning":"Situasi yang tadinya bermakna tidak lagi menyehatkan hati. Meninggalkan sesuatu yang tadinya berarti bisa menjadi hal yang menyedihkan sekaligus baik bagi Anda saat ini. Nilainya nyata, meskipun kebutuhan Anda akan makna yang lebih dalam telah berubah.","advice":"Pergi dengan jujur dan bergerak menuju pemenuhan yang lebih dalam yang kini Anda butuhkan.","yesNoMeaning":"The Eight of Cups condong ke tidak: pergi dengan kejujuran dan bergerak menuju pemenuhan yang lebih dalam yang sekarang Anda butuhkan."}' WHERE card_id = 'eight-of-cups' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Sembilan Piala","meaning":"Kepuasan dan rasa syukur membuat harapan yang tulus terasa dekat. Anda mungkin telah mencapai sesuatu yang pernah Anda idam-idamkan dan pantas untuk menikmatinya. Kepuasan akan bertahan lebih lama bila Anda tahu dari mana asalnya daripada terburu-buru ke keinginan berikutnya.","advice":"Nikmati apa yang ada di sini dan tanyakan apakah keinginan itu juga melayani nilai-nilai terdalam Anda.","yesNoMeaning":"Sembilan Piala condong ya: nikmati apa yang ada dan tanyakan apakah keinginan itu juga sesuai dengan nilai-nilai terdalammu."}' WHERE card_id = 'nine-of-cups' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Sepuluh Piala","meaning":"Harmoni emosional, rasa memiliki, dan hubungan yang langgeng mengelilingi rumah. Harmoni tumbuh melalui perhatian dan pendengaran yang berulang-ulang, bukan melalui rumah tangga tanpa perselisihan. Kartu ini membangkitkan kebebasan untuk menjadi diri sendiri di antara orang-orang yang ingin terus membangun bersama.","advice":"Rawat ikatan yang membuat kebahagiaan berkelanjutan dan bisa dibagikan.","yesNoMeaning":"Sepuluh Piala condong ya: rawat ikatan yang membuat kebahagiaan berkelanjutan dan dapat dibagikan."}' WHERE card_id = 'ten-of-cups' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Halaman Cangkir","meaning":"Pesan yang lembut atau penemuan intuitif mengundang keterbukaan emosional. Pesan lembut, perasaan tak terduga, atau ide imajinatif mungkin menarik perhatian Anda. Berikan ruang untuk kejutan tanpa menganggap setiap tanda sebagai janji yang pasti.","advice":"Tetap penasaran terhadap perasaan dan tanggapi dengan tulus daripada berasumsi.","yesNoMeaning":"Page of Cups tetap bersyarat: tetaplah ingin tahu tentang perasaan dan tanggapi dengan ketulusan daripada asumsi."}' WHERE card_id = 'page-of-cups' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Kesatria Cawan","meaning":"Romantisme, imajinasi, atau cita-cita menarik hati ke depan. Anda mungkin ingin mengikuti ajakan atau cita-cita yang tulus. Ketulusan memberi makna pada perjalanan, sementara kepraktisan membantu Anda melihat orang dan rencana mana yang dapat bepergian bersama Anda seiring waktu.","advice":"Ikuti undangan, tetapi tetap berpijak pada kenyataan seiring janji-janji terungkap.","yesNoMeaning":"Ksatria Piala condong ke ya: ikuti undangan, tetapi tetap berpijak pada kenyataan saat janji-janji terwujud."}' WHERE card_id = 'knight-of-cups' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Ratu Cawan","meaning":"Empati dan intuisi yang mendalam menciptakan ruang tenang untuk kebenaran. Mendengarkan dengan cermat dapat membantu seseorang merasa cukup aman untuk berbicara. Empati yang mendalam juga berarti mengetahui kebutuhan mana yang menjadi kebutuhan Anda dan kesedihan mana yang tidak dapat Anda tanggung untuk orang lain.","advice":"Dengarkan dengan penuh kasih sambil menjaga batas yang membuat perhatian tetap sehat.","yesNoMeaning":"Queen of Cups condong ke ya: dengarkan dengan penuh kasih sambil menjaga batasan yang membuat perhatian tetap sehat."}' WHERE card_id = 'queen-of-cups' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Raja Cawan","meaning":"Kematangan emosi memantapkan perasaan yang kuat tanpa menekannya. Perasaan yang kuat dapat tetap ada saat Anda memilih respons yang tenang dan bertanggung jawab. Kemantapan tersebut dapat membuat percakapan yang sulit menjadi lebih aman bagi semua orang yang terlibat.","advice":"Responlah dengan kasih sayang dan pengendalian diri, terutama ketika orang lain bereaksi.","yesNoMeaning":"Raja Piala condong ke ya: tanggapi dengan kasih sayang dan pengendalian diri, terutama ketika orang lain bereaksi."}' WHERE card_id = 'king-of-cups' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"As Pedang","meaning":"Wawasan yang bersih menembus kebingungan dan mengungkap kebenaran baru. Fakta baru atau percakapan jujur ​​mungkin bisa menghilangkan kebingungan. Kebenaran bisa saja tajam, jadi gunakanlah untuk memahami dan mengambil keputusan dengan lebih jelas, bukan untuk melukai.","advice":"Sebutkan masalah dengan jelas dan gunakan kejelasan untuk mendukung keputusan yang adil.","yesNoMeaning":"The Ace of Swords condong ke ya: sebutkan masalah dengan jelas dan gunakan kejelasan untuk melayani keputusan yang adil."}' WHERE card_id = 'ace-of-swords' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Dua Pedang","meaning":"Kebuntuan yang dijaga menunda pilihan yang tidak bisa ditangguhkan selamanya. Anda mungkin menjaga keseimbangan dengan menolak memilih, meski tekanan belum hilang. Ketenangan itu berguna; menghindari informasi yang tidak nyaman tidak akan membuat keputusan menjadi hilang.","advice":"Lepaskan penutup mata dengan lembut, kumpulkan fakta yang hilang, dan putuskan dari keseimbangan.","yesNoMeaning":"Dua Pedang belum jelas: lepaskan penutup mata dengan lembut, kumpulkan fakta yang hilang, dan putuskan dari keseimbangan."}' WHERE card_id = 'two-of-swords' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Tiga Pedang","meaning":"Kebenaran, perpisahan, atau kekecewaan yang menyakitkan meminta untuk diakui. Kata-kata, perpisahan, atau harapan yang hancur mungkin akan meninggalkan rasa sakit yang nyata. Sebutkan rasa sakitnya dan carilah dukungan daripada terburu-buru membuktikan bahwa Anda sudah baik-baik saja.","advice":"Biarkan perasaan itu mengalir melalui dirimu dan hindari mengubah rasa sakit menjadi cerita yang permanen.","yesNoMeaning":"Tiga Pedang tidak condong: biarkan perasaan itu mengalir melalui kamu dan hindari mengubah rasa sakit menjadi cerita yang permanen."}' WHERE card_id = 'three-of-swords' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Empat Pedang","meaning":"Istirahat dan ketenangan mental diperlukan setelah tekanan atau konflik. Setelah sekian lama bereaksi terhadap tekanan, pikiran Anda membutuhkan ruang untuk tenang. Istirahat adalah bagian dari pemulihan dan persiapan, bukan bukti bahwa Anda sudah menyerah.","advice":"Berhenti sejenak sebelum menjawab; pemulihan produktif ketika mengembalikan pikiran yang jernih.","yesNoMeaning":"Empat Pedang condong tidak: berhenti sejenak sebelum menjawab; pemulihan menjadi produktif ketika mengembalikan pikiran yang jernih."}' WHERE card_id = 'four-of-swords' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Lima Pedang","meaning":"Konflik dapat menghasilkan kemenangan yang sia-sia atau merusak kepercayaan. Memenangkan perdebatan mungkin masih merusak kepercayaan atau membuat Anda lelah. Tanyakan berapa harga kemenangan dan batasan apa yang dapat melindungi harga diri Anda.","advice":"Pilih martabat daripada menang dan jauhi taktik yang terlalu mahal.","yesNoMeaning":"Lima Pedang condong tidak: pilih martabat daripada kemenangan dan hindari taktik yang terlalu mahal harganya."}' WHERE card_id = 'five-of-swords' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Enam Pedang","meaning":"Bagian yang sulit bergerak secara bertahap menuju kondisi yang lebih tenang. Peralihannya mungkin sepi: meninggalkan pembicaraan yang menemui jalan buntu, lingkungan lama, atau cara berpikir yang melelahkan. Anda tidak perlu melihat tujuan yang sempurna untuk mengetahui bahwa Anda sedang bergerak menuju perdamaian yang lebih besar.","advice":"Ambil apa yang telah kamu pelajari, terima dukungan, dan terus bergerak menjauh dari kekacauan.","yesNoMeaning":"Enam Pedang condong ya: ambil apa yang telah Anda pelajari, terima dukungan, dan terus menjauh dari kekacauan."}' WHERE card_id = 'six-of-swords' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Tujuh Pedang","meaning":"Strategi, kerahasiaan, atau penghindaran mempersulit jalannya. Menjaga kerahasiaan rencana terkadang dapat melindungi Anda; menghindari tanggung jawab menciptakan jarak yang berbeda. Periksa motif di balik suatu strategi sebelum memutuskan untuk menggunakannya.","advice":"Bertindaklah dengan cerdik tetapi transparan; jalan pintas yang mengkhianati kepercayaan akan kembali sebagai masalah.","yesNoMeaning":"Seven of Swords condong ke tidak: bertindaklah cerdik tetapi transparan; jalan pintas yang mengkhianati kepercayaan akan kembali sebagai masalah."}' WHERE card_id = 'seven-of-swords' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Delapan Pedang","meaning":"Ketakutan dan keyakinan yang membatasi membuat pilihan yang ada sulit dilihat. Perasaan terjebak mungkin lebih besar dari batasan yang sebenarnya ada di sekitar Anda. Saat rasa takut mereda, satu pilihan kecil, orang yang membantu, atau jalan yang terlewatkan mungkin akan terlihat.","advice":"Pertanyakan pikiran yang mengatakan kamu terjebak dan ambil satu tindakan kecil untuk membebaskan diri.","yesNoMeaning":"The Eight of Swords condong ke tidak: pertanyakan pikiran yang mengatakan Anda terjebak dan ambil satu tindakan kecil untuk membebaskan diri."}' WHERE card_id = 'eight-of-swords' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Sembilan Pedang","meaning":"Kecemasan memperbesar bahaya dalam kegelapan dan melelahkan pikiran. Pikiran yang berulang bisa terasa paling sengit saat Anda menghadapinya sendirian. Pisahkan apa yang telah terjadi dari apa yang Anda bayangkan mungkin terjadi, dan biarkan diri Anda meminta bantuan.","advice":"Bawa rasa takut ke cahaya hari, cari dukungan, dan pisahkan fakta dari hasil yang dibayangkan.","yesNoMeaning":"Sembilan Pedang condong tidak: bawa ketakutan ke cahaya, cari dukungan, dan pisahkan fakta dari hasil yang dibayangkan."}' WHERE card_id = 'nine-of-swords' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Sepuluh Pedang","meaning":"Siklus yang menyakitkan mencapai batas akhirnya dan tidak dapat berlanjut tanpa perubahan. Bagian akhir mungkin akan membuat Anda kehabisan tenaga setelah situasi berlangsung terlalu lama. Pola lama tidak dapat terus berubah, namun batasan yang lebih jelas dapat memberikan ruang bagi pemulihan secara bertahap.","advice":"Terimalah akhir itu, lindungi pemulihan Anda, dan biarkan awal yang berbeda muncul.","yesNoMeaning":"Sepuluh Pedang condong tidak: terima akhir, lindungi pemulihanmu, dan biarkan awal yang berbeda muncul."}' WHERE card_id = 'ten-of-swords' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Halaman Pedang","meaning":"Rasa ingin tahu yang waspada mencari fakta, mengajukan pertanyaan, dan mengamati perubahan. Rasa ingin tahu mendorong Anda untuk mengajukan pertanyaan dan memeriksa detail sebelum menerima suatu kesimpulan. Kewaspadaan itu mendukung pembelajaran ketika tidak menjadi kecurigaan semua orang.","advice":"Riset dengan cermat dan berbicaralah dengan presisi daripada bereaksi terhadap setiap sinyal.","yesNoMeaning":"Halaman Pedang tetap bersifat kondisional: teliti dengan cermat dan berbicaralah dengan tepat daripada bereaksi terhadap setiap sinyal."}' WHERE card_id = 'page-of-swords' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Kesatria Pedang","meaning":"Kecerdasan terfokus bergerak cepat dan menghadapi rintangan secara langsung. Ide yang jelas mungkin akan mengarahkan Anda ke depan dan membuat Anda berbicara secara langsung. Tekad bekerja paling baik ketika Anda masih mendengar bukti baru dan memperhatikan bagaimana perkataan Anda memengaruhi orang lain.","advice":"Maju dengan keberanian, tetapi cukup lambat untuk mendengar apa yang mungkin terlewatkan oleh kepastian Anda.","yesNoMeaning":"Ksatria Pedang tetap bersyarat: maju dengan keberanian, tetapi cukup lambat untuk mendengar apa yang mungkin terlewat oleh keyakinanmu."}' WHERE card_id = 'knight-of-swords' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Ratu Pedang","meaning":"Persepsi yang jelas dan batasan yang jujur menghilangkan kebingungan. Pengalaman dapat membantu Anda melihat apa yang penting di antara persaingan perasaan dan janji. Bersikaplah lugas dan pertahankan batasan yang masuk akal tanpa kehilangan rasa kasihan.","advice":"Katakan yang benar dengan penuh kasih dan biarkan pengalaman mengasah, bukan mengeraskan, dirimu.","yesNoMeaning":"Queen of Swords condong ke ya: katakan apa yang benar dengan kasih dan biarkan pengalaman menajamkan, bukan mengeraskan, dirimu."}' WHERE card_id = 'queen-of-swords' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Raja Pedang","meaning":"Alasan, keadilan, dan penilaian yang disiplin memandu keputusan yang penting. Keputusan yang sulit memerlukan standar yang konsisten dan alasan yang jelas. Otoritas kartu ini berasal dari keadilan, bukan hanya dari keputusan akhir.","advice":"Gunakan bukti, tentukan standar, dan jangan biarkan bias pribadi mempengaruhi putusan.","yesNoMeaning":"Raja Pedang condong ke ya: gunakan bukti, tetapkan standar, dan jangan biarkan bias pribadi mempengaruhi putusan."}' WHERE card_id = 'king-of-swords' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"As Koin","meaning":"Peluang nyata menawarkan benih kemakmuran, pekerjaan, atau kesejahteraan. Pembukaan praktis mungkin muncul sebagai pekerjaan, dukungan, keterampilan, atau kondisi yang lebih sehat. Nilainya bergantung pada cara perawatannya dari waktu ke waktu, tidak hanya pada permohonan pertama.","advice":"Dasarkan peluang pada rencana praktis dan rawat secara konsisten.","yesNoMeaning":"Ace of Pentacles condong ya: tanamkan kesempatan dalam rencana yang praktis dan rawat secara konsisten."}' WHERE card_id = 'ace-of-pentacles' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Dua Pentakel","meaning":"Beberapa prioritas bergerak secara bersamaan dan memerlukan keseimbangan yang fleksibel. Anda mungkin menyeimbangkan pekerjaan, uang, waktu, dan kebutuhan pribadi sekaligus. Fleksibilitas membuat segala sesuatunya terus berjalan, namun serangkaian penyesuaian yang panjang memerlukan prioritas yang lebih jelas.","advice":"Sesuaikan ritme, lindungi hal-hal penting, dan hindari berjanji lebih dari yang bisa Anda tanggung.","yesNoMeaning":"Dua Pentakel tetap bersifat kondisional: sesuaikan ritme, lindungi hal-hal penting, dan hindari berjanji lebih dari yang dapat Anda tanggung."}' WHERE card_id = 'two-of-pentacles' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Tiga Koin","meaning":"Keterampilan tumbuh melalui kolaborasi, umpan balik, dan pengerjaan yang cermat. Pekerjaan yang baik tumbuh ketika setiap orang memahami bagian dan kekuatannya. Umpan balik yang spesifik, mempelajari suatu keahlian, dan rasa hormat terhadap usaha yang tenang semuanya penting di sini.","advice":"Kontribusikan kekuatan Anda, hormati keahlian, dan bangun hingga standar bersama.","yesNoMeaning":"Tiga Pentakel condong ke ya: kontribusikan kekuatanmu, hormati keahlian, dan bangun sesuai standar bersama."}' WHERE card_id = 'three-of-pentacles' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Empat Pentakel","meaning":"Berpegang teguh pada keamanan dapat menghemat sumber daya namun membatasi aliran yang sehat. Mempertahankan sumber daya yang diperoleh dengan susah payah bisa terasa masuk akal di tengah ketidakpastian. Ketika ketakutan akan kehilangan menguasai setiap pilihan, baik uang maupun ketenangan pikiran bisa terasa terkekang.","advice":"Lindungi apa yang penting tanpa membiarkan rasa takut menentukan setiap keputusanmu.","yesNoMeaning":"Empat Pentakel tetap bersyarat: lindungi apa yang penting tanpa membiarkan ketakutan mengontrol setiap keputusanmu."}' WHERE card_id = 'four-of-pentacles' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Lima Pentakel","meaning":"Ketegangan atau pengucilan materi menimbulkan kekhawatiran dan rasa kelangkaan. Kesulitan dapat membuat Anda merasa sendirian atau tidak layak menerima bantuan. Dukungan praktis mungkin masih tetap ada, bahkan ketika kesusahan membuat jalan menuju hal tersebut sulit terlihat.","advice":"Minta bantuan praktis dan perhatikan pintu yang telah dibuat mudah untuk diabaikan oleh kesulitan.","yesNoMeaning":"Lima Pentakel condong tidak: mintalah bantuan praktis dan perhatikan pintu yang sulit yang mungkin terlewatkan karena kesulitan."}' WHERE card_id = 'five-of-pentacles' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Enam Pentakel","meaning":"Pertukaran sumber daya menimbulkan pertanyaan tentang kemurahan hati, kekuasaan, dan keadilan. Bantuan akan bekerja paling baik jika pemberi dan penerima tetap mempertahankan martabat dan suara mereka. Lihatlah apakah pertukarannya seimbang dan kondisi apa yang muncul dari kemurahan hati.","advice":"Berikan atau terima dengan ketentuan yang jelas sehingga dukungan menjaga martabat di kedua sisi.","yesNoMeaning":"Enam Pentakel condong ke ya: memberi atau menerima dengan ketentuan yang jelas sehingga dukungan menjaga martabat di kedua sisi."}' WHERE card_id = 'six-of-pentacles' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Tujuh Pentakel","meaning":"Investasi yang sabar mencapai titik penilaian sebelum upaya berikutnya. Anda telah menginvestasikan upaya, tetapi hasilnya mungkin tidak sesuai dengan jadwal yang Anda inginkan. Tinjau kemajuannya dan bedakan apa yang memerlukan lebih banyak kesabaran dan apa yang memerlukan pendekatan baru.","advice":"Tinjau apa yang sedang berkembang, perbaiki metode, dan beri waktu untuk hasil yang berharga.","yesNoMeaning":"Tujuh Pentakel tetap bersyarat: tinjau apa yang sedang tumbuh, perbaiki metode, dan beri waktu untuk hasil yang berharga."}' WHERE card_id = 'seven-of-pentacles' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Delapan Koin","meaning":"Pengulangan yang terfokus mengembangkan penguasaan dan hasil yang dapat diandalkan. Keterampilan berkembang melalui pengulangan, koreksi, dan perhatian terhadap detail-detail kecil. Kartu ini menghargai latihan terus-menerus yang mungkin tidak pernah dilihat orang lain, daripada lompatan tiba-tiba.","advice":"Latih keterampilan penting, sambut koreksi, dan biarkan kualitas terkumpul.","yesNoMeaning":"The Eight of Pentacles condong ke ya: latih keterampilan yang esensial, sambut koreksi, dan biarkan kualitas menumpuk."}' WHERE card_id = 'eight-of-pentacles' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Sembilan Pentakel","meaning":"Kemandirian dan kenyamanan yang dipupuk mencerminkan kemajuan yang disiplin. Kenyamanan Anda saat ini mungkin mencerminkan banyak pilihan disiplin yang Anda buat sebelumnya. Nikmati apa yang telah Anda bangun sesuai kecepatan Anda sendiri dan kenali pekerjaan di baliknya.","advice":"Nikmati apa yang telah Anda bangun dan pertahankan kemandirian yang terhubung dengan rasa syukur.","yesNoMeaning":"Sembilan Koin condong ya: nikmati apa yang telah kamu bangun dan pertahankan kemandirian dengan mengaitkannya pada rasa syukur."}' WHERE card_id = 'nine-of-pentacles' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Sepuluh Koin","meaning":"Keamanan jangka panjang tumbuh melalui warisan, keluarga, dan yayasan bersama. Kisahnya tidak hanya mencakup kesuksesan seseorang, tetapi juga keluarga, komunitas, atau orang-orang yang mengikutinya. Fondasi yang kokoh tumbuh dari kepedulian yang penuh perhatian terhadap sumber daya bersama.","advice":"Rencanakan lebih dari sekadar kemenangan sesaat dan lindungi apa yang dapat mendukung orang lain seiring waktu.","yesNoMeaning":"Sepuluh Koin condong ya: rencanakan melampaui kemenangan langsung dan lindungi apa yang dapat mendukung orang lain seiring waktu."}' WHERE card_id = 'ten-of-pentacles' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Halaman Koin","meaning":"Pesan praktis mengundang pembelajaran, perencanaan, atau usaha baru yang membumi. Peluang praktis menjadi lebih jelas ketika Anda mempelajari dasar-dasarnya. Jelajahi dengan sabar, ujilah dalam skala kecil, dan perhatikan apa yang memiliki nilai abadi.","advice":"Pelajari dasar-dasarnya, tentukan tugas selanjutnya, dan buktikan ide melalui kerja yang konsisten.","yesNoMeaning":"Halaman Pentakel condong ke ya: pelajari dasar-dasarnya, tentukan tugas berikutnya, dan buktikan ide melalui kerja yang konsisten."}' WHERE card_id = 'page-of-pentacles' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Kesatria Koin","meaning":"Upaya yang dapat diandalkan berkembang secara perlahan namun jarang meninggalkan tugas. Kemajuan mungkin terasa sangat lambat sehingga Anda bertanya-tanya apakah Anda sudah bergerak, namun konsistensi adalah fondasi yang membangun. Keandalan juga membutuhkan ruang untuk istirahat.","advice":"Pertahankan rutinitas jujur dan konsisten; kemajuan lebih penting daripada kegembiraan.","yesNoMeaning":"Ksatria Koin condong ke ya: jaga rutinitas tetap jujur dan konsisten; kemajuan lebih penting daripada kegembiraan."}' WHERE card_id = 'knight-of-pentacles' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Ratu Pentakel","meaning":"Perawatan yang cerdas menciptakan kenyamanan, kesehatan, dan kelimpahan praktis. Keselamatan dapat diciptakan melalui tindakan nyata kepedulian dan penggunaan sumber daya secara bijaksana. Kemurahan hati yang berkelanjutan dimulai dengan mengingat kebutuhan Anda sendiri juga.","advice":"Rawat orang dan rencana dengan cara yang tetap berkelanjutan untukmu.","yesNoMeaning":"Queen of Pentacles condong ke ya: rawat orang dan rencana dengan cara yang tetap berkelanjutan untukmu."}' WHERE card_id = 'queen-of-pentacles' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"Raja Koin","meaning":"Kepemimpinan material mengubah pengalaman menjadi penatalayanan yang stabil dan murah hati. Pengalaman dapat mendukung masa depan yang stabil untuk pekerjaan, keluarga, atau komunitas. Kesuksesan akan lebih bermakna ketika orang-orang yang membantu membangunnya dapat berbagi stabilitas tersebut.","advice":"Buat pilihan jangka panjang yang bijaksana dan gunakan kesuksesan dengan bertanggung jawab.","yesNoMeaning":"Raja Koin condong ke ya: buat pilihan jangka panjang yang bijaksana dan gunakan keberhasilan secara bertanggung jawab."}' WHERE card_id = 'king-of-pentacles' AND locale = 'id';
UPDATE card_translations SET payload = '{"name":"मूर्ख","meaning":"एक खाली पन्ना और विश्वास की छलांग - एक नई यात्रा खुले दिल से शुरू होती है। पहला कदम उठाने से पहले आपको पूरे मानचित्र की आवश्यकता नहीं है। जिज्ञासा आपको प्रत्येक प्रयास से सीखने में मदद करती है, जबकि थोड़ी सी तैयारी आज़ादी को लापरवाही में बदलने से रोकती है।","advice":"अपने सामने के रास्ते पर भरोसा करें और पहला कदम उठाएँ, भले ही सभी उत्तर आपके पास न हों।","yesNoMeaning":"एक नई शुरुआत शायद ही कभी एक निश्चित उत्तर लेकर आती है — परिणाम उस कदम पर निर्भर करता है जो आप उठाते हैं।"}' WHERE card_id = 'fool' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"मैजिशियन","meaning":"आपके पास वे सभी उपकरण हैं जिनकी आपको आवश्यकता है। अपनी इच्छाशक्ति पर ध्यान केंद्रित करें और इरादे को कार्य में बदलें। एक विचार तब वास्तविक हो जाता है जब आपका ध्यान, समय और उपलब्ध संसाधन उसी कार्य की ओर इशारा करते हैं। किसी अन्य संकेत की प्रतीक्षा करने से पहले उन उपकरणों को देखें जो आपकी पहुंच में हैं।","advice":"अपने कौशल और संसाधनों का जानबूझकर उपयोग करें — अब इसे करने का समय है।","yesNoMeaning":"आपके पास पहले से ही सब कुछ है जो आवश्यक है — ऊर्जा आगे बढ़ने और केंद्रित रहने में सहायक है।"}' WHERE card_id = 'magician' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"द हाई प्रीस्टेस","meaning":"शांत ज्ञान सतह के नीचे छिपा रहता है। अपने अंतर्ज्ञान और आंतरिक आवाज को सुनें। मौन एक पैटर्न, एक ऐसी भावना को प्रकट कर सकता है जिसे आप अभी तक नाम नहीं दे सकते हैं, या ऐसी जानकारी जो अभी भी गायब है। हर चीज़ को खुले में लाने से पहले थोड़ी देर और निरीक्षण करें।","advice":"रोकें, अंदर की ओर जाएं, और कार्रवाई करने से पहले अपने अंतर्ज्ञान को मार्गदर्शन करने दें।","yesNoMeaning":"उत्तर अभी सतह के नीचे छिपा है — स्पष्ट हाँ या नहीं को जबरदस्ती करने के बजाय अपनी अंतर्दृष्टि पर भरोसा करें।"}' WHERE card_id = 'high-priestess' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"रानी","meaning":"विकास, प्रचुरता और पोषणकारी ऊर्जा आपके चारों ओर है। सुंदरता और देखभाल को फलने-फूलने दें। कोई रिश्ता, प्रोजेक्ट या आपका कोई हिस्सा निरंतर देखभाल के माध्यम से विकसित हो सकता है। यहां प्रचुरता का अर्थ है विकास के लिए जगह होना, न कि तब तक देना जब तक आपके पास कुछ न बचे।","advice":"धैर्यशील और उदार बनें — प्यार के साथ सृजन करें और चीज़ों को स्वाभाविक रूप से पकने दें।","yesNoMeaning":"विकास, समृद्धि और पोषणकारी ऊर्जा आपकी इच्छा का समर्थन करती हैं — उत्तर एक शांत हाँ है।"}' WHERE card_id = 'empress' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"साम्राज्यकारी","meaning":"संरचना, अधिकार और स्थिर नेतृत्व। अनुशासन के साथ ठोस जमीन पर निर्माण करें। एक उपयोगी संरचना लोगों को बढ़ने की सुरक्षा देती है। जिम्मेदारी लेने और हर विवरण को नियंत्रित करने की कोशिश के बीच अंतर पर ध्यान दें; वे पहली बार में एक जैसे दिख सकते हैं।","advice":"साफ़ योजना के साथ जिम्मेदारी लें; ठोस सीमाएं स्थायी स्थिरता लाती हैं।","yesNoMeaning":"संरचना, अधिकार और स्थिर अनुशासन आत्मविश्वासी हाँ के पीछे खड़ा है।"}' WHERE card_id = 'emperor' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"द हायरोफैंट","meaning":"परंपरा और विश्वसनीय मार्गदर्शन एक विश्वसनीय मार्ग प्रदान करते हैं। जो पहले आया है उससे सीखें. एक शिक्षक, समुदाय या स्थापित पद्धति एक अच्छा प्रारंभिक बिंदु प्रदान कर सकती है। जानें कि कोई परंपरा क्यों काम करती है ताकि आप इसे सोच-समझकर अपनी स्थिति में लागू कर सकें।","advice":"स्थापित ज्ञान का पालन करें और उन लोगों से परामर्श लें जिन पर आप भरोसा करते हैं।","yesNoMeaning":"परंपरा और भरोसेमंद मार्गदर्शन एक विश्वसनीय हाँ की ओर संकेत करते हैं — उस पर भरोसा करें जो पहले से ही अपने आप को साबित कर चुका है।"}' WHERE card_id = 'hierophant' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"लवर्स","meaning":"एक सार्थक बंधन या एक महत्वपूर्ण विकल्प. आपका हृदय वास्तव में जिसे महत्व देता है उसका पालन करें। स्थायी सद्भाव दोनों पक्षों को जरूरतों और सीमाओं के बारे में ईमानदारी से बोलने के लिए कहता है। यदि यह रोमांस के बजाय एक निर्णय है, तो पूछें कि कौन सा रास्ता आपके गहरे मूल्यों को दर्शाता है।","advice":"ईमानदारी और संरेखण के साथ चुनें — जब आप सच्चे होते हैं तो संबंध गहरा होता है।","yesNoMeaning":"यहाँ आपका दिल और मूल्य संरेखित हैं — उत्तर हाँ है, खासकर जब आप ईमानदारी के साथ चुनाव करते हैं।"}' WHERE card_id = 'lovers' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"सिंहासन","meaning":"इच्छाशक्ति और गति आपको आगे ले जाती है। केंद्रित रहें और आप जीतेंगे। जब आप उन्हें एक साझा दिशा देते हैं तो विरोधी आवेग भी आपको आगे ले जा सकते हैं। प्रगति आपकी भावनाओं और कार्यों को नियंत्रित करने पर निर्भर करती है, न कि केवल अधिक प्रयास करने पर।","advice":"अपने लक्ष्य पर ध्यान रखें और हर बाधा के माध्यम से आत्मविश्वास के साथ मार्गदर्शन करें।","yesNoMeaning":"इच्छाशक्ति और गति आपके पक्ष में हैं — एक केंद्रित हाँ, बशर्ते आप प्रतिबद्ध रहें।"}' WHERE card_id = 'chariot' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"शक्ति","meaning":"सच्ची शक्ति कोमल होती है - धैर्य, साहस और करुणा किसी भी चुनौती को वश में कर लेती है। सज्जनता साहस का एक सक्रिय रूप है: आप असुविधा के साथ रह सकते हैं बिना इसे अपनी प्रतिक्रिया तय करने दें। डर को स्वीकार करें और डर के ख़त्म होने का इंतज़ार करने के बजाय सावधानी से आगे बढ़ें।","advice":"शांत ताकत के साथ नेतृत्व करें; एक नरम हाथ अक्सर सबसे मजबूत होता है।","yesNoMeaning":"नम्र साहस और धैर्यपूर्ण संकल्प इसे हाँ बनाते हैं — शक्ति से नहीं, शांति से नेतृत्व करें।"}' WHERE card_id = 'strength' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"द हर्मिट","meaning":"पीछे हटने और आंतरिक स्पष्टता की तलाश करने का समय आ गया है। एकांत अब गहरे उत्तर लाता है। पीछे हटने से दूसरे लोगों की राय के बीच आपकी अपनी आवाज़ सुनना आसान हो सकता है। एकांत तब मदद करता है जब यह समझ की ओर ले जाता है, लेकिन यह जुड़ाव से बचने का एक तरीका भी बन सकता है।","advice":"अंदर की ओर मुड़ें, विचार करें, और शांति से यह जानने दें कि आपको वास्तव में क्या चाहिए।","yesNoMeaning":"अभी नहीं — कार्ड आपसे कहता है कि कार्रवाई करने से पहले पीछे हटकर आंतरिक स्पष्टता खोजें।"}' WHERE card_id = 'hermit' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"भाग्य का चक्र","meaning":"भाग्य बदल जाता है और चक्र बदल जाता है। अब जो परिवर्तन हो रहा है वह एक बड़ी लय का हिस्सा है। कोई पुराना चक्र घूम सकता है, जो संभावना के साथ-साथ असुविधा भी लेकर आ रहा है। आप हर घटना को नहीं चुन सकते, लेकिन आप यह चुन सकते हैं कि क्या आगे बढ़ाना है और अगले चरण के लिए कैसे तैयारी करनी है।","advice":"लचीलापन के साथ प्रवाह का आनंद लें — मोड़ को स्वीकार करें, चाहे अच्छा हो या अन्यथा।","yesNoMeaning":"भाग्य बदल रहा है — परिणाम इस बात पर निर्भर करता है कि आप बदलाव को कैसे संभालते हैं, न कि एक निश्चित हाँ या ना पर।"}' WHERE card_id = 'wheel-of-fortune' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"न्याय","meaning":"सच्चाई और निष्पक्षता दिन ले जाती है। कारण और प्रभाव अब संतुलन में आ गए हैं। जो कुछ हो रहा है वह एक अलग क्षण के बजाय पहले के विकल्पों की एक श्रृंखला को प्रतिबिंबित कर सकता है। तथ्यों की जाँच करें, इसमें शामिल लोगों की बात सुनें और जो हिस्सा आपका है उस पर अपना अधिकार रखें।","advice":"ईमानदारी से काम करें और दोनों पक्षों को तौलें; तराजू निष्पक्ष रूप से संतुलित होंगे।","yesNoMeaning":"तराजू अभी भी तौल रहे हैं — निष्पक्ष उत्तर तथ्यों और आपकी ईमानदारी पर निर्भर करता है।"}' WHERE card_id = 'justice' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"हैंग्ड मैन","meaning":"कुछ समय रुकना स्थिति को नए नज़रिए से देखने का अवसर दे सकता है। यदि आप हर समस्या का हल तुरंत कार्रवाई में ढूँढ़ते हैं, तो प्रतीक्षा कठिन लग सकती है। थोड़ा नियंत्रण छोड़ने या किसी अपेक्षा को जाने देने से वह बात स्पष्ट हो सकती है जो दबाव बढ़ाने से नहीं दिखती।","advice":"धक्कामुक्की करना बंद करें — क्षण को स्वीकार करें और नई दृष्टि आने दें।","yesNoMeaning":"पहले विराम की आवश्यकता है — इसे अभी जबरदस्ती करना केवल स्पष्ट उत्तर को रोक देगा।"}' WHERE card_id = 'hanged-man' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"मृत्यु","meaning":"अंत नवीनीकरण का रास्ता साफ़ करता है। जो अपना समय पूरा कर चुका है, उसे जाने दें। यह कार्ड हानि की शाब्दिक भविष्यवाणी के बजाय परिवर्तन की बात करता है। हो सकता है कि आप किसी पुरानी भूमिका, आदत या अपेक्षा से आगे निकल गए हों; इसे पीछे छोड़ने में अभी भी समय लग सकता है।","advice":"पछतावा किए बिना छोड़ दें; एक गहन परिवर्तन एक नया दरवाज़ा खोल रहा है।","yesNoMeaning":"एक अंत रास्ता साफ कर रहा है — वर्तमान मार्ग बंद हो रहा है ताकि एक नया मार्ग शुरू हो सके।"}' WHERE card_id = 'death' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"संयम","meaning":"संतुलन और धैर्य सद्भाव लाते हैं। विपरीतताओं को अनुग्रह के साथ मिश्रित करें। दो अलग-अलग दृष्टिकोणों से क्या मिश्रित किया जा सकता है, इसकी तलाश करें। शांत प्रगति एक स्थायी आदत, शांत बातचीत या ऐसी गति का रूप ले सकती है जिसे आप वास्तव में बनाए रख सकते हैं।","advice":"संतुलन में चलें और अपनी शांति बनाए रखें — स्थिर कदम मंजिल तक पहुंचते हैं।","yesNoMeaning":"संतुलन और धैर्य सामंजस्य लाते हैं — एक मापा हुआ हाँ, धीरे-धीरे एक कदम में लिया गया।"}' WHERE card_id = 'temperance' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"शैतान","meaning":"आसक्ति, प्रलोभन या कोई पुरानी आदत आपके चुनाव सीमित कर सकती है। थोड़े समय का लाभ उस आदत को छोड़ना कठिन बना देता है, भले ही उसकी कीमत लंबे समय तक चुकानी पड़े। उससे आपको क्या मिलता है और क्या खोना पड़ता है, इसे साफ़ देखने से चुनाव की स्वतंत्रता धीरे-धीरे लौट सकती है।","advice":"उस चीज़ को नाम दें जो आपको रोकती है और अपनी स्वतंत्रता वापस पाएं — जंजीर केवल तब बंधती है जब आप इसे अनुमति दें।","yesNoMeaning":"असक्ति या एक बंधन पैटर्न रास्ते में खड़ा होता है — अभी नहीं, जब तक श्रृंखला का नाम न रखा जाए और तोड़ा न जाए।"}' WHERE card_id = 'devil' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"टॉवर","meaning":"अचानक बदलाव किसी भरोसेमंद योजना को हिला सकता है और छिपी हुई सच्चाई सामने ला सकता है। ऐसे समय में तुरंत कोई सकारात्मक अर्थ ढूँढ़ना ज़रूरी नहीं। पहले देखें कि वास्तव में क्या बदला है और क्या अब भी आपका सहारा बन सकता है; फिर नए आधार पर आगे बढ़ें।","advice":"विपरीत परिस्थितियों का स्वागत करें; मलबे से एक स्पष्ट नींव बनाई जा सकती है।","yesNoMeaning":"अचानक परिवर्तन पुराना तोड़ रहा है — स्थिर हाँ संभव होने से पहले जमीन को जमना चाहिए।"}' WHERE card_id = 'tower' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"स्टार","meaning":"आशा, उपचार और शांत प्रेरणा तूफान के बाद आपकी आत्मा को नवीनीकृत करती है। आशा कोई वादा नहीं है कि सब कुछ अपने आप हल हो जाएगा। यह कठिनाई के बाद सांस लेने और परिणाम दिखाई देने से पहले जो मायने रखता है उसकी देखभाल जारी रखने के लिए जगह है।","advice":"आगे की रोशनी पर विश्वास रखें और विश्वास करते रहें — आपकी इच्छाएँ पहुँच के भीतर हैं।","yesNoMeaning":"आशा और शांत नवीनीकरण हाँ की ओर संकेत करते हैं — आने वाले प्रकाश पर भरोसा करें और अपनी इच्छा को जीवित रखें।"}' WHERE card_id = 'star' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"मून","meaning":"भ्रम और अनिश्चितता रास्ता धुंधला कर देती है। अपने अंतर्ज्ञान पर भरोसा करें, दिखावे पर नहीं। जब तथ्य अधूरे हों, तो स्मृति और भय एक ठोस कहानी से उस कमी को पूरा कर सकते हैं। धीमा करें, अपनी प्रतिक्रिया पर ध्यान दें और जो आपने सत्यापित किया है उससे जो आप महसूस करते हैं उसे अलग करें।","advice":"धीरे हो जाएँ और गहराई से देखें; स्पष्टता तब आएगी जब धुंध छट जाएगी।","yesNoMeaning":"भ्रम और अनिश्चितता रास्ते को धुंधला कर देते हैं — जवाब स्पष्ट नहीं होता जब तक आप बाहरी रूपों के नीचे नहीं देखते।"}' WHERE card_id = 'moon' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"सन","meaning":"खुशी, सफलता और उज्ज्वल स्पष्टता। सब कुछ उज्ज्वल और जीवन से भरपूर है। स्पष्टता आपको अपनी प्रगति को पहचानने और उसे कम किए बिना खुशी साझा करने में मदद कर सकती है। यदि काम बना रहता है, तो यह नवीनीकृत ऊर्जा आपको इसे अधिक खुले तौर पर पूरा करने में मदद कर सकती है।","advice":"जश्न मनाएं और चमकें — सकारात्मक ऊर्जा उन परिणामों को आकर्षित करती है जो आप चाहते हैं।","yesNoMeaning":"खुशी और प्रज्वलित स्पष्टता एक उज्ज्वल हां की पुष्टि करती है — सब कुछ आपके पक्ष में काम कर रहा है।"}' WHERE card_id = 'sun' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"न्याय","meaning":"उठने, नवीनीकरण करने और स्वयं के प्रति ईमानदार रहने का आह्वान। जागृति का फैसला. अतीत की समीक्षा करने का मतलब हमेशा के लिए खुद को दोष देना नहीं है। सबक लें, जो आप कर सकते हैं उसे माफ करें, और अब सचेत विकल्प के साथ बदलाव के आह्वान का उत्तर दें।","advice":"साहस के साथ कॉल का जवाब दें; अतीत को क्षमा करें और अपने अगले अध्याय में कदम रखें।","yesNoMeaning":"उठने और नवीनीकरण का आह्वान — हाँ, विशेष रूप से जब आप अतीत को माफ कर देते हैं और ईमानदारी से उत्तर देते हैं।"}' WHERE card_id = 'judgement' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"दुनिया","meaning":"पूर्णता और पूर्णता - एक चक्र पूर्णता में समाप्त होता है। उपलब्धि में आपके द्वारा इस दौरान हासिल किए गए कौशल, रिश्ते और परिप्रेक्ष्य शामिल हैं। इस चक्र के पूरा होने का सम्मान करें, भले ही एक व्यापक यात्रा जारी रहे।","advice":"आपने जो हासिल किया है उसका जश्न मनाएं; दरवाजा एक व्यापक दुनिया के लिए खुला है।","yesNoMeaning":"समापन और पूर्णता इसे एक पूर्ण हां के रूप में चिह्नित करती है — चक्र आपके पक्ष में बंद होता है।"}' WHERE card_id = 'world' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"छड़ी का एस","meaning":"प्रेरणा की एक चिंगारी एक साहसिक रचनात्मक मार्ग खोलती है। कोई निमंत्रण, प्रोजेक्ट या नई इच्छा आपको अधिक जीवंत महसूस करा सकती है। यह गारंटीकृत परिणाम के बजाय संभावित है; पहला उत्साह फीका पड़ने के बाद इसे प्रयोग और प्रतिबद्धता के लिए जगह की आवश्यकता होती है।","advice":"ताजगी भरी ऊर्जा के समय शुरू करें और विचार को एक वास्तविक पहला कदम दें।","yesNoMeaning":"डंडों का ऐस हां की ओर झुकाव रखता है: जब ऊर्जा ताज़ा हो, तब शुरुआत करें और विचार को वास्तविक पहला कदम दें।"}' WHERE card_id = 'ace-of-wands' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"दो छड़ें","meaning":"योजना और दिशा के चयन से भविष्य आकार ले रहा है। आप एक से अधिक मार्ग देख सकते हैं और पूछने लगे हैं कि आप कितनी दूर तक जाना चाहते हैं। एक व्यापक दृष्टिकोण मदद करता है, लेकिन अंतहीन योजना आपको दहलीज पर रख सकती है।","advice":"जो परिचित है उसके परे देखें, फिर उस रास्ते के लिए प्रतिबद्ध हों जिसमें बढ़ने की जगह हो।","yesNoMeaning":"छड़ी की दोहरी शर्तों पर निर्भर रहती है: परिचित चीजों के परे देखें, फिर बढ़ने की जगह के साथ मार्ग को अपनाएँ।"}' WHERE card_id = 'two-of-wands' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"तीन छड़ें","meaning":"अवसर और व्यापक क्षितिज सामने आने पर प्रारंभिक प्रयास का विस्तार होता है। आपने जो शुरू किया है वह परिचित क्षेत्र से परे प्रतिक्रिया प्राप्त करना शुरू कर रहा है। अपने पहले के काम को फल देने के लिए समय देते हुए संपर्कों और फीडबैक के लिए खुले रहें।","advice":"निर्माण करते रहें और तैयार रहें कि आपका काम जिस प्रतिक्रिया को आकर्षित करता है उसे देखें।","yesNoMeaning":"डंडों का तीन हाँ की ओर झुकता है: निर्माण जारी रखें और अपने काम द्वारा आकर्षित प्रतिक्रिया के लिए तैयार रहें।"}' WHERE card_id = 'three-of-wands' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"वांड का चार","meaning":"स्थिरता, स्वागत और साझा उत्सव एक मजबूत आधार बनाते हैं। एक मील का पत्थर उत्सव का पात्र है, भले ही यात्रा समाप्त न हुई हो। अपनापन और जिन लोगों ने इस पल को बनाने में मदद की, वे आपके अगले कदम को मजबूत कर सकते हैं।","advice":"चिह्नित करें और सहायक लोगों को इसमें शामिल होने दें।","yesNoMeaning":"चार वैंड्स हां की ओर झुकते हैं: इस मील के पत्थर को चिह्नित करें और इसे साझा करने के लिए सहायक लोगों को अनुमति दें।"}' WHERE card_id = 'four-of-wands' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"पाँच कांटे","meaning":"प्रतिस्पर्धा का उद्देश्य घर्षण, शोर या आत्मविश्वास की परीक्षा पैदा करना है। कई प्रतिस्पर्धी आवाजें साझा लक्ष्य को छिपा सकती हैं। संघर्ष एक विचार को तीव्र कर सकता है जब हर कोई जानता है कि वे वास्तव में किस पर बहस कर रहे हैं और मतभेदों को सुन सकते हैं।","advice":"प्रतिस्पर्धा को उपयोगी अभ्यास में बदलें और ऐसे संघर्ष से इंकार करें जिसका कोई उद्देश्य न हो।","yesNoMeaning":"दस्तों का पांच शर्तीय बना रहता है: प्रतिद्वंद्विता को उपयोगी अभ्यास में बदलें और उस संघर्ष से इंकार करें जिसका कोई उद्देश्य नहीं है।"}' WHERE card_id = 'five-of-wands' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"सिक्स ऑफ वैंड्स","meaning":"मान्यता दृढ़ प्रयास और दृश्यमान प्रगति के बाद आती है। आपका प्रयास आख़िरकार दूसरों को नज़र आ सकता है। पहचान आपको प्रोत्साहित कर सकती है, लेकिन आपके काम का मूल्य तब भी बना रहता है जब कोई दर्शक नहीं देख रहा हो।","advice":"प्रोत्साहन को स्वीकार करें, लेकिन अपने आत्मविश्वास को ईमानदार काम से जोड़े रखें।","yesNoMeaning":"सिक्स ऑफ वैंड्स हाँ की ओर झुकता है: प्रोत्साहन को स्वीकार करें, लेकिन अपनी आत्मविश्वास ईमानदार काम से जुड़ा रखें।"}' WHERE card_id = 'six-of-wands' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"कैंट का सात","meaning":"जब दबाव आपके संकल्प की परीक्षा लेता है तो आप मूल्यवान आधार रखते हैं। जो मायने रखता है उसकी रक्षा करने के लिए यह जानना आवश्यक है कि यह आपके लिए क्यों मायने रखता है। दबाव कई दिशाओं से आ सकता है, फिर भी हर चुनौती लड़ाई के लायक नहीं होती।","advice":"जिन बातों की अहमियत है, उनकी रक्षा स्पष्ट सीमाओं के साथ करें बजाय हर चुनौती से लड़ने के।","yesNoMeaning":"सेवन ऑफ वैंड्स हाँ की ओर झुकता है: हर चुनौती से लड़ने के बजाय स्पष्ट सीमाओं के साथ महत्वपूर्ण चीजों की रक्षा करें।"}' WHERE card_id = 'seven-of-wands' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"डंडों के आठ","meaning":"घटनाओं में तेजी आती है, संदेश आते हैं और गति देरी को दूर करती है। समाचार या निर्णय अपेक्षा से अधिक तेजी से आ सकते हैं। जब हर कोई दिशा समझता है तो गति मदद करती है; अस्पष्ट जानकारी गति को भ्रम में बदल सकती है।","advice":"तुरंत कार्रवाई करें और रास्ता खुला होने पर संचार को सीधा रखें।","yesNoMeaning":"छड़ी का आठ संकेत हाँ दर्शाता है: तुरंत कार्य करें और जब रास्ता खुला हो तो संचार को सीधे रखें।"}' WHERE card_id = 'eight-of-wands' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"नाइन ऑफ वैंड्स","meaning":"लचीलापन मजबूत है, हालांकि पिछला तनाव आपको सतर्क बनाता है। पिछले तनाव ने आपको सिखाया है कि अपनी सुरक्षा कैसे करें, लेकिन निरंतर सतर्कता थका देने वाली होती है। आज के सबूतों के साथ-साथ कल के घावों के आधार पर अपने सामने जोखिम का आकलन करें।","advice":"अपनी ऊर्जा की सुरक्षा करें और अगला कदम उठाएँ बिना यह उम्मीद किए कि हर घाव दोहराएगा।","yesNoMeaning":"नाइन ऑफ वांड्स शर्तीय बना रहता है: अपनी ऊर्जा की रक्षा करें और अगले कदम को बिना हर घाव दोहराए होने की उम्मीद किए उठाएं।"}' WHERE card_id = 'nine-of-wands' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"डंडों का दस","meaning":"ज़िम्मेदारी भारी हो गई है और सफलता अब बोझ लेकर आती है। जिस चीज़ पर आपको कभी गर्व था, उस पर अब बहुत सारी ज़िम्मेदारियाँ आ सकती हैं। आपकी क्षमता वास्तविक है, लेकिन इसके लिए जरूरी नहीं है कि आप हर काम अकेले ही करें।","advice":"कार्य सौंपें, सरल बनाएं, और उस काम को छोड़ दें जो अब वास्तव में आपका नहीं है।","yesNoMeaning":"डंडों का दस नहीं की ओर झुकता है: कार्य सौंपें, सरल बनाएं, और उस काम को छोड़ दें जो अब वास्तव में आपका नहीं है।"}' WHERE card_id = 'ten-of-wands' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"वैंड्स का पृष्ठ","meaning":"जिज्ञासा एक जीवंत संदेश, प्रयोग या नई रचनात्मक रुचि लेकर आती है। एक ताज़ा विचार एक नौसिखिया का उत्साह वापस ला सकता है। खोज करने से पहले आपको हर चीज़ में महारत हासिल करने की ज़रूरत नहीं है; अपने आप को अभ्यास में प्रयास करने, समायोजित करने और सीखने की अनुमति दें।","advice":"साहस के साथ खोज करें और शुरुआत की ऊर्जा आपको क्रियाओं के माध्यम से सिखाए।","yesNoMeaning":"पेज ऑफ वांड्स हाँ की ओर झुकाव रखता है: साहस के साथ खोज करें और शुरुआती ऊर्जा को क्रिया के माध्यम से सीखने दें।"}' WHERE card_id = 'page-of-wands' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"वैंड्स का नाइट","meaning":"जुनून तेजी से आगे बढ़ता है, रोमांच और संभावित अधीरता लाता है। किसी नई चीज़ की चाहत आपको तुरंत वहां से चले जाने के लिए प्रेरित कर सकती है। यह ऊर्जा तब आपकी सबसे अच्छी सेवा करती है जब एक स्पष्ट लक्ष्य आपको हर गुजरते आवेग के साथ दिशा बदलने से रोकता है।","advice":"गति का उपयोग करें, लेकिन गति आपके प्रयास को फैलाने से पहले दिशा चुनें।","yesNoMeaning":"वांड्स का नाइट शर्तीय रहता है: गति का उपयोग करें, लेकिन दिशा चुनें इससे पहले कि गति आपके प्रयास को बिखेर दे।"}' WHERE card_id = 'knight-of-wands' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"वांड्स की रानी","meaning":"हार्दिक आत्मविश्वास और रचनात्मक स्वतंत्रता दूसरों को आपके दृष्टिकोण की ओर आकर्षित करती है। आपकी खुली उपस्थिति दूसरों को साझा दृष्टिकोण में विश्वास करने के लिए प्रोत्साहित कर सकती है। यहां आत्मविश्वास के लिए किसी से आगे निकलने की आवश्यकता नहीं है; यह दूसरों के लिए भी चमकने की जगह बनाता है।","advice":"अपनी उपस्थिति पर भरोसा करें, दूसरों को प्रोत्साहित करें, और अपनी महत्वाकांक्षा को छोटा न करें।","yesNoMeaning":"वैंड्स की रानी झुकती है हाँ की ओर: अपनी उपस्थिति पर विश्वास करें, दूसरों को प्रोत्साहित करें, और अपनी महत्वाकांक्षा को मत घटाएं।"}' WHERE card_id = 'queen-of-wands' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"वैंड्स का राजा","meaning":"परिपक्व दृष्टि प्रेरणा को निर्णायक एवं नैतिक नेतृत्व में बदल देती है। एक बड़े दृष्टिकोण के लिए निर्णय, जिम्मेदारी और टीम की ऊर्जा को बनाए रखने की क्षमता की आवश्यकता होती है। केवल दबाव या अहंकार के बजाय स्पष्ट उद्देश्य के साथ आगे बढ़ें।","advice":"बड़े उद्देश्य से नेतृत्व करें और दूसरों को योगदान करने की जगह दें।","yesNoMeaning":"किंग ऑफ वैंड्स हां की ओर झुकते हैं: बड़े उद्देश्य से नेतृत्व करें और दूसरों को योगदान देने के लिए स्थान दें।"}' WHERE card_id = 'king-of-wands' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"कप्स का ऐस","meaning":"हृदय नए स्नेह, करुणा और भावनात्मक नवीनीकरण के लिए खुलता है। एक मुलाक़ात, एक नई भावना, या एक आंतरिक नरमी आपको अधिक स्वतंत्र रूप से देने और प्राप्त करने के लिए आमंत्रित कर सकती है। भावना को किसी विशेष परिणाम की ओर बाध्य करने से पहले उसे स्वीकार किया जाए।","advice":"भावना को ईमानदारी से स्वीकार करें और बिना किसी परिणाम की मजबूरी के देखभाल का प्रवाह होने दें।","yesNoMeaning":"कपों का ऐस हां की ओर झुकाव रखता है: भावना को ईमानदारी से स्वीकार करें और परिणाम को ज़बरदस्ती किए बिना देखभाल बहने दें।"}' WHERE card_id = 'ace-of-cups' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"दो कप्स","meaning":"आपसी मान्यता साझेदारी, आकर्षण या ईमानदार समझौता बनाती है। गहरा वादा इस बात में निहित है कि दो लोग प्रारंभिक आकर्षण से परे, एक-दूसरे को स्पष्ट रूप से देख रहे हैं। एक ईमानदार बातचीत, माफी या निष्पक्ष समझौता बंधन को मजबूत कर सकता है।","advice":"दूसरे व्यक्ति से समानता के साथ मिलें और दिल से बोलें।","yesNoMeaning":"कप की दोहरी हाँ की ओर झुकती है: दूसरे व्यक्ति से बराबरी के रूप में मिलें और दिल से बोलें।"}' WHERE card_id = 'two-of-cups' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"तीन प्यालों का","meaning":"मित्रता, समुदाय और साझा आनंद भावनात्मक समर्थन लाते हैं। एक छोटी सी सभा या समय पर समर्थन आपको याद दिला सकता है कि खुशी को अकेले ले जाने की जरूरत नहीं है। उन लोगों को याद रखें जो चीजें आसान होने से पहले आपके साथ खड़े थे।","advice":"साथ में जश्न मनाएं और याद रखें कि वास्तव में कौन आपके लिए मौजूद है।","yesNoMeaning":"प्यालों का तीन हाँ की ओर झुकता है: साथ मिलकर जश्न मनाएं और याद रखें कि वास्तव में कौन आपके लिए उपस्थित होता है।"}' WHERE card_id = 'three-of-cups' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"कप का चार","meaning":"भावनात्मक वापसी से उपलब्ध उपहार पर ध्यान देना मुश्किल हो जाता है। जब आप थके हुए या हतोत्साहित होते हैं, तो एक अच्छा प्रस्ताव भी नीरस लग सकता है। यह निर्णय लेने से पहले कि आपके आसपास कुछ भी मायने नहीं रखता, अपनी वर्तमान भावनाओं के प्रति ईमानदार रहें।","advice":"तुलना को रोकें और फिर से देखें कि क्या चुपचाप प्रस्तुत किया जा रहा है।","yesNoMeaning":"कप का चार झुकाव नहीं: तुलना को रोकें और फिर से देखें कि क्या शांतिपूर्वक प्रस्तुत किया जा रहा है।"}' WHERE card_id = 'four-of-cups' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"पांच पत्तों का कप","meaning":"हानि उस ओर ध्यान आकर्षित करती है जो बिखर गया जबकि कुछ सार्थक शेष रह जाता है। दुःख को त्वरित आशावाद से ढकने के बजाय नाम दिया जाना चाहिए। फिर भी, एक हार पूरी कहानी नहीं बता सकती; समर्थन या संभावना अभी भी पास में बनी रह सकती है।","advice":"निराशा का सम्मान करें, फिर उस समर्थन की ओर मुड़ें जो अभी भी मौजूद है।","yesNoMeaning":"कप का पांच संकेत नहीं दर्शाता: निराशा का सम्मान करें, फिर उस समर्थन की ओर मुड़ें जो अभी भी मौजूद है।"}' WHERE card_id = 'five-of-cups' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"सिक्स ऑफ कप्स","meaning":"स्मृति, मासूमियत, या एक परिचित बंधन कोमल गर्मजोशी के साथ लौटता है। कोई पुराना मित्र या स्मृति आपको सुरक्षा की भावना के साथ फिर से जोड़ सकती है। यह पहचानते हुए उस गर्मजोशी का स्वागत करें कि वर्तमान बदल गया है और आप भी इसके साथ बदल गए हैं।","advice":"भूत की दया का स्वागत करें बिना यह दिखावा किए कि आपको फिर से वहां रहना चाहिए।","yesNoMeaning":"सिक्स ऑफ कप्स हाँ की ओर झुकता है: अतीत की दयालुता का स्वागत करें बिना यह दिखावे के कि आपको फिर से वहां जीना होगा।"}' WHERE card_id = 'six-of-cups' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"कप का सात","meaning":"कई आकर्षक संभावनाएँ दृष्टि और भ्रम के बीच के अंतर को धुंधला कर देती हैं। प्रत्येक विकल्प एक खूबसूरत वादा लिए हुए प्रतीत हो सकता है, लेकिन हर वादे की बुनियाद एक जैसी नहीं होती। जो आप वास्तव में चाहते हैं उसे उससे अलग करें जो आपने उसके आसपास कल्पना की है।","advice":"विकल्पों को सीमित करें और किसी एक सपने की वास्तविकता के साथ जाँच करें, फिर ही प्रतिबद्ध हों।","yesNoMeaning":"कप्स का सात अभी स्पष्ट नहीं है: विकल्पों को सीमित करें और प्रतिबद्ध होने से पहले एक सपना को वास्तविकता के खिलाफ परखें।"}' WHERE card_id = 'seven-of-cups' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"कप के आठ","meaning":"एक समय की सार्थक स्थिति अब हृदय को पोषण नहीं देती। किसी सार्थक बात को एक बार छोड़ना अब आपके लिए दुखद भी हो सकता है और सही भी। इसका मूल्य वास्तविक था, भले ही गहरे अर्थ की आपकी आवश्यकता बदल गई हो।","advice":"ईमानदारी के साथ छोड़ें और उस गहरे संतोष की ओर बढ़ें जिसकी आपको अब आवश्यकता है।","yesNoMeaning":"कप का आठ संकेत नहीं दर्शाता: ईमानदारी के साथ छोड़ें और उस गहरी पूर्ति की ओर बढ़ें जिसकी अब आपको आवश्यकता है।"}' WHERE card_id = 'eight-of-cups' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"नाइन ऑफ कप्स","meaning":"संतुष्टि और कृतज्ञता एक हार्दिक इच्छा को करीब का एहसास कराती है। हो सकता है कि आप उस चीज़ तक पहुँच गए हों जिसकी आपने कभी कामना की थी और आप उसका आनंद लेने के योग्य हैं। संतुष्टि तब अधिक समय तक बनी रहती है जब आप अगली इच्छा की ओर भागने के बजाय यह जानते हैं कि यह कहां से आती है।","advice":"जो यहाँ है उसका आनंद लें और पूछें कि क्या आपकी इच्छा आपके गहरे मूल्यों की भी सेवा करती है।","yesNoMeaning":"कप्स का नौ हां की ओर झुकता है: जो है उसका आनंद लें और यह पूछें कि क्या यह इच्छा आपके गहरे मूल्यों की भी सेवा करती है।"}' WHERE card_id = 'nine-of-cups' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"कपों का दस","meaning":"भावनात्मक सद्भाव, अपनापन और स्थायी संबंध घर को चारों ओर से घेर लेते हैं। सद्भाव बार-बार देखभाल करने और सुनने से बढ़ता है, असहमति रहित घर से नहीं। यह कार्ड मिलकर निर्माण जारी रखने के इच्छुक लोगों के बीच स्वयं होने की स्वतंत्रता का आह्वान करता है।","advice":"उन बंधनों का पोषण करें जो खुशी को स्थायी और साझा बनाते हैं।","yesNoMeaning":"टेन ऑफ कप्स हाँ की ओर झुकता है: उन संबंधों को पोषित करें जो खुशी को टिकाऊ और साझा बनाते हैं।"}' WHERE card_id = 'ten-of-cups' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"कप्स का पृष्ठ","meaning":"एक कोमल संदेश या सहज खोज भावनात्मक खुलेपन को आमंत्रित करती है। कोई कोमल संदेश, अप्रत्याशित भावना या कल्पनाशील विचार आपका ध्यान खींच सकता है। हर संकेत को पक्का वादा न मानकर आश्चर्य के लिए जगह बनाएं।","advice":"भावना के प्रति जिज्ञासु रहें और अनुमान के बजाय ईमानदारी से प्रतिक्रिया दें।","yesNoMeaning":"पेज ऑफ कप्स शर्तीय बना रहता है: भावना के प्रति जिज्ञासु रहें और अनुमान के बजाय ईमानदारी से प्रतिक्रिया दें।"}' WHERE card_id = 'page-of-cups' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"कप्स का नाइट","meaning":"रोमांस, कल्पना या कोई आदर्श दिल को आगे की ओर खींचता है। आप किसी हार्दिक निमंत्रण या आदर्श का पालन करना चाह सकते हैं। ईमानदारी यात्रा को अर्थ देती है, जबकि व्यावहारिकता आपको यह देखने में मदद करती है कि समय के साथ कौन से लोग और योजनाएँ आपके साथ यात्रा कर सकते हैं।","advice":"आमंत्रण का पालन करें, लेकिन वादों के खुलने के साथ एक पैर जमीन पर रखें।","yesNoMeaning":"नाइट ऑफ कप्स हां की ओर झुकते हैं: निमंत्रण का पालन करें, लेकिन जैसे-जैसे वादे खुलते हैं, एक पैर जमीन पर रखें।"}' WHERE card_id = 'knight-of-cups' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"कव्स की रानी","meaning":"गहरी सहानुभूति और अंतर्ज्ञान सत्य के लिए एक शांत स्थान बनाते हैं। ध्यान से सुनने से किसी को बोलने के लिए पर्याप्त सुरक्षित महसूस करने में मदद मिल सकती है। गहरी सहानुभूति का अर्थ यह जानना भी है कि कौन सी ज़रूरतें आपकी हैं और कौन सा दुःख आप किसी अन्य व्यक्ति के लिए नहीं उठा सकते।","advice":"सहानुभूतिपूर्वक सुनें जबकि उन सीमाओं को बनाए रखें जो देखभाल को स्वस्थ बनाए रखती हैं।","yesNoMeaning":"क्वीन ऑफ कप्स हाँ की ओर झुकाव रखती है: सहानुभूतिपूर्ण सुनें जबकि उन सीमाओं को बनाए रखें जो देखभाल को स्वस्थ रखती हैं।"}' WHERE card_id = 'queen-of-cups' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"कप्स का राजा","meaning":"भावनात्मक परिपक्वता मजबूत भावनाओं को दबाए बिना स्थिर रखती है। जब आप शांत, जिम्मेदार प्रतिक्रिया चुनते हैं तो मजबूत भावनाएं मौजूद रह सकती हैं। वह स्थिरता एक कठिन बातचीत को इसमें शामिल सभी लोगों के लिए सुरक्षित बना सकती है।","advice":"करुणा और आत्म-आदेश के साथ जवाब दें, खासकर जब दूसरे प्रतिक्रियाशील हों।","yesNoMeaning":"किंग ऑफ कप्स हां की ओर झुकते हैं: सहानुभूति और आत्म-नियंत्रण के साथ प्रतिक्रिया दें, विशेष रूप से जब अन्य लोग प्रतिक्रिया कर रहे हों।"}' WHERE card_id = 'king-of-cups' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"तलवार का एस","meaning":"एक स्वच्छ अंतर्दृष्टि भ्रम को दूर करती है और एक नया सत्य प्रकट करती है। कोई नया तथ्य या ईमानदार बातचीत भ्रम को दूर कर सकती है। सत्य तीखा हो सकता है, इसलिए घाव भरने के बजाय अधिक स्पष्टता से समझने और निर्णय लेने के लिए इसका उपयोग करें।","advice":"मुद्दा स्पष्ट रूप से नाम दें और निष्पक्ष निर्णय के लिए स्पष्टता का उपयोग करें।","yesNoMeaning":"तलवारों का ऐस हां की ओर झुकाव रखता है: मुद्दे को स्पष्ट नाम दें और निष्पक्ष निर्णय की सेवा में स्पष्टता का उपयोग करें।"}' WHERE card_id = 'ace-of-swords' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"दो तलवारें","meaning":"एक संरक्षित गतिरोध एक विकल्प में देरी करता है जिसे हमेशा के लिए निलंबित नहीं रखा जा सकता है। हो सकता है कि आप चुनने से इनकार करके संतुलन बनाए रख रहे हों, हालाँकि दबाव दूर नहीं हुआ है। शांत रहना उपयोगी है; असुविधाजनक जानकारी से बचने से निर्णय गायब नहीं होगा।","advice":"अन्धे पट्टे को धीरे-धीरे हटाएँ, गायब तथ्य इकट्ठा करें, और संतुलन से निर्णय लें।","yesNoMeaning":"तलवार की दोहरी अभी स्पष्ट नहीं है: आंखों पर पट्टी को धीरे से हटाएं, गायब तथ्य इकट्ठा करें, और संतुलन से निर्णय लें।"}' WHERE card_id = 'two-of-swords' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"तीन तलवारें","meaning":"कड़वी सच्चाई, बिछड़ना या निराशा सचमुच दर्द दे सकती है। किसी बात या टूटे हुए भरोसे से लगी चोट को स्वीकार करना ठीक है। खुद को तुरंत ठीक साबित करने की जल्दी न करें; अपनी पीड़ा को नाम दें और ज़रूरत हो तो किसी भरोसेमंद व्यक्ति का सहारा लें।","advice":"इस भावना को आपमें बहने दें और चोट को स्थायी कहानी में बदलने से बचें।","yesNoMeaning":"तलवारों का तीन नहीं की ओर झुकता है: भावना को अपने माध्यम से गुजरने दें और चोट को स्थायी कहानी में बदलने से बचें।"}' WHERE card_id = 'three-of-swords' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"तलवार का चार","meaning":"दबाव या संघर्ष के बाद आराम और मानसिक शांति की आवश्यकता होती है। दबाव पर लंबे समय तक प्रतिक्रिया करने के बाद, आपके दिमाग को स्थिर होने के लिए जगह की जरूरत होती है। आराम पुनर्प्राप्ति और तैयारी का हिस्सा है, यह सबूत नहीं है कि आपने हार मान ली है।","advice":"उत्तर देने से पहले विराम लें; पुनर्प्राप्ति उत्पादक होती है जब यह स्पष्ट विचार को बहाल करता है।","yesNoMeaning":"तलवारों का चार झुकाव नहीं: उत्तर देने से पहले ठहरें; पुनर्प्राप्ति तब उत्पादक होती है जब यह स्पष्ट सोच को बहाल करती है।"}' WHERE card_id = 'four-of-swords' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"पाँच तलवारें","meaning":"संघर्ष से खोखली जीत हो सकती है या विश्वास क्षतिग्रस्त हो सकता है। किसी तर्क में जीतना अभी भी विश्वास को नुकसान पहुंचा सकता है या आपको थका सकता है। पूछें कि जीत की कीमत क्या है और कौन सी सीमाएँ आपके आत्मसम्मान की रक्षा करेंगी।","advice":"जीतने के बजाय गरिमा चुनें और उन रणनीतियों से दूर रहें जो बहुत महंगी पड़ती हैं।","yesNoMeaning":"तलवारों का पांच झुकाव नहीं: जीतने के बजाय प्रतिष्ठा को चुनें और उन रणनीतियों से दूर रहें जो बहुत अधिक कीमत लेती हैं।"}' WHERE card_id = 'five-of-swords' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"सिक्स ऑफ स्वॉर्ड्स","meaning":"एक कठिन मार्ग धीरे-धीरे शांत परिस्थितियों की ओर बढ़ता है। परिवर्तन शांत हो सकता है: गतिरोध वाली बातचीत, पुराने माहौल या थका देने वाले सोचने के तरीके को छोड़कर। यह जानने के लिए कि आप अधिक शांति की ओर बढ़ रहे हैं, आपको कोई आदर्श गंतव्य देखने की आवश्यकता नहीं है।","advice":"जो आपने सीखा है उसे लें, समर्थन स्वीकार करें, और अराजकता से दूर चलते रहें।","yesNoMeaning":"सिक्स ऑफ स्वॉर्ड्स हाँ की ओर झुकता है: आपने जो सीखा है उसे अपनाएं, सहायता स्वीकार करें, और झगड़े से दूर चलते रहें।"}' WHERE card_id = 'six-of-swords' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"तलवार का सात","meaning":"रणनीति, गोपनीयता या परहेज राह को जटिल बना देता है। किसी योजना को निजी रखना कभी-कभी आपकी सुरक्षा कर सकता है; जिम्मेदारी से भागने से एक अलग तरह की दूरी पैदा हो जाती है। किसी रणनीति का उपयोग करने का निर्णय लेने से पहले उसके पीछे के उद्देश्य की जांच करें।","advice":"चतुराई से लेकिन पारदर्शी रूप से कार्य करें; ऐसे शॉर्टकट जो विश्वास को धोखा देंगे, वे समस्याओं के रूप में लौटेंगे।","yesNoMeaning":"स्वॉर्ड्स का सात झुकता है नहीं की ओर: चालाकी से लेकिन पारदर्शी रूप से कार्य करें; ट्रस्ट को धोखा देने वाले शॉर्टकट्स समस्याओं के रूप में वापस आएंगे।"}' WHERE card_id = 'seven-of-swords' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"तलवारों के आठ","meaning":"भय और प्रतिबंधात्मक विश्वास उपलब्ध विकल्पों को देखना कठिन बना देते हैं। फँसे होने की भावना वास्तव में आपके आस-पास की सीमाओं से अधिक बड़ी हो सकती है। जैसे-जैसे डर कम होता है, एक छोटा विकल्प, एक मददगार व्यक्ति, या एक अनदेखा रास्ता दिखाई देने लगता है।","advice":"उस विचार पर सवाल करें जो कहता है कि आप फंसे हुए हैं और एक छोटा मुक्त करने वाला कदम उठाएँ।","yesNoMeaning":"तलवार का आठ संकेत नहीं दर्शाता: उस विचार पर प्रश्न उठाएं जो कहता है कि आप फंसे हुए हैं और एक छोटी मुक्ति की कार्रवाई करें।"}' WHERE card_id = 'eight-of-swords' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"नाइन ऑफ स्वोर्ड्स","meaning":"चिंता अंधेरे में ख़तरे को बढ़ा देती है और दिमाग़ को थका देती है। जब आप अकेले में विचारों का सामना करते हैं तो बार-बार आने वाले विचार सबसे उग्र महसूस हो सकते हैं। जो घटित हुआ है उसे उससे अलग करें जो आप कल्पना करते हैं कि घटित हो सकता है, और स्वयं को सहायता माँगने की अनुमति दें।","advice":"भय को उजाले में लाएं, समर्थन मांगें, और तथ्यों को कल्पित परिणामों से अलग करें।","yesNoMeaning":"स्वॉर्ड्स का नौ नहीं की ओर झुकता है: डर को उजाले में लाएं, समर्थन खोजें, और तथ्यों को कल्पित परिणामों से अलग करें।"}' WHERE card_id = 'nine-of-swords' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"तलवारों का दस","meaning":"एक दर्दनाक चक्र अपनी अंतिम सीमा तक पहुँच जाता है और अपरिवर्तित जारी नहीं रह सकता। किसी स्थिति के बहुत लंबे समय तक चलने के बाद अंत आपको थका हुआ बना सकता है। पुराना पैटर्न अपरिवर्तित जारी नहीं रह सकता है, लेकिन स्पष्ट सीमाएं धीरे-धीरे सुधार के लिए जगह बना सकती हैं।","advice":"अंत को स्वीकार करें, अपनी रिकवरी की रक्षा करें, और एक अलग शुरुआत को उभरने दें।","yesNoMeaning":"तलवारों का दस नहीं की ओर झुकता है: अंत को स्वीकार करें, अपनी रिकवरी की रक्षा करें, और एक अलग शुरुआत को उभरने की अनुमति दें।"}' WHERE card_id = 'ten-of-swords' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"तलवारों का पृष्ठ","meaning":"सतर्क जिज्ञासा तथ्यों की तलाश करती है, प्रश्न पूछती है और परिवर्तन पर नजर रखती है। जिज्ञासा आपको किसी निष्कर्ष को स्वीकार करने से पहले प्रश्न पूछने और विवरण जांचने के लिए प्रेरित करती है। वह सतर्कता सीखने में सहायता करती है जब वह हर किसी के संदेह में कठोर न हो जाए।","advice":"सावधानीपूर्वक अनुसंधान करें और हर संकेत पर प्रतिक्रिया देने के बजाय सटीकता के साथ बात करें।","yesNoMeaning":"पेज ऑफ स्वोर्ड्स शर्तीय बना रहता है: सावधानी से शोध करें और हर संकेत पर प्रतिक्रिया देने के बजाय सटीक बोलें।"}' WHERE card_id = 'page-of-swords' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"स्वोर्ड्स का नाइट","meaning":"एकाग्र बुद्धि तेजी से आगे बढ़ती है और बाधाओं का सीधा मुकाबला करती है। एक स्पष्ट विचार आपको आगे भेज सकता है और सीधे बात करने पर मजबूर कर सकता है। दृढ़ संकल्प तब सबसे अच्छा काम करता है जब आप अभी भी नए साक्ष्य सुनते हैं और नोटिस करते हैं कि आपके शब्द दूसरों को कैसे प्रभावित करते हैं।","advice":"साहस के साथ आगे बढ़ो, लेकिन इतना धीमे कि आप सुन सकें कि आपकी निश्चितता क्या मिस कर सकती है।","yesNoMeaning":"स्वॉर्ड्स का नाइट शर्तीय रहता है: साहस के साथ आगे बढ़ें, लेकिन इतना धीमा कि आप यह सुन सकें कि आपकी निश्चितता क्या छूट सकती है।"}' WHERE card_id = 'knight-of-swords' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"स्वॉर्ड्स की रानी","meaning":"स्पष्ट धारणा और ईमानदार सीमाएँ भ्रम को दूर करती हैं। अनुभव आपको यह देखने में मदद कर सकता है कि प्रतिस्पर्धी भावनाओं और वादों के बीच क्या मायने रखता है। प्रत्यक्ष रहें और करुणा खोए बिना ठोस सीमाएं बनाए रखें।","advice":"सहानुभूति के साथ सत्य कहें और अनुभव को आपको कठोर बनाने न दें, बल्कि परिपक्व करें।","yesNoMeaning":"स्वॉर्ड्स की रानी झुकती है हाँ की ओर: सहानुभूति के साथ सच बोलें और अनुभव को आपको कठोर बनाने के बजाय तेज़ करे।"}' WHERE card_id = 'queen-of-swords' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"स्वोर्ड्स का राजा","meaning":"तर्क, निष्पक्षता और अनुशासित निर्णय परिणामी निर्णय का मार्गदर्शन करते हैं। एक कठिन निर्णय के लिए सुसंगत मानकों और स्पष्ट तर्क की आवश्यकता होती है। इस कार्ड का अधिकार निष्पक्षता से आता है, न कि केवल अंतिम शब्द कहने से।","advice":"साक्ष्यों का उपयोग करें, मानक को परिभाषित करें, और फैसले में व्यक्तिगत पक्षपात को बाहर रखें।","yesNoMeaning":"किंग ऑफ स्वॉर्ड्स हां की ओर झुकते हैं: साक्ष्य का उपयोग करें, मानक को परिभाषित करें, और व्यक्तिगत पक्षपात को निर्णय से दूर रखें।"}' WHERE card_id = 'king-of-swords' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"पेंटाकल्स का ऐस","meaning":"एक ठोस अवसर समृद्धि, कार्य या खुशहाली का बीज प्रदान करता है। एक व्यावहारिक शुरुआत कार्य, सहायता, कौशल या स्वस्थ स्थितियों के रूप में प्रकट हो सकती है। इसका मूल्य इस बात पर निर्भर करता है कि समय के साथ इसकी देखभाल कैसे की जाती है, न कि केवल इसकी पहली अपील पर।","advice":"अवसर को व्यावहारिक योजना में आधारित करें और इसका लगातार ख्याल रखें।","yesNoMeaning":"सिक्कों का ऐस हां की ओर झुकाव रखता है: अवसर को व्यावहारिक योजना में जमीन पर उतारें और लगातार इसका ख्याल रखें।"}' WHERE card_id = 'ace-of-pentacles' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"दो पेंटाकल्स","meaning":"कई प्राथमिकताएँ एक साथ चलती हैं और लचीले संतुलन की आवश्यकता होती है। हो सकता है कि आप एक साथ काम, पैसा, समय और व्यक्तिगत ज़रूरतों के बीच संतुलन बना रहे हों। लचीलापन चीजों को गतिशील रखता है, लेकिन लंबे समय तक बाजीगरी के लिए स्पष्ट प्राथमिकताओं की आवश्यकता होती है।","advice":"ताल को समायोजित करें, आवश्यकताओं की रक्षा करें, और उतना ही वादा करें जितना आप संभाल सकते हैं।","yesNoMeaning":"पैसों की दोहरी शर्तों पर निर्भर रहती है: तालमेल एडजस्ट करें, आवश्यकताओं की रक्षा करें, और जितना आप वहन कर सकते हैं उससे अधिक वादा करने से बचें।"}' WHERE card_id = 'two-of-pentacles' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"तीन पेंटाकल्स","meaning":"कौशल सहयोग, प्रतिक्रिया और सावधानीपूर्वक शिल्प कौशल से बढ़ता है। अच्छा काम तब बढ़ता है जब प्रत्येक व्यक्ति अपनी भूमिका और शक्तियों को समझता है। विशिष्ट प्रतिक्रिया, एक शिल्प सीखना, और शांत प्रयास के लिए सम्मान सभी यहाँ मायने रखते हैं।","advice":"अपनी शक्ति का योगदान दें, विशेषज्ञता का सम्मान करें, और साझा मानक के अनुसार निर्माण करें।","yesNoMeaning":"पेंटाकल्स का तीन हाँ की ओर झुकता है: अपनी शक्ति का योगदान दें, विशेषज्ञता का सम्मान करें, और साझा मानक पर निर्माण करें।"}' WHERE card_id = 'three-of-pentacles' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"पेंटाकल का चार","meaning":"सुरक्षा को मजबूती से पकड़ने से संसाधनों को संरक्षित किया जा सकता है लेकिन स्वस्थ प्रवाह को प्रतिबंधित किया जा सकता है। अनिश्चितता के दौरान कड़ी मेहनत से जीते गए संसाधनों को संभाले रखना समझदारी हो सकती है। जब नुकसान का डर हर विकल्प को नियंत्रित करता है, तो धन और मन की शांति दोनों में बाधा महसूस हो सकती है।","advice":"जो महत्वपूर्ण है उसकी सुरक्षा करें बिना यह सोचे कि डर हर निर्णय आपके लिए ले।","yesNoMeaning":"पेंटाकल्स का चार शर्तीय बना रहता है: जो महत्वपूर्ण है उसकी रक्षा करें बिना यह डरने के कि हर निर्णय डर द्वारा प्रभावित हो।"}' WHERE card_id = 'four-of-pentacles' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"पाँच पेंटाकल्स","meaning":"भौतिक तनाव या बहिष्कार चिंता और कमी की भावना पैदा करता है। कठिनाई आपको अकेला या मदद के अयोग्य महसूस करा सकती है। व्यावहारिक समर्थन अभी भी करीब हो सकता है, तब भी जब संकट इसकी ओर रास्ता देखना मुश्किल बना देता है।","advice":"व्यावहारिक मदद मांगें और उस दरवाजे पर ध्यान दें जिसे कठिनाई ने नजरअंदाज करने में आसान बना दिया है।","yesNoMeaning":"पेंटाकल्स का पांच झुकाव नहीं: व्यावहारिक मदद मांगें और उस दरवाजे पर ध्यान दें जिसे कठिनाई ने अनदेखा करना आसान बना दिया है।"}' WHERE card_id = 'five-of-pentacles' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"सिक्स ऑफ पेंटाकल्स","meaning":"संसाधनों का आदान-प्रदान होता है, जिससे उदारता, शक्ति और निष्पक्षता के प्रश्न उठते हैं। मदद तब सबसे अच्छी तरह काम करती है जब देने वाला और पाने वाला दोनों अपनी गरिमा और आवाज बरकरार रखते हैं। देखें कि क्या आदान-प्रदान संतुलित है और उदारता के साथ क्या स्थितियाँ आती हैं।","advice":"स्पष्ट शर्तों के साथ दें या प्राप्त करें ताकि समर्थन दोनों पक्षों की गरिमा बनाए रखे।","yesNoMeaning":"सिक्स ऑफ पेंटाकल्स हाँ की ओर झुकता है: स्पष्ट शर्तों के साथ दें या प्राप्त करें ताकि सहायता दोनों पक्षों की गरिमा बनाए रखे।"}' WHERE card_id = 'six-of-pentacles' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"पेंटकल का सात","meaning":"अगले प्रयास से पहले रोगी का निवेश मूल्यांकन के एक बिंदु तक पहुँच जाता है। आपने प्रयास में निवेश किया है, लेकिन परिणाम आपके पसंदीदा समय पर नहीं आ सकते हैं। प्रगति की समीक्षा करें और इस बात में अंतर करें कि किस चीज़ में अधिक धैर्य की आवश्यकता है और किस चीज़ पर नए दृष्टिकोण की आवश्यकता है।","advice":"जो बढ़ रहा है उसकी समीक्षा करें, विधि में सुधार करें, और मूल्यवान परिणामों को समय दें।","yesNoMeaning":"पेंटाकल्स का सात शर्तों पर निर्भर रहता है: जो बढ़ रहा है उसकी समीक्षा करें, तरीका सुधारें, और मूल्यवान परिणामों को समय दें।"}' WHERE card_id = 'seven-of-pentacles' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"पेंटकल के आठ","meaning":"केंद्रित दोहराव से निपुणता और भरोसेमंद परिणाम विकसित होते हैं। कौशल दोहराव, सुधार और छोटे विवरणों पर ध्यान देने से विकसित होता है। कार्ड अचानक छलांग के बजाय स्थिर अभ्यास को महत्व देता है जिसे अन्य लोग कभी नहीं देख सकते हैं।","advice":"मुख्य कौशल का अभ्यास करें, सुधार का स्वागत करें, और गुणवत्ता को जमा होने दें।","yesNoMeaning":"पेंटाकल का आठ संकेत हाँ दर्शाता है: आवश्यक कौशल का अभ्यास करें, सुधार का स्वागत करें, और गुणवत्ता को जमा होने दें।"}' WHERE card_id = 'eight-of-pentacles' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"नाइन ऑफ पेंटाकल्स","meaning":"आत्मनिर्भरता और सुसंस्कृत आराम अनुशासित प्रगति को दर्शाते हैं। आपका वर्तमान आराम पहले से लिए गए कई अनुशासित विकल्पों को प्रतिबिंबित कर सकता है। आपने जो बनाया है उसका अपनी गति से आनंद लें और उसके पीछे के काम को पहचानें।","advice":"जो आपने बनाया है उसका आनंद लें और स्वतंत्रता को कृतज्ञता से जोड़े रखें।","yesNoMeaning":"पेंटाकल्स का नौ हां की ओर झुकता है: जो आपने बनाया है उसका आनंद लें और स्वतंत्रता को कृतज्ञता से जोड़ें।"}' WHERE card_id = 'nine-of-pentacles' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"सिक्कों का दस","meaning":"दीर्घकालिक सुरक्षा विरासत, परिवार और साझा नींव से बढ़ती है। कहानी एक व्यक्ति की सफलता से आगे बढ़कर परिवार, समुदाय या उसके अनुसरण करने वालों तक फैली हुई है। साझा संसाधनों की विचारशील देखभाल से एक टिकाऊ नींव विकसित होती है।","advice":"तत्काल जीत से आगे योजना बनाएं और वह रक्षा करें जो समय के साथ दूसरों का समर्थन कर सकती है।","yesNoMeaning":"पेंटाकल्स का दस हाँ की ओर झुकता है: तत्काल जीत के परे योजना बनाएं और उस चीज की रक्षा करें जो समय के साथ दूसरों का समर्थन कर सकती है।"}' WHERE card_id = 'ten-of-pentacles' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"पेंटाकल्स का पृष्ठ","meaning":"एक व्यावहारिक संदेश अध्ययन, योजना, या एक नए उद्यम को आमंत्रित करता है। जब आप इसकी मूल बातें सीख लेते हैं तो एक व्यावहारिक अवसर स्पष्ट हो जाता है। धैर्यपूर्वक अन्वेषण करें, छोटे पैमाने पर इसका परीक्षण करें और देखें कि किस चीज़ का स्थायी मूल्य है।","advice":"बुनियादी चीज़ें सीखें, अगला कार्य निर्धारित करें, और लगातार मेहनत से विचार को सिद्ध करें।","yesNoMeaning":"पेज ऑफ पेंटाकल्स हाँ की ओर झुकाव रखता है: मूल बातें सीखें, अगले कार्य को परिभाषित करें, और लगातार काम के माध्यम से विचार को प्रमाणित करें।"}' WHERE card_id = 'page-of-pentacles' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"पेंटाकल्स का नाइट","meaning":"विश्वसनीय प्रयास धीरे-धीरे आगे बढ़ता है लेकिन शायद ही कभी कार्य छोड़ता है। प्रगति इतनी धीमी लग सकती है कि आप सवाल करने लगते हैं कि क्या आप आगे बढ़ रहे हैं, फिर भी निरंतरता एक नींव का निर्माण कर रही है। विश्वसनीयता को आराम के लिए भी जगह चाहिए।","advice":"रूटीन को ईमानदार और लगातार बनाए रखें; प्रगति उत्साह से अधिक महत्वपूर्ण है।","yesNoMeaning":"पेंटाकल्स का नाइट हां की ओर झुकता है: दिनचर्या ईमानदार और लगातार रखें; प्रगति उत्साह से अधिक महत्व रखती है।"}' WHERE card_id = 'knight-of-pentacles' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"पेंटाकल्स की रानी","meaning":"संसाधनपूर्ण देखभाल आराम, स्वास्थ्य और व्यावहारिक प्रचुरता पैदा करती है। देखभाल के ठोस कार्यों और संसाधनों के बुद्धिमानीपूर्ण उपयोग के माध्यम से सुरक्षा बनाई जा सकती है। सतत उदारता आपकी अपनी जरूरतों को भी याद रखने से शुरू होती है।","advice":"लोगों और योजनाओं की देखभाल ऐसे तरीकों से करें जो आपके लिए स्थायी हों।","yesNoMeaning":"पेंटाकल्स की रानी झुकती है हाँ की ओर: लोगों और योजनाओं का पोषण ऐसे तरीके से करें जो आपके लिए टिकाऊ रहें।"}' WHERE card_id = 'queen-of-pentacles' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"पेंटाकल्स का राजा","meaning":"भौतिक नेतृत्व अनुभव को स्थिर और उदार नेतृत्व में बदल देता है। अनुभव कार्य, परिवार या समुदाय के लिए एक स्थिर भविष्य का समर्थन कर सकता है। सफलता तब अधिक मायने रखती है जब इसे बनाने में मदद करने वाले लोग उस स्थिरता में हिस्सा ले सकें।","advice":"दीर्घकालिक विकल्प बनाएं और सफलता का जिम्मेदारी से उपयोग करें।","yesNoMeaning":"किंग ऑफ पेंटाकल्स हां की ओर झुकते हैं: सही दीर्घकालिक विकल्प चुनें और सफलता का जिम्मेदारी से उपयोग करें।"}' WHERE card_id = 'king-of-pentacles' AND locale = 'hi';
UPDATE card_translations SET payload = '{"name":"คนโง่","meaning":"หน้ากระดาษเปล่าและศรัทธาที่ก้าวกระโดด — การเดินทางครั้งใหม่เริ่มต้นด้วยใจที่เปิดกว้าง คุณไม่จำเป็นต้องมีแผนที่ที่สมบูรณ์ก่อนดำเนินการขั้นตอนแรก ความอยากรู้อยากเห็นช่วยให้คุณเรียนรู้จากความพยายามแต่ละครั้ง ในขณะที่การเตรียมการเล็กๆ น้อยๆ ช่วยไม่ให้ความเป็นอิสระกลายเป็นความประมาท","advice":"วางใจในเส้นทางที่อยู่ข้างหน้าคุณและก้าวก้าวแรกนั้น แม้ยังไม่มีคำตอบทั้งหมด","yesNoMeaning":"การเริ่มต้นใหม่มักไม่มาพร้อมคำตอบที่แน่นอน — ผลลัพธ์ขึ้นอยู่กับก้าวที่คุณเลือก"}' WHERE card_id = 'fool' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"จอมเวทย์","meaning":"คุณถือเครื่องมือทั้งหมดที่คุณต้องการ มุ่งความสนใจไปที่เจตจำนงของคุณและเปลี่ยนความตั้งใจให้เป็นการกระทำ แนวคิดจะกลายเป็นจริงเมื่อความสนใจ เวลา และทรัพยากรที่มีอยู่ของคุณมุ่งไปที่งานเดียวกัน ดูเครื่องมือต่างๆ ที่อยู่ไม่ไกลก่อนที่จะรอป้ายอื่น","advice":"ใช้ทักษะและทรัพยากรของคุณอย่างรอบคอบ — ตอนนี้เป็นเวลาที่จะทำให้มันเกิดขึ้น","yesNoMeaning":"คุณมีทุกอย่างที่จำเป็นอยู่แล้ว — พลังงานช่วยสนับสนุนให้ก้าวไปข้างหน้าอย่างมีสมาธิ"}' WHERE card_id = 'magician' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"The High Priestess","meaning":"ปัญญาอันเงียบสงบซ่อนอยู่ใต้ผิวเผิน ฟังสัญชาตญาณและเสียงภายในของคุณ ความเงียบอาจเผยให้เห็นรูปแบบ ความรู้สึกที่คุณยังอธิบายไม่ได้ หรือข้อมูลที่ยังขาดหายไป สังเกตอีกสักหน่อยก่อนนำทุกอย่างไปเปิดเผย","advice":"หยุด, มองเข้าไปข้างใน, และปล่อยให้สัญชาตญาณนำทางคุณก่อนที่จะลงมือทำ","yesNoMeaning":"คำตอบซ่อนอยู่ใต้พื้นผิวในตอนนี้ — เชื่อสัญชาตญาณของคุณแทนที่จะบังคับให้มีคำตอบใช่หรือไม่"}' WHERE card_id = 'high-priestess' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"จักรพรรดินี","meaning":"การเติบโต ความอุดมสมบูรณ์ และพลังบำรุงเลี้ยงอยู่รอบตัวคุณ ให้ความงามและการดูแลเจริญรุ่งเรือง ความสัมพันธ์ โครงการ หรือส่วนหนึ่งของตัวคุณเองอาจเติบโตได้ด้วยการดูแลอย่างสม่ำเสมอ ความอุดมสมบูรณ์ที่นี่หมายถึงการมีพื้นที่ให้พัฒนา ไม่ให้จนไม่เหลืออะไร","advice":"จงอดทนและใจกว้าง — สร้างสรรค์ด้วยความรักและปล่อยให้สิ่งต่าง ๆ เจริญเติบโตตามธรรมชาติ","yesNoMeaning":"พลังแห่งการเติบโต ความอุดมสมบูรณ์ และการเลี้ยงดูสนับสนุนความปรารถนาของคุณ — คำตอบคือคำว่าใช้อย่างเงียบ ๆ"}' WHERE card_id = 'empress' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"จักรพรรดิ","meaning":"โครงสร้าง อำนาจ และความเป็นผู้นำที่มั่นคง สร้างบนพื้นฐานที่มั่นคงด้วยวินัย โครงสร้างที่เป็นประโยชน์ช่วยให้ผู้คนเติบโตได้อย่างปลอดภัย สังเกตความแตกต่างระหว่างการรับผิดชอบกับการพยายามควบคุมทุกรายละเอียด พวกเขาสามารถมีลักษณะเหมือนกันในตอนแรก","advice":"ควบคุมสถานการณ์ด้วยแผนที่ชัดเจน ขอบเขตที่แน่นอนนำมาซึ่งความมั่นคงที่ยั่งยืน","yesNoMeaning":"โครงสร้าง อำนาจ และวินัยที่มั่นคงยืนอยู่เบื้องหลังคำว่าใช้อย่างมั่นใจ"}' WHERE card_id = 'emperor' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"The Hierophant","meaning":"ประเพณีและคำแนะนำที่เชื่อถือได้นำเสนอเส้นทางที่เชื่อถือได้ เรียนรู้จากสิ่งที่มีมาก่อนหน้านี้ ครู ชุมชน หรือวิธีการที่กำหนดไว้อาจเป็นจุดเริ่มต้นที่ดี เรียนรู้ว่าเหตุใดประเพณีจึงได้ผลเพื่อที่คุณจะได้นำไปปรับใช้กับสถานการณ์ของคุณได้อย่างรอบคอบ","advice":"ติดตามปัญญาที่สืบทอดมาและขอคำปรึกษาจากผู้ที่คุณไว้วางใจ","yesNoMeaning":"ประเพณีและคำแนะนำที่เชื่อถือได้ชี้ไปที่คำตอบใช่ที่น่าเชื่อถือ — พึ่งพาสิ่งที่ได้พิสูจน์แล้วว่าได้ผล"}' WHERE card_id = 'hierophant' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"คู่รัก","meaning":"ความผูกพันที่มีความหมายหรือทางเลือกที่สำคัญ ทำตามสิ่งที่หัวใจของคุณเห็นคุณค่าอย่างแท้จริง ความสามัคคีที่ยั่งยืนขอให้ทั้งสองฝ่ายพูดอย่างตรงไปตรงมาเกี่ยวกับความต้องการและขอบเขต หากนี่คือการตัดสินใจมากกว่าความรัก ให้ถามว่าเส้นทางใดที่สะท้อนถึงคุณค่าที่ลึกซึ้งของคุณ","advice":"เลือกด้วยความซื่อสัตย์และสอดคล้อง — การเชื่อมโยงลึกซึ้งขึ้นเมื่อคุณจริงใจ","yesNoMeaning":"หัวใจและค่านิยมของคุณสอดคล้องกันที่นี่ — คำตอบคือใช่ โดยเฉพาะเมื่อคุณเลือกด้วยความซื่อสัตย์"}' WHERE card_id = 'lovers' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"รถม้า","meaning":"พลังจิตและโมเมนตัมจะพาคุณก้าวไปข้างหน้า มุ่งมั่นและคุณจะมีชัย แรงกระตุ้นที่ขัดแย้งกันยังคงสามารถพาคุณไปข้างหน้าได้เมื่อคุณให้ทิศทางร่วมกันแก่พวกเขา ความก้าวหน้าขึ้นอยู่กับการควบคุมความรู้สึกและการกระทำของคุณ ไม่ใช่แค่ผลักดันให้หนักขึ้นเท่านั้น","advice":"จงมุ่งมั่นสู่เป้าหมายและควบคุมด้วยความมั่นใจผ่านอุปสรรคทุกอย่าง","yesNoMeaning":"พลังใจและแรงผลักดันอยู่ข้างคุณ — ตอบว่าใช่แบบมุ่งมั่น แต่ต้องยึดมั่นเสมอ"}' WHERE card_id = 'chariot' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ความแข็งแกร่ง","meaning":"พลังที่แท้จริงนั้นอ่อนโยน ความอดทน ความกล้าหาญ และความเห็นอกเห็นใจเอาชนะทุกความท้าทาย ความอ่อนโยนเป็นรูปแบบหนึ่งของความกล้าหาญ คุณสามารถอยู่กับความรู้สึกไม่สบายได้โดยไม่ต้องปล่อยให้มันตัดสินใจตอบสนองของคุณ รับรู้ถึงความกลัวและเคลื่อนไหวด้วยความระมัดระวังแทนที่จะรอให้ความกลัวหายไป","advice":"นำด้วยความแข็งแกร่งที่สงบ มือที่อ่อนโยนมักเป็นมือที่แข็งแกร่งที่สุด","yesNoMeaning":"ความกล้าอันอ่อนโยนและความมุ่งมั่นอย่างอดทนทำให้สิ่งนี้เป็นคำตอบว่าใช่ — นำด้วยความสงบ ไม่ใช่กำลัง"}' WHERE card_id = 'strength' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"The Hermit","meaning":"ถึงเวลาที่จะถอยกลับและแสวงหาความชัดเจนจากภายใน ความเหงานำมาซึ่งคำตอบที่ลึกซึ้งยิ่งขึ้น การถอยออกไปจะทำให้เสียงของคุณถูกรับฟังได้ง่ายขึ้นท่ามกลางความคิดเห็นของคนอื่น ความสันโดษช่วยได้เมื่อมันนำไปสู่ความเข้าใจ แต่ก็สามารถกลายเป็นวิธีหลีกเลี่ยงการเชื่อมต่อได้เช่นกัน","advice":"หันเข้าไปภายใน ใคร่ครวญ และปล่อยให้ความสงบเปิดเผยสิ่งที่คุณต้องการจริง ๆ","yesNoMeaning":"ยังไม่ — ไพ่กำลังบอกให้คุณถอยกลับไปและหาความชัดเจนภายในก่อนที่จะลงมือทำ"}' WHERE card_id = 'hermit' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"วงล้อโชคชะตา","meaning":"โชคลาภเปลี่ยนและวงจรเปลี่ยน สิ่งที่เปลี่ยนแปลงไปตอนนี้เป็นส่วนหนึ่งของจังหวะที่ใหญ่ขึ้น วงจรเก่าอาจพลิกผัน นำมาซึ่งความไม่สะดวกควบคู่ไปกับความเป็นไปได้ คุณไม่สามารถเลือกทุกเหตุการณ์ได้ แต่คุณสามารถเลือกสิ่งที่จะดำเนินการต่อไปและวิธีเตรียมตัวสำหรับเทิร์นถัดไป","advice":"ล่องตามกระแสด้วยความยืดหยุ่น — ยอมรับการเปลี่ยนแปลง ไม่ว่าจะดีหรือไม่ดี","yesNoMeaning":"โชคชะตากำลังเปลี่ยน — ผลลัพธ์ขึ้นอยู่กับว่าคุณปรับตัวต่อการเปลี่ยนแปลงอย่างไร แทนที่จะเป็นใช่หรือไม่ใช่ที่แน่นอน"}' WHERE card_id = 'wheel-of-fortune' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ความยุติธรรม","meaning":"ความจริงและความยุติธรรมดำเนินไปทั้งวัน เหตุและผลตอนนี้เข้าสู่สมดุลแล้ว สิ่งที่เกิดขึ้นอาจสะท้อนถึงลูกโซ่ของตัวเลือกก่อนหน้านี้ แทนที่จะเป็นช่วงเวลาที่โดดเดี่ยว ตรวจสอบข้อเท็จจริง รับฟังผู้ที่เกี่ยวข้อง และเป็นเจ้าของชิ้นส่วนที่เป็นของคุณ","advice":"ทำอย่างซื่อสัตย์และชั่งน้ำหนักทั้งสองด้าน ตาชั่งจะปรับสมดุลอย่างยุติธรรม","yesNoMeaning":"ตาชั่งยังคงชั่งน้ำหนัก — คำตอบที่ยุติธรรมขึ้นอยู่กับข้อเท็จจริงและความซื่อสัตย์ของคุณ"}' WHERE card_id = 'justice' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"The Hanged Man","meaning":"การหยุดพักอาจช่วยให้คุณมองสถานการณ์จากอีกมุมหนึ่ง หากคุณคุ้นกับการแก้ปัญหาด้วยการลงมือทันที การรออาจทำให้อึดอัด แต่การผ่อนการควบคุมหรือปล่อยความคาดหวังบางอย่าง อาจทำให้เห็นคำตอบที่ความพยายามฝืนต่อไปไม่อาจให้ได้","advice":"หยุดการผลักดัน — ยอมรับช่วงเวลาและปล่อยให้มุมมองใหม่เข้ามา","yesNoMeaning":"จำเป็นต้องหยุดก่อน — การบังคับตอนนี้จะทำให้คำตอบชัดเจนน้อยลง"}' WHERE card_id = 'hanged-man' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ความตาย","meaning":"การสิ้นสุดทำให้ทางสู่การเริ่มต้นใหม่ชัดเจนขึ้น ปลดปล่อยสิ่งที่ทำหน้าที่ของมันตามกาลเวลา การ์ดใบนี้พูดถึงการเปลี่ยนแปลงมากกว่าคำทำนายว่าจะสูญเสียบางสิ่งจริง ๆ คุณอาจโตเกินบทบาท นิสัย หรือความคาดหวังเก่าๆ การทิ้งมันไว้ข้างหลังยังคงต้องใช้เวลา","advice":"ปล่อยวางโดยไม่เสียใจ การเปลี่ยนแปลงอย่างลึกซึ้งกำลังเปิดประตูใหม่","yesNoMeaning":"การสิ้นสุดคือการเคลียร์ทาง — เส้นทางปัจจุบันกำลังปิดเพื่อให้เส้นทางใหม่เริ่มต้น"}' WHERE card_id = 'death' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ความสมดุล","meaning":"ความสมดุลและความอดทนนำมาซึ่งความสามัคคี ผสมผสานสิ่งที่ตรงกันข้ามด้วยความสง่างาม มองหาสิ่งที่สามารถผสมผสานได้จากสองแนวทางที่แตกต่างกัน ความก้าวหน้าอย่างเงียบๆ อาจอยู่ในรูปแบบของนิสัยที่ยั่งยืน การสนทนาที่สงบมากขึ้น หรือก้าวที่คุณสามารถรักษาได้จริงๆ","advice":"เคลื่อนไหวอย่างพอประมาณและรักษาความเยือกเย็น — ก้าวที่มั่นคงจะถึงจุดหมาย","yesNoMeaning":"ความสมดุลและความอดทนสร้างความกลมกลืน — การตอบตกลงอย่างรอบคอบทีละก้าวอย่างมั่นคง"}' WHERE card_id = 'temperance' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ปีศาจ","meaning":"ความยึดติด สิ่งล่อใจ หรือความเคยชินบางอย่างอาจกำลังจำกัดทางเลือกของคุณ ผลดีในระยะสั้นอาจทำให้เลิกพฤติกรรมที่มีต้นทุนระยะยาวได้ยาก ลองมองให้ชัดว่าคุณได้อะไรและต้องแลกกับอะไร การเห็นทั้งสองด้านจะช่วยให้คุณค่อย ๆ กลับมาเลือกได้ด้วยตัวเอง","advice":"ระบุสิ่งที่ผูกมัดคุณและเรียกคืนอิสรภาพของคุณ — โซ่ผูกมัดก็ต่อเมื่อคุณยอมให้","yesNoMeaning":"การยึดติดหรือรูปแบบการผูกมัดจะขวางทาง — ยังไม่ใช่ตอนนี้ จนกว่าสายโซ่จะถูกตั้งชื่อและถูกตัดขาด"}' WHERE card_id = 'devil' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"เดอะทาวเวอร์","meaning":"ความเปลี่ยนแปลงที่เกิดขึ้นกะทันหันอาจสั่นคลอนสิ่งที่คุณเคยเชื่อว่ามั่นคง และเผยให้เห็นความจริงที่ถูกมองข้าม ช่วงเวลาเช่นนี้ไม่ง่าย โดยเฉพาะเมื่อกระทบแผนที่คุณเคยไว้ใจ คุณไม่จำเป็นต้องรีบมองหาด้านดีทันที เริ่มจากดูว่าอะไรเปลี่ยนไปจริง ๆ และอะไรยังเป็นหลักให้คุณยืนได้","advice":"ต้อนรับความว้าวุ่น; จากซากสามารถสร้างรากฐานที่ชัดเจนขึ้นได้","yesNoMeaning":"การเปลี่ยนแปลงอย่างกะทันหันกำลังทำลายสิ่งเก่า — พื้นที่ต้องสงบก่อนที่คำว่าใช้อย่างมั่นคงจะเป็นไปได้"}' WHERE card_id = 'tower' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ไพ่ The Star","meaning":"ความหวัง การเยียวยา และแรงบันดาลใจอันเงียบสงบช่วยฟื้นคืนจิตวิญญาณของคุณหลังพายุ ความหวังไม่ใช่คำสัญญาว่าทุกสิ่งจะคลี่คลายด้วยตัวมันเอง เป็นพื้นที่สำหรับหายใจหลังจากความยากลำบาก และดูแลสิ่งสำคัญต่อไปก่อนที่จะมองเห็นผลลัพธ์","advice":"วางใจในแสงสว่างข้างหน้าและเชื่อมั่นต่อไป — ความปรารถนาของคุณอยู่แค่เอื้อม","yesNoMeaning":"ความหวังและการฟื้นฟูอย่างเงียบสงบชี้ไปที่ใช่ — ไว้วางใจแสงสว่างข้างหน้าและรักษาความปรารถนาของคุณให้คงอยู่"}' WHERE card_id = 'star' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"พระจันทร์","meaning":"ภาพลวงตาและความไม่แน่นอนทำให้เส้นทางเบลอ เชื่อสัญชาตญาณของคุณ ไม่ใช่รูปลักษณ์ภายนอก เมื่อข้อเท็จจริงไม่สมบูรณ์ ความทรงจำและความกลัวสามารถเติมเต็มช่องว่างด้วยเรื่องราวที่น่าเชื่อถือ ช้าลงหน่อย สังเกตปฏิกิริยาของคุณ และแยกสิ่งที่คุณรู้สึกออกจากสิ่งที่คุณได้ตรวจสอบแล้ว","advice":"ชะลอและมองลึกลงไป; ความชัดจะมาถึงเมื่อหมอกจางลง","yesNoMeaning":"ภาพลวงตาและความไม่แน่นอนทำให้เส้นทางพร่ามัว — คำตอบไม่ชัดเจนจนกว่าคุณจะมองใต้ผิวเผิน"}' WHERE card_id = 'moon' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ไพ่ The Sun","meaning":"ความสุข ความสำเร็จ และความสดใสอันสดใส ทุกอย่างสดใสและเต็มไปด้วยชีวิต ความชัดเจนสามารถช่วยให้คุณรับรู้ถึงความก้าวหน้าและแบ่งปันความสุขโดยไม่ลดทอนลง หากยังมีงานทำอยู่ พลังงานใหม่นี้สามารถช่วยให้คุณพบงานได้อย่างเปิดเผยมากขึ้น","advice":"เฉลิมฉลองและเปล่งประกาย — พลังบวกดึงดูดผลลัพธ์ที่คุณปรารถนา","yesNoMeaning":"ความยินดีและความชัดเจนเจิดจ้าชี้ให้เห็นคำตอบที่สดใส — ทุกสิ่งกำลังเป็นไปในทางที่คุณได้เปรียบ"}' WHERE card_id = 'sun' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"การตัดสิน","meaning":"การเรียกร้องให้ลุกขึ้นต่ออายุและซื่อสัตย์กับตัวเอง คำพิพากษาของการตื่น. การทบทวนอดีตไม่จำเป็นต้องโทษตัวเองตลอดไป รับบทเรียน ให้อภัยในสิ่งที่คุณทำได้ และรับสายเพื่อเปลี่ยนแปลงด้วยการตัดสินใจอย่างมีสติทันที","advice":"ตอบรับการเรียกร้องด้วยความกล้า; อภัยในอดีตและก้าวเข้าสู่บทต่อไปของคุณ","yesNoMeaning":"การเรียกร้องให้ลุกขึ้นและฟื้นฟู — ใช่ โดยเฉพาะเมื่อคุณให้อภัยอดีตและตอบอย่างซื่อสัตย์"}' WHERE card_id = 'judgement' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ไพ่ The World","meaning":"ความสมบูรณ์และการบรรลุผล — วงจรปิดลงด้วยความสมบูรณ์สมบูรณ์ ความสำเร็จรวมถึงทักษะ ความสัมพันธ์ และมุมมองที่คุณได้รับตลอดเส้นทาง ให้เกียรติการเสร็จสิ้นของวัฏจักรนี้แม้ว่าการเดินทางในวงกว้างจะดำเนินต่อไปก็ตาม","advice":"เฉลิมฉลองสิ่งที่คุณทำสำเร็จ; ประตูเปิดสู่โลกที่กว้างขึ้น","yesNoMeaning":"ความสมบูรณ์และความครบถ้วนเป็นเครื่องหมายว่านี่คือการตอบรับที่สมบูรณ์ — วงจรปิดลงในความโปรดปรานของคุณ"}' WHERE card_id = 'world' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"เอซแห่งไม้เท้า","meaning":"ประกายแห่งแรงบันดาลใจเปิดเส้นทางสร้างสรรค์อันกล้าหาญ การเชื้อเชิญ โครงการ หรือความปรารถนาใหม่ๆ อาจทำให้คุณรู้สึกมีชีวิตชีวามากขึ้น นี่คือศักยภาพมากกว่าผลลัพธ์ที่รับประกัน มันต้องการพื้นที่สำหรับการทดลองและความมุ่งมั่นหลังจากความตื่นเต้นครั้งแรกหายไป","advice":"เริ่มต้นในขณะที่พลังยังสดใหม่และให้ไอเดียก้าวแรกที่แท้จริง","yesNoMeaning":"เอซของไม้เท้าโน้มเอียงไปใช่: เริ่มต้นขณะที่พลังงานสดใหม่และให้แนวคิดนั้นมีขั้นตอนแรกที่เป็นจริง"}' WHERE card_id = 'ace-of-wands' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"สองไม้เท้า","meaning":"อนาคตกำลังเป็นรูปเป็นร่างผ่านการวางแผนและการเลือกทิศทาง คุณสามารถดูได้มากกว่าหนึ่งเส้นทางและเริ่มถามว่าคุณต้องการไปไกลแค่ไหน มุมมองกว้างๆ ช่วยได้ แต่การวางแผนอย่างไม่มีที่สิ้นสุดสามารถทำให้คุณก้าวข้ามขีดจำกัดได้","advice":"มองไกลกว่าสิ่งที่คุ้นเคย แล้วจงมุ่งมั่นไปบนเส้นทางที่มีพื้นที่ให้เติบโต","yesNoMeaning":"ไพ่ Two of Wands ยังคงแบบมีเงื่อนไข: มองไกลออกไปเกินสิ่งที่คุ้นเคย แล้วจึงมุ่งมั่นไปในเส้นทางที่มีโอกาสเติบโต"}' WHERE card_id = 'two-of-wands' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ไพ่สามไม้เท้า","meaning":"ความพยายามในช่วงแรกจะขยายออกไปเมื่อมีโอกาสและขอบเขตอันกว้างไกลเข้ามามองเห็น สิ่งที่คุณเริ่มต้นคือการเริ่มได้รับการตอบสนองเกินกว่าขอบเขตที่คุ้นเคย เปิดใจรับการติดต่อและข้อเสนอแนะ ในขณะเดียวกันก็ให้เวลากับงานก่อนหน้านี้ของคุณให้เกิดผล","advice":"สร้างต่อไปและเตรียมพร้อมรับผลตอบรับจากงานของคุณ","yesNoMeaning":"ไพ่สามไม้เท้าโน้มไปทางใช่: สร้างต่อไปและเตรียมพร้อมที่จะพบกับผลลัพธ์จากงานของคุณ"}' WHERE card_id = 'three-of-wands' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"สี่คฑา","meaning":"ความมั่นคง การต้อนรับ และการเฉลิมฉลองร่วมกันสร้างรากฐานที่แข็งแกร่ง ความสำเร็จครั้งสำคัญควรค่าแก่การเฉลิมฉลองแม้ว่าการเดินทางจะยังไม่สิ้นสุดก็ตาม การเป็นส่วนหนึ่งและผู้ที่ช่วยสร้างช่วงเวลานี้สามารถเสริมสร้างความเข้มแข็งให้กับก้าวต่อไปของคุณได้","advice":"ทำเครื่องหมายเหตุการณ์สำคัญและให้ผู้สนับสนุนร่วมแบ่งปัน","yesNoMeaning":"The Four of Wands มีแนวโน้มว่าใช่: ทำเครื่องหมายเหตุการณ์สำคัญและให้คนที่สนับสนุนได้มีส่วนร่วมในมัน"}' WHERE card_id = 'four-of-wands' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ไพ่ห้าไม้","meaning":"เป้าหมายที่แข่งขันกันทำให้เกิดการเสียดสี เสียง หรือการทดสอบความมั่นใจ เสียงของผู้แข่งขันมากมายสามารถซ่อนเป้าหมายร่วมกันได้ ความขัดแย้งอาจทำให้ความคิดมีความคมชัดขึ้นเมื่อทุกคนรู้ว่าจริงๆ แล้วพวกเขากำลังโต้เถียงเรื่องอะไรอยู่ และสามารถรับฟังความแตกต่างได้","advice":"เปลี่ยนการแข่งขันให้เป็นการฝึกฝนที่เป็นประโยชน์และปฏิเสธความขัดแย้งที่ไม่มีประโยชน์","yesNoMeaning":"ไพไม้เท้าห้าใบยังคงมีเงื่อนไข: เปลี่ยนการแข่งขันให้เป็นการฝึกฝนที่มีประโยชน์และปฏิเสธความขัดแย้งที่ไม่มีจุดประสงค์"}' WHERE card_id = 'five-of-wands' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ไพ่หกไม้เท้า","meaning":"การยอมรับเป็นไปตามความพยายามที่มุ่งมั่นและความก้าวหน้าที่มองเห็นได้ ความพยายามของคุณอาจถูกคนอื่นเห็นในที่สุด การยกย่องชมเชยสามารถให้กำลังใจคุณได้ แต่คุณค่าของงานของคุณยังคงอยู่แม้ว่าจะไม่มีผู้ชมชมก็ตาม","advice":"ยอมรับคำปลุกใจ แต่คงความมั่นใจของคุณไว้กับการทำงานอย่างซื่อสัตย์","yesNoMeaning":"ไพ่ Six of Wands โน้มไปทางใช่: ยอมรับกำลังใจ แต่เก็บความมั่นใจของคุณไว้กับงานที่ซื่อสัตย์"}' WHERE card_id = 'six-of-wands' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"เจ็ดแท่ง","meaning":"คุณยึดมั่นในจุดยืนอันมีค่าในขณะที่ความกดดันทดสอบความมุ่งมั่นของคุณ การปกป้องสิ่งที่สำคัญต้องรู้ว่าเหตุใดจึงสำคัญสำหรับคุณ ความกดดันอาจมาจากหลายทิศทาง แต่ไม่ใช่ทุกความท้าทายที่สมควรได้รับการต่อสู้","advice":"ปกป้องสิ่งที่สำคัญด้วยขอบเขตที่ชัดเจน แทนที่จะต่อสู้กับทุกความท้าทาย","yesNoMeaning":"ไพ่ Seven of Wands โน้มไปทางใช่: ปกป้องสิ่งที่สำคัญด้วยขอบเขตที่ชัดเจน แทนที่จะต่อสู้กับทุกความท้าทาย"}' WHERE card_id = 'seven-of-wands' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"แปดของไม้เท้า","meaning":"เหตุการณ์เร่งขึ้น ข้อความมาถึง และโมเมนตัมขจัดความล่าช้า ข่าวหรือการตัดสินใจอาจมาเร็วกว่าที่คาด ความเร็วจะช่วยได้เมื่อทุกคนเข้าใจทิศทาง ข้อมูลที่ไม่ชัดเจนสามารถเปลี่ยนโมเมนตัมให้กลายเป็นความสับสนได้","advice":"ลงมือทำอย่างรวดเร็วและติดต่อสื่อสารตรงไปตรงมาตลอดเส้นทางที่เปิดอยู่","yesNoMeaning":"แปดของไม้เท้าเอนโน้ต: ลงมืออย่างรวดเร็วและสื่อสารโดยตรงในขณะที่เส้นทางเปิดอยู่"}' WHERE card_id = 'eight-of-wands' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"เก้าไม้เท้า","meaning":"การฟื้นตัวนั้นแข็งแกร่ง แม้ว่าความเครียดในอดีตจะทำให้คุณตื่นตัว ความเครียดในอดีตได้สอนวิธีป้องกันตัวเอง แต่การระมัดระวังอย่างต่อเนื่องนั้นเหนื่อยมาก ตัดสินความเสี่ยงที่อยู่ตรงหน้าคุณด้วยหลักฐานของวันนี้และบาดแผลของเมื่อวาน","advice":"ปกป้องพลังงานของตัวเองและก้าวต่อไปโดยไม่คาดหวังว่าบาดแผลทุกครั้งจะเกิดซ้ำ","yesNoMeaning":"ไพ่เก้าไม้เท้ายังคงมีเงื่อนไข: ปกป้องพลังงานของคุณและก้าวไปข้างหน้าโดยไม่คาดหวังว่าบาดแผลทุกอย่างจะเกิดซ้ำ"}' WHERE card_id = 'nine-of-wands' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"สิบไม้เท้า","meaning":"ความรับผิดชอบเริ่มหนักหน่วงและความสำเร็จก็กลายเป็นภาระ สิ่งที่คุณเคยภูมิใจตอนนี้อาจมีภาระผูกพันมากเกินไป ความสามารถของคุณมีอยู่จริง แต่คุณไม่จำเป็นต้องทำงานทุกอย่างเพียงลำพัง","advice":"มอบหมายงาน ทำให้เรียบง่าย และวางงานที่ไม่ใช่ของคุณอีกต่อไป","yesNoMeaning":"ไพ่สิบไม้เท้าโน้มไปทางไม่: มอบหมายงาน ทำให้เรียบง่าย และวางงานที่ไม่ใช่ของคุณอีกต่อไป"}' WHERE card_id = 'ten-of-wands' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"หน้าไพ่ไม้เท้า","meaning":"ความอยากรู้อยากเห็นนำมาซึ่งข้อความที่มีชีวิตชีวา การทดลอง หรือความสนใจเชิงสร้างสรรค์ใหม่ๆ แนวคิดใหม่ๆ สามารถนำความตื่นเต้นของผู้เริ่มต้นกลับมาได้ คุณไม่จำเป็นต้องเชี่ยวชาญทุกอย่างก่อนที่จะสำรวจ ให้สิทธิ์ตัวเองในการลอง ปรับเปลี่ยน และเรียนรู้ในทางปฏิบัติ","advice":"สำรวจด้วยความกล้าและให้พลังของผู้เริ่มต้นสอนคุณผ่านการลงมือทำ","yesNoMeaning":"ไพ่เพจไม้เท้ามีแนวโน้มไปทางใช่: สำรวจด้วยความกล้าหาญและให้พลังงานของผู้เริ่มต้นสอนคุณผ่านการกระทำ"}' WHERE card_id = 'page-of-wands' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"อัศวินไม้เท้า","meaning":"ความหลงใหลพุ่งไปข้างหน้าอย่างรวดเร็ว นำมาซึ่งการผจญภัยและความไม่อดทนที่อาจเกิดขึ้นได้ การดึงสิ่งใหม่อาจทำให้คุณอยากออกไปทันที พลังงานนี้จะให้บริการคุณได้ดีที่สุดเมื่อเป้าหมายที่ชัดเจนขัดขวางไม่ให้คุณเปลี่ยนเส้นทางทุกครั้งที่มีแรงกระตุ้นที่ผ่านไป","advice":"ใช้แรงส่ง แต่เลือกทิศทางก่อนที่ความเร็วจะกระจายความพยายามของคุณ","yesNoMeaning":"อัศวินแห่งไม้เท้า ยังมีเงื่อนไข: ใช้แรงผลักดัน แต่เลือกทิศทางก่อนที่ความเร็วจะกระจายความพยายามของคุณ"}' WHERE card_id = 'knight-of-wands' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ราชินีแห่งไม้เท้า","meaning":"ความมั่นใจอันอบอุ่นและความเป็นอิสระในการสร้างสรรค์ดึงดูดผู้อื่นให้เข้ามาสู่วิสัยทัศน์ของคุณ การปรากฏตัวอย่างเปิดเผยของคุณสามารถกระตุ้นให้ผู้อื่นเชื่อในวิสัยทัศน์ที่มีร่วมกัน ความมั่นใจในที่นี้ไม่จำเป็นต้องโดดเด่นกว่าใคร มันทำให้มีที่ว่างให้คนอื่นได้เฉิดฉายเช่นกัน","advice":"วางใจในตัวตนของคุณ ส่งเสริมผู้อื่น และอย่ากดความทะเยอทะยานของคุณ","yesNoMeaning":"ราชินีแห่งไม้เท้าเอียงไปทางใช่: ไว้วางใจในตัวตนของคุณ สนับสนุนผู้อื่น และอย่าลดทอนความทะเยอทะยานของคุณ"}' WHERE card_id = 'queen-of-wands' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ราชาไม้เท้า","meaning":"วิสัยทัศน์ที่เป็นผู้ใหญ่เปลี่ยนแรงบันดาลใจให้กลายเป็นผู้นำที่เด็ดขาดและมีจริยธรรม วิสัยทัศน์ที่ยิ่งใหญ่จำเป็นต้องมีการตัดสินใจ ความรับผิดชอบ และความสามารถในการรักษาพลังของทีม เป็นผู้นำด้วยจุดประสงค์ที่ชัดเจน แทนที่จะกดดันหรืออัตตาเพียงอย่างเดียว","advice":"นำจากความตั้งใจใหญ่และให้ผู้อื่นมีพื้นที่ในการมีส่วนร่วม","yesNoMeaning":"The King of Wands มีแนวโน้มว่าใช่: นำจากเป้าหมายที่ใหญ่ขึ้นและให้ผู้อื่นมีพื้นที่ในการมีส่วนร่วม"}' WHERE card_id = 'king-of-wands' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"เอซแห่งถ้วย","meaning":"หัวใจเปิดรับความรัก ความเห็นอกเห็นใจ และการต่ออายุทางอารมณ์ครั้งใหม่ การประชุม ความรู้สึกใหม่ๆ หรือจิตใจที่อ่อนลงอาจเชิญชวนให้คุณให้และรับอย่างอิสระมากขึ้น ปล่อยให้อารมณ์ได้รับการยอมรับก่อนที่จะบังคับไปสู่ผลลัพธ์บางอย่าง","advice":"รับรู้ความรู้สึกอย่างซื่อสัตย์และปล่อยให้ความเอาใจใส่ไหลโดยไม่บังคับผลลัพธ์","yesNoMeaning":"เอซของถ้วยโน้มเอียงไปใช่: รับความรู้สึกอย่างแท้จริงและปล่อยให้ความเอาใจใส่ไหลโดยไม่บังคับผลลัพธ์"}' WHERE card_id = 'ace-of-cups' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"สองถ้วย","meaning":"การยอมรับซึ่งกันและกันจะสร้างความร่วมมือ ความดึงดูดใจ หรือข้อตกลงที่จริงใจ คำสัญญาที่ลึกกว่านั้นอยู่ที่ว่าคนสองคนมองเห็นกันอย่างชัดเจน เกินกว่าความดึงดูดใจในตอนแรก การสนทนาอย่างจริงใจ การขอโทษ หรือข้อตกลงที่ยุติธรรมอาจช่วยกระชับสายสัมพันธ์ให้แน่นแฟ้นยิ่งขึ้น","advice":"พบคนอื่นในฐานะที่เท่าเทียมและพูดจากใจ","yesNoMeaning":"ไพ่ Two of Cups โน้มไปทางใช่: พบกับอีกฝ่ายในฐานะที่เท่าเทียมและพูดจากใจ"}' WHERE card_id = 'two-of-cups' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ไพ่สามถ้วย","meaning":"มิตรภาพ ชุมชน และความสุขร่วมกันนำมาซึ่งกำลังใจ การรวมตัวเล็กๆ น้อยๆ หรือการสนับสนุนอย่างทันท่วงทีสามารถเตือนคุณได้ว่าไม่จำเป็นต้องแบกรับความสุขเพียงลำพัง จำคนที่ยืนเคียงข้างคุณก่อนที่ทุกอย่างจะง่ายขึ้น","advice":"เฉลิมฉลองร่วมกันและจดจำผู้ที่เข้ามาอย่างจริงใจ","yesNoMeaning":"ไพ่สามถ้วยโน้มไปทางใช่: เฉลิมฉลองร่วมกันและจำคนที่อยู่เคียงข้างคุณอย่างแท้จริง"}' WHERE card_id = 'three-of-cups' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"สี่ถ้วย","meaning":"การถอนตัวทางอารมณ์ทำให้ยากต่อการสังเกตของขวัญที่มีอยู่ เมื่อคุณเหนื่อยหรือท้อแท้ แม้แต่ข้อเสนอที่ดีก็อาจดูน่าเบื่อ ซื่อสัตย์กับความรู้สึกในปัจจุบันของคุณก่อนที่จะตัดสินใจว่าสิ่งรอบตัวคุณไม่สำคัญ","advice":"หยุดการเปรียบเทียบและมองสิ่งที่กำลังถูกเสนออย่างเงียบ ๆ อีกครั้ง","yesNoMeaning":"ไพถ้วยสี่ใบเอียงไปไม่: หยุดการเปรียบเทียบและมองอีกครั้งในสิ่งที่กำลังถูกมอบให้อย่างเงียบ ๆ"}' WHERE card_id = 'four-of-cups' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ไพ่ห้าถ้วย","meaning":"การสูญเสียดึงความสนใจไปที่สิ่งที่รั่วไหลในขณะที่บางสิ่งที่มีความหมายยังคงอยู่ ความเศร้าโศกสมควรได้รับการเอ่ยนาม แทนที่จะปกปิดด้วยการมองโลกในแง่ดีอย่างรวดเร็ว ถึงกระนั้น การสูญเสียเพียงครั้งเดียวอาจไม่บอกเรื่องราวทั้งหมดได้ การสนับสนุนหรือความเป็นไปได้อาจยังคงอยู่ใกล้เคียง","advice":"เคารพความผิดหวัง จากนั้นหันไปหาการสนับสนุนที่ยังมีอยู่","yesNoMeaning":"ห้าของถ้วยเอนโน้ต: ให้เกียรติความผิดหวัง จากนั้นหันไปสู่การสนับสนุนที่ยังคงอยู่"}' WHERE card_id = 'five-of-cups' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ไพ่หกถ้วย","meaning":"ความทรงจำ ความไร้เดียงสา หรือสายสัมพันธ์ที่คุ้นเคยกลับมาพร้อมกับความอบอุ่นอันอ่อนโยน เพื่อนเก่าหรือความทรงจำอาจเชื่อมโยงคุณเข้ากับความรู้สึกปลอดภัยอีกครั้ง ยินดีต้อนรับความอบอุ่นนั้นโดยตระหนักว่าปัจจุบันมีการเปลี่ยนแปลงและคุณก็เปลี่ยนแปลงตามไปด้วย","advice":"ยอมรับความใจดีในอดีตโดยไม่ต้องแสร้งว่าคุณต้องกลับไปใช้ชีวิตที่นั่นอีกครั้ง","yesNoMeaning":"ไพ่ Six of Cups โน้มไปทางใช่: ยอมรับความเมตตาของอดีตโดยไม่ต้องแกล้งทำเหมือนว่าคุณต้องกลับไปอยู่ที่นั่นอีกครั้ง"}' WHERE card_id = 'six-of-cups' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"เจ็ดดวงถ้วย","meaning":"ความเป็นไปได้ที่น่าดึงดูดหลายประการทำให้ความแตกต่างระหว่างการมองเห็นและภาพลวงตาพร่ามัว แต่ละทางเลือกอาจดูเหมือนมีคำสัญญาที่สวยงาม แต่ไม่ใช่ทุกคำสัญญาที่มีรากฐานที่เหมือนกัน แยกสิ่งที่คุณต้องการอย่างแท้จริงออกจากสิ่งที่คุณจินตนาการไว้","advice":"จำกัดทางเลือกและทดสอบความฝันหนึ่งกับความจริงก่อนที่จะตัดสินใจ","yesNoMeaning":"เจ็ดถ้วยยังไม่ชัดเจน: จำกัดทางเลือกและทดสอบความฝันหนึ่งกับความจริงก่อนจะมุ่งมั่น"}' WHERE card_id = 'seven-of-cups' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"แปดของถ้วย","meaning":"สถานการณ์ที่ครั้งหนึ่งมีความหมายไม่ได้หล่อเลี้ยงหัวใจอีกต่อไป การทิ้งบางสิ่งที่ครั้งหนึ่งเคยมีความหมายอาจเป็นเรื่องน่าเศร้าและใช่สำหรับคุณในตอนนี้ คุณค่าของมันมีอยู่จริง แม้ว่าความต้องการความหมายที่ลึกซึ้งยิ่งขึ้นของคุณจะเปลี่ยนไปก็ตาม","advice":"จากไปอย่างซื่อสัตย์และมุ่งสู่ความพึงพอใจที่ลึกซึ้งกว่าที่คุณต้องการในตอนนี้","yesNoMeaning":"แปดของถ้วยเอนโน้ต: ออกไปด้วยความซื่อสัตย์และมุ่งสู่ความเติมเต็มที่ลึกซึ้งที่คุณต้องการในตอนนี้"}' WHERE card_id = 'eight-of-cups' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"เก้าถ้วย","meaning":"ความพึงพอใจและความกตัญญูทำให้ความปรารถนาจากใจรู้สึกใกล้ชิด คุณอาจบรรลุสิ่งที่คุณเคยปรารถนาและสมควรที่จะเพลิดเพลินไปกับมัน ความพึงพอใจจะคงอยู่นานขึ้นเมื่อคุณรู้ว่ามันมาจากไหน แทนที่จะรีบเร่งไปสู่ความปรารถนาต่อไป","advice":"สนุกกับสิ่งที่มีอยู่ที่นี่และถามว่าความปรารถนานั้นสอดคล้องกับค่านิยมลึกซึ้งของคุณด้วยหรือไม่","yesNoMeaning":"เก้าถ้วยคว่ำไปทางใช่: เพลิดเพลินกับสิ่งที่อยู่ตรงหน้าและถามว่าความปรารถนานั้นสอดคล้องกับคุณค่าลึกๆ ของคุณหรือไม่"}' WHERE card_id = 'nine-of-cups' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"สิบถ้วย","meaning":"ความสามัคคีทางอารมณ์ ความเป็นเจ้าของ และการเชื่อมต่อที่ยั่งยืนล้อมรอบบ้าน ความสามัคคีเติบโตผ่านการดูแลและการฟังซ้ำๆ ไม่ใช่ผ่านครอบครัวที่ไม่มีความขัดแย้ง การ์ดใบนี้กระตุ้นให้เกิดอิสรภาพในการเป็นตัวของตัวเองท่ามกลางผู้คนที่ยินดีจะร่วมกันสร้างต่อไป","advice":"บำรุงความสัมพันธ์ที่ทำให้ความสุขยั่งยืนและแบ่งปันกันได้","yesNoMeaning":"ไพ่ Ten of Cups โน้มไปทางใช่: ดูแลความสัมพันธ์ที่ทำให้ความสุขเป็นสิ่งที่ยั่งยืนและแบ่งปันร่วมกัน"}' WHERE card_id = 'ten-of-cups' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"หน้าไพ่ถ้วย","meaning":"ข้อความที่อ่อนโยนหรือการค้นพบตามสัญชาตญาณเชิญชวนให้เกิดการเปิดกว้างทางอารมณ์ ข้อความที่อ่อนโยน ความรู้สึกที่ไม่คาดคิด หรือความคิดเชิงจินตนาการอาจดึงดูดความสนใจของคุณได้ สร้างพื้นที่สำหรับความประหลาดใจโดยไม่ต้องถือว่าทุกสัญญาณเป็นคำมั่นสัญญาที่มั่นคง","advice":"รักษาความอยากรู้อยากเห็นเกี่ยวกับความรู้สึกและตอบสนองด้วยความจริงใจแทนการสันนิษฐาน","yesNoMeaning":"ไพ่เพจถ้วยยังคงมีเงื่อนไข: อย่าหยุดสงสัยในความรู้สึกและตอบสนองด้วยความจริงใจแทนการสมมติ"}' WHERE card_id = 'page-of-cups' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"อัศวินถ้วย","meaning":"ความโรแมนติก จินตนาการ หรืออุดมคติดึงดูดใจให้ก้าวไปข้างหน้า คุณอาจต้องการปฏิบัติตามคำเชื้อเชิญจากใจจริงหรืออุดมคติ ความจริงใจทำให้การเดินทางมีความหมาย ในขณะที่การปฏิบัติจริงช่วยให้คุณเห็นว่าผู้คนและแผนงานใดบ้างที่สามารถเดินทางไปกับคุณเมื่อเวลาผ่านไป","advice":"ตอบรับคำเชิญ แต่จงวางเท้าหนึ่งข้างบนพื้นในขณะที่คำสัญญาถูกเปิดเผย","yesNoMeaning":"The Knight of Cups มีแนวโน้มว่าใช่: ทำตามคำเชิญ แต่ให้หนึ่งเท้ายังคงอยู่บนพื้นขณะที่คำสัญญาค่อย ๆ เกิดขึ้น"}' WHERE card_id = 'knight-of-cups' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ราชินีแห่งถ้วย","meaning":"ความเห็นอกเห็นใจและสัญชาตญาณอย่างลึกซึ้งสร้างพื้นที่สงบสำหรับความจริง การฟังอย่างใกล้ชิดสามารถช่วยให้ใครบางคนรู้สึกปลอดภัยพอที่จะพูดได้ การเอาใจใส่อย่างลึกซึ้งยังหมายถึงการรู้ว่าความต้องการใดเป็นของคุณ และความโศกเศร้าใดที่คุณไม่สามารถแบกรับไว้เพื่อบุคคลอื่นได้","advice":"ฟังด้วยความเอาใจใส่อย่างมีเมตตาในขณะที่รักษาขอบเขตที่ทำให้การดูแลมีสุขภาพดี","yesNoMeaning":"ไพ่ควีนถ้วยมีแนวโน้มไปทางใช่: ฟังด้วยความเมตตาในขณะที่รักษาขอบเขตที่ทำให้การดูแลเป็นไปอย่างมีสุขภาพดี"}' WHERE card_id = 'queen-of-cups' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ราชาถ้วย","meaning":"วุฒิภาวะทางอารมณ์จะรักษาความรู้สึกที่แข็งแกร่งโดยไม่ระงับความรู้สึกเหล่านั้น ความรู้สึกที่รุนแรงสามารถยังคงอยู่ได้ในขณะที่คุณเลือกการตอบสนองที่สงบและมีความรับผิดชอบ ความมั่นคงนั้นสามารถทำให้การสนทนาที่ยากลำบากปลอดภัยยิ่งขึ้นสำหรับทุกคนที่เกี่ยวข้อง","advice":"ตอบสนองด้วยความเห็นอกเห็นใจและการควบคุมตนเอง โดยเฉพาะเมื่อผู้อื่นมีปฏิกิริยา","yesNoMeaning":"The King of Cups มีแนวโน้มว่าใช่: ตอบสนองด้วยความเห็นอกเห็นใจและควบคุมตนเอง โดยเฉพาะเมื่อคนอื่นมีปฏิกิริยา"}' WHERE card_id = 'king-of-cups' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"เอซแห่งดาบ","meaning":"ความเข้าใจที่สะอาดจะขจัดความสับสนและเผยให้เห็นความจริงใหม่ ข้อเท็จจริงใหม่หรือการสนทนาที่ตรงไปตรงมาอาจทำให้สับสนได้ ความจริงอาจมีความคมชัดได้ ดังนั้นจงใช้มันเพื่อทำความเข้าใจและตัดสินใจให้ชัดเจนยิ่งขึ้น แทนที่จะทำร้ายจิตใจ","advice":"ระบุปัญหาอย่างชัดเจนและใช้ความชัดเจนเพื่อการตัดสินใจอย่างเป็นธรรม","yesNoMeaning":"เอซของดาบโน้มเอียงไปใช่: ระบุปัญหาอย่างชัดเจนและใช้ความชัดเจนในการตัดสินใจอย่างเป็นธรรม"}' WHERE card_id = 'ace-of-swords' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"สองดาบ","meaning":"ทางตันที่ได้รับการปกป้องจะทำให้ตัวเลือกที่ไม่สามารถระงับได้ตลอดไปล่าช้า คุณอาจรักษาสมดุลด้วยการปฏิเสธที่จะเลือก แม้ว่าความกดดันจะไม่หายไปก็ตาม ความสงบมีประโยชน์ การหลีกเลี่ยงข้อมูลที่ไม่สะดวกจะไม่ทำให้การตัดสินใจหายไป","advice":"ค่อยๆ เอาผ้าปิดตาออก รวบรวมข้อเท็จจริงที่ขาดหายไป และตัดสินใจจากความสมดุล","yesNoMeaning":"ไพ่ Two of Swords ยังไม่ชัดเจน: ค่อย ๆ ถอดผ้าปิดตา เก็บข้อเท็จจริงที่ขาดหาย และตัดสินใจจากสมดุล"}' WHERE card_id = 'two-of-swords' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ไพ่สามดาบ","meaning":"ความจริงที่เจ็บปวด การจากลา หรือความผิดหวังควรได้รับการยอมรับ คำพูดหรือความหวังที่พังลงอาจทิ้งบาดแผลไว้จริง ๆ คุณไม่จำเป็นต้องรีบพิสูจน์ว่าตัวเองหายดีแล้ว ลองเรียกชื่อความรู้สึกนั้นและขอแรงพยุงจากคนที่ไว้ใจเมื่อจำเป็น","advice":"ปล่อยให้ความรู้สึกไหลผ่านตัวคุณและหลีกเลี่ยงการเปลี่ยนความเจ็บปวดให้กลายเป็นเรื่องเล่าที่ถาวร","yesNoMeaning":"ไพ่สามดาบโน้มไปทางไม่: ให้ความรู้สึกผ่านตัวคุณและหลีกเลี่ยงการเปลี่ยนความเจ็บปวดให้เป็นเรื่องราวถาวร"}' WHERE card_id = 'three-of-swords' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"สี่ดาบ","meaning":"การพักผ่อนและจิตใจสงบเป็นสิ่งจำเป็นหลังจากแรงกดดันหรือความขัดแย้ง หลังจากการตอบสนองต่อแรงกดดันเป็นเวลานาน จิตใจของคุณต้องการพื้นที่ในการปรับตัว การพักผ่อนเป็นส่วนหนึ่งของการฟื้นฟูและการเตรียมตัว ไม่ใช่ข้อพิสูจน์ว่าคุณยอมแพ้","advice":"หยุดก่อนตอบ; การฟื้นฟูเป็นสิ่งที่มีประสิทธิภาพเมื่อทำให้ความคิดชัดเจนขึ้น","yesNoMeaning":"ไพดาบสี่ใบเอียงไปไม่: หยุดก่อนตอบ; การฟื้นตัวมีประสิทธิภาพเมื่อมันฟื้นความคิดที่ชัดเจน"}' WHERE card_id = 'four-of-swords' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ไพ่ห้าอาวุธ","meaning":"ความขัดแย้งอาจก่อให้เกิดชัยชนะอันว่างเปล่าหรือทำให้ความไว้วางใจเสียหาย การชนะการโต้แย้งอาจยังทำลายความไว้วางใจหรือทำให้คุณหมดแรง ถามว่าชัยชนะต้องแลกมาด้วยราคาเท่าใด และขอบเขตใดที่จะปกป้องความเคารพในตนเองของคุณ","advice":"เลือกความมีศักดิ์ศรีมากกว่าการชนะ และละทิ้งกลยุทธ์ที่มีค่าใช้จ่ายสูงเกินไป","yesNoMeaning":"ไพดาบห้าใบเอียงไปไม่: เลือกศักดิ์ศรีเหนือชัยชนะและหลีกเลี่ยงกลยุทธ์ที่มีค่าใช้จ่ายสูงเกินไป"}' WHERE card_id = 'five-of-swords' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ไพ่หกดาบ","meaning":"ข้อความที่ยากจะค่อยๆ เคลื่อนไปสู่สภาวะที่สงบมากขึ้น การเปลี่ยนแปลงอาจจะเงียบๆ: ทิ้งบทสนทนาที่ติดขัด สภาพแวดล้อมเก่าๆ หรือวิธีคิดที่น่าเบื่อหน่าย คุณไม่จำเป็นต้องเห็นจุดหมายปลายทางที่สมบูรณ์แบบเพื่อที่จะรู้ว่าคุณกำลังก้าวไปสู่ความสงบสุขที่มากขึ้น","advice":"นำสิ่งที่คุณได้เรียนรู้ ยอมรับการสนับสนุน และเดินหน้าห่างจากความวุ่นวาย","yesNoMeaning":"ไพ่ Six of Swords โน้มไปทางใช่: นำสิ่งที่คุณได้เรียนรู้ รับการสนับสนุน และก้าวต่อไปให้พ้นจากความวุ่นวาย"}' WHERE card_id = 'six-of-swords' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"เจ็ดดาบ","meaning":"กลยุทธ์ ความลับ หรือการหลีกเลี่ยงทำให้เส้นทางซับซ้อน การเก็บแผนไว้เป็นส่วนตัวในบางครั้งสามารถปกป้องคุณได้ การหลีกเลี่ยงความรับผิดชอบทำให้เกิดระยะห่างที่แตกต่างออกไป ตรวจสอบแรงจูงใจเบื้องหลังกลยุทธ์ก่อนตัดสินใจใช้","advice":"ทำตัวอย่างฉลาดแต่โปร่งใส ทางลัดที่ทรยศต่อความไว้วางใจจะกลับมาพร้อมปัญหา","yesNoMeaning":"เจ็ดดาบเอียงไปทางไม่: ลงมืออย่างชาญฉลาดแต่โปร่งใส; ทางลัดที่ทรยศต่อความไว้วางใจจะกลับมาสร้างปัญหา"}' WHERE card_id = 'seven-of-swords' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"แปดของดาบ","meaning":"ความกลัวและความเชื่อที่จำกัดทำให้มองเห็นตัวเลือกที่มีอยู่ได้ยาก ความรู้สึกของการติดกับดักอาจมีมากกว่าขอบเขตที่อยู่รอบตัวคุณจริงๆ เมื่อความกลัวคลายลง ทางเลือกเล็กๆ ทางเลือกหนึ่ง คนที่เป็นประโยชน์ หรือเส้นทางที่ถูกมองข้ามก็อาจปรากฏให้เห็น","advice":"ตั้งคำถามต่อความคิดที่บอกว่าคุณติดอยู่และทำการปลดปล่อยเพียงเล็กน้อย","yesNoMeaning":"แปดของดาบเอนโน้ต: ตั้งคำถามกับความคิดที่บอกว่าคุณติดอยู่และทำการกระทำเล็ก ๆ เพื่อปลดปล่อย"}' WHERE card_id = 'eight-of-swords' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"เก้าดาบ","meaning":"ความวิตกกังวลขยายอันตรายในความมืดและทำให้จิตใจเหนื่อยล้า การคิดซ้ำๆ อาจรู้สึกรุนแรงที่สุดเมื่อคุณเผชิญมันตามลำพัง แยกสิ่งที่เกิดขึ้นออกจากสิ่งที่คุณจินตนาการว่าจะเกิดขึ้น และปล่อยให้ตัวเองขอความช่วยเหลือ","advice":"นำความกลัวออกมาให้สว่างในวัน พยายามหาการสนับสนุน และแยกข้อเท็จจริงออกจากผลลัพธ์ที่จินตนาการ","yesNoMeaning":"เก้าดาบคว่ำไปทางไม่: นำความกลัวออกสู่แสงสว่าง หาแนวทางสนับสนุน และแยกข้อเท็จจริงออกจากผลลัพธ์ที่จินตนาการขึ้น"}' WHERE card_id = 'nine-of-swords' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"สิบทวน","meaning":"วงจรที่เจ็บปวดมาถึงขีดจำกัดสุดท้ายและไม่สามารถดำเนินต่อไปได้โดยไม่เปลี่ยนแปลง การจบลงอาจทำให้คุณรู้สึกหมดแรงหลังจากสถานการณ์ดำเนินไปนานเกินไป รูปแบบเก่าไม่สามารถดำเนินต่อไปได้โดยไม่เปลี่ยนแปลง แต่ขอบเขตที่ชัดเจนยิ่งขึ้นสามารถสร้างพื้นที่สำหรับการฟื้นตัวอย่างค่อยเป็นค่อยไป","advice":"ยอมรับจุดจบ ปกป้องการฟื้นตัวของคุณ และอนุญาตให้การเริ่มต้นใหม่เกิดขึ้น","yesNoMeaning":"ไพ่สิบดาบโน้มไปทางไม่: ยอมรับการสิ้นสุด ปกป้องการฟื้นตัวของคุณ และเปิดโอกาสให้การเริ่มต้นใหม่เกิดขึ้น"}' WHERE card_id = 'ten-of-swords' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"หน้าไพ่ดาบ","meaning":"แจ้งเตือนความอยากรู้อยากเห็นแสวงหาข้อเท็จจริง ถามคำถาม และเฝ้าดูการเปลี่ยนแปลง ความอยากรู้อยากเห็นผลักดันให้คุณถามคำถามและตรวจสอบรายละเอียดก่อนที่จะยอมรับข้อสรุป ความตื่นตัวนั้นสนับสนุนการเรียนรู้เมื่อไม่ทำให้ทุกคนสงสัย","advice":"ค้นคว้าอย่างรอบคอบและพูดอย่างแม่นยำ แทนที่จะตอบสนองต่อทุกสัญญาณ","yesNoMeaning":"ไพ่เพจดาบยังคงมีเงื่อนไข: ศึกษาอย่างรอบคอบและพูดอย่างแม่นยำ แทนที่จะตอบสนองต่อทุกสัญญาณ"}' WHERE card_id = 'page-of-swords' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"อัศวินดาบ","meaning":"สติปัญญาที่มุ่งเน้นเคลื่อนที่อย่างรวดเร็วและเผชิญหน้ากับอุปสรรคโดยตรง ความคิดที่ชัดเจนอาจส่งคุณไปข้างหน้าและทำให้คุณพูดได้โดยตรง การตัดสินใจจะได้ผลดีที่สุดเมื่อคุณยังคงได้ยินหลักฐานใหม่ๆ และสังเกตว่าคำพูดของคุณส่งผลต่อผู้อื่นอย่างไร","advice":"ก้าวไปด้วยความกล้าหาญ แต่ช้าเพียงพอที่จะฟังสิ่งที่ความมั่นใจของคุณอาจพลาด","yesNoMeaning":"อัศวินแห่งดาบยังคงมีเงื่อนไข: ก้าวไปด้วยความกล้า แต่ช้าเพียงพอที่จะได้ยินสิ่งที่ความมั่นใจของคุณอาจพลาด"}' WHERE card_id = 'knight-of-swords' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ราชินีแห่งดาบ","meaning":"การรับรู้ที่ชัดเจนและขอบเขตที่ซื่อสัตย์ช่วยลดความสับสน ประสบการณ์สามารถช่วยให้คุณเห็นสิ่งสำคัญระหว่างความรู้สึกและคำสัญญาที่แข่งขันกัน ตรงไปตรงมาและรักษาขอบเขตที่ดีโดยไม่สูญเสียความเห็นอกเห็นใจ","advice":"พูดความจริงด้วยความเมตตาและให้ประสบการณ์ลับคมคุณ ไม่ใช่ทำให้คุณแข็ง","yesNoMeaning":"ราชินีแห่งดาบเอียงไปทางใช่: พูดความจริงด้วยความเมตตาและให้ประสบการณ์ทำให้คุณเฉียบคม แต่ไม่แข็งกระด้าง"}' WHERE card_id = 'queen-of-swords' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ราชาดาบ","meaning":"เหตุผล ความเป็นธรรม และวิจารณญาณที่มีระเบียบวินัยเป็นแนวทางในการตัดสินใจที่เป็นผลสืบเนื่อง การตัดสินใจที่ยากลำบากจะต้องอาศัยมาตรฐานที่สอดคล้องกันและเหตุผลที่ชัดเจน อำนาจของไพ่ใบนี้มาจากความเป็นธรรม ไม่ใช่แค่จากคำพูดสุดท้ายเท่านั้น","advice":"ใช้หลักฐาน กำหนดมาตรฐาน และควรตัดอคติส่วนตัวออกจากคำตัดสิน","yesNoMeaning":"The King of Swords มีแนวโน้มว่าใช่: ใช้หลักฐาน กำหนดมาตรฐาน และเก็บความลำเอียงส่วนตัวออกจากคำตัดสิน"}' WHERE card_id = 'king-of-swords' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"เอซแห่งเหรียญ","meaning":"โอกาสที่จับต้องได้มอบเมล็ดพันธุ์แห่งความเจริญรุ่งเรือง การงาน หรือความเป็นอยู่ที่ดี การเปิดภาคปฏิบัติอาจดูเหมือนเป็นงาน การสนับสนุน ทักษะ หรือสภาวะที่ดีต่อสุขภาพ คุณค่าของมันขึ้นอยู่กับว่าการดูแลมันอย่างไรเมื่อเวลาผ่านไป ไม่ใช่แค่การอุทธรณ์ครั้งแรกเท่านั้น","advice":"จุดรากโอกาสในแผนปฏิบัติและดูแลมันอย่างสม่ำเสมอ","yesNoMeaning":"เอซของเหรียญโน้มเอียงไปใช่: วางโอกาสบนแผนปฏิบัติและดูแลมันอย่างต่อเนื่อง"}' WHERE card_id = 'ace-of-pentacles' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"สองเหรียญ","meaning":"ลำดับความสำคัญหลายอย่างดำเนินไปในคราวเดียวและต้องการความสมดุลที่ยืดหยุ่น คุณอาจสร้างสมดุลระหว่างงาน เงิน เวลา และความต้องการส่วนตัวในคราวเดียว ความยืดหยุ่นช่วยให้สิ่งต่างๆ เคลื่อนไหวได้ แต่การดำเนินการที่ยืดเยื้อจำเป็นต้องจัดลำดับความสำคัญที่ชัดเจนยิ่งขึ้น","advice":"ปรับจังหวะ ปกป้องสิ่งสำคัญ และหลีกเลี่ยงการสัญญามากเกินกว่าที่คุณรับไหว","yesNoMeaning":"ไพ่ Two of Pentacles ยังคงแบบมีเงื่อนไข: ปรับจังหวะ ปกป้องสิ่งสำคัญ และหลีกเลี่ยงการสัญญามากเกินกว่าที่คุณจะรับได้"}' WHERE card_id = 'two-of-pentacles' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ไพ่สามเหรียญ","meaning":"ทักษะเติบโตผ่านการทำงานร่วมกัน ข้อเสนอแนะ และงานฝีมือที่ระมัดระวัง งานที่ดีจะเติบโตเมื่อแต่ละคนเข้าใจส่วนและจุดแข็งของตนเอง ความคิดเห็นที่เจาะจง การเรียนรู้งานฝีมือ และการเคารพต่อความพยายามอย่างเงียบๆ ล้วนมีความสำคัญที่นี่","advice":"ร่วมแรงร่วมใจ ให้เกียรติเฉพาะด้าน และสร้างไปสู่มาตรฐานร่วม","yesNoMeaning":"ไพ่สามดวงเพนทาเคิลโน้มไปทางใช่: มีส่วนร่วมด้วยความสามารถของคุณ ให้เกียรติผู้เชี่ยวชาญ และสร้างตามมาตรฐานร่วมกัน"}' WHERE card_id = 'three-of-pentacles' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"สี่เหรียญ","meaning":"การรักษาความปลอดภัยอย่างแน่นหนาสามารถรักษาทรัพยากรได้ แต่จำกัดการไหลที่ดี การยึดมั่นในทรัพยากรที่ได้มาอย่างยากลำบากสามารถรู้สึกสมเหตุสมผลในช่วงที่มีความไม่แน่นอน เมื่อความกลัวต่อการสูญเสียครอบงำทุกทางเลือก ทั้งเงินและความอุ่นใจก็อาจถูกจำกัด","advice":"ปกป้องสิ่งที่สำคัญโดยไม่ให้ความกลัวเป็นตัวกำหนดทุกการตัดสินใจ","yesNoMeaning":"ไพพิณสี่ใบยังคงมีเงื่อนไข: ปกป้องสิ่งที่สำคัญโดยไม่ให้ความกลัวเป็นตัวกำหนดทุกการตัดสินใจของคุณ"}' WHERE card_id = 'four-of-pentacles' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ไพ่ห้าเหรียญ","meaning":"ความเครียดหรือการกีดกันของวัสดุทำให้เกิดความกังวลและความรู้สึกขาดแคลน ความยากลำบากทำให้คุณรู้สึกโดดเดี่ยวหรือไม่สมควรได้รับความช่วยเหลือ ความช่วยเหลือที่เป็นประโยชน์อาจยังอยู่ใกล้ตัว แม้ว่าความทุกข์ยากจะทำให้มองเห็นได้ยากก็ตาม","advice":"ขอความช่วยเหลือในทางปฏิบัติและสังเกตประตูที่ความลำบากทำให้มองข้ามได้ง่าย","yesNoMeaning":"ไพพิณห้าใบเอียงไปไม่: ขอความช่วยเหลือที่เป็นรูปธรรมและสังเกตประตูที่ความยากลำบากทำให้มองข้ามได้ง่าย"}' WHERE card_id = 'five-of-pentacles' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ไพ่หกเหรียญ","meaning":"มีการแลกเปลี่ยนทรัพยากร ทำให้เกิดคำถามถึงความมีน้ำใจ อำนาจ และความเป็นธรรม ความช่วยเหลือจะทำงานได้ดีที่สุดเมื่อทั้งผู้ให้และผู้รับรักษาศักดิ์ศรีและกระบอกเสียง ดูว่าการแลกเปลี่ยนมีความสมดุลหรือไม่และมีเงื่อนไขใดบ้างที่มาพร้อมกับความเอื้ออาทร","advice":"ให้หรือรับด้วยเงื่อนไขชัดเจนเพื่อให้การสนับสนุนยังคงรักษาศักดิ์ศรีทั้งสองฝ่าย","yesNoMeaning":"ไพ่ Six of Pentacles โน้มไปทางใช่: ให้หรือรับอย่างมีเงื่อนไขชัดเจนเพื่อให้การสนับสนุนรักษาศักดิ์ศรีของทั้งสองฝ่าย"}' WHERE card_id = 'six-of-pentacles' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"เจ็ดดวงเหรียญ","meaning":"การลงทุนของผู้ป่วยถึงจุดประเมินก่อนที่จะดำเนินการครั้งต่อไป คุณได้ลงทุนลงแรงแล้ว แต่ผลลัพธ์อาจไม่เป็นไปตามกำหนดเวลาที่คุณต้องการ ทบทวนความคืบหน้าและแยกแยะสิ่งที่ต้องการความอดทนมากขึ้นจากสิ่งที่ต้องการแนวทางใหม่","advice":"ทบทวนสิ่งที่กำลังเติบโต ปรับปรุงวิธีการ และให้เวลาสำหรับผลลัพธ์ที่คุ้มค่า","yesNoMeaning":"เจ็ดเหรียญยังคงเป็นไปตามเงื่อนไข: ตรวจสอบสิ่งที่กำลังเติบโต ปรับปรุงวิธีการ และให้เวลาผลลัพธ์ที่คุ้มค่า"}' WHERE card_id = 'seven-of-pentacles' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"แปดของเหรียญ","meaning":"การทำซ้ำอย่างมุ่งเน้นจะพัฒนาความเชี่ยวชาญและผลลัพธ์ที่เชื่อถือได้ ทักษะพัฒนาผ่านการทำซ้ำ การแก้ไข และความใส่ใจในรายละเอียดเล็กๆ น้อยๆ การ์ดให้ความสำคัญกับการฝึกฝนที่มั่นคงซึ่งคนอื่นอาจไม่เคยเห็น มากกว่าการก้าวกระโดดอย่างกะทันหัน","advice":"ฝึกทักษะที่จำเป็น ยินดีรับการแก้ไข และปล่อยให้คุณภาพสะสม","yesNoMeaning":"แปดของเงินเหรียญเอนโน้ต: ฝึกฝนทักษะที่จำเป็น ยินรับการแก้ไข และปล่อยให้คุณภาพสะสม"}' WHERE card_id = 'eight-of-pentacles' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"เก้าเหรียญ","meaning":"การพึ่งพาตนเองและความสะดวกสบายที่ได้รับการฝึกฝนสะท้อนถึงความก้าวหน้าที่มีระเบียบวินัย ความสบายใจในปัจจุบันของคุณอาจสะท้อนถึงการเลือกที่มีระเบียบวินัยมากมายที่ทำไว้ก่อนหน้านี้ เพลิดเพลินไปกับสิ่งที่คุณสร้างขึ้นตามจังหวะของคุณเองและรับรู้ถึงผลงานเบื้องหลัง","advice":"สนุกกับสิ่งที่คุณสร้างขึ้นและรักษาอิสระที่เชื่อมโยงกับความกตัญญู","yesNoMeaning":"เก้าเหรียญคว่ำไปทางใช่: เพลิดเพลินกับสิ่งที่คุณสร้างขึ้นและเก็บความเป็นอิสระเชื่อมโยงกับความกตัญญู"}' WHERE card_id = 'nine-of-pentacles' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"สิบเหรียญ","meaning":"ความมั่นคงระยะยาวเติบโตผ่านมรดก ครอบครัว และรากฐานที่มีร่วมกัน เรื่องราวขยายออกไปไกลกว่าความสำเร็จของบุคคลหนึ่งไปสู่ครอบครัว ชุมชน หรือผู้ที่ติดตาม รากฐานที่ทนทานเติบโตจากการดูแลทรัพยากรที่ใช้ร่วมกันอย่างรอบคอบ","advice":"วางแผนเกินกว่าชัยชนะในทันทีและปกป้องสิ่งที่สามารถสนับสนุนผู้อื่นในระยะยาว","yesNoMeaning":"ไพ่สิบดวงเพนทาเคิลโน้มไปทางใช่: วางแผนเกินกว่าชัยชนะทันทีและปกป้องสิ่งที่สามารถสนับสนุนผู้อื่นในระยะยาว"}' WHERE card_id = 'ten-of-pentacles' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"หน้าไพ่เหรียญ","meaning":"ข้อความที่เป็นประโยชน์เชิญชวนให้ศึกษา วางแผน หรือการร่วมลงทุนครั้งใหม่ที่มีพื้นฐาน โอกาสเชิงปฏิบัติจะชัดเจนยิ่งขึ้นเมื่อคุณเรียนรู้พื้นฐานของโอกาสนั้น สำรวจอย่างอดทน ทดสอบในระดับเล็กๆ และสังเกตว่าสิ่งใดมีคุณค่าที่ยั่งยืน","advice":"เรียนรู้พื้นฐาน กำหนดงานต่อไป และพิสูจน์แนวคิดผ่านการทำงานอย่างมั่นคง","yesNoMeaning":"ไพ่เพจเพนตาเคิลมีแนวโน้มไปทางใช่: เรียนรู้พื้นฐาน กำหนดงานต่อไป และพิสูจน์แนวคิดด้วยการทำงานอย่างมั่นคง"}' WHERE card_id = 'page-of-pentacles' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"อัศวินเหรียญ","meaning":"ความพยายามที่เชื่อถือได้ก้าวหน้าอย่างช้าๆ แต่ไม่ค่อยละทิ้งงาน ความก้าวหน้าอาจรู้สึกช้ามากจนคุณสงสัยว่าคุณกำลังเคลื่อนไหวหรือไม่ แต่ความสม่ำเสมอกำลังสร้างรากฐาน ความน่าเชื่อถือยังต้องการพื้นที่พักผ่อนอีกด้วย","advice":"รักษากิจวัตรให้น่าเชื่อถือและสม่ำเสมอ ความก้าวหน้าสำคัญกว่าความตื่นเต้น","yesNoMeaning":"อัศวินแห่งเหรียญคว่ำไปทางใช่: รักษากิจวัตรให้น่าเชื่อถือและสม่ำเสมอ; ความก้าวหน้าสำคัญกว่าความตื่นเต้น"}' WHERE card_id = 'knight-of-pentacles' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ราชินีแห่งเพนทาเคิล","meaning":"การดูแลอย่างมีทรัพยากรช่วยสร้างความสะดวกสบาย สุขภาพ และความอุดมสมบูรณ์ในทางปฏิบัติ ความปลอดภัยสามารถสร้างขึ้นได้ด้วยการดูแลอย่างเป็นรูปธรรมและการใช้ทรัพยากรอย่างชาญฉลาด ความมีน้ำใจที่ยั่งยืนเริ่มต้นด้วยการจดจำความต้องการของคุณเองเช่นกัน","advice":"ดูแลผู้คนและแผนการในวิธีที่ยั่งยืนสำหรับตัวคุณ","yesNoMeaning":"ราชินีแห่งเหรียญเอียงไปทางใช่: ดูแลผู้คนและแผนการในวิธีที่ยั่งยืนสำหรับคุณ"}' WHERE card_id = 'queen-of-pentacles' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"ราชาเหรียญ","meaning":"ความเป็นผู้นำด้านวัสดุเปลี่ยนประสบการณ์ให้กลายเป็นการดูแลที่มั่นคงและมีน้ำใจ ประสบการณ์สามารถสนับสนุนอนาคตที่มั่นคงของการทำงาน ครอบครัว หรือชุมชนได้ ความสำเร็จมีความหมายมากขึ้นเมื่อผู้ที่ช่วยสร้างสามารถมีส่วนร่วมในความมั่นคงนั้นได้","advice":"ตัดสินใจเลือกเสียงในระยะยาวและใช้ความสำเร็จอย่างรับผิดชอบ","yesNoMeaning":"The King of Pentacles มีแนวโน้มว่าใช่: ทำทางเลือกที่เป็นประโยชน์ในระยะยาวและใช้ความสำเร็จอย่างรับผิดชอบ"}' WHERE card_id = 'king-of-pentacles' AND locale = 'th';
UPDATE card_translations SET payload = '{"name":"Le Mat","meaning":"Une page blanche et un acte de foi : un nouveau voyage commence avec un cœur ouvert. Vous n’avez pas besoin d’une carte complète avant de faire le premier pas. La curiosité vous aide à apprendre de chaque tentative, tandis qu''un peu de préparation empêche la liberté de se transformer en insouciance.","advice":"Faites confiance au chemin devant vous et faites ce premier pas, même sans toutes les réponses.","yesNoMeaning":"Un nouveau départ ne porte rarement une réponse fixe — le résultat dépend de la mesure que vous prenez."}' WHERE card_id = 'fool' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Le Magicien","meaning":"Vous détenez tous les outils dont vous avez besoin. Concentrez votre volonté et transformez votre intention en action. Une idée devient réelle lorsque votre attention, votre temps et les ressources disponibles sont orientés vers la même tâche. Regardez les outils déjà à portée de main avant d’attendre un autre signe.","advice":"Utilisez vos compétences et ressources délibérément — le moment est venu de passer à l''action.","yesNoMeaning":"Vous détenez déjà tout ce qui est nécessaire — l''énergie soutient l''avancement avec concentration."}' WHERE card_id = 'magician' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"La Grande Prêtresse","meaning":"La sagesse tranquille se cache sous la surface. Écoutez votre intuition et votre voix intérieure. Le silence peut révéler une tendance, un sentiment que vous ne pouvez pas encore nommer ou une information qui manque encore. Observez encore un peu avant de tout mettre au grand jour.","advice":"Faites une pause, tournez-vous vers l''intérieur et laissez vos instincts vous guider avant d''agir.","yesNoMeaning":"La réponse est cachée sous la surface pour l''instant — faites confiance à votre intuition plutôt que de forcer un oui ou un non clair."}' WHERE card_id = 'high-priestess' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"L''Impératrice","meaning":"La croissance, l’abondance et l’énergie nourricière vous entourent. Laissez la beauté et les soins s''épanouir. Une relation, un projet ou une partie de vous-même peut se développer grâce à des soins constants. L’abondance signifie ici avoir de la place pour se développer, ne pas donner jusqu’à ce qu’il ne reste plus rien.","advice":"Soyez patient et généreux — créez avec amour et laissez les choses mûrir naturellement.","yesNoMeaning":"Croissance, abondance et énergie nourricière soutiennent votre souhait — la réponse est un oui silencieux."}' WHERE card_id = 'empress' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"L''Empereur","meaning":"Structure, autorité et leadership stable. Construisez sur des bases solides avec discipline. Une structure utile donne aux gens la sécurité de grandir. Remarquez la différence entre assumer la responsabilité et essayer de contrôler chaque détail ; ils peuvent se ressembler au début.","advice":"Prenez les commandes avec un plan clair ; des limites fermes apportent une stabilité durable.","yesNoMeaning":"Structure, autorité et discipline constante soutiennent un oui confiant."}' WHERE card_id = 'emperor' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Le Hiérophante","meaning":"La tradition et des conseils fiables offrent un chemin fiable. Apprenez de ce qui a précédé. Un enseignant, une communauté ou une méthode établie peuvent constituer un bon point de départ. Découvrez pourquoi une tradition fonctionne afin de pouvoir l''appliquer de manière réfléchie à votre propre situation.","advice":"Suivez la sagesse établie et demandez conseil à ceux en qui vous avez confiance.","yesNoMeaning":"La tradition et les conseils de confiance indiquent un oui fiable — appuyez-vous sur ce qui a déjà fait ses preuves."}' WHERE card_id = 'hierophant' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Les Amoureux","meaning":"Un lien significatif ou un choix important. Suivez ce que votre cœur valorise vraiment. Une harmonie durable demande aux deux parties de parler honnêtement de leurs besoins et de leurs limites. S''il s''agit d''une décision plutôt que d''une romance, demandez quel chemin reflète vos valeurs les plus profondes.","advice":"Choisissez avec honnêteté et alignement — la connexion s''approfondit lorsque vous êtes sincère.","yesNoMeaning":"Votre cœur et vos valeurs sont alignés ici — la réponse est oui, surtout lorsque vous choisissez avec honnêteté."}' WHERE card_id = 'lovers' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Le Chariot","meaning":"La volonté et l’élan vous font avancer. Restez concentré et vous gagnerez. Des impulsions opposées peuvent toujours vous faire avancer lorsque vous leur donnez une direction commune. Le progrès dépend de la gestion de vos sentiments et de vos actions, et pas simplement de vos efforts.","advice":"Gardez les yeux sur le but et dirigez avec confiance à travers chaque obstacle.","yesNoMeaning":"La volonté et l''élan sont de votre côté — un oui concentré, à condition de rester engagé."}' WHERE card_id = 'chariot' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Force","meaning":"Le vrai pouvoir est doux : la patience, le courage et la compassion maîtrisent tous les défis. La douceur est une forme active de courage : vous pouvez rester avec l''inconfort sans le laisser décider de votre réponse. Reconnaissez la peur et bougez avec précaution plutôt que d’attendre que la peur disparaisse.","advice":"Dirigez avec une force calme; une main douce est souvent la plus forte.","yesNoMeaning":"Un courage doux et une résolution patiente font de cela un oui — avancez avec calme, et non par la force."}' WHERE card_id = 'strength' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"L''Hermite","meaning":"Il est temps de prendre du recul et de rechercher la clarté intérieure. La solitude apporte désormais des réponses plus profondes. Prendre du recul peut rendre votre propre voix plus facile à entendre parmi les opinions des autres. La solitude aide lorsqu’elle mène à la compréhension, mais elle peut aussi devenir un moyen d’éviter la connexion.","advice":"Tournez-vous vers l''intérieur, réfléchissez, et laissez le calme révéler ce dont vous avez vraiment besoin.","yesNoMeaning":"Pas encore — la carte vous demande de prendre du recul et de trouver la clarté intérieure avant d''agir."}' WHERE card_id = 'hermit' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Roue de la Fortune","meaning":"La fortune tourne et les cycles changent. Ce qui change maintenant s’inscrit dans un rythme plus large. Un ancien cycle est peut-être en train de se retourner, apportant des inconvénients aux côtés des possibilités. Vous ne pouvez pas choisir chaque événement, mais vous pouvez choisir ce que vous souhaitez reporter et comment vous préparer pour le prochain tour.","advice":"Surfez sur la vague avec flexibilité — acceptez le tournant, qu''il soit bon ou non.","yesNoMeaning":"La fortune tourne — le résultat dépend de la façon dont vous traversez le changement plutôt que d''un oui ou non fixe."}' WHERE card_id = 'wheel-of-fortune' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Justice","meaning":"La vérité et l’équité l’emportent. La cause et l’effet s’équilibrent désormais. Ce qui se passe reflète peut-être une chaîne de choix antérieurs plutôt qu’un moment isolé. Vérifiez les faits, entendez les personnes impliquées et possédez la pièce qui vous appartient.","advice":"Agis avec honnêteté et pèse les deux côtés ; les balances se régleront équitablement.","yesNoMeaning":"Les balances sont encore en train de se peser — la réponse juste dépend des faits et de votre honnêteté."}' WHERE card_id = 'justice' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"L''Homme Pendu","meaning":"Une pause nécessaire. Relâchez le contrôle et voyez la situation sous un nouvel angle. Attendre peut être inconfortable lorsque l’action est votre réponse habituelle. Un changement de perspective, ou quelque chose que vous choisissez de libérer, peut révéler ce que davantage de pression ne pourrait pas faire.","advice":"Arrêtez de pousser — abandonnez-vous au moment et laissez arriver une nouvelle perspective.","yesNoMeaning":"Une pause est nécessaire d’abord — forcer cela maintenant ne ferait que retarder une réponse plus claire."}' WHERE card_id = 'hanged-man' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Mort","meaning":"Une fin ouvre la voie au renouveau. Libérez ce qui a fait son temps. Cette carte parle de transition plutôt que d’une prédiction littérale de perte. Vous avez peut-être dépassé un ancien rôle, une habitude ou une attente ; le laisser derrière vous peut encore prendre du temps.","advice":"Lâche prise sans regret ; une transformation profonde ouvre une nouvelle porte.","yesNoMeaning":"Une fin est en train de dégager le chemin — le chemin actuel se ferme pour qu''un nouveau puisse commencer."}' WHERE card_id = 'death' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Tempérance","meaning":"L''équilibre et la patience apportent l''harmonie. Mélangez les contraires avec grâce. Recherchez ce qui peut être combiné à partir de deux approches différentes. Les progrès tranquilles peuvent prendre la forme d’une habitude durable, d’une conversation plus calme ou d’un rythme que vous pouvez réellement maintenir.","advice":"Avancez avec modération et gardez votre calme — des pas réguliers atteignent la destination.","yesNoMeaning":"L''équilibre et la patience apportent l''harmonie — un oui mesuré, pris un pas stable à la fois."}' WHERE card_id = 'temperance' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Le Diable","meaning":"Méfiez-vous de l’attachement, de la tentation ou d’un modèle contraignant. Reconnaissez les chaînes. Un avantage à court terme peut rendre difficile l’abandon d’un modèle coûteux. Nommer ce que vous en tirez, ainsi que ce que cela coûte, peut vous redonner un peu de liberté de choix.","advice":"Nomme ce qui te retient et reprends ta liberté — la chaîne ne te lie que si tu le permets.","yesNoMeaning":"L''attachement ou un schéma contraignant fait obstacle — pas encore, jusqu''à ce que la chaîne soit nommée et brisée."}' WHERE card_id = 'devil' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"La Tour","meaning":"Un changement soudain brise le faux et révèle la vérité. Ce qui tombe n’a jamais été censé durer. La perturbation est difficile lorsqu’elle ébranle un projet auquel vous faisiez confiance. Vous n’êtes pas obligé de trouver immédiatement le bon côté des choses ; remarquez d’abord ce qui a vraiment changé et ce qui reste debout.","advice":"Accueillez le bouleversement ; des décombres, une fondation plus claire peut être construite.","yesNoMeaning":"Un changement soudain brise l''ancien — le sol doit se stabiliser avant qu''un oui ferme soit possible."}' WHERE card_id = 'tower' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"L''Étoile","meaning":"L''espoir, la guérison et une inspiration tranquille renouvellent votre esprit après la tempête. L’espoir n’est pas une promesse que tout se résoudra tout seul. Il est possible de respirer après une difficulté et de continuer à s’occuper de ce qui compte avant que le résultat ne soit visible.","advice":"Faites confiance à la lumière qui vous attend et continuez à croire — vos souhaits sont à portée de main.","yesNoMeaning":"L''espoir et le renouveau tranquille indiquent oui — faites confiance à la lumière à venir et gardez votre souhait vivant."}' WHERE card_id = 'star' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"La Lune","meaning":"L’illusion et l’incertitude brouillent les pistes. Faites confiance à votre intuition, pas aux apparences. Lorsque les faits sont incomplets, la mémoire et la peur peuvent combler les lacunes avec une histoire convaincante. Ralentissez, remarquez votre réaction et séparez ce que vous ressentez de ce que vous avez vérifié.","advice":"Ralentissez et regardez plus profondément ; la clarté viendra lorsque le brouillard se dissipe.","yesNoMeaning":"L''illusion et l''incertitude brouillent le chemin — la réponse n''est pas claire tant que vous ne regardez pas au-delà des apparences."}' WHERE card_id = 'moon' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Le Soleil","meaning":"Joie, réussite et clarté rayonnante. Tout est lumineux et plein de vie. La clarté peut vous aider à reconnaître vos progrès et à partager votre joie sans la minimiser. S’il reste du travail, cette énergie renouvelée peut vous aider à l’affronter plus ouvertement.","advice":"Célébrez et brillez — l''énergie positive attire les résultats que vous désirez.","yesNoMeaning":"La joie et une clarté radieuse confirment un oui éclatant — tout fonctionne en votre faveur."}' WHERE card_id = 'sun' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Jugement","meaning":"Un appel à s’élever, à se renouveler et à être honnête avec soi-même. Un verdict de réveil. Revoir le passé ne signifie pas nécessairement se blâmer pour toujours. Tirez la leçon, pardonnez ce que vous pouvez et répondez dès maintenant à l’appel au changement par un choix conscient.","advice":"Répondez à l''appel avec courage ; pardonnez le passé et entrez dans votre prochain chapitre.","yesNoMeaning":"Un appel à se lever et à se renouveler — oui, surtout une fois que vous avez pardonné le passé et répondu honnêtement."}' WHERE card_id = 'judgement' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Le Monde","meaning":"Achèvement et épanouissement – un cycle se termine dans une parfaite intégralité. La réussite inclut les compétences, les relations et la perspective que vous avez acquises en cours de route. Honorez l’achèvement de ce cycle alors même qu’un voyage plus large se poursuit.","advice":"Célébrez ce que vous avez accompli ; la porte est ouverte vers un monde plus vaste.","yesNoMeaning":"Accomplissement et plénitude marquent cela comme un oui accompli — le cycle se termine en votre faveur."}' WHERE card_id = 'world' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"As de Bâtons","meaning":"Une étincelle d’inspiration ouvre un chemin créatif audacieux. Une invitation, un projet ou une nouvelle envie peuvent vous faire sentir plus vivant. Il s’agit là d’un résultat potentiel plutôt que d’un résultat garanti ; il a besoin d’espace pour expérimenter et d’engagement une fois que la première excitation s’est estompée.","advice":"Commencez pendant que l''énergie est fraîche et donnez à l''idée un véritable premier pas.","yesNoMeaning":"L''As de Bâtons penche pour oui : commencez tant que l''énergie est fraîche et donnez à l''idée un vrai premier pas."}' WHERE card_id = 'ace-of-wands' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Deux de Bâtons","meaning":"Un avenir se dessine grâce à la planification et à un choix d’orientation. Vous pouvez voir plus d’un itinéraire et commencez à vous demander jusqu’où vous voulez aller. Une vue d’ensemble est utile, mais une planification sans fin peut vous maintenir sur le seuil.","advice":"Regarde au-delà de ce qui est familier, puis engage-toi sur le chemin avec de la place pour grandir.","yesNoMeaning":"Le Deux de Bâtons reste conditionnel : regardez au-delà de ce qui est familier, puis engagez-vous sur le chemin offrant de la place pour grandir."}' WHERE card_id = 'two-of-wands' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Trois de Bâtons","meaning":"Les premiers efforts s’étendent à mesure que des opportunités et des horizons plus larges apparaissent. Ce que vous avez commencé commence à susciter une réponse au-delà du territoire familier. Restez ouvert aux contacts et aux commentaires tout en laissant le temps à vos travaux antérieurs de porter leurs fruits.","advice":"Continuez à construire et soyez prêt à faire face à la réaction que votre travail suscite.","yesNoMeaning":"Le Trois de Bâtons penche vers oui : continuez à construire et soyez prêt à rencontrer la réponse que votre travail attire."}' WHERE card_id = 'three-of-wands' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Quatre de Bâtons","meaning":"La stabilité, l’accueil et la célébration partagée créent une base solide. Une étape importante mérite d’être célébrée même si le voyage n’est pas terminé. L’appartenance et les personnes qui ont contribué à construire ce moment peuvent renforcer votre prochaine étape.","advice":"Marquez l''étape et laissez les personnes de soutien en profiter.","yesNoMeaning":"Le Quatre de Bâtons penche vers oui : marquez l''étape et laissez les personnes de soutien en profiter."}' WHERE card_id = 'four-of-wands' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Cinq de Bâtons","meaning":"Des objectifs concurrents créent des frictions, du bruit ou un test de confiance. De nombreuses voix concurrentes peuvent cacher l’objectif commun. Le conflit peut affiner une idée lorsque tout le monde sait de quoi il débat réellement et peut écouter au-delà des différences.","advice":"Transformez la rivalité en pratique utile et refusez les conflits qui n''ont aucun but.","yesNoMeaning":"Le Cinq de Bâtons reste conditionnel : transformez la rivalité en pratique utile et refusez le conflit qui n''a aucun but."}' WHERE card_id = 'five-of-wands' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Six de Bâtons","meaning":"La reconnaissance suit un effort déterminé et des progrès visibles. Vos efforts pourraient enfin être vus par les autres. La reconnaissance peut vous encourager, mais la valeur de votre travail demeure même lorsqu''aucun public ne vous regarde.","advice":"Acceptez l''encouragement, mais gardez votre confiance liée à un travail honnête.","yesNoMeaning":"Le Six de Bâtons penche vers oui : acceptez les encouragements, mais gardez votre confiance liée à un travail honnête."}' WHERE card_id = 'six-of-wands' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Sept de Bâtons","meaning":"Vous détenez un terrain précieux pendant que la pression met votre détermination à l’épreuve. Pour protéger ce qui compte, il faut savoir pourquoi cela compte pour vous. La pression peut provenir de plusieurs directions, mais tous les défis ne méritent pas un combat.","advice":"Défendez ce qui compte avec des limites claires au lieu de combattre chaque défi.","yesNoMeaning":"Le Sept de Bâtons penche vers oui : défendez ce qui compte avec des limites claires plutôt que de combattre chaque défi."}' WHERE card_id = 'seven-of-wands' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Huit de Baguettes","meaning":"Les événements s’accélèrent, les messages arrivent et l’élan élimine les retards. Les nouvelles ou les décisions peuvent arriver plus rapidement que prévu. La vitesse est utile lorsque tout le monde comprend la direction ; des informations peu claires peuvent transformer l’élan en confusion.","advice":"Agissez rapidement et maintenez une communication directe tant que la voie est ouverte.","yesNoMeaning":"Le Huit de Bâtons penche pour oui : agissez rapidement et gardez la communication directe tant que le chemin est ouvert."}' WHERE card_id = 'eight-of-wands' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Neuf de Bâtons","meaning":"La résilience est forte, même si les tensions passées vous obligent à être vigilant. Les tensions passées vous ont appris à vous protéger, mais une vigilance constante est épuisante. Jugez du risque qui se présente à vous à l''aune des preuves d''aujourd''hui ainsi qu''aux blessures d''hier.","advice":"Protégez votre énergie et faites le prochain pas sans vous attendre à ce que chaque blessure se répète.","yesNoMeaning":"Le Neuf de Bâtons reste conditionnel : protégez votre énergie et faites le prochain pas sans vous attendre à ce que chaque blessure se répète."}' WHERE card_id = 'nine-of-wands' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Dix de Bâtons","meaning":"La responsabilité est devenue lourde et le succès porte désormais un fardeau. Quelque chose dont vous étiez autrefois fier peut maintenant comporter trop d''obligations. Votre capacité est réelle, mais elle ne vous oblige pas à accomplir chaque tâche seul.","advice":"Déléguez, simplifiez et abandonnez le travail qui n''est plus vraiment le vôtre.","yesNoMeaning":"Le Dix de Bâtons penche vers non : déléguez, simplifiez et laissez tomber le travail qui n''est plus vraiment le vôtre."}' WHERE card_id = 'ten-of-wands' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Valet de Bâtons","meaning":"La curiosité apporte un message vivant, une expérience ou un nouvel intérêt créatif. Une nouvelle idée peut raviver l''enthousiasme d''un débutant. Vous n’avez pas besoin de tout maîtriser avant d’explorer ; donnez-vous la permission d’essayer, de vous ajuster et d’apprendre dans la pratique.","advice":"Explorez avec courage et laissez l''énergie du débutant vous enseigner par l''action.","yesNoMeaning":"Le Valet de Bâtons penche vers le oui : explorez avec courage et laissez l''énergie de débutant vous enseigner par l''action."}' WHERE card_id = 'page-of-wands' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Chevalier de Bâtons","meaning":"La passion avance rapidement, apportant l’aventure et éventuellement l’impatience. L’attraction de quelque chose de nouveau peut vous donner envie de partir immédiatement. Cette énergie vous sert mieux lorsqu’un objectif clair vous empêche de changer de cap à chaque impulsion qui passe.","advice":"Utilisez l''élan, mais choisissez une direction avant que la vitesse ne disperse vos efforts.","yesNoMeaning":"Le Chevalier de Bâtons reste conditionnel : utilisez l''élan, mais choisissez une direction avant que la vitesse ne disperse votre effort."}' WHERE card_id = 'knight-of-wands' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Reine de Bâtons","meaning":"Une confiance chaleureuse et une indépendance créative attirent les autres vers votre vision. Votre présence ouverte peut encourager les autres à croire en une vision partagée. Ici, la confiance n’exige pas de surpasser qui que ce soit ; cela permet aux autres de briller aussi.","advice":"Faites confiance à votre présence, encouragez les autres et ne réduisez pas votre ambition.","yesNoMeaning":"La Reine de Bâtons penche oui : faites confiance à votre présence, encouragez les autres et ne réduisez pas votre ambition."}' WHERE card_id = 'queen-of-wands' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Roi de Bâtons","meaning":"Une vision mature transforme l’inspiration en un leadership décisif et éthique. Une vision large nécessite des décisions, des responsabilités et la capacité de maintenir l''énergie d''une équipe. Dirigez vers un objectif clair plutôt que par la pression ou l’ego seul.","advice":"Dirigez à partir d''un objectif plus grand et donnez aux autres l''espace pour contribuer.","yesNoMeaning":"Le Roi de Bâtons penche vers oui : dirigez-vous à partir d''un objectif plus large et donnez aux autres l''espace pour contribuer."}' WHERE card_id = 'king-of-wands' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"As de Coupes","meaning":"Le cœur s’ouvre à une nouvelle affection, compassion et renouveau émotionnel. Une rencontre, un sentiment nouveau ou un adoucissement intérieur peuvent vous inviter à donner et recevoir plus librement. Laissez l’émotion être reconnue avant de la forcer vers un résultat particulier.","advice":"Recevez le sentiment honnêtement et laissez le soin couler sans forcer un résultat.","yesNoMeaning":"L''As de Coupes penche vers le oui : Recevez le sentiment honnêtement et laissez l''attention circuler sans forcer un résultat."}' WHERE card_id = 'ace-of-cups' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Deux de Coupes","meaning":"La reconnaissance mutuelle crée un partenariat, une attirance ou un accord sincère. La promesse la plus profonde réside dans le fait que deux personnes se voient clairement, au-delà de l’attraction initiale. Une conversation sincère, des excuses ou un accord équitable peuvent renforcer le lien.","advice":"Rencontrez l''autre personne en tant qu''égal et parlez avec le cœur.","yesNoMeaning":"Le Deux de Coupes penche vers oui : rencontrez l''autre personne en tant qu''égal et parlez avec le cœur."}' WHERE card_id = 'two-of-cups' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Trois de Coupes","meaning":"L''amitié, la communauté et la joie partagée apportent un soutien émotionnel. Un petit rassemblement ou un soutien opportun peut vous rappeler que la joie ne doit pas nécessairement être portée seule. Souvenez-vous de ceux qui se tenaient à vos côtés avant que les choses ne deviennent plus faciles.","advice":"Célébrez ensemble et souvenez-vous de ceux qui se présentent vraiment pour vous.","yesNoMeaning":"Le Trois de Coupes penche vers oui : célébrez ensemble et souvenez-vous de ceux qui se présentent réellement pour vous."}' WHERE card_id = 'three-of-cups' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Quatre de Coupes","meaning":"Le retrait émotionnel rend un cadeau disponible difficile à remarquer. Lorsque vous êtes fatigué ou découragé, même une bonne offre peut paraître ennuyeuse. Soyez honnête à propos de vos sentiments actuels avant de décider que rien autour de vous n''a d''importance.","advice":"Mettez la comparaison en pause et regardez à nouveau ce qui est tranquillement offert.","yesNoMeaning":"Le Quatre de Coupes penche vers non : pausez la comparaison et regardez à nouveau ce qui est offert silencieusement."}' WHERE card_id = 'four-of-cups' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Cinq de Coupes","meaning":"La perte attire l’attention sur ce qui s’est répandu alors qu’il reste quelque chose de significatif. Le deuil mérite d’être nommé plutôt que couvert d’un optimisme rapide. Même ainsi, une seule perte peut ne pas raconter toute l’histoire ; un soutien ou une possibilité peuvent encore rester à proximité.","advice":"Honorez la déception, puis tournez-vous vers le soutien toujours présent.","yesNoMeaning":"Le Cinq de Coupes penche vers non : honorez la déception, puis tournez-vous vers le soutien encore présent."}' WHERE card_id = 'five-of-cups' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Six de Coupes","meaning":"Le souvenir, l’innocence ou un lien familier reviennent avec une douce chaleur. Un vieil ami ou un souvenir peut vous reconnecter avec un sentiment de sécurité. Accueillez cette chaleur tout en reconnaissant que le présent a changé et que vous avez changé avec lui.","advice":"Accueillez la gentillesse du passé sans prétendre que vous devez y vivre à nouveau.","yesNoMeaning":"Le Six de Coupes penche vers oui : accueillez la gentillesse du passé sans prétendre que vous devez y vivre à nouveau."}' WHERE card_id = 'six-of-cups' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Sept de Coupes","meaning":"De nombreuses possibilités attrayantes brouillent la différence entre vision et illusion. Chaque option peut sembler porteuse d’une belle promesse, mais toutes les promesses ne reposent pas sur le même fondement. Séparez ce que vous voulez vraiment de ce que vous avez imaginé autour.","advice":"Réduisez les choix et testez un rêve contre la réalité avant de vous engager.","yesNoMeaning":"Le Sept de Coupes n''est pas encore clair : restreignez les choix et testez un rêve contre la réalité avant de vous engager."}' WHERE card_id = 'seven-of-cups' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Huit de Coupes","meaning":"Une situation autrefois significative ne nourrit plus le cœur. Abandonner quelque chose qui avait autrefois du sens peut être à la fois triste et bon pour vous maintenant. Sa valeur était réelle, même si votre besoin de sens plus profond a changé.","advice":"Partez avec honnêteté et allez vers l''épanouissement plus profond dont vous avez maintenant besoin.","yesNoMeaning":"Le Huit de Coupes penche pour non : partez avec honnêteté et avancez vers la satisfaction plus profonde dont vous avez maintenant besoin."}' WHERE card_id = 'eight-of-cups' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Neuf de Coupes","meaning":"Le contentement et la gratitude font qu''un souhait sincère se sent proche. Vous avez peut-être atteint quelque chose que vous souhaitiez autrefois et méritez d’en profiter. La satisfaction dure plus longtemps lorsque l’on sait d’où elle vient au lieu de se précipiter vers le désir suivant.","advice":"Appréciez ce qui est ici et demandez-vous si le souhait sert également vos valeurs profondes.","yesNoMeaning":"Le Neuf de Coupes penche oui : profitez de ce qui est là et demandez si le souhait sert également vos valeurs profondes."}' WHERE card_id = 'nine-of-cups' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Dix de Coupes","meaning":"L''harmonie émotionnelle, l''appartenance et la connexion durable entourent la maison. L''harmonie se développe grâce à des soins et une écoute répétés, et non à travers un foyer sans désaccord. Cette carte évoque la liberté d’être soi parmi des personnes désireuses de continuer à construire ensemble.","advice":"Entretenez les liens qui rendent la joie durable et partagée.","yesNoMeaning":"Le Dix de Coupes penche vers oui : entretenez les liens qui rendent la joie durable et partagée."}' WHERE card_id = 'ten-of-cups' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Valet de Coupes","meaning":"Un message tendre ou une découverte intuitive invite à l’ouverture émotionnelle. Un message tendre, un sentiment inattendu ou une idée imaginative peuvent attirer votre attention. Laissez place à la surprise sans considérer chaque signe comme une promesse ferme.","advice":"Restez curieux du ressenti et répondez avec sincérité plutôt qu''avec des suppositions.","yesNoMeaning":"Le Valet de Coupes reste conditionnel : restez curieux du sentiment et répondez avec sincérité plutôt qu''avec des suppositions."}' WHERE card_id = 'page-of-cups' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Chevalier de Coupes","meaning":"La romance, l’imagination ou un idéal attirent le cœur. Vous voudrez peut-être suivre une invitation ou un idéal sincère. La sincérité donne un sens au voyage, tandis que le côté pratique vous aide à voir quelles personnes et quels projets peuvent voyager avec vous au fil du temps.","advice":"Suivez l''invitation, mais gardez un pied sur terre à mesure que les promesses se réalisent.","yesNoMeaning":"Le Cavalier de Coupes penche vers oui : suivez l''invitation, mais gardez un pied sur terre pendant que les promesses se réalisent."}' WHERE card_id = 'knight-of-cups' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Reine de Coupes","meaning":"Une empathie profonde et une intuition créent un espace calme pour la vérité. Écouter attentivement peut aider quelqu''un à se sentir suffisamment en sécurité pour parler. Une profonde empathie signifie également savoir quels sont vos besoins et quelle tristesse vous ne pouvez pas porter pour une autre personne.","advice":"Écoutez avec compassion tout en préservant les limites qui maintiennent les soins en bonne santé.","yesNoMeaning":"La Reine de Coupes penche vers le oui : écoutez avec compassion tout en préservant les limites qui maintiennent le soin en bonne santé."}' WHERE card_id = 'queen-of-cups' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Roi de Coupes","meaning":"La maturité émotionnelle stabilise les sentiments forts sans les réprimer. Des sentiments forts peuvent rester présents pendant que vous choisissez une réponse calme et responsable. Cette stabilité peut rendre une conversation difficile plus sûre pour toutes les personnes impliquées.","advice":"Répondez avec compassion et maîtrise de soi, surtout lorsque les autres sont réactifs.","yesNoMeaning":"Le Roi de Coupes penche vers oui : répondez avec compassion et maîtrise de soi, surtout lorsque les autres réagissent."}' WHERE card_id = 'king-of-cups' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"As d''Épées","meaning":"Une vision claire dissipe la confusion et révèle une nouvelle vérité. Un fait nouveau ou une conversation honnête peut dissiper la confusion. La vérité peut être tranchante, alors utilisez-la pour comprendre et décider plus clairement plutôt que pour blesser.","advice":"Nommez le problème clairement et utilisez la clarté au service d''une décision juste.","yesNoMeaning":"L''As d''Épées penche pour oui : nommez le problème clairement et utilisez la clarté au service d''une décision juste."}' WHERE card_id = 'ace-of-swords' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Deux d''Épées","meaning":"Une impasse prudente retarde un choix qui ne peut pas rester éternellement suspendu. Vous maintenez peut-être l’équilibre en refusant de choisir, même si la pression n’a pas disparu. Le calme est utile ; éviter les informations inconfortables ne fera pas disparaître la décision.","advice":"Retirez le bandeau doucement, rassemblez le fait manquant et décidez à partir de l''équilibre.","yesNoMeaning":"Les Deux d''Épées ne sont pas encore clairs : retirez le bandeau doucement, rassemblez le fait manquant, et décidez à partir de l''équilibre."}' WHERE card_id = 'two-of-swords' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Trois d''Épées","meaning":"Une vérité douloureuse, une séparation ou une déception demande à être reconnue. Les mots, la séparation ou une attente brisée peuvent laisser une réelle souffrance. Nommez la blessure et cherchez de l’aide au lieu de vous précipiter pour prouver que vous allez déjà bien.","advice":"Laissez le sentiment vous traverser et évitez de transformer la douleur en une histoire permanente.","yesNoMeaning":"Le Trois d''Épées penche non : laissez le sentiment vous traverser et évitez de transformer la douleur en une histoire permanente."}' WHERE card_id = 'three-of-swords' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Quatre d''Épées","meaning":"Le repos et la tranquillité mentale sont nécessaires après une pression ou un conflit. Après une longue période de réaction à la pression, votre esprit a besoin d’espace pour s’installer. Le repos fait partie de la récupération et de la préparation, ce n''est pas la preuve que vous avez abandonné.","advice":"Faites une pause avant de répondre ; la récupération est productive quand elle restaure la clarté de la pensée.","yesNoMeaning":"Le Quatre d''Épées penche vers non : pausez avant de répondre ; le rétablissement est productif lorsqu''il restaure la clarté de la pensée."}' WHERE card_id = 'four-of-swords' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Cinq d''Épées","meaning":"Un conflit peut produire une victoire vide de sens ou ébranler la confiance. Gagner une dispute peut quand même nuire à la confiance ou vous épuiser. Demandez-vous combien coûte la victoire et quelles limites protégeraient votre estime de soi.","advice":"Choisissez la dignité plutôt que la victoire et éloignez-vous de tactiques trop coûteuses.","yesNoMeaning":"Le Cinq d''Épées penche vers non : choisissez la dignité plutôt que la victoire et éloignez-vous des tactiques qui coûtent trop."}' WHERE card_id = 'five-of-swords' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Six d''Épées","meaning":"Un passage difficile évolue progressivement vers des conditions plus calmes. La transition peut être tranquille : sortir d’une conversation dans l’impasse, d’un environnement ancien ou d’une façon de penser fatigante. Vous n’avez pas besoin de voir une destination parfaite pour savoir que vous avancez vers une plus grande paix.","advice":"Prenez ce que vous avez appris, acceptez le soutien et continuez à vous éloigner du tumulte.","yesNoMeaning":"Le Six d''Épées penche vers oui : prenez ce que vous avez appris, acceptez le soutien et continuez à vous éloigner des tourments."}' WHERE card_id = 'six-of-swords' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Sept d''Épées","meaning":"La stratégie, le secret ou l’évitement compliquent le chemin. Garder un régime privé peut parfois vous protéger ; se soustraire à ses responsabilités crée un autre type de distance. Examinez le motif derrière une stratégie avant de décider de l’utiliser.","advice":"Agis avec intelligence mais en toute transparence ; les raccourcis qui trahissent la confiance reviendront sous forme de problèmes.","yesNoMeaning":"Le Sept d''Épées penche vers le non : agissez intelligemment mais de manière transparente ; les raccourcis qui trahissent la confiance reviendront sous forme de problèmes."}' WHERE card_id = 'seven-of-swords' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Huit d''Épées","meaning":"La peur et les croyances restrictives rendent les options disponibles difficiles à voir. Le sentiment d’être piégé peut être plus grand que les limites qui vous entourent réellement. À mesure que la peur s’atténue, une petite option, une personne serviable ou un chemin négligé peut devenir visible.","advice":"Remettez en question la pensée qui dit que vous êtes piégé et prenez une petite action libératrice.","yesNoMeaning":"Le Huit d''Épées penche pour non : remettez en question la pensée qui dit que vous êtes piégé et faites une petite action libératrice."}' WHERE card_id = 'eight-of-swords' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Neuf d''Épées","meaning":"L’anxiété amplifie le danger dans l’obscurité et épuise l’esprit. Les pensées répétitives peuvent sembler plus féroces lorsque vous y faites face seul. Séparez ce qui s’est passé de ce que vous imaginez pouvoir arriver et permettez-vous de demander de l’aide.","advice":"Amenez la peur à la lumière du jour, cherchez du soutien et séparez les faits des résultats imaginés.","yesNoMeaning":"Le Neuf d''Épées penche non : mettez la peur au grand jour, cherchez du soutien et séparez les faits des résultats imaginés."}' WHERE card_id = 'nine-of-swords' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Dix d''Épées","meaning":"Un cycle douloureux atteint sa limite finale et ne peut continuer sans changement. La fin peut vous épuiser après qu’une situation ait duré trop longtemps. L’ancien schéma ne peut pas perdurer, mais des limites plus claires peuvent ouvrir la voie à une reprise progressive.","advice":"Acceptez la fin, protégez votre rétablissement et permettez à un nouveau début d''émerger.","yesNoMeaning":"Le Dix d''Épées penche vers non : acceptez la fin, protégez votre rétablissement et permettez à un autre commencement d''émerger."}' WHERE card_id = 'ten-of-swords' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Valet d’Épées","meaning":"La curiosité alerte recherche des faits, pose des questions et surveille le changement. La curiosité vous pousse à poser des questions et à vérifier les détails avant d''accepter une conclusion. Cette vigilance favorise l’apprentissage lorsqu’elle ne se transforme pas en suspicion envers tout le monde.","advice":"Recherchez soigneusement et parlez avec précision plutôt que de réagir à chaque signal.","yesNoMeaning":"Le Valet d''Épées reste conditionnel : faites des recherches avec soin et parlez avec précision plutôt que de réagir à chaque signal."}' WHERE card_id = 'page-of-swords' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Chevalier d''Épées","meaning":"L’intellect concentré évolue rapidement et affronte directement les obstacles. Une idée claire peut vous faire avancer et vous faire parler directement. La détermination fonctionne mieux lorsque vous entendez encore de nouvelles preuves et remarquez comment vos paroles affectent les autres.","advice":"Avancez avec courage, mais assez lentement pour entendre ce que votre certitude pourrait manquer.","yesNoMeaning":"Le Chevalier d''Épées reste conditionnel : avancez avec courage, mais assez lentement pour entendre ce que votre certitude pourrait manquer."}' WHERE card_id = 'knight-of-swords' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Reine d''Épées","meaning":"Une perception claire et des limites honnêtes éliminent la confusion. L’expérience peut vous aider à voir ce qui compte parmi des sentiments et des promesses concurrents. Soyez direct et gardez des limites saines sans perdre votre compassion.","advice":"Dis ce qui est vrai avec compassion et laisse l''expérience t''affûter, pas te durcir.","yesNoMeaning":"La Reine d''Épées penche vers le oui : dites ce qui est vrai avec compassion et laissez l''expérience vous affûter, non vous durcir."}' WHERE card_id = 'queen-of-swords' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Roi d''Épées","meaning":"La raison, l’équité et un jugement discipliné guident une décision conséquente. Une décision difficile nécessite des normes cohérentes et un raisonnement clair. L''autorité de cette carte vient de l''équité, et pas seulement du fait d''avoir le dernier mot.","advice":"Utilisez des preuves, définissez la norme et écartez les préjugés personnels du verdict.","yesNoMeaning":"Le Roi d''Épées penche vers oui : utilisez des preuves, définissez la norme et gardez les préjugés personnels hors du verdict."}' WHERE card_id = 'king-of-swords' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"As de Pentacles","meaning":"Une opportunité tangible offre le germe de la prospérité, du travail ou du bien-être. Une ouverture pratique peut apparaître sous la forme d’un travail, d’un soutien, d’une compétence ou de conditions plus saines. Sa valeur dépend de la manière dont on l’entretient au fil du temps, et pas seulement de son premier attrait.","advice":"Ancrez l''opportunité dans un plan pratique et prenez-en soin de manière constante.","yesNoMeaning":"L''As de Pentacles penche vers le oui : Ancrez l''opportunité dans un plan pratique et prenez-en soin régulièrement."}' WHERE card_id = 'ace-of-pentacles' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Deux de Pentacles","meaning":"Plusieurs priorités évoluent en même temps et nécessitent un équilibre flexible. Vous êtes peut-être en train de concilier travail, argent, temps et besoins personnels à la fois. La flexibilité fait avancer les choses, mais une longue période de jonglerie nécessite des priorités plus claires.","advice":"Ajustez le rythme, protégez l''essentiel et évitez de promettre plus que ce que vous pouvez porter.","yesNoMeaning":"Le Deux de Pentacles reste conditionnel : ajustez le rythme, protégez l''essentiel et évitez de promettre plus que ce que vous pouvez porter."}' WHERE card_id = 'two-of-pentacles' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Trois de Pentacles","meaning":"Les compétences se développent grâce à la collaboration, aux commentaires et à un savoir-faire minutieux. Le bon travail se développe lorsque chaque personne comprend son rôle et ses points forts. Les commentaires spécifiques, l’apprentissage d’un métier et le respect de l’effort silencieux sont tous importants ici.","advice":"Apportez votre force, respectez l''expertise et construisez selon une norme partagée.","yesNoMeaning":"Les Trois de Pentacles penchent pour oui : apportez votre force, respectez l''expertise et construisez selon une norme partagée."}' WHERE card_id = 'three-of-pentacles' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Quatre de Pentacles","meaning":"S’en tenir strictement à la sécurité peut préserver les ressources mais restreindre les flux sains. Conserver des ressources durement gagnées peut sembler judicieux en période d’incertitude. Lorsque la peur de la perte régit chaque choix, l’argent et la tranquillité d’esprit peuvent sembler limités.","advice":"Protégez ce qui compte sans laisser la peur prendre toutes vos décisions.","yesNoMeaning":"Le Quatre de Pentacles reste conditionnel : protégez ce qui compte sans laisser la peur dicter chaque décision."}' WHERE card_id = 'four-of-pentacles' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Cinq de Pentacles","meaning":"La tension matérielle ou l’exclusion crée de l’inquiétude et un sentiment de pénurie. Les difficultés peuvent vous faire sentir seul ou ne pas mériter d’aide. Un soutien pratique peut encore être proche, même lorsque la détresse rend difficile d’en voir le chemin.","advice":"Demandez une aide pratique et remarquez la porte que les difficultés ont rendue facile à négliger.","yesNoMeaning":"Le Cinq de Pentacles penche vers non : demandez de l''aide pratique et remarquez la porte que les difficultés ont rendu facile à négliger."}' WHERE card_id = 'five-of-pentacles' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Six de Pentacles","meaning":"Les ressources sont échangées, soulevant des questions de générosité, de pouvoir et d’équité. L’aide fonctionne mieux lorsque celui qui donne et celui qui reçoit conservent leur dignité et leur voix. Regardez si l''échange est équilibré et quelles conditions accompagnent la générosité.","advice":"Donner ou recevoir avec des termes clairs afin que le soutien préserve la dignité des deux côtés.","yesNoMeaning":"Le Six de Pentacles penche pour oui : donner ou recevoir avec des conditions claires afin que le soutien préserve la dignité des deux côtés."}' WHERE card_id = 'six-of-pentacles' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Sept de Pentacles","meaning":"L’investissement du patient atteint un point d’évaluation avant le prochain effort. Vous avez investi des efforts, mais les résultats risquent de ne pas arriver selon le calendrier souhaité. Passez en revue les progrès et distinguez ce qui nécessite plus de patience de ce qui nécessite une nouvelle approche.","advice":"Examine ce qui pousse, améliorez la méthode et donnez du temps aux résultats valables.","yesNoMeaning":"Le Sept de Pentacles reste conditionnel : examinez ce qui pousse, améliorez la méthode et laissez le temps aux résultats valables."}' WHERE card_id = 'seven-of-pentacles' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Huit de Deniers","meaning":"La répétition ciblée développe la maîtrise et des résultats fiables. La compétence se développe grâce à la répétition, à la correction et à l’attention portée aux petits détails. La carte valorise une pratique régulière que d’autres ne verront peut-être jamais, plutôt qu’un saut soudain.","advice":"Pratiquez la compétence essentielle, accueillez la correction et laissez la qualité s''accumuler.","yesNoMeaning":"Le Huit de Pentacles penche pour oui : pratiquez la compétence essentielle, accueillez les corrections et laissez la qualité s''accumuler."}' WHERE card_id = 'eight-of-pentacles' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Neuf de Pentacles","meaning":"L’autonomie et le confort cultivé reflètent un progrès discipliné. Votre confort actuel peut refléter de nombreux choix disciplinés faits plus tôt. Profitez de ce que vous avez construit à votre rythme et reconnaissez le travail qui se cache derrière.","advice":"Profitez de ce que vous avez construit et maintenez l''indépendance liée à la gratitude.","yesNoMeaning":"Le Neuf de Pentacles penche oui : profitez de ce que vous avez construit et gardez l''indépendance reliée à la gratitude."}' WHERE card_id = 'nine-of-pentacles' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Dix de Pentacles","meaning":"La sécurité à long terme se développe grâce à des fondations héritées, familiales et partagées. L''histoire s''étend au-delà du succès d''une personne et s''étend à la famille, à la communauté ou à ceux qui la suivent. Une fondation durable naît d’une attention réfléchie aux ressources partagées.","advice":"Planifiez au-delà du gain immédiat et protégez ce qui peut soutenir les autres au fil du temps.","yesNoMeaning":"Le Dix de Pentacles penche vers oui : planifiez au-delà du gain immédiat et protégez ce qui peut soutenir les autres sur le long terme."}' WHERE card_id = 'ten-of-pentacles' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Valet de Pentacles","meaning":"Un message pratique invite à l’étude, à la planification ou à une nouvelle entreprise fondée. Une opportunité pratique devient plus claire lorsque vous en apprenez les bases. Explorez patiemment, testez-le à petite échelle et remarquez ce qui a une valeur durable.","advice":"Apprenez les bases, définissez la prochaine tâche et prouvez l''idée par un travail constant.","yesNoMeaning":"Le Valet de Pentacles penche vers le oui : apprenez les bases, définissez la tâche suivante et démontrez l''idée par un travail régulier."}' WHERE card_id = 'page-of-pentacles' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Chevalier de Deniers","meaning":"Un effort fiable avance lentement mais abandonne rarement la tâche. Les progrès peuvent sembler si lents que vous vous demandez si vous avancez, mais la cohérence constitue une base. La fiabilité a également besoin d’espace pour se reposer.","advice":"Gardez la routine honnête et cohérente ; le progrès compte plus que l''excitation.","yesNoMeaning":"Le Cavalier de Pentacles penche vers oui : maintenez la routine honnête et cohérente ; le progrès compte plus que l''excitation."}' WHERE card_id = 'knight-of-pentacles' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Reine de Pentacles","meaning":"Des soins ingénieux créent du confort, de la santé et une abondance pratique. La sécurité peut être créée grâce à des actes concrets de prudence et à une utilisation judicieuse des ressources. La générosité durable commence également par le fait de se souvenir de ses propres besoins.","advice":"Nourrissez les personnes et les projets d’une manière qui reste durable pour vous.","yesNoMeaning":"La Reine de Pentacles penche vers le oui : nourrissez les personnes et les plans de manière à rester durable pour vous."}' WHERE card_id = 'queen-of-pentacles' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Roi de Pentacles","meaning":"Le leadership matériel transforme l’expérience en une gestion stable et généreuse. L''expérience peut soutenir un avenir stable pour le travail, la famille ou la communauté. Le succès signifie davantage lorsque les personnes qui ont contribué à sa construction peuvent partager cette stabilité.","advice":"Faites le choix sonore à long terme et utilisez le succès de manière responsable.","yesNoMeaning":"Le Roi de Pentacles penche vers oui : faites le choix solide à long terme et utilisez le succès de manière responsable."}' WHERE card_id = 'king-of-pentacles' AND locale = 'fr';
UPDATE card_translations SET payload = '{"name":"Der Narr","meaning":"Eine leere Seite und ein Vertrauensvorschuss – eine neue Reise beginnt mit einem offenen Herzen. Sie benötigen keine vollständige Karte, bevor Sie den ersten Schritt unternehmen. Neugier hilft Ihnen, aus jedem Versuch zu lernen, während ein wenig Vorbereitung verhindert, dass die Freiheit zur Sorglosigkeit wird.","advice":"Vertraue dem Weg vor dir und mache den ersten Schritt, auch ohne alle Antworten zu haben.","yesNoMeaning":"Ein neuer Anfang trägt selten eine feste Antwort — das Ergebnis hängt von dem Schritt ab, den du machst."}' WHERE card_id = 'fool' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Der Magier","meaning":"Sie verfügen über alle Werkzeuge, die Sie benötigen. Konzentrieren Sie Ihren Willen und setzen Sie Ihre Absicht in die Tat um. Eine Idee wird Wirklichkeit, wenn Ihre Aufmerksamkeit, Zeit und verfügbaren Ressourcen auf dieselbe Aufgabe ausgerichtet sind. Schauen Sie sich die Werkzeuge an, die bereits in Reichweite sind, bevor Sie auf ein weiteres Zeichen warten.","advice":"Setze deine Fähigkeiten und Ressourcen gezielt ein — jetzt ist die Zeit, es zu verwirklichen.","yesNoMeaning":"Du besitzt bereits alles, was nötig ist — die Energie unterstützt es, mit Fokus voranzuschreiten."}' WHERE card_id = 'magician' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Die Hohepriesterin","meaning":"Stille Weisheit verbirgt sich unter der Oberfläche. Hören Sie auf Ihre Intuition und innere Stimme. Schweigen kann ein Muster offenbaren, ein Gefühl, das Sie noch nicht benennen können, oder eine Information, die noch fehlt. Beobachten Sie etwas länger, bevor Sie alles ans Licht bringen.","advice":"Halten Sie inne, gehen Sie nach innen und lassen Sie sich von Ihren Instinkten leiten, bevor Sie handeln.","yesNoMeaning":"Die Antwort ist vorerst unter der Oberfläche verborgen — vertraue deiner Intuition, statt ein klares Ja oder Nein zu erzwingen."}' WHERE card_id = 'high-priestess' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Die Kaiserin","meaning":"Wachstum, Fülle und nährende Energie umgeben Sie. Lassen Sie Schönheit und Pflege aufblühen. Eine Beziehung, ein Projekt oder ein Teil von Ihnen kann durch stetige Fürsorge wachsen. Fülle bedeutet hier, Raum zur Entfaltung zu haben und nicht zu geben, bis man nichts mehr übrig hat.","advice":"Sei geduldig und großzügig — kreiere mit Liebe und lass die Dinge natürlich reifen.","yesNoMeaning":"Wachstum, Fülle und nährende Energie unterstützen deinen Wunsch — die Antwort ist ein stilles Ja."}' WHERE card_id = 'empress' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Der Kaiser","meaning":"Struktur, Autorität und stabile Führung. Bauen Sie mit Disziplin auf einem soliden Boden auf. Eine nützliche Struktur gibt Menschen die Sicherheit, sich zu entwickeln. Beachten Sie den Unterschied zwischen der Übernahme von Verantwortung und dem Versuch, jedes Detail zu kontrollieren. Sie können auf den ersten Blick ähnlich aussehen.","advice":"Übernimm die Führung mit einem klaren Plan; feste Grenzen bringen dauerhafte Stabilität.","yesNoMeaning":"Struktur, Autorität und stetige Disziplin stehen hinter einem selbstbewussten Ja."}' WHERE card_id = 'emperor' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Der Hierophant","meaning":"Tradition und vertrauenswürdige Führung bieten einen verlässlichen Weg. Lernen Sie aus dem, was vorher war. Ein Lehrer, eine Gemeinschaft oder eine etablierte Methode können einen guten Ausgangspunkt bieten. Erfahren Sie, warum eine Tradition funktioniert, damit Sie sie mit Bedacht auf Ihre eigene Situation anwenden können.","advice":"Folge bewährter Weisheit und suche Rat bei denen, denen du vertraust.","yesNoMeaning":"Tradition und vertrauenswürdige Orientierung weisen auf ein verlässliches Ja hin — stütze dich auf das, was sich bereits bewährt hat."}' WHERE card_id = 'hierophant' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Die Liebenden","meaning":"Eine bedeutungsvolle Bindung oder eine wichtige Entscheidung. Folgen Sie dem, was Ihr Herz wirklich schätzt. Dauerhafte Harmonie verlangt von beiden Seiten, ehrlich über Bedürfnisse und Grenzen zu sprechen. Wenn es sich eher um eine Entscheidung als um eine Romanze handelt, fragen Sie, welcher Weg Ihre tieferen Werte widerspiegelt.","advice":"Wähle mit Ehrlichkeit und Übereinstimmung — Verbindung vertieft sich, wenn du aufrichtig bist.","yesNoMeaning":"Ihr Herz und Ihre Werte sind hier ausgerichtet — die Antwort ist ja, besonders wenn Sie mit Ehrlichkeit wählen."}' WHERE card_id = 'lovers' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Der Wagen","meaning":"Willenskraft und Schwung bringen Sie voran. Bleiben Sie konzentriert und Sie werden sich durchsetzen. Gegensätzliche Impulse können Sie dennoch weiterbringen, wenn Sie ihnen eine gemeinsame Richtung vorgeben. Fortschritt hängt von der Steuerung Ihrer Gefühle und Handlungen ab und nicht nur davon, dass Sie sich noch mehr anstrengen.","advice":"Behalte das Ziel im Auge und steuere mit Zuversicht durch jedes Hindernis.","yesNoMeaning":"Willenskraft und Schwung sind auf deiner Seite — ein fokussiertes Ja, vorausgesetzt, du bleibst engagiert."}' WHERE card_id = 'chariot' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Stärke","meaning":"Wahre Macht ist sanft – Geduld, Mut und Mitgefühl meistern jede Herausforderung. Sanftmut ist eine aktive Form von Mut: Sie können beim Unbehagen bleiben, ohne dass es Ihre Reaktion bestimmt. Erkennen Sie die Angst an und gehen Sie vorsichtig vor, anstatt darauf zu warten, dass die Angst verschwindet.","advice":"Führe mit ruhiger Stärke; eine sanfte Hand ist oft die stärkste.","yesNoMeaning":"Sanfter Mut und geduldige Entschlossenheit machen dies zu einem Ja — führe mit Ruhe, nicht mit Gewalt."}' WHERE card_id = 'strength' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Der Eremit","meaning":"Zeit, einen Schritt zurückzutreten und nach innerer Klarheit zu suchen. Die Einsamkeit bringt jetzt tiefere Antworten. Wenn Sie einen Schritt zurücktreten, können Sie Ihre eigene Stimme inmitten der Meinungen anderer Menschen leichter hören. Einsamkeit hilft, wenn sie zu Verständnis führt, kann aber auch zu einer Möglichkeit werden, Verbindungen zu vermeiden.","advice":"Kehre nach innen, reflektiere und lasse die Stille offenbaren, was du wirklich brauchst.","yesNoMeaning":"Noch nicht — die Karte fordert Sie auf, einen Schritt zurückzutreten und innere Klarheit zu finden, bevor Sie handeln."}' WHERE card_id = 'hermit' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Glücksrad","meaning":"Schicksalsschläge und Zyklen ändern sich. Was sich jetzt ändert, ist Teil eines größeren Rhythmus. Möglicherweise dreht sich ein alter Zyklus, der neben Möglichkeiten auch Unannehmlichkeiten mit sich bringt. Sie können nicht jedes Ereignis auswählen, aber Sie können entscheiden, was Sie mitnehmen und wie Sie sich auf die nächste Runde vorbereiten möchten.","advice":"Reite die Welle mit Flexibilität – nimm die Wendung an, ob gut oder schlecht.","yesNoMeaning":"Das Glück wendet sich — das Ergebnis hängt davon ab, wie du den Wandel bewältigst, nicht von einem festen Ja oder Nein."}' WHERE card_id = 'wheel-of-fortune' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Gerechtigkeit","meaning":"Wahrheit und Fairness setzen sich durch. Ursache und Wirkung kommen nun ins Gleichgewicht. Was geschieht, spiegelt möglicherweise eher eine Kette früherer Entscheidungen als einen isolierten Moment wider. Prüfen Sie die Fakten, hören Sie die beteiligten Personen an und machen Sie sich den Teil zu eigen, der Ihnen gehört.","advice":"Handeln Sie ehrlich und wägen Sie beide Seiten ab; die Waage wird sich fair einstellen.","yesNoMeaning":"Die Waage ist noch im Gleichgewicht — die faire Antwort hängt von den Fakten und deiner Ehrlichkeit ab."}' WHERE card_id = 'justice' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Der Gehängte","meaning":"Eine notwendige Pause. Lassen Sie die Kontrolle los und betrachten Sie die Situation aus einem neuen Blickwinkel. Warten kann sich unangenehm anfühlen, wenn Handeln die übliche Antwort ist. Eine veränderte Perspektive oder etwas, das Sie loslassen möchten, kann offenbaren, was mehr Druck nicht verdeutlichen konnte.","advice":"Hör auf zu drängen — übergebe dich dem Moment und lass eine neue Perspektive eintreffen.","yesNoMeaning":"Zuerst ist eine Pause nötig — ein erzwungenes Handeln würde nur eine klarere Antwort zurückhalten."}' WHERE card_id = 'hanged-man' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Tod","meaning":"Ein Ende macht den Weg frei für eine Erneuerung. Lassen Sie los, was seine Zeit gehabt hat. Diese Karte spricht eher von einem Übergang als von einer wörtlichen Vorhersage eines Verlusts. Vielleicht sind Sie einer alten Rolle, Gewohnheit oder Erwartung entwachsen; es kann immer noch einige Zeit dauern, es hinter sich zu lassen.","advice":"Lass los ohne Bedauern; eine tiefgreifende Transformation öffnet eine neue Tür.","yesNoMeaning":"Ein Ende schafft Klarheit — der aktuelle Weg schließt sich, damit ein neuer beginnen kann."}' WHERE card_id = 'death' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Mäßigung","meaning":"Ausgeglichenheit und Geduld bringen Harmonie. Verschmelzen Sie Gegensätze mit Anmut. Suchen Sie nach Möglichkeiten, die sich aus zwei unterschiedlichen Ansätzen kombinieren lassen. Ruhiger Fortschritt kann die Form einer nachhaltigen Gewohnheit, eines ruhigeren Gesprächs oder eines Tempos annehmen, das Sie tatsächlich beibehalten können.","advice":"Bewegen Sie sich mit Maß und bewahren Sie Ruhe – beständige Schritte erreichen das Ziel.","yesNoMeaning":"Balance und Geduld bringen Harmonie — ein überlegtes Ja, Schritt für Schritt."}' WHERE card_id = 'temperance' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Der Teufel","meaning":"Hüten Sie sich vor Anhaftung, Versuchung oder einem bindenden Muster. Erkennen Sie die Fesseln. Ein kurzfristiger Nutzen kann es schwierig machen, aus einem kostspieligen Muster auszusteigen. Wenn Sie benennen, was Sie davon haben und was es kostet, können Sie ein wenig Entscheidungsfreiheit gewinnen.","advice":"Nenne, was dich hält, und erlange deine Freiheit zurück — die Kette bindet nur, wenn du es zulässt.","yesNoMeaning":"Anhaftung oder ein bindendes Muster steht im Weg — noch nicht, bis die Kette benannt und durchbrochen ist."}' WHERE card_id = 'devil' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Der Turm","meaning":"Plötzliche Veränderungen zerstören das Falsche und offenbaren die Wahrheit. Was fällt, sollte niemals bestehen bleiben. Ein Umbruch ist schwierig, wenn sie einen Plan, dem Sie vertraut haben, ins Wanken bringt. Sie müssen nicht sofort eine positive Seite finden; Beachten Sie zunächst, was sich wirklich verändert hat und was bestehen bleibt.","advice":"Begrüße das Durcheinander; aus den Trümmern kann ein klareres Fundament gebaut werden.","yesNoMeaning":"Plötzliche Veränderungen erschüttern das Alte – der Boden muss sich setzen, bevor ein stabiles Ja möglich ist."}' WHERE card_id = 'tower' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Der Stern","meaning":"Hoffnung, Heilung und stille Inspiration erneuern Ihren Geist nach dem Sturm. Hoffnung ist kein Versprechen, dass sich alles von selbst lösen wird. Es gibt Raum, nach Schwierigkeiten durchzuatmen und sich weiter um das Wesentliche zu kümmern, bevor das Ergebnis sichtbar wird.","advice":"Vertraue dem Licht vor dir und glaube weiter — deine Wünsche sind greifbar.","yesNoMeaning":"Hoffnung und stille Erneuerung weisen auf Ja hin – vertraue dem Licht voraus und halte deinen Wunsch lebendig."}' WHERE card_id = 'star' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Der Mond","meaning":"Illusion und Unsicherheit verwischen den Weg. Vertrauen Sie Ihrer Intuition, nicht dem Schein. Wenn Fakten unvollständig sind, können Erinnerung und Angst die Lücken mit einer überzeugenden Geschichte füllen. Machen Sie es langsamer, bemerken Sie Ihre Reaktion und trennen Sie das, was Sie fühlen, von dem, was Sie bestätigt haben.","advice":"Langsam machen und genauer hinschauen; Klarheit wird kommen, wenn der Nebel sich lichtet.","yesNoMeaning":"Illusion und Unsicherheit verschwimmen den Weg – die Antwort ist unklar, bis du unter die Oberfläche blickst."}' WHERE card_id = 'moon' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Die Sonne","meaning":"Freude, Erfolg und strahlende Klarheit. Alles ist hell und voller Leben. Klarheit kann Ihnen helfen, Ihre Fortschritte zu erkennen und Freude zu teilen, ohne sie zu verharmlosen. Wenn Arbeit bleibt, kann Ihnen diese neue Energie dabei helfen, offener damit umzugehen.","advice":"Feiere und strahle — positive Energie zieht die Ergebnisse an, die du dir wünschst.","yesNoMeaning":"Freude und strahlende Klarheit bestätigen ein helles Ja — alles arbeitet zu deinen Gunsten."}' WHERE card_id = 'sun' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Urteil","meaning":"Ein Aufruf, aufzustehen, sich zu erneuern und ehrlich zu sich selbst zu sein. Ein Urteil des Erwachens. Ein Rückblick auf die Vergangenheit bedeutet nicht, dass man sich für immer die Schuld geben muss. Nehmen Sie die Lektion an, vergeben Sie, was Sie können, und folgen Sie dem Aufruf zur Veränderung jetzt mit einer bewussten Entscheidung.","advice":"Beantworte den Ruf mit Mut; vergib der Vergangenheit und tritt in dein nächstes Kapitel ein.","yesNoMeaning":"Ein Aufruf, sich zu erheben und zu erneuern – ja, besonders wenn du der Vergangenheit vergibst und ehrlich antwortest."}' WHERE card_id = 'judgement' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Die Welt","meaning":"Vollendung und Erfüllung – ein Zyklus schließt sich in vollkommener Ganzheit. Der Erfolg umfasst die Fähigkeiten, Beziehungen und Perspektiven, die Sie auf diesem Weg erworben haben. Ehren Sie den Abschluss dieses Zyklus, auch wenn eine umfassendere Reise weitergeht.","advice":"Feiere, was du erreicht hast; die Tür ist zu einer größeren Welt geöffnet.","yesNoMeaning":"Abschluss und Ganzheit kennzeichnen dies als ein erfülltes Ja — der Zyklus schließt sich zu deinen Gunsten."}' WHERE card_id = 'world' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Ass der Stäbe","meaning":"Ein Funke Inspiration eröffnet einen mutigen kreativen Weg. Eine Einladung, ein Projekt oder ein neuer Wunsch kann dazu führen, dass Sie sich lebendiger fühlen. Dies ist eher ein potenzielles als ein garantiertes Ergebnis. Es braucht Raum zum Experimentieren und Engagement, nachdem die erste Aufregung verflogen ist.","advice":"Beginne, während die Energie frisch ist, und gib der Idee einen echten ersten Schritt.","yesNoMeaning":"Das Stab-Ass tendiert zu Ja: Beginne, solange die Energie frisch ist, und gib der Idee einen echten ersten Schritt."}' WHERE card_id = 'ace-of-wands' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Zwei der Stäbe","meaning":"Durch Planung und Richtungswahl entsteht eine Zukunft. Sie können mehr als eine Route sehen und beginnen sich zu fragen, wie weit Sie gehen möchten. Eine umfassende Sicht hilft, aber endloses Planen kann Sie auf der Schwelle halten.","advice":"Sieh über das Vertraute hinaus und dann verpflichte dich dem Weg mit Raum zum Wachsen.","yesNoMeaning":"Die Zwei der Stäbe bleibt bedingt: Schau über das Vertraute hinaus und entscheide dich dann für den Weg mit Raum zum Wachsen."}' WHERE card_id = 'two-of-wands' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Drei der Stäbe","meaning":"Die frühen Bemühungen weiten sich aus, wenn Möglichkeiten und breitere Horizonte sichtbar werden. Was Sie begonnen haben, ist, eine Reaktion hervorzurufen, die über das gewohnte Terrain hinausgeht. Bleiben Sie offen für Kontakte und Feedback und lassen Sie Ihrer bisherigen Arbeit Zeit, Früchte zu tragen.","advice":"Baue weiter und sei bereit, die Reaktion zu empfangen, die deine Arbeit hervorruft.","yesNoMeaning":"Die Drei der Stäbe tendiert zu ja: Baue weiter auf und sei bereit, auf die Resonanz deiner Arbeit zu reagieren."}' WHERE card_id = 'three-of-wands' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Vier der Stäbe","meaning":"Stabilität, Willkommen und gemeinsames Feiern bilden ein starkes Fundament. Ein Meilenstein verdient Feier, auch wenn die Reise noch nicht zu Ende ist. Zugehörigkeit und die Menschen, die diesen Moment mitgestaltet haben, können Ihren nächsten Schritt stärken.","advice":"Markiere den Meilenstein und lass unterstützende Menschen daran teilhaben.","yesNoMeaning":"Die Vier der Stäbe neigt zu Ja: Markiere den Meilenstein und lasse unterstützende Menschen daran teilhaben."}' WHERE card_id = 'four-of-wands' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Fünf der Stäbe","meaning":"Konkurrierende Ziele erzeugen Reibung, Lärm oder stellen das Vertrauen auf die Probe. Viele konkurrierende Stimmen können das gemeinsame Ziel verbergen. Ein Konflikt kann eine Idee schärfen, wenn jeder weiß, worüber er tatsächlich debattiert, und über Unterschiede hinweg zuhören kann.","advice":"Verwandle Rivalität in nützliche Praxis und lehne Konflikte ab, die keinen Zweck haben.","yesNoMeaning":"Die Fünf der Stäbe bleibt bedingt: Verwandle Rivalität in nützliche Übung und verweigere Konflikte, die keinen Zweck haben."}' WHERE card_id = 'five-of-wands' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Sechs der Stäbe","meaning":"Anerkennung folgt entschlossener Anstrengung und sichtbarem Fortschritt. Ihre Bemühungen werden vielleicht endlich von anderen gesehen. Anerkennung kann Sie ermutigen, aber der Wert Ihrer Arbeit bleibt auch dann bestehen, wenn kein Publikum zuschaut.","advice":"Nimm die Ermutigung an, aber halte dein Vertrauen an ehrlicher Arbeit fest.","yesNoMeaning":"Die Sechs der Stäbe neigt zu Ja: Nimm die Ermutigung an, halte aber dein Selbstvertrauen an ehrlicher Arbeit gebunden."}' WHERE card_id = 'six-of-wands' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Sieben der Stäbe","meaning":"Sie halten wertvolles Terrain, während der Druck Ihre Entschlossenheit auf die Probe stellt. Um das zu schützen, was wichtig ist, müssen Sie wissen, warum es Ihnen wichtig ist. Druck kann aus verschiedenen Richtungen kommen, doch nicht jede Herausforderung verdient einen Kampf.","advice":"Verteidige, was zählt, mit klaren Grenzen, anstatt jede Herausforderung zu bekämpfen.","yesNoMeaning":"Die Sieben der Stäbe tendiert zu Ja: Verteidige, was wichtig ist, mit klaren Grenzen, anstatt jede Herausforderung zu bekämpfen."}' WHERE card_id = 'seven-of-wands' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Acht der Stäbe","meaning":"Ereignisse beschleunigen sich, Nachrichten treffen ein und Dynamik beseitigt Verzögerungen. Nachrichten oder Entscheidungen können schneller eintreffen als erwartet. Geschwindigkeit hilft, wenn jeder die Richtung versteht; Unklare Informationen können Schwung in Verwirrung verwandeln.","advice":"Handeln Sie zügig und halten Sie die Kommunikation direkt, solange der Weg offen ist.","yesNoMeaning":"Die Acht der Stäbe tendiert zu Ja: Handle prompt und halte die Kommunikation direkt, solange der Weg offen ist."}' WHERE card_id = 'eight-of-wands' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Neun der Stäbe","meaning":"Die Belastbarkeit ist stark, auch wenn die Belastungen der Vergangenheit Sie wachsam machen. Durch die Belastungen der Vergangenheit haben Sie gelernt, wie Sie sich schützen können, aber ständige Wachsamkeit ist anstrengend. Beurteilen Sie das Risiko, das vor Ihnen liegt, anhand der heutigen Beweise und der Wunden von gestern.","advice":"Schütze deine Energie und gehe den nächsten Schritt, ohne zu erwarten, dass jede Wunde sich wiederholt.","yesNoMeaning":"Die Neun der Stäbe bleibt bedingt: Schütze deine Energie und mache den nächsten Schritt, ohne zu erwarten, dass jede Wunde sich wiederholt."}' WHERE card_id = 'nine-of-wands' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Zehn der Stäbe","meaning":"Die Verantwortung ist schwer geworden und der Erfolg birgt nun eine Bürde. Etwas, auf das Sie einst stolz waren, bringt jetzt möglicherweise zu viele Verpflichtungen mit sich. Ihre Fähigkeiten sind real, aber Sie müssen nicht jede Aufgabe alleine bewältigen.","advice":"Delegiere, vereinfache und lege Arbeit nieder, die nicht mehr wirklich deine ist.","yesNoMeaning":"Die Zehn der Stäbe tendiert zu nein: delegiere, vereinfache und lege Arbeit ab, die nicht mehr wirklich dir gehört."}' WHERE card_id = 'ten-of-wands' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Bube der Stäbe","meaning":"Neugier bringt eine lebendige Botschaft, ein Experiment oder ein neues kreatives Interesse mit sich. Eine frische Idee kann die Begeisterung eines Anfängers zurückbringen. Sie müssen nicht alles beherrschen, bevor Sie es erkunden. Geben Sie sich die Erlaubnis, in der Praxis auszuprobieren, sich anzupassen und zu lernen.","advice":"Erkunde mit Mut und lass die Energie des Anfängers dich durch Handeln lehren.","yesNoMeaning":"Der Bube der Stäbe tendiert zu ja: Erkunden Sie mit Mut und lassen Sie die Anfängerkraft Sie durch Handeln lehren."}' WHERE card_id = 'page-of-wands' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Ritter der Stäbe","meaning":"Die Leidenschaft schreitet schnell voran und bringt Abenteuer und möglicherweise Ungeduld mit sich. Die Anziehungskraft von etwas Neuem kann dazu führen, dass Sie sofort gehen möchten. Diese Energie nützt Ihnen am besten, wenn ein klares Ziel Sie davon abhält, bei jedem vorbeiziehenden Impuls den Kurs zu ändern.","advice":"Nutze die Dynamik, aber wähle eine Richtung, bevor die Geschwindigkeit deine Bemühungen zerstreut.","yesNoMeaning":"Der Ritter der Stäbe bleibt bedingt: Nutze das Momentum, aber wähle eine Richtung, bevor die Geschwindigkeit deine Anstrengung zerstreut."}' WHERE card_id = 'knight-of-wands' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Königin der Stäbe","meaning":"Warmes Selbstvertrauen und kreative Unabhängigkeit ziehen andere für Ihre Vision an. Ihre offene Präsenz kann andere dazu ermutigen, an eine gemeinsame Vision zu glauben. Selbstvertrauen bedeutet hier nicht, dass man irgendjemanden in den Schatten stellt; Es gibt anderen Raum, auch zu glänzen.","advice":"Vertraue deiner Präsenz, ermutige andere und mindere nicht deinen Ehrgeiz.","yesNoMeaning":"Die Königin der Stäbe neigt sich ja: Vertraue auf deine Präsenz, ermutige andere und schränke deinen Ehrgeiz nicht ein."}' WHERE card_id = 'queen-of-wands' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"König der Stäbe","meaning":"Eine ausgereifte Vision verwandelt Inspiration in entschlossene und ethische Führung. Eine große Vision erfordert Entscheidungen, Verantwortung und die Fähigkeit, die Energie eines Teams aufrechtzuerhalten. Führen Sie durch ein klares Ziel und nicht durch Druck oder Ego allein.","advice":"Führe aus einem größeren Zweck heraus und gib anderen Raum zur Mitwirkung.","yesNoMeaning":"Der König der Stäbe neigt zu Ja: Führe vom größeren Zweck aus und gib anderen Raum, beizutragen."}' WHERE card_id = 'king-of-wands' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Ass der Kelche","meaning":"Das Herz öffnet sich für neue Zuneigung, Mitgefühl und emotionale Erneuerung. Eine Begegnung, ein neues Gefühl oder eine innere Erweichung kann Sie dazu einladen, freier zu geben und zu empfangen. Lassen Sie Emotionen anerkennen, bevor Sie sie zu einem bestimmten Ergebnis zwingen.","advice":"Nimm das Gefühl ehrlich wahr und lasse Fürsorge fließen, ohne ein Ergebnis erzwingen zu müssen.","yesNoMeaning":"Das Ass der Kelche tendiert zu Ja: Nimm das Gefühl ehrlich an und lasse Fürsorge fließen, ohne ein Ergebnis erzwingen zu wollen."}' WHERE card_id = 'ace-of-cups' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Zwei der Kelche","meaning":"Gegenseitige Anerkennung schafft Partnerschaft, Anziehung oder aufrichtige Zustimmung. Das tiefere Versprechen liegt darin, dass sich zwei Menschen über die anfängliche Anziehungskraft hinaus deutlich sehen. Ein aufrichtiges Gespräch, eine Entschuldigung oder eine faire Vereinbarung können die Bindung stärken.","advice":"Treffen Sie die andere Person auf Augenhöhe und sprechen Sie von Herzen.","yesNoMeaning":"Die Zwei der Kelche tendiert zu ja: Begegne der anderen Person als Gleichwertige/r und sprich von Herzen."}' WHERE card_id = 'two-of-cups' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Drei der Kelche","meaning":"Freundschaft, Gemeinschaft und gemeinsame Freude bringen emotionale Unterstützung. Eine kleine Zusammenkunft oder rechtzeitige Unterstützung können Sie daran erinnern, dass Freude nicht allein getragen werden muss. Erinnern Sie sich an diejenigen, die an Ihrer Seite standen, bevor die Dinge einfacher wurden.","advice":"Feiere gemeinsam und erinnere dich daran, wer wirklich für dich da ist.","yesNoMeaning":"Die Drei der Kelche tendiert zu ja: feiere gemeinsam und erinnere dich daran, wer wirklich für dich da ist."}' WHERE card_id = 'three-of-cups' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Vier der Kelche","meaning":"Emotionaler Rückzug macht es schwierig, ein verfügbares Geschenk wahrzunehmen. Wenn Sie müde oder entmutigt sind, kann selbst ein gutes Angebot langweilig erscheinen. Seien Sie ehrlich über Ihre gegenwärtigen Gefühle, bevor Sie entscheiden, dass nichts um Sie herum wichtig ist.","advice":"Unterbrechen Sie den Vergleich und schauen Sie erneut, was still angeboten wird.","yesNoMeaning":"Die Vier der Kelche lehnt ab: halte den Vergleich inne und schaue erneut, was still angeboten wird."}' WHERE card_id = 'four-of-cups' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Fünf der Kelche","meaning":"Verlust lenkt die Aufmerksamkeit auf das, was verschüttet wurde, während etwas Sinnvolles bleibt. Trauer verdient es, beim Namen genannt zu werden, anstatt sie mit schnellem Optimismus zu überdecken. Dennoch erzählt ein einzelner Verlust möglicherweise nicht die ganze Geschichte. Unterstützung oder Möglichkeit bleibt möglicherweise noch in der Nähe.","advice":"Ehre die Enttäuschung, wende dich dann der Unterstützung zu, die noch da ist.","yesNoMeaning":"Die Fünf der Kelche neigt sich zu nein: Ehre die Enttäuschung und wende dich dann der Unterstützung zu, die noch vorhanden ist."}' WHERE card_id = 'five-of-cups' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Sechs der Kelche","meaning":"Erinnerungen, Unschuld oder eine vertraute Bindung kehren mit sanfter Wärme zurück. Ein alter Freund oder eine alte Erinnerung kann Ihnen wieder ein Gefühl der Sicherheit vermitteln. Begrüßen Sie diese Wärme und erkennen Sie gleichzeitig, dass sich die Gegenwart verändert hat und Sie sich mit ihr verändert haben.","advice":"Begrüße die Freundlichkeit der Vergangenheit, ohne so zu tun, als müsstest du dort wieder leben.","yesNoMeaning":"Die Sechs der Kelche tendiert zu Ja: Begrüße die Freundlichkeit der Vergangenheit, ohne so zu tun, als müsstest du dort wieder leben."}' WHERE card_id = 'six-of-cups' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Sieben der Kelche","meaning":"Viele attraktive Möglichkeiten verwischen den Unterschied zwischen Vision und Illusion. Jede Option scheint ein schönes Versprechen zu enthalten, aber nicht jedes Versprechen hat die gleiche Grundlage. Trennen Sie das, was Sie wirklich wollen, von dem, was Sie sich vorgestellt haben.","advice":"Eingrenzen Sie die Auswahlmöglichkeiten und prüfen Sie einen Traum an der Realität, bevor Sie sich festlegen.","yesNoMeaning":"Die Sieben der Kelche ist noch nicht klar: Engen Sie die Optionen ein und prüfen Sie einen Traum gegen die Realität, bevor Sie sich festlegen."}' WHERE card_id = 'seven-of-cups' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Acht der Kelche","meaning":"Eine einmal bedeutungsvolle Situation nährt das Herz nicht mehr. Etwas einst Bedeutsames zu hinterlassen, kann für Sie jetzt sowohl traurig als auch richtig sein. Sein Wert war real, auch wenn sich Ihr Bedürfnis nach einer tieferen Bedeutung geändert hat.","advice":"Gehe mit Ehrlichkeit und bewege dich auf die tiefere Erfüllung zu, die du jetzt brauchst.","yesNoMeaning":"Die Acht der Kelche tendiert zu Nein: Gehe ehrlich weg und bewege dich auf die tiefere Erfüllung zu, die du jetzt brauchst."}' WHERE card_id = 'eight-of-cups' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Neun der Kelche","meaning":"Zufriedenheit und Dankbarkeit lassen einen Herzenswunsch nah werden. Vielleicht haben Sie etwas erreicht, was Sie sich einst gewünscht haben, und haben es verdient, es zu genießen. Die Zufriedenheit hält länger an, wenn man weiß, woher sie kommt, anstatt sich dem nächsten Wunsch zuzuwenden.","advice":"Genießen Sie, was hier ist, und fragen Sie, ob der Wunsch auch Ihren tieferen Werten dient.","yesNoMeaning":"Die Neun der Kelche tendiert zu Ja: Genieße, was da ist, und frage, ob der Wunsch auch deinen tieferen Werten dient."}' WHERE card_id = 'nine-of-cups' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Zehn der Kelche","meaning":"Emotionale Harmonie, Zugehörigkeit und dauerhafte Verbindung umgeben das Zuhause. Harmonie wächst durch wiederholte Fürsorge und Zuhören, nicht durch ein Zuhause ohne Meinungsverschiedenheiten. Diese Karte weckt die Freiheit, unter Menschen, die bereit sind, gemeinsam weiter aufzubauen, man selbst zu sein.","advice":"Pflege die Bindungen, die Freude nachhaltig und geteilt machen.","yesNoMeaning":"Die Zehn der Kelche tendiert zu ja: pflege die Bindungen, die Freude nachhaltig und geteilt machen."}' WHERE card_id = 'ten-of-cups' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Bube der Kelche","meaning":"Eine liebevolle Botschaft oder eine intuitive Entdeckung lädt zu emotionaler Offenheit ein. Eine liebevolle Nachricht, ein unerwartetes Gefühl oder eine fantasievolle Idee können Ihre Aufmerksamkeit erregen. Lassen Sie Raum für Überraschungen, ohne jedes Zeichen als festes Versprechen zu betrachten.","advice":"Bleibe neugierig über das Gefühl und reagiere mit Aufrichtigkeit statt mit Annahmen.","yesNoMeaning":"Der Bube der Kelche bleibt bedingt: Bleiben Sie neugierig auf das Gefühl und reagieren Sie mit Aufrichtigkeit statt mit Annahmen."}' WHERE card_id = 'page-of-cups' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Ritter der Kelche","meaning":"Romantik, Fantasie oder ein Ideal treiben das Herz voran. Vielleicht möchten Sie einer herzlichen Einladung oder einem Ideal folgen. Aufrichtigkeit gibt der Reise einen Sinn, während Praktikabilität Ihnen hilft zu erkennen, welche Menschen und Pläne Sie im Laufe der Zeit begleiten können.","advice":"Folge der Einladung, aber halte einen Fuß auf dem Boden, während sich die Versprechen entfalten.","yesNoMeaning":"Der Ritter der Kelche neigt zu Ja: Folge der Einladung, behalte aber einen Fuß auf dem Boden, während sich Versprechen entfalten."}' WHERE card_id = 'knight-of-cups' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Königin der Kelche","meaning":"Tiefes Einfühlungsvermögen und Intuition schaffen einen ruhigen Raum für die Wahrheit. Genaues Zuhören kann dazu beitragen, dass sich jemand sicher genug fühlt, um zu sprechen. Tiefe Empathie bedeutet auch zu wissen, welche Bedürfnisse die eigenen sind und welche Trauer man für einen anderen Menschen nicht ertragen kann.","advice":"Höre mit Mitgefühl zu, während du die Grenzen bewahrst, die Fürsorge gesund halten.","yesNoMeaning":"Die Königin der Kelche tendiert zu ja: Hören Sie mit Mitgefühl zu, während Sie die Grenzen wahren, die Fürsorge gesund halten."}' WHERE card_id = 'queen-of-cups' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"König der Kelche","meaning":"Emotionale Reife stabilisiert starke Gefühle, ohne sie zu unterdrücken. Starke Gefühle können bestehen bleiben, während Sie sich für eine ruhige, verantwortungsvolle Reaktion entscheiden. Diese Beständigkeit kann ein schwieriges Gespräch für alle Beteiligten sicherer machen.","advice":"Reagiere mit Mitgefühl und Selbstbeherrschung, besonders wenn andere reaktiv sind.","yesNoMeaning":"Der König der Kelche neigt zu Ja: Reagiere mit Mitgefühl und Selbstbeherrschung, besonders wenn andere reaktiv sind."}' WHERE card_id = 'king-of-cups' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Ass der Schwerter","meaning":"Eine klare Einsicht durchbricht Verwirrung und enthüllt eine neue Wahrheit. Eine neue Tatsache oder ein ehrliches Gespräch kann Verwirrung stiften. Die Wahrheit kann scharf sein, also nutzen Sie sie, um klarer zu verstehen und zu entscheiden, anstatt zu verletzen.","advice":"Nennen Sie das Problem klar und verwenden Sie Klarheit im Dienst einer fairen Entscheidung.","yesNoMeaning":"Das Schwert-Ass tendiert zu Ja: Nenne das Thema klar und nutze Klarheit zum Dienst einer fairen Entscheidung."}' WHERE card_id = 'ace-of-swords' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Zwei der Schwerter","meaning":"Eine vorsichtige Pattsituation verzögert eine Entscheidung, die nicht für immer ausgesetzt bleiben kann. Möglicherweise bewahren Sie das Gleichgewicht, indem Sie sich weigern, eine Entscheidung zu treffen, auch wenn der Druck nicht nachgelassen hat. Ruhe ist nützlich; Das Vermeiden unangenehmer Informationen wird die Entscheidung nicht verschwinden lassen.","advice":"Entferne die Augenbinde sanft, sammle die fehlenden Fakten und entscheide aus dem Gleichgewicht.","yesNoMeaning":"Die Zwei der Schwerter ist noch unklar: Entferne die Augenbinde behutsam, sammle die fehlenden Fakten und entscheide aus der Balance heraus."}' WHERE card_id = 'two-of-swords' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Drei der Schwerter","meaning":"Eine schmerzliche Wahrheit, eine Trennung oder eine Enttäuschung verlangt nach Anerkennung. Worte, eine Trennung oder eine gebrochene Erwartung können echte Schmerzen hinterlassen. Benennen Sie den Schmerz und suchen Sie Unterstützung, anstatt zu beweisen, dass es Ihnen bereits gut geht.","advice":"Lass das Gefühl durch dich hindurchfließen und vermeide es, Schmerz in eine dauerhafte Geschichte zu verwandeln.","yesNoMeaning":"Die Drei der Schwerter tendiert zu nein: Lass das Gefühl durch dich hindurchgehen und vermeide, Schmerz in eine permanente Geschichte zu verwandeln."}' WHERE card_id = 'three-of-swords' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Vier der Schwerter","meaning":"Nach Druck oder Konflikten sind Ruhe und geistige Ruhe erforderlich. Nachdem Sie lange Zeit auf Druck reagiert haben, braucht Ihr Geist Raum, um zur Ruhe zu kommen. Ruhe ist Teil der Erholung und Vorbereitung und kein Beweis dafür, dass Sie aufgegeben haben.","advice":"Pause vor dem Antworten; Erholung ist produktiv, wenn sie klares Denken wiederherstellt.","yesNoMeaning":"Die Vier der Schwerter lehnt sich zurück: Pausiere, bevor du antwortest; Erholung ist produktiv, wenn sie klares Denken wiederherstellt."}' WHERE card_id = 'four-of-swords' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Fünf der Schwerter","meaning":"Ein Konflikt kann zu einem hohlen Sieg führen oder das Vertrauen beschädigen. Einen Streit zu gewinnen, kann immer noch das Vertrauen schädigen oder Sie erschöpfen. Fragen Sie, was der Sieg kostet und welche Grenzen Ihre Selbstachtung schützen würden.","advice":"Wähle Würde über Sieg und entferne dich von Taktiken, die zu viel kosten.","yesNoMeaning":"Die Fünf der Schwerter neigt sich zu nein: Wähle Würde über Sieg und tritt von Taktiken zurück, die zu viel kosten."}' WHERE card_id = 'five-of-swords' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Sechs der Schwerter","meaning":"Eine schwierige Passage führt allmählich zu ruhigeren Bedingungen. Der Übergang kann ruhig sein: Sie hinterlassen ein festgefahrenes Gespräch, eine alte Umgebung oder eine ermüdende Denkweise. Sie müssen kein perfektes Ziel sehen, um zu wissen, dass Sie auf dem Weg zu mehr Frieden sind.","advice":"Nimm, was du gelernt hast, akzeptiere Unterstützung und bewege dich weiterhin weg vom Aufruhr.","yesNoMeaning":"Die Sechs der Schwerter neigt sich ja: Nimm, was du gelernt hast, akzeptiere Unterstützung und bewege dich weiter weg vom Aufruhr."}' WHERE card_id = 'six-of-swords' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Sieben der Schwerter","meaning":"Strategie, Geheimhaltung oder Vermeidung erschweren den Weg. Die Geheimhaltung eines Plans kann Sie manchmal schützen; Sich der Verantwortung zu entziehen, schafft eine andere Art von Distanz. Untersuchen Sie die Beweggründe einer Strategie, bevor Sie sich für deren Anwendung entscheiden.","advice":"Handle clever, aber transparent; Abkürzungen, die Vertrauen verraten, werden als Probleme zurückkehren.","yesNoMeaning":"Die Sieben der Schwerter tendiert zu Nein: Handle klug, aber transparent; Abkürzungen, die Vertrauen verraten, werden als Probleme zurückkehren."}' WHERE card_id = 'seven-of-swords' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Acht der Schwerter","meaning":"Angst und restriktive Überzeugungen machen es schwierig, die verfügbaren Optionen zu erkennen. Das Gefühl, gefangen zu sein, kann größer sein als die Grenzen, die Sie tatsächlich umgeben. Wenn die Angst nachlässt, kann eine kleine Option, eine hilfsbereite Person oder ein übersehener Weg sichtbar werden.","advice":"Hinterfrage den Gedanken, der sagt, du seist gefangen, und unternimm eine kleine befreiende Handlung.","yesNoMeaning":"Die Acht der Schwerter tendiert zu Nein: Hinterfrage den Gedanken, der sagt, dass du gefangen bist, und mache eine kleine befreiende Handlung."}' WHERE card_id = 'eight-of-swords' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Neun der Schwerter","meaning":"Angst vergrößert die Gefahr im Dunkeln und erschöpft den Geist. Sich wiederholende Gedanken können sich am heftigsten anfühlen, wenn man ihnen alleine gegenübersteht. Trennen Sie das Geschehene von dem, was Sie sich vorstellen, und erlauben Sie sich, um Hilfe zu bitten.","advice":"Bringe die Angst ans Licht, suche Unterstützung und trenne Fakten von eingebildeten Ergebnissen.","yesNoMeaning":"Die Neun der Schwerter tendiert zu Nein: Bring die Angst ans Tageslicht, suche Unterstützung und trenne Fakten von eingebildeten Ergebnissen."}' WHERE card_id = 'nine-of-swords' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Zehn der Schwerter","meaning":"Ein schmerzhafter Kreislauf erreicht seine letzte Grenze und kann nicht unverändert weitergehen. Das Ende kann Sie erschöpft zurücklassen, nachdem eine Situation zu lange gedauert hat. Das alte Muster kann nicht unverändert fortbestehen, aber klarere Grenzen können Raum für eine allmähliche Erholung schaffen.","advice":"Akzeptiere das Ende, schütze deine Genesung und erlaube einen anderen Anfang zu entstehen.","yesNoMeaning":"Die Zehn der Schwerter tendiert zu nein: akzeptiere das Ende, schütze deine Erholung und erlaube, dass ein anderer Anfang entsteht."}' WHERE card_id = 'ten-of-swords' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Bube der Schwerter","meaning":"Wachsame Neugier sucht nach Fakten, stellt Fragen und achtet auf Veränderungen. Neugier treibt Sie dazu, Fragen zu stellen und Details zu überprüfen, bevor Sie eine Schlussfolgerung akzeptieren. Diese Wachsamkeit unterstützt das Lernen, wenn es nicht zu Misstrauen gegenüber allen führt.","advice":"Forsche sorgfältig und spreche präzise, anstatt auf jedes Signal zu reagieren.","yesNoMeaning":"Der Bube der Schwerter bleibt bedingt: Forschen Sie sorgfältig und sprechen Sie präzise, statt auf jedes Signal zu reagieren."}' WHERE card_id = 'page-of-swords' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Ritter der Schwerter","meaning":"Der fokussierte Intellekt bewegt sich schnell und begegnet Hindernissen direkt. Eine klare Idee kann Sie voranbringen und Sie direkt zum Sprechen bringen. Entschlossenheit funktioniert am besten, wenn Sie noch neue Beweise hören und bemerken, wie Ihre Worte andere beeinflussen.","advice":"Gehen Sie mutig voran, aber langsam genug, um zu hören, was Ihre Sicherheit möglicherweise verpasst.","yesNoMeaning":"Der Ritter der Schwerter bleibt bedingt: Gehe mutig voran, aber langsam genug, um zu hören, was deine Gewissheit möglicherweise übersieht."}' WHERE card_id = 'knight-of-swords' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Königin der Schwerter","meaning":"Klare Wahrnehmung und ehrliche Grenzen verhindern Verwirrung. Erfahrung kann Ihnen helfen zu erkennen, worauf es bei konkurrierenden Gefühlen und Versprechen ankommt. Seien Sie direkt und halten Sie klare Grenzen ein, ohne das Mitgefühl zu verlieren.","advice":"Sprich, was wahr ist, mit Mitgefühl und lass die Erfahrung dich schärfen, nicht verhärten.","yesNoMeaning":"Die Königin der Schwerter tendiert zu ja: Sagen Sie, was wahr ist, mit Mitgefühl und lassen Sie Erfahrung Sie schärfen, nicht verhärten."}' WHERE card_id = 'queen-of-swords' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"König der Schwerter","meaning":"Vernunft, Fairness und diszipliniertes Urteilsvermögen leiten eine folgenreiche Entscheidung. Eine schwierige Entscheidung erfordert einheitliche Standards und klare Begründungen. Die Autorität dieser Karte beruht auf Fairness und nicht nur darauf, dass sie das letzte Wort hat.","advice":"Verwende Beweise, definiere den Standard und halte persönliche Vorurteile aus dem Urteil fern.","yesNoMeaning":"Der König der Schwerter neigt zu Ja: Nutze Beweise, definiere den Standard und halte persönliche Voreingenommenheit aus dem Urteil fern."}' WHERE card_id = 'king-of-swords' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Ass der Münzen","meaning":"Eine greifbare Chance bietet den Keim für Wohlstand, Arbeit oder Wohlbefinden. Eine praktische Stelle kann als Arbeit, Unterstützung, Fertigkeit oder gesündere Bedingungen erscheinen. Sein Wert hängt davon ab, wie es im Laufe der Zeit gepflegt wird, nicht nur von seinem ersten Aufruf.","advice":"Verankere die Gelegenheit in einem praktischen Plan und pflege sie kontinuierlich.","yesNoMeaning":"Das Ass der Münzen tendiert zu Ja: Verankere die Gelegenheit in einem praktischen Plan und pflege sie konsequent."}' WHERE card_id = 'ace-of-pentacles' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Zwei der Münzen","meaning":"Mehrere Prioritäten bewegen sich gleichzeitig und erfordern ein flexibles Gleichgewicht. Möglicherweise bringen Sie Arbeit, Geld, Zeit und persönliche Bedürfnisse gleichzeitig in Einklang. Flexibilität hält die Dinge in Bewegung, aber eine lange Phase des Jonglierens erfordert klarere Prioritäten.","advice":"Passen Sie den Rhythmus an, schützen Sie das Wesentliche und vermeiden Sie es, mehr zu versprechen, als Sie tragen können.","yesNoMeaning":"Die Zwei der Münzen bleibt bedingt: Passe den Rhythmus an, schütze das Wesentliche und vermeide es, mehr zu versprechen, als du tragen kannst."}' WHERE card_id = 'two-of-pentacles' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Drei der Münzen","meaning":"Die Fähigkeiten wachsen durch Zusammenarbeit, Feedback und sorgfältige Handwerkskunst. Gute Arbeit wächst, wenn jeder seine Rolle und seine Stärken versteht. Hier kommt es auf konkretes Feedback, das Erlernen eines Handwerks und den Respekt vor stiller Anstrengung an.","advice":"Trage deine Stärke bei, respektiere Fachwissen und baue auf einen gemeinsamen Standard.","yesNoMeaning":"Die Drei der Münzen tendiert zu ja: Trage deine Stärke bei, respektiere Fachwissen und baue nach einem gemeinsamen Standard."}' WHERE card_id = 'three-of-pentacles' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Vier der Münzen","meaning":"Durch strenge Einhaltung der Sicherheit können Ressourcen geschont, aber ein gesunder Datenfluss eingeschränkt werden. In Zeiten der Unsicherheit kann es sinnvoll sein, an hart erkämpften Ressourcen festzuhalten. Wenn jede Entscheidung von der Angst vor Verlust bestimmt wird, können sowohl Geld als auch Seelenfrieden eingeschränkt sein.","advice":"Schütze, was wichtig ist, ohne Angst jede Entscheidung für dich treffen zu lassen.","yesNoMeaning":"Die Vier der Münzen bleibt bedingt: Schütze, was wichtig ist, ohne dass Angst jede Entscheidung für dich trifft."}' WHERE card_id = 'four-of-pentacles' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Fünf der Münzen","meaning":"Materielle Belastung oder Ausgrenzung erzeugen Sorgen und ein Gefühl der Knappheit. Notlage kann dazu führen, dass Sie sich alleine fühlen oder keine Hilfe verdienen. Praktische Unterstützung kann immer noch nah sein, selbst wenn die Not den Weg dorthin schwer zu erkennen macht.","advice":"Bitte um praktische Hilfe und achte auf die Tür, die durch Schwierigkeiten leicht übersehen werden kann.","yesNoMeaning":"Die Fünf der Münzen neigt sich zu nein: Bitte um praktische Hilfe und achte auf die Tür, die Härte leicht übersehen lässt."}' WHERE card_id = 'five-of-pentacles' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Sechs der Münzen","meaning":"Ressourcen werden ausgetauscht, was Fragen nach Großzügigkeit, Macht und Fairness aufwirft. Hilfe funktioniert am besten, wenn sowohl der Geber als auch der Empfänger ihre Würde und ihre Stimme bewahren. Schauen Sie, ob der Austausch ausgewogen ist und welche Bedingungen mit Großzügigkeit einhergehen.","advice":"Gib oder empfange mit klaren Bedingungen, damit die Unterstützung die Würde beider Seiten bewahrt.","yesNoMeaning":"Die Sechs der Münzen tendiert zu Ja: Gib oder empfange mit klaren Bedingungen, damit Unterstützung die Würde auf beiden Seiten bewahrt."}' WHERE card_id = 'six-of-pentacles' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Sieben der Münzen","meaning":"Die Investition des Patienten erreicht einen Bewertungspunkt vor der nächsten Anstrengung. Sie haben sich viel Mühe gegeben, aber die Ergebnisse kommen möglicherweise nicht nach Ihrem Wunschplan an. Überprüfen Sie den Fortschritt und unterscheiden Sie, was mehr Geduld erfordert und was einen neuen Ansatz erfordert.","advice":"Überprüfen Sie, was wächst, verbessern Sie die Methode und geben Sie lohnenswerten Ergebnissen Zeit.","yesNoMeaning":"Die Sieben der Münzen bleibt bedingt: Überprüfe, was wächst, verbessere die Methode und gib lohnenswerten Ergebnissen Zeit."}' WHERE card_id = 'seven-of-pentacles' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Acht der Münzen","meaning":"Konzentrierte Wiederholungen entwickeln Meisterschaft und zuverlässige Ergebnisse. Fähigkeiten entwickeln sich durch Wiederholung, Korrektur und Aufmerksamkeit für kleine Details. Die Karte legt Wert auf stetiges Üben, das andere möglicherweise nie sehen, und nicht auf einen plötzlichen Sprung.","advice":"Üben Sie die wesentliche Fähigkeit, nehmen Sie Korrektur an und lassen Sie Qualität sich ansammeln.","yesNoMeaning":"Die Acht der Münzen tendiert zu Ja: Übe die wesentliche Fähigkeit, begrüße Korrektur und lasse Qualität entstehen."}' WHERE card_id = 'eight-of-pentacles' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Neun der Münzen","meaning":"Eigenständigkeit und kultivierter Komfort spiegeln disziplinierten Fortschritt wider. Ihr gegenwärtiges Wohlbefinden spiegelt möglicherweise viele zuvor getroffene disziplinierte Entscheidungen wider. Genießen Sie das, was Sie in Ihrem eigenen Tempo aufgebaut haben, und erkennen Sie die Arbeit dahinter.","advice":"Genieße, was du aufgebaut hast, und halte Unabhängigkeit mit Dankbarkeit verbunden.","yesNoMeaning":"Die Neun der Münzen tendiert zu Ja: Genieße, was du aufgebaut hast, und halte die Unabhängigkeit im Einklang mit Dankbarkeit."}' WHERE card_id = 'nine-of-pentacles' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Zehn der Münzen","meaning":"Langfristige Sicherheit wächst durch Vermächtnis, Familie und gemeinsame Grundlagen. Die Geschichte erstreckt sich über den Erfolg einer Person hinaus auf die Familie, die Gemeinschaft oder diejenigen, die ihnen folgen. Ein dauerhaftes Fundament entsteht aus der sorgfältigen Pflege gemeinsamer Ressourcen.","advice":"Planen Sie über den unmittelbaren Gewinn hinaus und schützen Sie, was anderen langfristig unterstützen kann.","yesNoMeaning":"Die Zehn der Münzen tendiert zu ja: plane über den unmittelbaren Gewinn hinaus und schütze, was anderen langfristig Unterstützung bieten kann."}' WHERE card_id = 'ten-of-pentacles' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Bube der Münzen","meaning":"Eine praktische Botschaft lädt zum Lernen, Planen oder zu einem fundierten neuen Unterfangen ein. Eine praktische Möglichkeit wird klarer, wenn Sie ihre Grundlagen erlernen. Entdecken Sie geduldig, testen Sie es im Kleinen und merken Sie, was bleibenden Wert hat.","advice":"Lerne die Grundlagen, definiere die nächste Aufgabe und beweise die Idee durch stetige Arbeit.","yesNoMeaning":"Der Bube der Münzen tendiert zu ja: Lernen Sie die Grundlagen, definieren Sie die nächste Aufgabe und beweisen Sie die Idee durch stetige Arbeit."}' WHERE card_id = 'page-of-pentacles' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Ritter der Münzen","meaning":"Zuverlässige Bemühungen schreiten langsam voran, geben die Aufgabe jedoch selten auf. Der Fortschritt mag sich so langsam anfühlen, dass Sie sich fragen, ob Sie sich bewegen, doch Beständigkeit bildet das Fundament. Zuverlässigkeit braucht auch Raum für Ruhe.","advice":"Halten Sie die Routine ehrlich und konsequent; Fortschritt ist wichtiger als Aufregung.","yesNoMeaning":"Der Ritter der Münzen neigt zu Ja: Halte die Routine ehrlich und konsistent; Fortschritt ist wichtiger als Aufregung."}' WHERE card_id = 'knight-of-pentacles' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"Königin der Münzen","meaning":"Einfallsreiche Pflege schafft Komfort, Gesundheit und praktische Fülle. Durch konkrete Sorgfalt und den sinnvollen Umgang mit Ressourcen kann Sicherheit geschaffen werden. Nachhaltige Großzügigkeit beginnt damit, dass man sich auch an die eigenen Bedürfnisse erinnert.","advice":"Pflege Menschen und Pläne auf eine Weise, die für dich nachhaltig bleibt.","yesNoMeaning":"Die Königin der Münzen tendiert zu ja: Pflegen Sie Menschen und Pläne auf eine Weise, die für Sie nachhaltig bleibt."}' WHERE card_id = 'queen-of-pentacles' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"König der Münzen","meaning":"Materielle Führung verwandelt Erfahrung in stabile und großzügige Führung. Erfahrung kann eine stabile Zukunft für Beruf, Familie oder Gemeinschaft unterstützen. Erfolg bedeutet mehr, wenn die Menschen, die ihn aufgebaut haben, an dieser Stabilität teilhaben können.","advice":"Treffe die langfristige Wahl und nutze den Erfolg verantwortungsvoll.","yesNoMeaning":"Der König der Münzen neigt zu Ja: Triff die vernünftige langfristige Wahl und nutze Erfolg verantwortungsvoll."}' WHERE card_id = 'king-of-pentacles' AND locale = 'de';
UPDATE card_translations SET payload = '{"name":"愚者","meaning":"白紙のページと未知への一歩 - 新しい旅は開かれた心から始まります。最初の一歩を踏み出す前に完全な地図は必要ありません。好奇心は、それぞれの試みから学ぶのに役立ちますが、少しの準備が自由が無謀さに変わるのを防ぎます。","advice":"目の前の道を信じ、すべての答えがなくても最初の一歩を踏み出してください。","yesNoMeaning":"新しい始まりはめったに固定された答えを持たない — 結果はあなたが踏み出す一歩にかかっています。"}' WHERE card_id = 'fool' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"魔術師","meaning":"必要なツールはすべて揃っています。意志を集中させ、意図を行動に移します。注意、時間、利用可能なリソースが同じタスクに向けられると、アイデアが現実になります。別のサインを待つ前に、すでに手の届くところにあるツールを確認してください。","advice":"スキルと資源を意図的に使う — 今こそ実行する時","yesNoMeaning":"あなたはすでに必要なすべてを持っています — このエネルギーは集中して前進することをサポートします。"}' WHERE card_id = 'magician' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"女教皇","meaning":"静かな知恵が水面下に隠れています。自分の直感と内なる声に耳を傾けてください。沈黙は、パターン、まだ名前を付けることができない感情、またはまだ欠けている情報を明らかにするかもしれません。すべてを公にする前に、もう少し観察してください。","advice":"立ち止まり、内面に向かい、行動する前に本能に導かれるようにしてください。","yesNoMeaning":"答えはまだ表面下に隠れている — 無理に明確な肯定や否定を求めず、直感を信じましょう。"}' WHERE card_id = 'high-priestess' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"女帝","meaning":"成長、豊かさ、そして育むエネルギーがあなたを取り囲んでいます。美しさとケアを開花させましょう。人間関係、プロジェクト、または自分自身の一部は、着実なケアを通じて成長する可能性があります。ここでの豊かさとは、成長する余地があること、何も残らないまで与えないことを意味します。","advice":"辛抱強く、寛大でありなさい — 愛を持って創造し、物事を自然に熟成させなさい。","yesNoMeaning":"成長、豊かさ、そして育むエネルギーがあなたの願いを支えてくれます — 答えは静かな肯定です。"}' WHERE card_id = 'empress' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"皇帝","meaning":"構造、権限、そして安定したリーダーシップ。規律を持って強固な基盤を築きましょう。有用な構造は人々に安全な成長を与えます。責任を取ることと、細部までコントロールしようとすることの違いに注意してください。最初は似ているように見えるかもしれません。","advice":"明確な計画で主導権を握りましょう；確固たる境界が持続的な安定をもたらします。","yesNoMeaning":"構造、権威、そして着実な規律が自信ある「はい」を支える。"}' WHERE card_id = 'emperor' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"法王","meaning":"伝統と信頼できる指導が信頼できる道を提供します。これまでに起こったことから学びましょう。教師、コミュニティ、または確立された方法が、適切な出発点となる可能性があります。伝統がなぜ機能するのかを学び、それを自分の状況に思慮深く適用できるようにしてください。","advice":"確立された知恵に従い、信頼できる人々に助言を求める。","yesNoMeaning":"伝統と信頼できる指針は信頼できる「はい」を示しています ― 既に実証されているものに頼りましょう。"}' WHERE card_id = 'hierophant' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"恋人たち","meaning":"意味のある絆や重要な選択。自分の心が本当に大切にしているものに従ってください。永続的な調和を実現するには、双方がニーズと境界線について正直に話すことが求められます。これがロマンスではなく決断である場合は、どの道があなたのより深い価値観を反映しているかを尋ねてください。","advice":"誠実さと整合性を持って選ぶ — 誠実であるとき、つながりは深まる。","yesNoMeaning":"あなたの心と価値観はここで一致しています — 特に正直に選ぶとき、答えはイエスです。"}' WHERE card_id = 'lovers' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"戦車","meaning":"意志の力と勢いがあなたを前進させます。集中力を維持すれば勝利します。相反する衝動であっても、共通の方向性を与えると、あなたは前進することができます。進歩は、単に無理をするのではなく、自分の感情と行動をコントロールすることにかかっています。","advice":"目標に目を向け、すべての障害を自信を持って乗り越えながら進みなさい。","yesNoMeaning":"意志力と勢いはあなたの味方です — 集中した「はい」、ただし継続を約束する場合に限ります。"}' WHERE card_id = 'chariot' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"強さ","meaning":"本当の力は優しいものです。忍耐、勇気、思いやりがどんな困難にも対処します。優しさは積極的な勇気の形です。不快感に反応を決められることなく、不快感を抱えていても大丈夫です。恐怖が消えるのを待つのではなく、恐怖を認識し、慎重に行動してください。","advice":"穏やかな力で導きなさい；柔らかい手はしばしば最も強い手です。","yesNoMeaning":"穏やかな勇気と忍耐強い決意がこれを「はい」にする — 力ではなく冷静さで導く。"}' WHERE card_id = 'strength' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"隠者","meaning":"一歩下がって内面の明晰さを求める時が来ました。孤独は今、より深い答えをもたらします。一歩下がってみると、他の人の意見の中でも自分の声が聞きやすくなります。孤独は理解につながる場合には役立ちますが、つながりを避ける方法になることもあります。","advice":"内面に向かい、振り返り、静けさの中で本当に必要なものを見つけてください。","yesNoMeaning":"まだです — カードは行動する前に一歩引いて内なる明確さを見つけるよう求めています。"}' WHERE card_id = 'hermit' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"運命の輪","meaning":"運命は変わり、サイクルが変わります。今変化しているのは、より大きなリズムの一部です。古いサイクルが変わり、可能性と同時に不便ももたらしている可能性があります。すべてのイベントを選択することはできませんが、何を引き継ぐか、次のターンにどのように準備するかを選択できます。","advice":"柔軟に潮流に乗る — 良いことでも悪いことでも変化を受け入れましょう。","yesNoMeaning":"運は変わりつつある — 結果は固定されたはい・いいえではなく、変化にどう対応するかによる。"}' WHERE card_id = 'wheel-of-fortune' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"正義","meaning":"真実と公平さが日々を支えます。原因と結果のバランスが整いました。起こっていることは、単一の瞬間ではなく、以前の一連の選択を反映している可能性があります。事実を確認し、関係者の話を聞き、自分に属する部分を所有しましょう。","advice":"正直に行動し、両方の側面を考慮しなさい；天秤は公平に落ち着くでしょう。","yesNoMeaning":"天秤はまだ測定中です — 公正な答えは事実とあなたの正直さに依存します。"}' WHERE card_id = 'justice' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"吊るされた男","meaning":"立ち止まることで、状況を別の角度から見られるかもしれません。すぐに動くことに慣れていると、待つ時間は落ち着かないものです。それでも、少し力を抜き、手放せる期待を見つけることで、無理に進むだけでは得られなかった気づきが生まれます。","advice":"無理をせず、瞬間に身を委ね、新しい視点を受け入れなさい。","yesNoMeaning":"まず一時停止が必要である — 今これを無理に行うことは、より明確な答えを妨げるだけである。"}' WHERE card_id = 'hanged-man' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"死","meaning":"終わりは新たな始まりへの道を開きます。役目を終えたものを手放しましょう。このカードは、文字通りの喪失の予測ではなく、移行について語っています。あなたは古い役割、習慣、期待を超えて成長しているかもしれません。それを手放すには、まだ時間がかかるかもしれません。","advice":"後悔せずに手放すこと；深い変容が新しい扉を開こうとしています。","yesNoMeaning":"終わりは道を清める — 現在の道は閉じつつあり、新しい道が始まる。"}' WHERE card_id = 'death' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"節制","meaning":"バランスと忍耐が調和をもたらします。相反するものを優雅にブレンドします。 2 つの異なるアプローチから何をブレンドできるかを探してください。静かな進歩は、持続可能な習慣、穏やかな会話、実際に維持できるペースなどの形をとる場合があります。","advice":"ほどほどに行動し、冷静さを保つ — 着実な一歩が目的地に到達する。","yesNoMeaning":"バランスと忍耐は調和をもたらします — 一歩ずつ着実に進める慎重な「はい」。"}' WHERE card_id = 'temperance' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"悪魔","meaning":"執着や誘惑、抜け出しにくい習慣が選択肢を狭めているかもしれません。目先の利益があるほど、長い目で見た代償には気づきにくいものです。その習慣から得ているものと失っているものを見つめることで、少しずつ選ぶ自由を取り戻せます。","advice":"自分を束縛しているものを名付け、自由を取り戻す — チェーンは許可しなければ縛ることはない。","yesNoMeaning":"執着や縛るパターンが邪魔をしています — まだではありません、その鎖が名付けられ、断ち切られるまでは。"}' WHERE card_id = 'devil' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"塔","meaning":"突然の変化が、確かだと思っていたものを揺さぶり、見過ごしていた事実を明らかにするかもしれません。信じていた計画が崩れるのはつらいことです。すぐに前向きな意味を探さなくても大丈夫。まず何が変わり、何がまだ残っているのかを確かめましょう。","advice":"混乱を歓迎してください；瓦礫の中からより明確な基盤を築くことができます。","yesNoMeaning":"突然の変化が古いものを壊している — 安定した「はい」が可能になる前に、基盤は落ち着かなければならない。"}' WHERE card_id = 'tower' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"星","meaning":"希望、癒し、そして静かなインスピレーションが嵐の後にあなたの精神を新たにします。希望は、すべてが自然に解決されるという約束ではありません。困難の後に一息つき、結果が目に見える前に重要なことに気を配り続ける余地があります。","advice":"前方の光を信じ、信じ続けてください—あなたの願いは手の届くところにあります。","yesNoMeaning":"希望と静かな再生は「はい」を示しています — 先にある光を信じて、あなたの願いを生かし続けましょう。"}' WHERE card_id = 'star' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"月","meaning":"幻想と不確実性が道を曖昧にします。見た目ではなく、自分の直感を信じてください。事実が不完全な場合、記憶と恐怖が説得力のある物語でギャップを埋めることができます。速度を落とし、自分の反応に気づき、自分が感じていることと検証したことを区別してください。","advice":"速度を落として深く見つめてください；霧が晴れると明確さがやってきます。","yesNoMeaning":"幻想と不確実性が道を曖昧にする — 外見の下を見ない限り答えは明確ではない。"}' WHERE card_id = 'moon' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"太陽","meaning":"喜び、成功、そして輝くような明晰さ。すべてが明るく、生命力に満ちています。明晰さは、自分の進歩を認識し、それを軽視することなく喜びを共有するのに役立ちます。仕事が残っている場合、この新たなエネルギーは、よりオープンに仕事に取り組むのに役立ちます。","advice":"祝って輝きましょう — ポジティブなエネルギーは望む結果を引き寄せます。","yesNoMeaning":"喜びと輝く明晰さが明るいイエスを確認します — すべてがあなたの味方に働いています。"}' WHERE card_id = 'sun' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"審判","meaning":"立ち上がって、新たになり、自分自身に正直になるよう呼びかけます。覚醒の判決。過去を振り返ることは、永遠に自分を責め続けることを意味する必要はありません。教訓を受け入れ、できることは許し、今すぐ意識的な選択をして変化への呼びかけに答えてください。","advice":"勇気を持って呼びかけに応じ、過去を許し、次の章に踏み出せ。","yesNoMeaning":"立ち上がり新たにする呼びかけ — 過去を許し正直に答えたなら、特にそうです。"}' WHERE card_id = 'judgement' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"世界","meaning":"完成と充実 — サイクルは完全な状態で終了します。成果には、その過程で得たスキル、人間関係、視点が含まれます。より広範な旅が続く中でも、このサイクルの完了を讃えましょう。","advice":"達成したことを祝いましょう；扉はより広い世界に開かれています。","yesNoMeaning":"完成と全体性は、これを成就した「はい」として示す — サイクルはあなたに有利に閉じる。"}' WHERE card_id = 'world' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ワンドのエース","meaning":"インスピレーションのひらめきが、大胆な創造の道を切り開きます。招待状、プロジェクト、または新しい願望があなたをより生き生きと感じさせるかもしれません。これは保証された結果ではなく、潜在的なものです。最初の興奮が冷めた後は、試して取り組む余地が必要です。","advice":"エネルギーが新鮮なうちに始め、アイデアに本当の第一歩を踏ませる。","yesNoMeaning":"ワンドのエースは肯定傾向: エネルギーが新鮮なうちに始め、アイデアに実際の第一歩を与える。"}' WHERE card_id = 'ace-of-wands' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ワンドの2","meaning":"未来は、計画と方向性の選択を通じて形を作ります。複数のルートが表示され、どこまで行きたいかを尋ね始めます。広い視野を持つことは役に立ちますが、終わりのない計画を立てると敷居が高くなってしまう可能性があります。","advice":"慣れ親しんだものの先を見つめ、成長の余地がある道に身を委ねなさい。","yesNoMeaning":"ワンドの2は条件付きです：慣れ親しんだものを超えて見つめ、その後成長の余地のある道にコミットしましょう。"}' WHERE card_id = 'two-of-wands' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ワンドの3","meaning":"初期の取り組みは、機会とより広い視野が得られるにつれて拡大します。あなたが始めたことは、慣れ親しんだ領域を超えて反響を呼び始めています。これまでの取り組みが実を結ぶ時間を確保しながら、連絡やフィードバックを常に受け​​入れてください。","advice":"作り続け、あなたの仕事が引き寄せる反応に備えなさい。","yesNoMeaning":"ワンドの3は「はい」に傾く：建設を続け、あなたの仕事が引き寄せる反応に応じる準備をしましょう。"}' WHERE card_id = 'three-of-wands' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ワンドの4","meaning":"安定性、歓迎、そして祝賀の共有が強固な基盤を築きます。たとえ旅が終わっていないとしても、マイルストーンは祝う価値があります。所属すること、そしてこの瞬間を築くのを手伝ってくれた人々は、あなたの次のステップを強化することができます。","advice":"節目を記して、支えてくれる人々と共有しましょう。","yesNoMeaning":"ワンドの4はイエス傾向：節目を祝し、支えてくれる人たちと分かち合いましょう。"}' WHERE card_id = 'four-of-wands' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ワンドの5","meaning":"目標を競うことは摩擦、騒音、または自信のテストを引き起こします。多くの競合する声が共有の目標を隠してしまう可能性があります。誰もが実際に何を議論しているのかを理解し、意見の相違を超えて耳を傾けることができれば、対立によってアイデアが鮮明になる可能性があります。","advice":"競争心を有益な練習に変え、意味のない対立を拒否してください。","yesNoMeaning":"ワンドの5は条件付きのまま：ライバル関係を有益な練習に変え、目的のない対立を拒む。"}' WHERE card_id = 'five-of-wands' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ワンドの6","meaning":"評価は、断固とした努力と目に見える進歩の後に得られます。あなたの努力がついに他の人の目に留まるかもしれません。評価されると励みになりますが、たとえ観客が見ていなくても、あなたの作品の価値は残ります。","advice":"励ましを受け入れなさい、しかし自信は正直な仕事に結びつけたままにしなさい。","yesNoMeaning":"ワンドの6はイエスの傾き: 励ましを受け入れつつ、自信は正直な仕事に結びつけ続けましょう。"}' WHERE card_id = 'six-of-wands' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ワンドの7","meaning":"プレッシャーがあなたの決意を試す中、あなたは貴重な立場を保持します。重要なものを保護するには、それがなぜあなたにとって重要なのかを知る必要があります。プレッシャーはさまざまな方向から来る可能性がありますが、すべての課題が戦うに値するわけではありません。","advice":"すべての挑戦と戦うのではなく、明確な境界を持って大切なものを守りなさい。","yesNoMeaning":"ワンドの7はイエスの傾き: すべての挑戦と戦うのではなく、明確な境界線で大切なものを守りましょう。"}' WHERE card_id = 'seven-of-wands' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ワンドの8","meaning":"イベントが加速し、メッセージが到着し、勢いが遅れを解消します。ニュースや決定事項が予想よりも早く届く場合があります。全員が方向性を理解している場合、スピードが役立ちます。不明確な情報は勢いを混乱に変える可能性があります。","advice":"迅速に行動し、道が開かれている間は直接的なコミュニケーションを保ちなさい。","yesNoMeaning":"ワンドの8は「はい」に傾く：道が開いている間に素早く行動し、直接的にコミュニケーションを取りましょう。"}' WHERE card_id = 'eight-of-wands' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ワンドの9","meaning":"立ち直る力は強いですが、過去のストレスに注意を払われます。過去の緊張から自分を守る方法は学べましたが、常に警戒するのは疲れます。昨日の傷だけでなく、今日の証拠によって目の前のリスクを判断してください。","advice":"すべての傷が繰り返されることを期待せずに、自分のエネルギーを守りながら次のステップを踏む。","yesNoMeaning":"ワンドの9は条件付きのままです：自分のエネルギーを守り、すべての傷が繰り返されることを期待せずに次のステップを踏んでください。"}' WHERE card_id = 'nine-of-wands' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ワンドの10","meaning":"責任は重くなり、成功には負担がかかるようになりました。かつては誇りに思っていたものが、今ではあまりにも多くの義務を負っている可能性があります。あなたの能力は本物ですが、すべてのタスクを一人でこなす必要はありません。","advice":"仕事を委任し、簡素化し、もはや本当に自分のものでない仕事を手放しなさい。","yesNoMeaning":"ワンドの10は「いいえ」に傾く：委任し、簡素化し、もはや自分のものではない仕事を手放しましょう。"}' WHERE card_id = 'ten-of-wands' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ワンドのペイジ","meaning":"好奇心は、生き生きとしたメッセージ、実験、または新しい創造的な興味をもたらします。新鮮なアイデアは初心者の興奮を取り戻すことができます。探索する前にすべてをマスターする必要はありません。実際に試し、調整し、学ぶ許可を自分に与えてください。","advice":"勇気を持って探求し、初心者のエネルギーから行動を通じて学ぶ。","yesNoMeaning":"ワンドのペイジはやや肯定です：勇気を持って探求し、初心者のエネルギーから行動を通じて学びましょう。"}' WHERE card_id = 'page-of-wands' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ワンドのナイト","meaning":"情熱は急速に前進し、冒険と場合によっては焦りをもたらします。新しいものに惹かれると、すぐに立ち去りたくなるかもしれません。このエネルギーは、明確な目標があり、衝動が過ぎるたびに方向を変えないようにするときに最も効果的です。","advice":"勢いを利用するが、速度に努力が散らされる前に方向を選ぶ","yesNoMeaning":"ワンドのナイトは条件付きです：勢いを活かすが、速度が努力を散らさないうちに方向を選ぶこと。"}' WHERE card_id = 'knight-of-wands' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ワンドの女王","meaning":"温かい自信と創造的な独立心が、他の人をあなたのビジョンに引き寄せます。あなたがオープンに存在することで、他の人が共通のビジョンを信じるようになります。ここでの自信は、誰よりも優れている必要はありません。それは他の人にも輝ける余地を与えます。","advice":"自分の存在を信じ、他者を励まし、野心を縮めないでください。","yesNoMeaning":"ワンドの女王は肯定的です：自分の存在を信じ、他者を励まし、野心を縮小させないでください。"}' WHERE card_id = 'queen-of-wands' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ワンドのキング","meaning":"成熟したビジョンは、インスピレーションを決断力のある倫理的なリーダーシップに変えます。大きなビジョンには、意思決定、責任、そしてチームのエネルギーを維持する能力が必要です。プレッシャーやエゴだけではなく、明確な目的を通して導きます。","advice":"より大きな目的に従って導き、他の人が貢献できる余地を与える。","yesNoMeaning":"ワンドの王はイエス傾向：大きな目的から導き、他者が貢献できる余地を与えましょう。"}' WHERE card_id = 'king-of-wands' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"カップのエース","meaning":"心は新たな愛情、思いやり、感情の再生に向けて開かれます。出会い、新たな感情、または内面の柔らかさによって、あなたはもっと自由に贈ったり受け取ったりするようになるかもしれません。感情を特定の結果に強制する前に、感情を認めましょう。","advice":"感情を正直に受け取り、結果を強制せずに思いやりを流しましょう。","yesNoMeaning":"カップのエースは肯定傾向: 感情を正直に受け取り、結果を強制せずに配慮を流す。"}' WHERE card_id = 'ace-of-cups' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"カップの2","meaning":"相互認識により、パートナーシップ、魅力、または誠実な合意が生まれます。より深い約束は、最初の魅力を超えて、二人がお互いをはっきりと見ることにあります。誠実な会話、謝罪、または公正な合意により、絆が強化される可能性があります。","advice":"他者と対等に会い、心から話す。","yesNoMeaning":"カップの2は肯定的です：相手を対等に受け止め、心から語りましょう。"}' WHERE card_id = 'two-of-cups' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"カップの3","meaning":"友情、コミュニティ、喜びの共有は精神的な支えをもたらします。小さな集まりやタイムリーなサポートは、喜びを一人で抱え込む必要はないことを思い出させてくれます。物事が楽になる前にあなたの隣に立っていてくれた人たちのことを思い出してください。","advice":"一緒に祝って、誰が本当にあなたのために現れるかを覚えておきましょう。","yesNoMeaning":"カップの3は「はい」に傾く：一緒に祝福し、誰が本当にあなたのために現れるかを覚えておきましょう。"}' WHERE card_id = 'three-of-cups' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"カップの4","meaning":"感情的に引きこもっていると、手に入る贈り物に気づきにくくなります。疲れていたり落胆しているときは、たとえ良いオファーであっても鈍く見えるかもしれません。自分の周りにあるものは何も重要ではないと判断する前に、自分の現在の感情に正直になってください。","advice":"比較を一時停止して、静かに提供されているものをもう一度見てください。","yesNoMeaning":"カップの4は「いいえ」の傾き：比較を一時停止し、静かに提供されているものを再確認する。"}' WHERE card_id = 'four-of-cups' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"カップの5","meaning":"喪失は流出したものに注目を集めますが、意味のあるものは残ります。悲しみには、安易な楽観主義で覆い隠すよりも、名前を付ける価値がある。そうであっても、1 つの損失がすべてを語るわけではないかもしれません。サポートや可能性はまだ近くにあるかもしれません。","advice":"失望を尊重し、それからまだ存在する支援の方へ向かう。","yesNoMeaning":"カップの5は「いいえ」に傾く：失望を認めた後、まだ存在する支えの方に向かいましょう。"}' WHERE card_id = 'five-of-cups' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"カップの6","meaning":"記憶、無邪気さ、あるいは馴染みのある絆が、優しい温もりとともに戻ってきます。古い友人や思い出があなたに安心感を再びもたらすかもしれません。現在が変化し、それに伴ってあなた自身も変化したことを認識しながら、その暖かさを歓迎してください。","advice":"過去の親切を歓迎し、再びそこに住まなければならないふりをしないでください。","yesNoMeaning":"カップの6はイエスの傾き: 過去の優しさを歓迎しつつ、そこに再び住まなければならないふりはしないでください。"}' WHERE card_id = 'six-of-cups' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"カップの7","meaning":"多くの魅力的な可能性により、視覚と幻想の違いが曖昧になります。それぞれのオプションには素晴らしい約束があるように見えますが、すべての約束が同じ基盤を持っているわけではありません。あなたが本当に望むものと、それを中心に想像しているものを分けてください。","advice":"選択肢を絞り、夢を現実と照らし合わせてテストしてから決める。","yesNoMeaning":"カップの7はまだ不明確です：選択肢を絞り、一つの夢を現実と照らし合わせてからコミットしましょう。"}' WHERE card_id = 'seven-of-cups' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"カップの8","meaning":"かつて意味を持っていた状況は、もはや心に栄養を与えません。かつて意味があったものを手放すことは、悲しいことでもありますが、今のあなたにとっては正しいことでもあります。たとえより深い意味へのニーズが変わったとしても、その価値は本物でした。","advice":"正直に去り、今必要なより深い充実に向かって進みなさい。","yesNoMeaning":"カップの8は「いいえ」に傾く：正直に去り、今必要なより深い充足へ向かいましょう。"}' WHERE card_id = 'eight-of-cups' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"カップの9","meaning":"満足感と感謝の気持ちがあれば、心からの願いが身近に感じられます。あなたはかつて望んでいたものに到達し、それを楽しむ価値があるかもしれません。急いで次の欲求に向かうのではなく、満足感がどこから来るのかを知っていれば、満足感は長く続きます。","advice":"ここにあるものを楽しみ、願いが自分のより深い価値観にもかなうかを問いかけてください。","yesNoMeaning":"カップの9は肯定的です：ここにあるものを楽しみ、願いが自分のより深い価値観にも役立つかどうかを問うこと。"}' WHERE card_id = 'nine-of-cups' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"カップの10","meaning":"感情的な調和、帰属意識、そして永続的なつながりが家を囲みます。調和は、意見の相違のない家庭を通してではなく、思いやりと耳を傾けることを繰り返すことで育まれます。このカードは、一緒に構築を続けようとする人々の間で、自分らしくある自由を呼び起こします。","advice":"喜びを持続可能かつ共有できる絆を育てましょう。","yesNoMeaning":"カップの10はイエスの傾き: 喜びを持続的かつ共有できるものにする絆を育んでください。"}' WHERE card_id = 'ten-of-cups' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"カップのペイジ","meaning":"優しいメッセージや直感的な発見は、感情的な開放感をもたらします。優しいメッセージ、予期せぬ感情、想像力豊かなアイデアがあなたの注意を引くかもしれません。すべての兆候を固い約束として扱わずに、驚きを受け入れる余地を残してください。","advice":"感覚に好奇心を持ち、仮定ではなく誠実に反応してください。","yesNoMeaning":"カップのペイジは条件付きのままです：感情に対して好奇心を持ち、推測ではなく誠意をもって対応してください。"}' WHERE card_id = 'page-of-cups' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"カップのナイト","meaning":"ロマンス、想像力、理想は心を前に導きます。心からの誘いや理想に従いたいと思うかもしれません。誠実さは旅に意味を与えますが、実用性は時間の経過とともにどのような人や計画を一緒に旅行できるかを知るのに役立ちます。","advice":"招待に従うが、約束が展開する間は足を地に着けておく。","yesNoMeaning":"カップの騎士はイエス傾向：招待に従いながら、約束が進展する中で地に足をつけ続けましょう。"}' WHERE card_id = 'knight-of-cups' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"カップのクイーン","meaning":"深い共感と直観は、真実のための穏やかな空間を生み出します。注意深く聞くことで、相手は安心して話せるようになります。深い共感とは、どのニーズが自分のものであり、どの悲しみを他の人のために背負うことができないかを知ることも意味します。","advice":"思いやりを持って聞きながら、ケアを健全に保つ境界を守る。","yesNoMeaning":"カップのクイーンはやや肯定です：思いやりを持って耳を傾けつつ、ケアを健全に保つ境界線を守ってください。"}' WHERE card_id = 'queen-of-cups' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"カップのキング","meaning":"感情的に成熟すると、強い感情を抑制することなく安定します。冷静で責任ある対応を選択している間は、強い感情が残り続ける可能性があります。その安定性により、難しい会話が関係者全員にとってより安全になります。","advice":"他人が反応的なときには、特に思いやりと自己抑制をもって応答してください。","yesNoMeaning":"カップの王はイエス傾向：特に他者が反応的な時に、思いやりと自己制御をもって対応しましょう。"}' WHERE card_id = 'king-of-cups' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ソードのエース","meaning":"純粋な洞察は混乱を切り裂き、新たな真実を明らかにします。新しい事実や正直な会話が混乱を打ち破るかもしれません。真実は鋭いものであるため、傷つけるのではなく、より明確に理解し、決定するために使用します。","advice":"問題をはっきりと名指しし、公正な決定のために明確さを活用する。","yesNoMeaning":"ソードのエースは肯定傾向: 問題を率直に指摘し、公正な判断のために明確さを活用する。"}' WHERE card_id = 'ace-of-swords' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ソードの2","meaning":"ガードされた行き詰まりは選択を遅らせ、永遠に保留したままにすることはできません。プレッシャーは消えていないものの、選択を拒否することでバランスを保っているのかもしれません。冷静さは役に立ちます。不快な情報を避けたからといって、その決定が消えるわけではありません。","advice":"目隠しを優しく外し、欠けている事実を集め、バランスから判断する。","yesNoMeaning":"ソードの2はまだはっきりしていません：目隠しを優しく外し、欠けている事実を集め、バランスから決めましょう。"}' WHERE card_id = 'two-of-swords' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ソードの3","meaning":"つらい真実や別れ、期待が崩れた痛みを、なかったことにしなくていいのです。言葉に傷ついたなら、その気持ちを認めてください。もう平気だと急いで証明するより、必要なときは信頼できる人に支えを求めることが大切です。","advice":"感情を通して動かし、傷を永続的な物語にしないようにしましょう。","yesNoMeaning":"ソードの3は「いいえ」に傾く：感情を通過させ、傷を永続的な物語に変えないようにしましょう。"}' WHERE card_id = 'three-of-swords' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ソードの4","meaning":"プレッシャーや葛藤の後には、休息と精神的静寂が必要です。プレッシャーに長い間反応し続けた後は、心に落ち着く余地が必要です。休息は回復と準備の一部であり、諦めたことを証明するものではありません。","advice":"答える前に一時停止すること；回復は、明確な思考を取り戻すときに生産的である。","yesNoMeaning":"ソードの4は「いいえ」の傾き：答える前に一息つく；回復は明確な思考を取り戻すときに有益である。"}' WHERE card_id = 'four-of-swords' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"剣の5","meaning":"対立は空虚な勝利を生んだり、信頼を傷つけたりする可能性があります。議論に勝ったとしても、信頼を傷つけたり、疲れ果てたりする可能性はあります。勝利の代償はいくらなのか、自尊心を守るための境界線は何かを考えてみましょう。","advice":"勝つことより尊厳を選び、代償の大きすぎる戦術から離れる。","yesNoMeaning":"ソードの5は「いいえ」の傾き：勝つことより尊厳を選び、あまりにも代償の大きい戦術からは身を引く。"}' WHERE card_id = 'five-of-swords' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ソードの6","meaning":"困難な通路は徐々に穏やかな状況に向かって進みます。行き詰まった会話、古い環境、疲れる考え方から離れるなど、移行は静かに行われるかもしれません。より大きな平和に向かって進んでいることを知るために、完璧な目的地を見る必要はありません。","advice":"学んだことを活かし、支援を受け入れ、混乱から離れ続けなさい。","yesNoMeaning":"ソードの6はイエスの傾き: 学んだことを持ち、支援を受け入れ、混乱から遠ざかり続けましょう。"}' WHERE card_id = 'six-of-swords' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ソードの7","meaning":"戦略、秘密主義、回避が道を複雑にします。計画を非公開にしておくことで身を守ることができる場合があります。責任を回避すると、別の種類の距離が生まれます。戦略の使用を決定する前に、その戦略の背後にある動機を検討してください。","advice":"賢く行動しなさい、しかし透明性を持って行動して。信頼を裏切る近道は問題として戻ってくるでしょう。","yesNoMeaning":"ソードの7は否定的です：賢く行動しつつ透明性を保ち、信頼を裏切るような近道は問題として返ってきます。"}' WHERE card_id = 'seven-of-swords' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ソードの8","meaning":"恐怖と制限的な信念により、利用可能な選択肢が見えにくくなります。閉じ込められているという感覚は、実際の周囲の限界よりも大きいかもしれません。恐怖が和らぐにつれて、小さな選択肢の 1 つ、助けてくれる人、見落とされていた道が見えてくるかもしれません。","advice":"自分が閉じ込められているという考えに疑問を持ち、一つ小さな解放の行動を取ってみましょう。","yesNoMeaning":"ソードの8は「いいえ」に傾く：自分が閉じ込められているという思いを疑い、一歩の小さな解放行動を取りましょう。"}' WHERE card_id = 'eight-of-swords' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ソードの9","meaning":"不安は暗闇の中で危険を増大させ、心を疲弊させます。繰り返し考えていることは、一人でそれに直面しているときに最も激しく感じることがあります。起こったことと、これから起こるかもしれないと想像していることを分けて、自分に助けを求めましょう。","advice":"恐怖を日の光のもとに出し、サポートを求め、事実と想像の結果を区別する。","yesNoMeaning":"ソードの9は否定的です：恐怖を日の光にさらし、支援を求め、事実と想像上の結果を区別すること。"}' WHERE card_id = 'nine-of-swords' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ソードの10","meaning":"痛みを伴うサイクルは最終限界に達し、そのまま続けることはできません。状況が長すぎると、エンディングで疲れ果ててしまうかもしれません。古いパターンを変更せずに続けることはできませんが、境界を明確にすることで、段階的に回復する余地を作ることができます。","advice":"終わりを受け入れ、回復を守り、異なる始まりが現れることを許しなさい。","yesNoMeaning":"ソードの10は「いいえ」に傾く：終わりを受け入れ、回復を守り、別の始まりが現れるのを許しましょう。"}' WHERE card_id = 'ten-of-swords' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ソードのペイジ","meaning":"鋭い好奇心が事実を求め、質問し、変化を監視します。好奇心が高まると、結論を受け入れる前に質問したり、詳細を確認したりするようになります。その警戒心は、誰もが疑念を抱くまで固まらないときの学習をサポートします。","advice":"注意深く研究し、あらゆる信号に反応するのではなく、正確に話すこと。","yesNoMeaning":"ソードのペイジは条件付きのままです：慎重に調査し、すべての信号に反応するのではなく正確に話してください。"}' WHERE card_id = 'page-of-swords' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ソードのナイト","meaning":"集中した知性は素早く動き、障害物に直接立ち向かいます。明確なアイデアがあれば、あなたは前進し、率直に話すようになるかもしれません。まだ新しい証拠を聞いて、自分の言葉が他の人にどのような影響を与えているかに気づいたときに、決意が最も効果的です。","advice":"勇気を持って進みなさい、しかし自信が見逃すかもしれないことに耳を傾けるために十分にゆっくり進みなさい。","yesNoMeaning":"ソードのナイトは条件付きです：勇気をもって前進するが、自分の確信が見逃すかもしれないことも聞くためにゆっくり進むこと。"}' WHERE card_id = 'knight-of-swords' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ソードのクイーン","meaning":"明確な認識と正直な境界線が混乱を遮断します。経験は、競合する感情や約束の中で何が重要かを理解するのに役立ちます。思いやりを失わずに、率直で健全な境界線を保ちましょう。","advice":"思いやりをもって真実を語り、経験により自分を研ぎ澄ませ、硬直させないようにしましょう。","yesNoMeaning":"ソードの女王は肯定的です：真実を思いやりを持って語り、経験によって硬くなるのではなく研ぎ澄まされるようにしましょう。"}' WHERE card_id = 'queen-of-swords' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ソードのキング","meaning":"理性、公平性、規律ある判断が結果的な決定を導きます。難しい決断には、一貫した基準と明確な理由が必要です。このカードの権威は、単に最終決定を下すことによってではなく、公平性によってもたらされます。","advice":"証拠を使い、基準を定義し、個人的な偏見を判決に入れない","yesNoMeaning":"剣の王はイエス傾向：証拠を用い、基準を定め、個人的な偏見を判断に持ち込まないようにしましょう。"}' WHERE card_id = 'king-of-swords' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ペンタクルのエース","meaning":"具体的な機会は、繁栄、仕事、幸福の種をもたらします。現実的な開口部は、仕事、サポート、スキル、またはより健康的な状態として現れるかもしれません。その価値は、最初の魅力だけでなく、時間の経過とともにどのように手入れされるかによって決まります。","advice":"機会を現実的な計画に基づかせ、継続的に大切に育ててください。","yesNoMeaning":"ペンタクルのエースは肯定傾向: 機会を実践的な計画に基づかせ、継続的に大切にする。"}' WHERE card_id = 'ace-of-pentacles' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ペンタクルの2","meaning":"複数の優先事項が同時に移行するため、柔軟なバランスが必要です。あなたは仕事、お金、時間、個人的なニーズのバランスを同時にとっているかもしれません。柔軟性があれば物事はスムーズに進みますが、長い間ジャグリングを行うには、より明確な優先順位が必要になります。","advice":"リズムを調整し、重要なものを守り、運べる以上の約束は避けなさい。","yesNoMeaning":"ペンタクルの2は条件付きです：リズムを調整し、重要なものを守り、運べる以上の約束を避けましょう。"}' WHERE card_id = 'two-of-pentacles' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ペンタクルの3","meaning":"スキルは、コラボレーション、フィードバック、丁寧な職人技によって成長します。一人ひとりが自分の役割と強みを理解することで、良い仕事が生まれます。ここでは、具体的なフィードバック、技術の習得、そして静かな努力への敬意がすべて重要です。","advice":"自分の力を貢献し、専門知識を尊重し、共有された基準に向けて構築する。","yesNoMeaning":"ペンタクルの3は「はい」に傾く：自分の力を提供し、専門知識を尊重し、共通の基準に沿って築きましょう。"}' WHERE card_id = 'three-of-pentacles' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ペンタクルの4","meaning":"セキュリティをしっかりと守ると、リソースは保護されますが、健全なフローは制限されます。不確実性の高い状況では、苦労して獲得したリソースにしがみつくことは賢明だと思われるかもしれません。喪失への恐怖があらゆる選択を支配すると、お金も心の平安も束縛されているように感じられることがあります。","advice":"恐れにすべての判断を委ねず、大切なものを守る。","yesNoMeaning":"ペンタクルの4は条件付きのまま：恐れにすべての判断を委ねることなく、大切なものを守る。"}' WHERE card_id = 'four-of-pentacles' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ペンタクルの5","meaning":"物質的な負担や排除は、不安や欠乏感を生み出します。困難があると、孤独感を感じたり、助けてもらう価値がないと感じたりすることがあります。たとえ苦痛によってその道が見えにくくなったとしても、実際的な支援はまだ近くにあるかもしれません。","advice":"実際的な助けを求め、困難によって見落としやすくなった扉に気づきなさい。","yesNoMeaning":"ペンタクルの5は「いいえ」の傾き：実際的な助けを求め、困難が気づきにくくした扉に注意を払う。"}' WHERE card_id = 'five-of-pentacles' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ペンタクルの6","meaning":"リソースが交換されると、寛大さ、権力、公平性の問題が生じます。援助は、与える側も受ける側も尊厳と発言権を保っているときに最も効果を発揮します。交換のバランスが取れているかどうか、また寛大さにはどのような条件が伴うのかを検討してください。","advice":"明確な条件で与えたり受け取ったりすることで、支援が両者の尊厳を保つ。","yesNoMeaning":"ペンタクルの6はイエスの傾き: サポートが双方の尊厳を守るように、明確な条件で与えたり受け取ったりしましょう。"}' WHERE card_id = 'six-of-pentacles' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ペンタクルの7","meaning":"忍耐強い投資は、次の取り組みの前に評価点に達します。労力を費やしましたが、結果が希望のスケジュールどおりに得られない場合があります。進捗状況を確認し、さらに忍耐が必要なものと、新しいアプローチが必要なものを区別します。","advice":"育っているものを見直し、方法を改善し、価値のある結果に時間を与えましょう。","yesNoMeaning":"ペンタクルの7は条件付きです：成長しているものを見直し、方法を改善し、価値のある結果には時間を与えましょう。"}' WHERE card_id = 'seven-of-pentacles' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ペンタクルの8","meaning":"集中して繰り返すことで熟練し、信頼できる結果が得られます。繰り返し、修正し、細部に注意を払うことでスキルが向上します。このカードは、突然の飛躍よりも、他人には決して見られないような地道な練習を大切にしています。","advice":"基本的なスキルを実践し、訂正を歓迎し、質を蓄積する。","yesNoMeaning":"ペンタクルの8は「はい」に傾く：基本的なスキルを練習し、訂正を受け入れ、質を積み重ねましょう。"}' WHERE card_id = 'eight-of-pentacles' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ペンタクルの9","meaning":"自立心と培われた快適さは、規律ある進歩を反映しています。あなたの現在の快適さは、以前に行われた多くの規律ある選択を反映している可能性があります。自分のペースで構築したものを楽しみ、その背後にある取り組みを認識してください。","advice":"築き上げたものを楽しみ、感謝と結びつけた独立心を維持してください。","yesNoMeaning":"ペンタクルの9は肯定的です：自分が築いたものを楽しみ、独立を感謝と結びつけて保つこと。"}' WHERE card_id = 'nine-of-pentacles' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ペンタクルの10","meaning":"長期的なセキュリティは、レガシー、ファミリー、共有基盤を通じて強化されます。この物語は、一人の成功を超えて、家族、コミュニティ、またはその後の人々にまで広がります。耐久性のある基盤は、共有リソースに対する思慮深い配慮から生まれます。","advice":"目先の勝利を超えて計画し、他者を長期的に支えるものを守りましょう。","yesNoMeaning":"ペンタクルの10は「はい」に傾く：目先の勝利を超えて計画し、時間をかけて他者を支えられるものを守りましょう。"}' WHERE card_id = 'ten-of-pentacles' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ペンタクルのペイジ","meaning":"実用的なメッセージは、研究、計画、または地に足の着いた新しい事業を促します。基本を学ぶと、実践的な機会がより明確になります。辛抱強く探索し、小規模でテストし、永続的な価値があるものに気づきます。","advice":"基本を学び、次のタスクを定義し、着実な作業を通じてアイデアを証明する。","yesNoMeaning":"ペンタクルのペイジはやや肯定です：基本を学び、次の課題を定義し、着実な努力でアイデアを証明してください。"}' WHERE card_id = 'page-of-pentacles' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ペンタクルのナイト","meaning":"確実な努力はゆっくりと進みますが、タスクを放棄することはほとんどありません。進歩が非常に遅く感じられるため、自分が進んでいるのかと疑問に思うかもしれませんが、一貫性が基礎を築いています。信頼性には休息の余地も必要です。","advice":"日課を正直かつ一貫して保ちなさい；興奮よりも進歩が重要です。","yesNoMeaning":"ペンタクルのナイトは肯定的です：ルーチンを正直で一貫したものに保つこと。進歩は刺激よりも重要です。"}' WHERE card_id = 'knight-of-pentacles' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ペンタクルのクイーン","meaning":"資源に富んだケアは、快適さ、健康、そして実際的な豊かさを生み出します。安全は、具体的な注意行動と資源の賢明な使用によって生み出されます。持続可能な寛大さは、自分自身のニーズも思い出すことから始まります。","advice":"自分にとって持続可能な方法で人々と計画を育てましょう。","yesNoMeaning":"ペンタクルの女王は肯定的です：自分にとって持続可能な方法で人や計画を育てましょう。"}' WHERE card_id = 'queen-of-pentacles' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"ペンタクルのキング","meaning":"物質的なリーダーシップは、経験を安定した寛大な管理に変えます。経験は、仕事、家族、地域社会の安定した将来をサポートします。構築に貢献した人々がその安定性を共有できれば、成功の意味はさらに大きくなります。","advice":"長期的な選択を行い、成功を責任を持って活用してください。","yesNoMeaning":"ペンタクルの王はイエス傾向：健全な長期的選択を行い、成功を責任をもって活用しましょう。"}' WHERE card_id = 'king-of-pentacles' AND locale = 'ja';
UPDATE card_translations SET payload = '{"name":"바보","meaning":"빈 페이지와 믿음의 도약 — 새로운 여정은 열린 마음에서 시작됩니다. 첫걸음을 내딛기 전에 완전한 지도가 필요하지 않습니다. 호기심은 각 시도에서 배우는 데 도움이 되는 반면, 조금만 준비해도 자유가 무모함으로 바뀌는 것을 막을 수 있습니다.","advice":"당신 앞의 길을 믿고 모든 답을 알지 못하더라도 첫걸음을 내디디세요.","yesNoMeaning":"새로운 시작은 거의 고정된 답을 가지지 않습니다 — 결과는 당신이 취하는 단계에 달려 있습니다."}' WHERE card_id = 'fool' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"마술사","meaning":"필요한 모든 도구를 보유하고 있습니다. 의지를 집중하고 의도를 행동으로 바꾸십시오. 동일한 작업을 향한 관심, 시간 및 사용 가능한 리소스가 집중될 때 아이디어가 현실이 됩니다. 다른 신호를 기다리기 전에 이미 손이 닿는 곳에 있는 도구를 살펴보세요.","advice":"당신의 기술과 자원을 신중하게 사용하세요 — 지금이 실현할 때입니다.","yesNoMeaning":"당신은 이미 필요한 모든 것을 가지고 있다 — 에너지가 집중하여 앞으로 나아가는 것을 지지한다."}' WHERE card_id = 'magician' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"여교황","meaning":"조용한 지혜는 표면 아래에 숨어 있습니다. 직관과 내면의 목소리에 귀를 기울이십시오. 침묵은 패턴, 아직 이름을 붙일 수 없는 감정, 아직 누락된 정보를 드러낼 수 있습니다. 모든 것을 공개하기 전에 조금 더 관찰하십시오.","advice":"잠시 멈추고 내면으로 들어가 행동하기 전에 본능이 안내하도록 하세요.","yesNoMeaning":"정답은 지금은 표면 아래에 숨겨져 있습니다 — 명확한 예 또는 아니오를 강요하기보다는 직관을 신뢰하세요."}' WHERE card_id = 'high-priestess' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"황후","meaning":"성장, 풍요, 육성 에너지가 당신을 둘러싸고 있습니다. 아름다움과 보살핌이 번성하게 해주세요. 꾸준한 관리를 통해 관계, 프로젝트 또는 자신의 일부가 성장할 수 있습니다. 여기서 풍요란 발전할 여지가 있다는 뜻이며, 아무것도 남지 않을 때까지 주지 않는 것을 의미합니다.","advice":"인내심을 가지고 관대하게 — 사랑으로 창조하고 일이 자연스럽게 무르익게 두세요.","yesNoMeaning":"성장, 풍요, 그리고 돌보는 에너지가 당신의 소원을 지지합니다 — 답은 조용한 ''예''입니다."}' WHERE card_id = 'empress' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"황제","meaning":"구조, 권위, 꾸준한 리더십. 규율을 바탕으로 견고한 기반을 구축하세요. 유용한 구조는 사람들이 성장할 수 있는 안전을 제공합니다. 책임을 지는 것과 모든 세부 사항을 통제하려는 것의 차이를 주목하십시오. 처음에는 비슷해 보일 수 있습니다.","advice":"명확한 계획으로 주도권을 잡으세요; 확고한 경계는 지속적인 안정감을 가져옵니다.","yesNoMeaning":"구조, 권위 및 꾸준한 훈육이 자신 있는 ''예''를 뒷받침합니다."}' WHERE card_id = 'emperor' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"교황","meaning":"전통과 신뢰할 수 있는 지침은 신뢰할 수 있는 길을 제공합니다. 이전에 있었던 일로부터 배우십시오. 교사, 커뮤니티 또는 확립된 방법이 건전한 출발점을 제공할 수 있습니다. 자신의 상황에 신중하게 적용할 수 있도록 전통이 작동하는 이유를 알아보세요.","advice":"정립된 지혜를 따르고 신뢰하는 사람에게 조언을 구하세요.","yesNoMeaning":"전통과 신뢰할 수 있는 지침은 믿을 만한 ''예''를 가리킨다 — 이미 증명된 것에 기대라."}' WHERE card_id = 'hierophant' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"연인들","meaning":"의미 있는 유대감이나 중요한 선택. 당신의 마음이 진정으로 가치있게 여기는 것을 따르십시오. 지속적인 조화는 양측이 필요와 경계에 대해 솔직하게 말할 것을 요구합니다. 이것이 로맨스가 아닌 결정이라면 어떤 길이 당신의 더 깊은 가치를 반영하는지 물어보세요.","advice":"정직과 일치를 기준으로 선택하세요 — 진실할 때 연결이 깊어집니다.","yesNoMeaning":"당신의 마음과 가치는 여기서 일치합니다 — 답은 예입니다. 특히 정직하게 선택할 때 그렇습니다."}' WHERE card_id = 'lovers' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"전차","meaning":"의지력과 추진력이 당신을 앞으로 나아가게 합니다. 계속 집중하면 승리할 수 있습니다. 반대 충동은 당신이 공유된 방향을 제시할 때 여전히 당신을 앞으로 나아갈 수 있습니다. 발전은 단순히 더 열심히 밀어붙이는 것이 아니라 자신의 감정과 행동을 조정하는 데 달려 있습니다.","advice":"목표에 집중하고 모든 장애물을 자신 있게 헤쳐 나가세요.","yesNoMeaning":"의지력과 추진력이 당신 편이다 — 헌신을 유지하면 명확한 예입니다."}' WHERE card_id = 'chariot' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"힘","meaning":"진정한 힘은 온화합니다. 인내, 용기, 동정심은 어떤 어려움도 극복합니다. 부드러움은 용기의 적극적인 형태입니다. 불편함이 반응을 결정하도록 두지 않고 불편함을 유지할 수 있습니다. 두려움이 사라질 때까지 기다리기보다는 두려움을 인정하고 조심스럽게 움직이십시오.","advice":"차분한 힘으로 이끄세요; 부드러운 손이 종종 가장 강한 손입니다.","yesNoMeaning":"부드러운 용기와 인내심 있는 결단이 이것을 예스로 만듭니다 — 힘이 아닌 침착함으로 이끄세요."}' WHERE card_id = 'strength' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"은둔자","meaning":"한발 물러나 내면의 명확성을 추구할 시간입니다. 고독은 이제 더 깊은 답변을 제공합니다. 한 걸음 물러서면 다른 사람들의 의견 속에서 자신의 목소리가 더 쉽게 들리게 될 수 있습니다. 고독은 이해로 이어질 때 도움이 되지만 연결을 피하는 방법이 될 수도 있습니다.","advice":"내면으로 돌아가고, 반성하며, 조용함이 당신이 진정으로 필요한 것을 드러내게 하세요.","yesNoMeaning":"아직 — 카드가 행동하기 전에 한발 물러서서 내면의 명확성을 찾으라고 요청합니다."}' WHERE card_id = 'hermit' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"운명의 수레바퀴","meaning":"행운이 바뀌고 주기가 바뀐다. 지금 변화하는 것은 더 큰 리듬의 일부입니다. 오래된 사이클이 바뀌면서 가능성과 함께 불편함도 가져올 수 있습니다. 모든 이벤트를 선택할 수는 없지만 앞으로 무엇을 진행할지, 다음 턴을 어떻게 준비할지 선택할 수 있습니다.","advice":"유연하게 흐름을 따르세요 — 좋든 나쁘든 전환을 받아들이세요.","yesNoMeaning":"운이 돌아오고 있습니다 — 결과는 고정된 예 또는 아니오가 아니라 변화에 어떻게 대응하느냐에 달려 있습니다."}' WHERE card_id = 'wheel-of-fortune' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"정의","meaning":"진실과 공정이 승리합니다. 이제 원인과 결과가 균형을 이루고 있습니다. 지금 일어나고 있는 일은 한 번의 고립된 순간이 아니라 이전의 일련의 선택을 반영할 수 있습니다. 사실을 확인하고, 관련된 사람들의 말을 듣고, 당신에게 속한 부분을 소유하십시오.","advice":"정직하게 행동하고 양쪽을 저울질하세요; 저울은 공정하게 균형을 잡을 것입니다.","yesNoMeaning":"저울은 아직도 무게를 재고 있습니다 — 공정한 답은 사실과 당신의 정직함에 달려 있습니다."}' WHERE card_id = 'justice' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"매달린 남자","meaning":"잠시 멈추면 상황을 다른 각도에서 볼 수 있습니다. 문제를 곧바로 행동으로 해결하는 데 익숙하다면 기다림이 불편할 수 있습니다. 그래도 통제를 조금 내려놓거나 한 가지 기대를 놓아주면, 더 밀어붙일 때는 보이지 않던 점을 발견할 수 있습니다.","advice":"밀지 마세요 — 순간에 맡기고 새로운 관점이 도래하게 하세요.","yesNoMeaning":"먼저 일시정지가 필요합니다 — 지금 억지로 진행하면 더 명확한 답변을 방해할 뿐입니다."}' WHERE card_id = 'hanged-man' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"죽음","meaning":"하나의 끝은 새로운 시작을 위한 길을 엽니다. 제 역할을 다한 것은 놓아주세요. 이 카드는 문자 그대로의 손실 예측보다는 전환을 말합니다. 당신은 오래된 역할, 습관, 기대보다 더 성장했을 수도 있습니다. 그것을 뒤로하는 데는 시간이 더 걸릴 수 있습니다.","advice":"후회 없이 놓아주세요; 깊은 변형이 새로운 문을 열고 있습니다.","yesNoMeaning":"결말은 길을 열어주고 있습니다 — 현재의 길이 닫히면서 새로운 길이 시작될 수 있습니다."}' WHERE card_id = 'death' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"절제","meaning":"균형과 인내가 조화를 가져옵니다. 우아함과 반대되는 것을 섞으세요. 두 가지 다른 접근 방식을 혼합할 수 있는 방법을 찾아보세요. 조용한 발전은 지속 가능한 습관, 차분한 대화 또는 실제로 유지할 수 있는 속도의 형태를 취할 수 있습니다.","advice":"절제하며 움직이고 침착함을 유지하세요 — 꾸준한 발걸음이 목적지에 도달합니다.","yesNoMeaning":"균형과 인내는 조화를 가져옵니다 — 신중한 ‘예’를 한 번에 한 걸음씩 나아가면서 취하세요."}' WHERE card_id = 'temperance' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"악마","meaning":"집착이나 유혹, 벗어나기 어려운 습관이 선택의 폭을 좁히고 있을 수 있습니다. 당장의 이익 때문에 오래가는 부담을 알면서도 멈추기 어려울 때가 있습니다. 그 습관에서 무엇을 얻고 무엇을 잃는지 살펴보면, 스스로 선택할 여지가 조금씩 돌아옵니다.","advice":"나를 억누르는 것을 명확히 하고 자유를 되찾으세요 — 사슬은 허락할 때만 묶습니다.","yesNoMeaning":"집착이나 구속적인 패턴이 방해가 됩니다 — 아직은 아니지만, 사슬이 이름 붙여지고 끊어질 때까지는 그렇습니다."}' WHERE card_id = 'devil' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"탑","meaning":"갑작스러운 변화가 견고하다고 믿었던 계획을 흔들고, 보지 못했던 사실을 드러낼 수 있습니다. 믿음이 무너지는 순간은 힘듭니다. 바로 긍정적인 의미를 찾으려 애쓰지 않아도 됩니다. 먼저 무엇이 실제로 달라졌고 무엇이 여전히 남아 있는지 확인하세요.","advice":"뒤흔들림을 환영하세요; 잔해 속에서 더 명확한 기초가 세워질 수 있습니다.","yesNoMeaning":"갑작스러운 변화가 오래된 것을 깨뜨립니다 — 안정적인 ''예''가 가능하려면 땅이 가라앉아야 합니다."}' WHERE card_id = 'tower' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"별","meaning":"폭풍우가 지나간 후 희망, 치유, 조용한 영감이 당신의 영혼을 새롭게 해줄 것입니다. 희망은 모든 것이 저절로 해결될 것이라는 약속이 아닙니다. 어려움이 지나고 숨을 쉬고 결과가 눈에 띄기 전에 중요한 일을 계속 돌볼 수있는 공간입니다.","advice":"앞에 있는 빛을 믿고 계속 믿으세요 — 당신의 소원은 손에 닿을 수 있습니다.","yesNoMeaning":"희망과 조용한 재생은 ''예''를 가리킵니다 — 앞의 빛을 믿고 당신의 소원을 지키세요."}' WHERE card_id = 'star' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"달","meaning":"환상과 불확실성이 길을 흐리게 합니다. 겉모습이 아닌 직감을 믿으세요. 사실이 불완전할 때 기억과 두려움이 설득력 있는 이야기로 그 공백을 채울 수 있습니다. 속도를 늦추고, 당신의 반응을 주목하고, 당신이 확인한 것과 당신이 느끼는 것을 분리하십시오.","advice":"속도를 늦추고 더 깊이 살펴보세요; 안개가 걷히면 명확성이 올 것입니다.","yesNoMeaning":"환상과 불확실성이 길을 흐리게 합니다 — 겉모습 아래를 보기 전까지 답은 명확하지 않습니다."}' WHERE card_id = 'moon' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"태양","meaning":"기쁨, 성공, 빛나는 선명함. 모든 것이 밝고 생기가 넘칩니다. 명확성은 진행 상황을 인식하고 이를 최소화하지 않고도 기쁨을 공유하는 데 도움이 됩니다. 일이 남아 있다면, 이 새로운 에너지는 당신이 그것을 더 공개적으로 만나는 데 도움이 될 수 있습니다.","advice":"축하하고 빛나세요 — 긍정적인 에너지가 원하는 결과를 끌어옵니다.","yesNoMeaning":"기쁨과 빛나는 명료함이 밝은 긍정을 확인합니다 — 모든 것이 당신에게 유리하게 작용하고 있습니다."}' WHERE card_id = 'sun' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"심판","meaning":"일어서고, 새롭게 하고, 자신에게 정직하라는 부르심입니다. 각성 판정. 과거를 되돌아보는 것이 영원히 자신을 비난한다는 의미는 아닙니다. 교훈을 얻고, 당신이 할 수 있는 것을 용서하고, 지금 의식적인 선택으로 변화하라는 ​​부르심에 응답하십시오.","advice":"용기를 가지고 부름에 응하세요; 과거를 용서하고 다음 장으로 나아가세요.","yesNoMeaning":"일어나고 새로워지라는 부름 — 특히 과거를 용서하고 정직하게 응답할 때 그렇습니다."}' WHERE card_id = 'judgement' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"세계","meaning":"완성과 성취 - 순환은 완전한 완전함으로 마무리됩니다. 성과에는 그 과정에서 얻은 기술, 관계 및 관점이 포함됩니다. 더 넓은 여정이 계속되는 동안에도 이 주기의 완성을 기리세요.","advice":"당신이 성취한 것을 축하하세요; 문은 더 넓은 세상으로 열려 있습니다.","yesNoMeaning":"완성과 온전함은 이것이 충족된 ''예''임을 나타냅니다 — 주기가 당신에게 유리하게 닫힙니다."}' WHERE card_id = 'world' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"완드의 에이스","meaning":"영감의 불꽃은 대담한 창조의 길을 열어줍니다. 초대, 프로젝트 또는 새로운 소망은 당신이 더욱 살아있음을 느끼게 할 수 있습니다. 이는 보장된 결과라기보다는 잠재적인 결과입니다. 첫 번째 흥분이 사라진 후에는 실험과 헌신을 위한 공간이 필요합니다.","advice":"에너지가 충만할 때 시작하고 그 아이디어에 실제 첫걸음을 내딛으세요.","yesNoMeaning":"완드의 에이스는 긍정에 기울어 있습니다: 에너지가 신선할 때 시작하고 아이디어에 실제 첫걸음을 주세요."}' WHERE card_id = 'ace-of-wands' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"완드 두 장","meaning":"미래는 계획과 방향의 선택을 통해 형성됩니다. 하나 이상의 경로를 볼 수 있으며 얼마나 멀리 가고 싶은지 묻기 시작합니다. 폭넓은 시각이 도움이 되지만 끝없는 계획은 한계에 부딪힐 수 있습니다.","advice":"익숙한 것 너머를 바라본 후, 성장할 수 있는 여지가 있는 길에 헌신하세요.","yesNoMeaning":"완드의 투는 조건적임: 익숙한 것을 넘어 바라본 후, 성장할 여지가 있는 길에 헌신하라."}' WHERE card_id = 'two-of-wands' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"완드 3","meaning":"기회와 더 넓은 시야가 확보됨에 따라 초기 노력이 확대됩니다. 당신이 시작한 일은 익숙한 영역을 넘어서는 반응을 이끌어 내기 시작하는 것입니다. 초기 작업이 결실을 맺을 수 있도록 시간을 허용하면서 연락과 피드백에 열린 자세를 유지하세요.","advice":"계속해서 쌓아 나가고, 당신의 노력이 끌어오는 반응을 만날 준비를 하십시오.","yesNoMeaning":"완 3카드는 긍정 성향: 계속 구축하고 당신의 일이 불러오는 반응을 맞이할 준비를 하세요."}' WHERE card_id = 'three-of-wands' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"완드 4","meaning":"안정, 환영, 공유된 축하는 강력한 기반을 만듭니다. 여정이 끝나지 않았더라도 중요한 이정표는 축하할 가치가 있습니다. 소속감과 이 순간을 만드는 데 도움을 준 사람들이 다음 단계를 강화할 수 있습니다.","advice":"이정표를 표시하고 지지하는 사람들이 함께 나누도록 하라.","yesNoMeaning":"완드 4는 긍정적인 의미를 기울입니다: 이정표를 기념하고 지지하는 사람들과 함께 나누세요."}' WHERE card_id = 'four-of-wands' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"완드의 오형","meaning":"경쟁적인 목표는 마찰, 소음 또는 신뢰 테스트를 생성합니다. 많은 경쟁 목소리가 공유된 목표를 숨길 수 있습니다. 갈등은 모든 사람이 자신이 실제로 토론하고 있는 내용을 알고 차이점을 들을 수 있을 때 아이디어를 날카롭게 만들 수 있습니다.","advice":"경쟁을 유용한 연습으로 바꾸고 목적 없는 갈등은 거부하세요.","yesNoMeaning":"막대 다섯은 조건부로 유지된다: 경쟁을 유용한 연습으로 바꾸고, 목적 없는 갈등은 거부하라."}' WHERE card_id = 'five-of-wands' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"완드의 여섯","meaning":"인정은 확고한 노력과 눈에 보이는 진전을 따릅니다. 당신의 노력은 마침내 다른 사람들에게 보일 수도 있습니다. 인정을 받으면 격려를 받을 수 있지만, 시청하는 청중이 없을 때에도 작업의 가치는 그대로 유지됩니다.","advice":"격려를 받아들이되, 자신감을 정직한 일에 묶어 두세요.","yesNoMeaning":"완드 6번 카드는 예 쪽으로 기울어져 있습니다: 격려를 받아들이되, 자신감을 정직한 일에 묶어 두세요."}' WHERE card_id = 'six-of-wands' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"완드의 7","meaning":"압력이 당신의 결심을 시험하는 동안 당신은 귀중한 기반을 확보하고 있습니다. 중요한 것을 보호하려면 그것이 왜 중요한지 알아야 합니다. 압력은 여러 방향에서 올 수 있지만 모든 도전이 싸울 만한 가치가 있는 것은 아닙니다.","advice":"모든 도전과 싸우기보다는 명확한 경계로 중요한 것을 지켜라.","yesNoMeaning":"완드 7번 카드는 예 쪽으로 기울어져 있습니다: 모든 도전에 맞서기보다는 명확한 경계로 중요한 것을 지키세요."}' WHERE card_id = 'seven-of-wands' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"완드의 8","meaning":"이벤트가 가속화되고 메시지가 도착하며 모멘텀이 지연을 제거합니다. 뉴스나 결정이 예상보다 빨리 도착할 수 있습니다. 모든 사람이 방향을 이해할 때 속도는 도움이 됩니다. 불분명한 정보는 추진력을 혼란으로 바꿀 수 있습니다.","advice":"신속하게 행동하고 길이 열려 있는 동안 소통을 직접적으로 유지하세요.","yesNoMeaning":"완드의 여덟은 그렇다고 기운다: 길이 열려 있는 동안 신속하게 행동하고 의사소통을 직접적으로 유지하라."}' WHERE card_id = 'eight-of-wands' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"완드의 아홉","meaning":"회복력은 강하지만 과거의 긴장으로 인해 경계심을 갖게 됩니다. 과거의 긴장은 자신을 보호하는 방법을 가르쳐 주었지만 끊임없는 경계는 지치게 합니다. 어제의 상처뿐만 아니라 오늘의 증거로 당신 앞에 놓인 위험을 판단하십시오.","advice":"에너지를 보호하고 모든 상처가 반복될 것을 기대하지 않고 다음 단계를 밟으세요.","yesNoMeaning":"완드 9은 조건적입니다: 당신의 에너지를 보호하고 모든 상처가 반복될 것을 기대하지 않고 다음 단계를 밟으세요."}' WHERE card_id = 'nine-of-wands' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"완드의 열","meaning":"책임감은 무거워졌고 성공은 이제 부담을 안겨줍니다. 한때 자랑스러워했던 것이 이제는 너무 많은 의무를 지닐 수도 있습니다. 당신의 능력은 실제적이지만 모든 일을 혼자서 수행할 것을 요구하지는 않습니다.","advice":"위임하고 단순화하며 더 이상 진정으로 자신의 것이 아닌 일을 내려놓아라.","yesNoMeaning":"완 10카드는 부정 성향: 일을 위임하고 단순화하며 더 이상 진정으로 당신의 것이 아닌 일을 내려놓으세요."}' WHERE card_id = 'ten-of-wands' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"완드의 기사","meaning":"호기심은 생생한 메시지, 실험 또는 새로운 창의적 관심을 가져옵니다. 신선한 아이디어는 초보자의 설렘을 되살릴 수 있습니다. 탐험하기 전에 모든 것을 마스터할 필요는 없습니다. 실제로 시도하고, 조정하고, 배울 수 있는 권한을 스스로에게 부여하십시오.","advice":"용기를 가지고 탐험하고, 초심자의 에너지가 행동을 통해 당신을 가르치도록 하세요.","yesNoMeaning":"완드의 시종은 긍정 쪽으로 기울입니다: 용기를 가지고 탐험하며 초보자의 에너지가 행동을 통해 당신을 가르치게 하세요."}' WHERE card_id = 'page-of-wands' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"완드의 기사","meaning":"열정은 빠르게 진행되어 모험과 조바심을 불러일으킵니다. 새로운 것을 끌어당기면 즉시 떠나고 싶을 수도 있습니다. 이 에너지는 명확한 목표가 모든 충동에 따라 진로를 바꾸지 못하게 할 때 가장 잘 도움이 됩니다.","advice":"운동량을 이용하되, 속도가 노력을 흩뜨리기 전에 방향을 선택하세요.","yesNoMeaning":"완드의 기사: 조건부 - 추진력을 사용하되, 속도가 노력을 흩뜨리기 전에 방향을 선택하라."}' WHERE card_id = 'knight-of-wands' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"완드의 여왕","meaning":"따뜻한 자신감과 창의적인 독립성은 다른 사람들을 당신의 비전으로 끌어들입니다. 당신의 공개적인 존재는 다른 사람들이 공유된 비전을 믿도록 격려할 수 있습니다. 여기서 자신감은 누구보다 빛날 것을 요구하지 않습니다. 다른 사람들도 빛날 수 있는 여지를 만들어줍니다.","advice":"자신의 존재를 신뢰하고, 다른 사람들을 격려하며, 당신의 야망을 줄이지 마세요.","yesNoMeaning":"완드의 여왕은 긍정에 기울어 있습니다: 자신의 존재를 믿고, 다른 사람을 격려하며, 야망을 줄이지 마세요."}' WHERE card_id = 'queen-of-wands' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"완즈의 왕","meaning":"성숙한 비전은 영감을 결단력 있고 윤리적인 리더십으로 바꿔줍니다. 큰 비전에는 결정, 책임, 팀의 에너지를 유지하는 능력이 필요합니다. 압력이나 자존심만 따르기보다는 명확한 목적을 통해 이끌어 나가십시오.","advice":"더 큰 목적에서 이끌고 다른 사람들이 기여할 공간을 주십시오.","yesNoMeaning":"완드의 왕은 긍정적인 의미를 기울입니다: 더 큰 목적에서 이끌고 다른 사람들이 기여할 공간을 주세요."}' WHERE card_id = 'king-of-wands' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"컵의 에이스","meaning":"마음은 새로운 애정, 동정심, 정서적 갱신으로 열립니다. 만남, 새로운 느낌 또는 내면의 부드러워짐은 당신이 더 자유롭게 주고받도록 초대할 수 있습니다. 특정 결과를 강요하기 전에 감정을 인정하십시오.","advice":"감정을 솔직하게 받아들이고 결과를 강요하지 않고 배려를 흘러가게 두세요.","yesNoMeaning":"컵의 에이스는 긍정에 기울어 있습니다: 감정을 솔직하게 받고 결과를 강요하지 않고 배려를 흘려보내세요."}' WHERE card_id = 'ace-of-cups' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"컵 2","meaning":"상호 인정은 파트너십, 매력 또는 진실한 합의를 창출합니다. 더 깊은 약속은 처음의 매력을 넘어 서로를 명확하게 보는 두 사람에 있습니다. 진지한 대화, 사과, 공정한 합의는 유대감을 강화할 수 있습니다.","advice":"상대방을 평등한 사람으로 만나고 마음에서 우러나오는 말을 하세요.","yesNoMeaning":"컵의 투는 긍정으로 기울어짐: 상대를 동등하게 만나고 진심으로 이야기하라."}' WHERE card_id = 'two-of-cups' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"컵 3","meaning":"우정, 공동체, 공유된 기쁨은 정서적 지원을 가져옵니다. 작은 모임이나 시기적절한 지원은 기쁨을 혼자 가지고 갈 필요가 없다는 것을 상기시켜 줄 수 있습니다. 상황이 더 쉬워지기 전에 당신 옆에 서 있던 사람들을 기억하십시오.","advice":"함께 축하하고 진심으로 당신을 위해 나타나는 사람들을 기억하세요.","yesNoMeaning":"컵 3카드는 긍정 성향: 함께 축하하고 진심으로 당신을 위해 나타나는 사람이 누구인지 기억하세요."}' WHERE card_id = 'three-of-cups' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"컵 4","meaning":"감정적인 철수로 인해 사용 가능한 선물을 알아차리기가 어렵습니다. 피곤하거나 낙담할 때는 아무리 좋은 제안이라도 지루해 보일 수 있습니다. 주변에 아무것도 중요하지 않다고 결정하기 전에 현재의 감정에 대해 솔직해지세요.","advice":"비교를 잠시 멈추고 조용히 제공되고 있는 것을 다시 보세요.","yesNoMeaning":"컵 네는 ''아니오'' 쪽으로 기울어진다: 비교를 잠시 멈추고, 조용히 제공되고 있는 것을 다시 보라."}' WHERE card_id = 'four-of-cups' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"컵 5장","meaning":"상실은 의미 있는 것이 남아 있는 동안 유출된 것에 관심을 집중시킵니다. 슬픔은 성급한 낙관으로 덮이기보다는 이름을 붙여야 할 가치가 있습니다. 그럼에도 불구하고 한 번의 손실이 전체 이야기를 말해주지는 않을 수도 있습니다. 지원이나 가능성이 여전히 근처에 남아 있을 수 있습니다.","advice":"실망을 존중한 후, 여전히 존재하는 지지를 향해 돌아서세요.","yesNoMeaning":"컵의 다섯은 아니라고 기운다: 실망을 존중한 후, 여전히 존재하는 지지로 향하라."}' WHERE card_id = 'five-of-cups' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"컵의 여섯","meaning":"기억, 순수함, 익숙한 유대감이 부드러운 따뜻함으로 돌아옵니다. 오랜 친구나 추억이 당신을 안정감으로 다시 연결해 줄 수도 있습니다. 현재가 변했고, 당신도 그에 따라 변했다는 것을 인식하면서 그 따뜻함을 환영하세요.","advice":"과거의 친절을 환영하되, 다시 그곳에 살아야 한다고 가장하지 마세요.","yesNoMeaning":"컵 6번 카드는 예 쪽으로 기울어져 있습니다: 과거의 친절을 환영하되, 다시 그곳에서 살아야 한다고 가장하지 마세요."}' WHERE card_id = 'six-of-cups' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"컵의 7","meaning":"많은 매력적인 가능성이 비전과 환상의 차이를 모호하게 만듭니다. 각 옵션은 아름다운 약속을 담고 있는 것처럼 보일 수 있지만 모든 약속이 동일한 기반을 갖고 있는 것은 아닙니다. 당신이 진정으로 원하는 것과 그것을 둘러싸고 상상했던 것을 분리하십시오.","advice":"선택지를 좁히고 한 가지 꿈을 현실과 비교한 후에 결정하세요.","yesNoMeaning":"컵의 7은 아직 명확하지 않습니다: 선택을 좁히고 한 가지 꿈을 현실과 비교하여 검토한 후 헌신하세요."}' WHERE card_id = 'seven-of-cups' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"컵의 8","meaning":"한때 의미 있었던 상황은 더 이상 마음에 영양을 공급하지 않습니다. 한때 의미가 있었던 것을 떠나는 것은 지금 당신에게 슬프면서도 옳은 일이 될 수 있습니다. 더 깊은 의미에 대한 요구가 변하더라도 그 가치는 실제였습니다.","advice":"정직하게 떠나고, 이제 필요로 하는 더 깊은 성취를 향해 나아가세요.","yesNoMeaning":"컵의 여덟은 아니라고 기운다: 정직하게 떠나고 지금 필요한 더 깊은 충만으로 나아가라."}' WHERE card_id = 'eight-of-cups' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"컵의 아홉","meaning":"만족과 감사는 진심 어린 소원을 가깝게 느끼게 합니다. 당신은 한때 원했던 것을 얻었고 그것을 즐길 자격이 있을 수도 있습니다. 만족감은 다음 욕구로 달려가는 것보다 그것이 어디서 오는지 알 때 더 오래 지속됩니다.","advice":"여기에 있는 것을 즐기고, 그 소망이 당신의 깊은 가치에도 부합하는지 물어보세요.","yesNoMeaning":"컵의 9: 예로 기울어짐 - 여기 있는 것을 즐기고, 소원이 당신의 깊은 가치에 부합하는지 물어보라."}' WHERE card_id = 'nine-of-cups' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"컵의 열","meaning":"정서적 조화, 소속감, 지속적인 연결이 가정을 둘러싸고 있습니다. 화합은 의견충돌이 없는 가정을 통해서가 아니라, 반복적인 배려와 경청을 통해 성장합니다. 이 카드는 계속해서 함께 만들고자 하는 사람들 사이에서 자신이 될 수 있는 자유를 불러일으킵니다.","advice":"기쁨을 지속 가능하고 함께 나눌 수 있는 유대를 돌보세요.","yesNoMeaning":"컵 10번 카드는 예 쪽으로 기울어져 있습니다: 기쁨을 지속적이고 공유 가능하게 만드는 유대감을 키우세요."}' WHERE card_id = 'ten-of-cups' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"컵의 기사","meaning":"부드러운 메시지나 직관적인 발견은 감정적인 개방성을 불러옵니다. 부드러운 메시지, 예상치 못한 느낌, 상상력이 풍부한 아이디어가 당신의 관심을 끌 수 있습니다. 모든 표시를 확고한 약속으로 여기지 말고 놀라움을 위한 여지를 남겨두십시오.","advice":"감정에 대해 호기심을 가지고, 추측보다는 성실하게 반응하세요.","yesNoMeaning":"컵의 시종은 조건적입니다: 감정에 대해 호기심을 유지하고 가정이 아니라 진심으로 반응하세요."}' WHERE card_id = 'page-of-cups' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"컵의 기사","meaning":"로맨스, 상상, 이상이 마음을 앞으로 끌어당깁니다. 진심 어린 초대나 이상을 따르고 싶을 수도 있습니다. 성실함은 여행에 의미를 부여하고, 실용성은 시간이 지남에 따라 어떤 사람과 계획을 가지고 여행할 수 있는지 확인하는 데 도움이 됩니다.","advice":"초대를 따르되, 약속이 이루어짐에 따라 한 발은 현실에 두세요.","yesNoMeaning":"컵의 기사은 긍정적인 의미를 기울입니다: 초대를 따르되 약속이 펼쳐질 때 한 발은 현실에 두세요."}' WHERE card_id = 'knight-of-cups' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"컵의 여왕","meaning":"깊은 공감과 직관은 진실을 위한 차분한 공간을 만들어냅니다. 주의 깊게 듣는 것은 누군가가 말할 수 있을 만큼 안전하다고 느끼는 데 도움이 될 수 있습니다. 깊은 공감은 또한 당신의 욕구가 무엇인지, 다른 사람을 위해 감당할 수 없는 슬픔이 무엇인지 아는 것을 의미합니다.","advice":"돌봄을 건강하게 유지하는 경계를 지키면서도 동정심 있게 경청하세요.","yesNoMeaning":"컵의 여왕은 긍정 쪽으로 기울입니다: 돌봄을 건강하게 유지하는 경계를 지키면서 공감하게 들어주세요."}' WHERE card_id = 'queen-of-cups' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"컵의 왕","meaning":"정서적 성숙은 강한 감정을 억누르지 않고 안정시킵니다. 차분하고 책임감 있는 반응을 선택하는 동안에도 강한 감정이 남아 있을 수 있습니다. 그러한 꾸준함은 관련된 모든 사람이 어려운 대화를 더 안전하게 만들 수 있습니다.","advice":"특히 다른 사람들이 반응적일 때에는 연민과 자기절제를 가지고 대응하세요.","yesNoMeaning":"컵의 왕은 긍정적인 의미를 기울입니다: 다른 사람들이 반응할 때에도 연민과 자기 통제를 가지고 대응하세요."}' WHERE card_id = 'king-of-cups' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"소드의 에이스","meaning":"깨끗한 통찰력은 혼란을 뚫고 새로운 진실을 드러냅니다. 새로운 사실이나 솔직한 대화가 혼란을 해소할 수 있습니다. 진실은 날카로울 수 있으므로 상처를 주기보다는 좀 더 명확하게 이해하고 결정하는 데 활용하세요.","advice":"문제를 명확히 밝히고 공정한 결정을 위해 명료함을 사용하세요.","yesNoMeaning":"검의 에이스는 긍정에 기울어 있습니다: 문제를 분명히 이름 짓고 공정한 결정을 위해 명료함을 사용하세요."}' WHERE card_id = 'ace-of-swords' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"검 두 장","meaning":"조심스러운 교착상태는 영원히 보류될 수 없는 선택을 지연시킵니다. 비록 압박감이 사라지지는 않았지만 선택을 거부함으로써 균형을 유지하고 있을 수도 있습니다. 차분한 것이 유용합니다. 불편한 정보를 피한다고 해서 결정이 사라지지는 않습니다.","advice":"눈가리개를 부드럽게 제거하고, 누락된 사실을 수집한 후 균형을 기준으로 결정한다.","yesNoMeaning":"소드의 투는 아직 명확하지 않음: 눈가리개를 부드럽게 제거하고, 누락된 사실을 수집한 후 균형에서 판단하라."}' WHERE card_id = 'two-of-swords' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"검 3","meaning":"아픈 진실이나 이별, 실망은 있는 그대로 인정받아야 합니다. 말 한마디나 깨진 기대가 남긴 상처를 서둘러 덮지 않아도 됩니다. 이미 괜찮아졌다고 증명하려 하기보다 감정을 이름 붙이고, 필요하다면 믿을 만한 사람에게 도움을 구하세요.","advice":"감정이 당신을 통해 흐르게 하고, 상처를 영구적인 이야기로 만들지 마세요.","yesNoMeaning":"검 3카드는 부정 성향: 감정을 통해 흘려보내고 상처를 영구적인 이야기로 만들지 마세요."}' WHERE card_id = 'three-of-swords' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"검 4","meaning":"압박감이나 갈등 후에는 휴식과 정신적 안정이 필요합니다. 압력에 오랫동안 반응한 후에는 마음이 안정될 공간이 필요합니다. 휴식은 회복과 준비의 일부이지 포기했다는 증거가 아닙니다.","advice":"답변 전에 잠시 멈추기; 명확한 생각을 회복할 때 회복이 생산적입니다.","yesNoMeaning":"검 네는 ''아니오'' 쪽으로 기울어진다: 답하기 전에 잠시 멈추라; 회복은 명확한 사고를 회복할 때 생산적이다."}' WHERE card_id = 'four-of-swords' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"검의 오형","meaning":"갈등은 공허한 승리를 가져오거나 신뢰를 손상시킬 수 있습니다. 논쟁에서 이기더라도 신뢰가 손상되거나 지칠 수 있습니다. 승리의 대가가 무엇인지, 그리고 당신의 자존심을 보호할 경계는 무엇인지 물어보십시오.","advice":"승리보다 품위를 선택하고 너무 많은 비용이 드는 전략에서는 물러서세요.","yesNoMeaning":"검 다섯은 ''아니오'' 쪽으로 기울어진다: 승리보다 존엄을 선택하고, 너무 큰 대가를 치르는 전략에서 물러나라."}' WHERE card_id = 'five-of-swords' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"검의 여섯","meaning":"어려운 통로는 점점 더 차분한 상태로 이동합니다. 전환은 조용할 수 있습니다. 교착 상태에 빠진 대화, 오래된 환경 또는 피곤한 사고 방식을 떠나는 것입니다. 당신이 더 큰 평화를 향해 나아가고 있다는 것을 알기 위해 완벽한 목적지를 볼 필요는 없습니다.","advice":"배운 것을 받아들이고, 도움을 받아들이며, 혼란에서 계속 벗어나세요.","yesNoMeaning":"소드 6번 카드는 예 쪽으로 기울어져 있습니다: 배운 것을 가져가고, 지원을 받아들이며, 혼란으로부터 계속 멀어지세요."}' WHERE card_id = 'six-of-swords' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"검의 7","meaning":"전략, 비밀 또는 회피는 경로를 복잡하게 만듭니다. 계획을 비공개로 유지하면 때로는 귀하를 보호할 수 있습니다. 책임을 회피하는 것은 다른 종류의 거리를 만듭니다. 전략을 사용하기로 결정하기 전에 전략 이면의 동기를 조사하십시오.","advice":"영리하지만 투명하게 행동하세요; 신뢰를 배신하는 지름길은 문제로 돌아옵니다.","yesNoMeaning":"검의 7은 부정에 기울어 있습니다: 영리하지만 투명하게 행동하세요; 신뢰를 배반하는 지름길은 문제로 돌아옵니다."}' WHERE card_id = 'seven-of-swords' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"검의 8","meaning":"두려움과 제한적인 신념으로 인해 사용 가능한 옵션을 보기가 어렵습니다. 갇혀 있다는 느낌은 실제로 주변의 한계보다 더 클 수도 있습니다. 두려움이 완화되면서 하나의 작은 선택, 도움이 되는 사람, 또는 간과되었던 길이 보일 수 있습니다.","advice":"스스로 갇혀 있다고 생각하는 마음에 의문을 제기하고 작은 자유로운 행동 하나를 취하세요.","yesNoMeaning":"검의 여덟은 아니라고 기운다: 자신이 갇혔다고 말하는 생각에 의문을 제기하고 작은 자유로운 행동 하나를 취하라."}' WHERE card_id = 'eight-of-swords' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"검의 아홉","meaning":"불안은 어둠 속에서 위험을 확대하고 정신을 지치게 합니다. 반복되는 생각은 혼자 마주할 때 가장 치열하게 느껴질 수 있습니다. 발생한 일과 일어날 수도 있다고 생각하는 일을 분리하고 스스로 도움을 요청하세요.","advice":"두려움을 낮에 드러내고, 지원을 구하며, 사실과 상상된 결과를 구분하세요.","yesNoMeaning":"검의 9: 아니오로 기울어짐 - 두려움을 낮의 빛으로 가져오고, 지원을 구하며, 사실과 상상된 결과를 분리하라."}' WHERE card_id = 'nine-of-swords' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"검의 열","meaning":"고통스러운 주기는 최종 한계에 도달하며 변함없이 계속될 수 없습니다. 상황이 너무 오래 지속되면 결말로 인해 지칠 수 있습니다. 오래된 패턴은 변함없이 계속될 수 없지만 경계가 명확해지면 점진적인 회복을 위한 공간을 만들 수 있습니다.","advice":"끝을 받아들이고, 회복을 보호하며, 다른 시작이 나타나도록 허용하세요.","yesNoMeaning":"검 10카드는 부정 성향: 끝을 받아들이고 회복을 보호하며 새로운 시작이 나타나도록 허용하세요."}' WHERE card_id = 'ten-of-swords' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"검의 기사","meaning":"경계심이 강한 호기심은 사실을 찾고, 질문하고, 변화를 지켜봅니다. 호기심은 결론을 받아들이기 전에 질문을 하고 세부 사항을 확인하도록 유도합니다. 모든 사람의 의심이 굳어지지 않을 때 그러한 경계심은 학습을 지원합니다.","advice":"모든 신호에 반응하기보다는 신중하게 조사하고 정확하게 말하세요.","yesNoMeaning":"검의 시종은 조건적입니다: 신중하게 조사하고 모든 신호에 반응하기보다는 정확하게 말하세요."}' WHERE card_id = 'page-of-swords' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"검의 기사","meaning":"집중된 지성은 빠르게 움직이며 장애물에 직접 직면합니다. 명확한 아이디어는 당신을 앞으로 나아가게 하고 직접적으로 말하게 만들 수 있습니다. 새로운 증거를 계속 듣고 자신의 말이 다른 사람에게 어떤 영향을 미치는지 알아차릴 때 결단력이 가장 잘 작동합니다.","advice":"용기를 가지고 나아가되, 확신이 놓칠 수 있는 것을 들을 수 있을 만큼 천천히 움직이세요.","yesNoMeaning":"검의 기사: 조건부 - 용기를 가지고 나아가지만, 확신이 놓칠 수 있는 것을 들을 수 있을 만큼 천천히 진행하라."}' WHERE card_id = 'knight-of-swords' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"검의 여왕","meaning":"명확한 인식과 정직한 경계가 혼란을 없애줍니다. 경험은 상충되는 감정과 약속 사이에서 무엇이 중요한지 파악하는 데 도움이 됩니다. 동정심을 잃지 않고 직접적이고 건전한 경계를 유지하십시오.","advice":"연민과 함께 진실을 말하고, 경험이 당신을 단단하게 만들지 않고, 다듬도록 하세요.","yesNoMeaning":"검의 여왕은 긍정에 기울어 있습니다: 진실을 연민과 함께 말하고, 경험이 당신을 단단하게 하기보다 날카롭게 하도록 하세요."}' WHERE card_id = 'queen-of-swords' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"검의 왕","meaning":"이성, 공정성, 규율 있는 판단이 결과적인 결정을 이끌어냅니다. 어려운 결정에는 일관된 기준과 명확한 추론이 필요합니다. 이 카드의 권위는 단순히 최종 결정을 내리는 데서 오는 것이 아니라 공정성에서 비롯됩니다.","advice":"증거를 사용하고, 기준을 정의하며, 개인적 편견을 평결에서 제외하세요.","yesNoMeaning":"검의 왕은 긍정적인 의미를 기울입니다: 증거를 사용하고 기준을 정의하며, 개인적인 편견을 판결에 개입시키지 마세요."}' WHERE card_id = 'king-of-swords' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"펜타클의 에이스","meaning":"실질적인 기회는 번영, 일, 웰빙의 씨앗을 제공합니다. 실용적인 오프닝은 일, 지원, 기술 또는 더 건강한 상태로 나타날 수 있습니다. 그 가치는 첫 번째 매력뿐만 아니라 시간이 지남에 따라 어떻게 관리되는지에 따라 달라집니다.","advice":"기회를 실질적인 계획에 기반하고 꾸준히 돌보세요.","yesNoMeaning":"펜타클의 에이스는 긍정에 기울어 있습니다: 기회를 실질적인 계획에 기반하고 꾸준히 돌보세요."}' WHERE card_id = 'ace-of-pentacles' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"펜타클 2","meaning":"여러 가지 우선순위가 동시에 움직이며 유연한 균형이 필요합니다. 당신은 일, 돈, 시간, 개인적인 필요의 균형을 동시에 맞출 수 있습니다. 유연성은 일을 계속 진행시키지만 장기간의 저글링을 위해서는 보다 명확한 우선순위가 필요합니다.","advice":"리듬을 조정하고, 필수적인 것을 보호하며, 감당할 수 있는 것 이상을 약속하지 마세요.","yesNoMeaning":"펜타클의 투는 조건적임: 리듬을 조정하고, 필수적인 것을 보호하며, 감당할 수 있는 것 이상을 약속하지 마라."}' WHERE card_id = 'two-of-pentacles' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"펜타클 3","meaning":"기술은 협업, 피드백, 세심한 장인정신을 통해 성장합니다. 좋은 일은 각자가 자신의 역할과 강점을 이해할 때 성장합니다. 여기서는 구체적인 피드백, 기술 학습, 조용한 노력에 대한 존중이 모두 중요합니다.","advice":"당신의 힘을 기여하고, 전문성을 존중하며, 공동 표준에 맞춰 구축하세요.","yesNoMeaning":"펜타클 3카드는 긍정 성향: 당신의 힘을 기여하고, 전문성을 존중하며, 공동 기준에 맞추어 구축하세요."}' WHERE card_id = 'three-of-pentacles' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"펜타클 4","meaning":"보안을 엄격하게 유지하면 리소스는 보존되지만 건전한 흐름은 제한될 수 있습니다. 힘들게 얻은 자원을 붙잡는 것은 불확실한 상황에서 합리적이라고 느낄 수 있습니다. 손실에 대한 두려움이 모든 선택을 좌우할 때 돈과 마음의 평화 모두 제약을 받을 수 있습니다.","advice":"두려움이 모든 결정을 내리게 하지 않고 중요한 것을 보호하세요.","yesNoMeaning":"펜타클 네는 조건부로 유지된다: 중요한 것을 보호하되, 두려움이 모든 결정을 내리게 하지 말라."}' WHERE card_id = 'four-of-pentacles' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"펜타클의 오형","meaning":"물질적인 부담이나 배제는 걱정과 결핍감을 불러일으킵니다. 어려움을 겪으면 외로움을 느끼거나 도움을 받을 자격이 없다고 느낄 수 있습니다. 고통으로 인해 앞이 보이지 않는 경우에도 실질적인 지원은 여전히 ​​가까울 수 있습니다.","advice":"실질적인 도움을 요청하고, 고난 때문에 쉽게 간과하게 된 문을 주목하라.","yesNoMeaning":"펜타클 다섯은 ''아니오'' 쪽으로 기울어진다: 실질적인 도움을 요청하고, 어려움 때문에 쉽게 간과하게 되는 문을 주목하라."}' WHERE card_id = 'five-of-pentacles' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"펜타클의 여섯","meaning":"자원이 교환되면서 관대함, 권력, 공정성에 대한 의문이 제기됩니다. 도움은 주는 사람과 받는 사람 모두가 존엄성과 목소리를 유지할 때 가장 잘 작동합니다. 교환이 균형을 이루고 있는지, 관대함에는 어떤 조건이 따르는지 살펴보세요.","advice":"명확한 조건으로 주거나 받아서 지원이 양쪽 모두의 존엄을 지킬 수 있게 하세요.","yesNoMeaning":"펜타클 6번 카드는 예 쪽으로 기울어져 있습니다: 지원이 양쪽 모두의 존엄성을 지킬 수 있도록 명확한 조건으로 주거나 받으세요."}' WHERE card_id = 'six-of-pentacles' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"펜타클의 7","meaning":"인내심 있는 투자는 다음 노력이 이루어지기 전에 평가 지점에 도달합니다. 노력을 기울였으나 원하는 일정에 결과가 나오지 않을 수도 있습니다. 진행 상황을 검토하고 인내심이 더 필요한 것과 새로운 접근 방식이 필요한 것을 구별하세요.","advice":"자라는 것을 검토하고, 방법을 개선하며, 가치 있는 결과가 나타날 시간을 허용하십시오.","yesNoMeaning":"펜타클의 7은 조건부로 남아 있습니다: 자라고 있는 것을 검토하고, 방법을 개선하며, 가치 있는 결과에 시간을 주세요."}' WHERE card_id = 'seven-of-pentacles' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"펜타클의 8","meaning":"집중된 반복을 통해 숙달되고 신뢰할 수 있는 결과를 얻을 수 있습니다. 기술은 반복, 수정, 작은 세부 사항에 대한 관심을 통해 발전합니다. 카드는 갑작스러운 도약보다는 남들이 볼 수 없는 꾸준한 실천을 중요하게 생각합니다.","advice":"필수 기술을 연습하고, 교정을 환영하며, 품질을 축적하세요.","yesNoMeaning":"펜타클의 여덟은 그렇다고 기운다: 필수 기술을 연습하고, 교정을 받아들이며, 질을 쌓게 하라."}' WHERE card_id = 'eight-of-pentacles' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"펜타클의 아홉","meaning":"자립과 편안함은 규율 있는 발전을 반영합니다. 당신이 현재 누리는 편안함은 이전에 내린 많은 규율 있는 선택을 반영할 수 있습니다. 자신의 속도에 맞춰 자신이 만든 것을 즐기고 그 뒤에 있는 작업을 인식하십시오.","advice":"당신이 쌓아 올린 것을 즐기고, 감사와 연결된 독립성을 유지하세요.","yesNoMeaning":"펜타클의 9: 예로 기울어짐 - 당신이 쌓아 올린 것을 즐기고, 독립성을 감사와 연결하여 유지하라."}' WHERE card_id = 'nine-of-pentacles' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"펜타클의 열","meaning":"장기적인 보안은 레거시, 가족 및 공유 기반을 통해 성장합니다. 이야기는 한 사람의 성공을 넘어 가족, 지역 사회 또는 따르는 사람들에게까지 확장됩니다. 내구성 있는 기반은 공유 리소스에 대한 사려 깊은 관리를 통해 성장합니다.","advice":"즉각적인 승리를 넘어 계획하고 시간이 지나면서 다른 사람들을 지원할 수 있는 것을 보호하세요.","yesNoMeaning":"펜타클 10카드는 긍정 성향: 즉각적인 승리 너머를 계획하고 시간이 지나도 다른 사람을 지원할 수 있는 것을 보호하세요."}' WHERE card_id = 'ten-of-pentacles' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"펜타클의 기사","meaning":"실용적인 메시지는 연구, 계획 또는 기반이 있는 새로운 모험을 초대합니다. 실용적인 기회는 기본을 배우면 더욱 명확해집니다. 인내심을 갖고 탐색하고, 소규모로 테스트하고, 지속적인 가치가 있는 것이 무엇인지 알아보세요.","advice":"기본을 배우고, 다음 과제를 정의하며, 꾸준한 작업을 통해 아이디어를 증명하세요.","yesNoMeaning":"펜타클의 시종은 긍정 쪽으로 기울입니다: 기본을 배우고, 다음 과제를 정의하며, 꾸준한 노력으로 아이디어를 증명하세요."}' WHERE card_id = 'page-of-pentacles' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"펜타클의 기사","meaning":"신뢰할 수 있는 노력은 천천히 진행되지만 작업을 포기하는 경우는 거의 없습니다. 진행이 너무 느리게 느껴져서 이동 중인지 의문이 들 수도 있지만 일관성은 기초를 구축하는 것입니다. 신뢰성에는 휴식을 위한 공간도 필요합니다.","advice":"루틴을 정직하고 일관되게 유지하십시오; 흥분보다는 진전이 더 중요합니다.","yesNoMeaning":"펜타클의 기사: 예로 기울어짐 - 일상을 정직하고 꾸준하게 유지하라; 진전이 흥분보다 중요하다."}' WHERE card_id = 'knight-of-pentacles' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"펜타클의 여왕","meaning":"풍부한 배려는 편안함과 건강, 실용적인 풍요를 만들어냅니다. 안전은 구체적인 배려 행위와 자원의 현명한 사용을 통해 창출될 수 있습니다. 지속 가능한 관대함은 자신의 필요 사항도 기억하는 것에서 시작됩니다.","advice":"자신에게 지속 가능한 방식으로 사람과 계획을 돌보세요.","yesNoMeaning":"펜타클의 여왕은 긍정에 기울어 있습니다: 지속 가능하게 사람과 계획을 돌보세요."}' WHERE card_id = 'queen-of-pentacles' AND locale = 'ko';
UPDATE card_translations SET payload = '{"name":"펜타클의 왕","meaning":"물질적 리더십은 경험을 안정적이고 관대한 청지기직으로 바꿉니다. 경험은 직장, 가족 또는 지역 사회의 안정적인 미래를 지원할 수 있습니다. 성공은 그것을 구축하는 데 도움을 준 사람들이 그 안정성을 공유할 수 있을 때 더 많은 것을 의미합니다.","advice":"장기적인 선택을 하고 성공을 책임감 있게 사용하라.","yesNoMeaning":"펜타클의 왕은 긍정적인 의미를 기울입니다: 장기적인 선택을 하고 성공을 책임감 있게 사용하세요."}' WHERE card_id = 'king-of-pentacles' AND locale = 'ko';
PRAGMA user_version = 9;
COMMIT;
